window.PACK={"book":{"id":"muallaqat","title":"شرح المعلقات السبع","type":"adabbook","author":"الزوزني (ت ٤٨٦هـ)","source":"المكتبة الشاملة عبر مشروع OpenITI","edition":"دار احياء التراث العربي","optional":true,"packVersion":"a21fee4b7d40"},"items":[{"id":"muallaqat:1","bookId":"muallaqat","type":"section","seq":1,"chapter":"مدخل","title":"مدخل","page":"","text":"...\nبسم الله الرحمن الرحيم\nقال القاضي الإمام أبو عبد الله الحسين بن أحمد بن الحسين الزوزني: هذا شرح القصائد السبع أمليته على حد الإيجاز والاقتصار على حسب ما اقترح علي، مستعينا بالله على إتمامه.\nذكر رواة أيام العرب أن امرأ القيس بن حجر بن عمرو الكندي كان يعشق عنيزة ابنة عمه شرحبيل، وكان لا يحظى بلقائها ووصالها، فانتظر ظعن1 الحي، وتخلف عن الرجال حتى إذا ظعنت النساء سبقهن إلى الغدير المسمى دارة جلجل واستخفى ثم إذ علم أنهن إذا وردن هذا الماء اغتسلن. فلما وردت العذارى اللواتي كانت عنيزة فيهن ونضون ثيابهن وشرعن في الانغماس في الماء ظهر امرؤ القيس وجمع ثيابهن وجلس عليها، ثم حلف على ألا يدفع إليهن ثيابهن إلا بعد أن يخرجن عاريات، فخاصمنه زمنا طويلا من النهار فأبى إلا إبرار قسمه، فخرجت إليه أوقحهن فرمى بثيابها إليها، ثم تتابعن حتى بقيت عنيزة وأقسمت عليه فقال: يا ابنة الكرام لا بد لك من أن تفعلي مثل ما فعلن، فخرجت إليه فرآها مقبلة ومدبرة، فلما لبسن ثيابهن أخذن في عذله2، وقلن: قد جوعتنا وأخرتنا عن الحي.\nفقال لهن: لو عقرت راحلتي أتأكلن؟\nقلن: نعم.\nفعقر راحلته ونحرها، وجمعت الإماء الحطب وجعلن يشوين اللحم إلى أن\nشبعن، وكانت معه ركوة1 فيها خمر فسقاهن منها، فلما ارتحلن قسمن أمتعته فبقي هو دون راحلة، فقال لعنيزة: يا ابنة الكرام لابد لك من أن تحمليني، وألحت عليها صواحبها أن تحمله على مقدم هودجها فحملته، فجعل يدخل رأسه في الهودج يقبلها ويشمها، وذكر هذه القصة في أثناء القصيدة."},{"id":"muallaqat:2","bookId":"muallaqat","type":"section","seq":2,"chapter":"مدخل","title":"نسبه","page":"ج1 ص14","text":"...\nترجمة امرئ القيس 565م\nنسبه:\nهو امرؤ القيس بن حجر الكندي، كنيته أبو وهب، أو أبو الحارث. قيل: إن اسمه جندح وإن امرأ القيس لقب غلب عليه، ومعناه رجل الشدة، لقب به لما لقي من الشدائد.\nولد امرؤ القيس في أوائل القرن السادس للمسيح في نجد. وذكر مؤرخوه أن أمه هي فاطمة بنت ربيعة بنت الحارث أخت كليب والمهلهل. ولكن هذا القول مشكوك في صحته؛ لأن امرأ القيس ذكر في شعره خالا له يدعى ابن كبشة، فلو كان كليب والمهلهل خالية لما كان استنكف من ذكرهما، وهما من عرف محلهما في الشرف والشجاعة. ثم إن الذين نقلوا أخباره يقولون: إن أباه طرده لأنه شبب بفاطمة، فمن غير المعقول أن يكون قد شبب بأمه، ولكن فاطمة هذه كانت ولا ريب زوج أبيه شبب بها لما كانت عليه من جمال فغار أبوه وطرده."},{"id":"muallaqat:3","bookId":"muallaqat","type":"section","seq":3,"chapter":"مدخل","title":"سبب ملك آبائه","page":"ج1 ص15","text":"أما سبب ملك آبائه على بني وائل رواه أبو عبيدة قال:\nلما تسافهت1 بكر بن وائل وقطع بعضها أرحام بعض اجتمع رؤساؤهم فقالوا: إن سفهاءنا قد غلبوا علينا حتى أكل القوي الضعيف ولا نستطيع دفع ذلك فنرى أن نملك علينا ملكا نعطيه الشاء والبعير فيأخذ للضعيف من القوي ويرد على المظلوم من\nالظالم، ولا يمكن أن يكون من بعض قبائلنا فيأباه الآخرون فيفسد ذات بيننا ولكنا نأتي تبعا1 فنملكه علينا. فأتوه وذكروا له أمرهم فملك عليهم حجرا ملك كندة. فلما ملك سدد أمورهم وساسهم أحسن سياسة وانتزع من اللخميين2 ما كان بأيديهم من أرض بكر بن وائل.\nولما مات ملك ابنه عمرو إلى سنة 524م ثم الحارث بن عمرو وهو جد امرئ القيس وأمه بنت عوف بن محلم بن ذهل بن شيبان ونزل الحيرة وكانت فيها النصرانية وبقي عليها.\nثم تفاسدت3 القبائل من نزار فأتاه أشرافهم فقالوا: إنا في دينك، ونحن نخاف أن نتفانى فيما يحدث بيننا فوجه معنا بنيك ينزلون فينا فيكفون بعضنا عن بعض.\nوكان للحارث خمسة بنين: حجر ومعدي كرب الملقب بالغلفاء، لأنه كان يغلف رأسه بالطيب وشرحبيل، وسلمة، وعبد الله. فقرقهم الحارث أبوهم في قبائل العرب: فملك ابنه حجرا على بني أسد وغطفان، وملك شرحبيل على بكر بن وائل وبني حنظلة؛ وملك معدي كرب على بني تغلب وطوائف بني دارم وبني رقية، وملك عبد الله على بني عبد القيس، وملك سلمة على قيس.\nوبقي الحارث مدة في ملكه حتى طلبه أنوشروان وكان ينقم عليه لأمر صدر منه أيام والده قباذ. فبلغ ذلك الحارث وهو بالأنبار وكان بها منزله. فخرج هاربا في هجائنه وماله وولده بالثوية. وتبعه المنذر بالخيل من تغلب وبهراء وإياد، فلحث بأرض كلب، فنجا، وانتهب ماله وهجائنه، وأخذت بنو تغلب ثمانية وأربعين نفسا من بني آكل المرار4 فقتلوهم بجفر الأملاك في ديار بني مرينا العباديين بين دير هند والكوفة، وفيهم يقول امرؤ القيس أبياته التي مطلعها:\nألا يا عين! بكي لي شنينا ... وبكي لي الملوك الذاهبينا\nومضى الحارث وأقام بأرض كلب، وكلب يزعمون أنهم قتلوه، وعلماء كندة يزعمون أنه خرج إلى الصيد فألظ بتيس من الظباء، فأعجزه، فآلى بألية1 ألا يأكل أولا إلا من كبده فطلبته الخيل ثلاثا، فأتى به بعد الثالثة وقد هلك جوعا، فشوى له الكبد وتناول منه فلذة2 فأكلها حارة فمات."},{"id":"muallaqat:4","bookId":"muallaqat","type":"section","seq":4,"chapter":"مدخل","title":"مقتل والد امرئ القيس","page":"ج1 ص17","text":"أما حجر ابنه فكان على بني أسد، وكانت له عليهم إتاوة3، في كل سنة، موقتة، فعمر كذلك دهرا ثم بعث إليهم جابيه الذي كان يجبيهم، فمنعوه ذلك، وحجر، يومئذ، بتهامة، وضربوا رسله وضرحوهم4 ضرحا شديدا قبيحا. فبلغ ذلك حجرا فسار إليهم بجند من ربيعة وجند من جند أخيه من قيس وكنانة، فأتاهم وأخذ سرواتهم5، فجعل يقتلهم بالعصا، فسموا عبيد العصا. وأباح الأموال وصيرهم إلى تهامة وحبس أشرافهم ثم رق لهم، فاستكانوا له حتى إذا وجدوا منه غفلة تمالئوا عليه فقتلوه.\nوخلف حجر أولادا منهم نافع، وكان أكبر ولده، وامرؤ القيس، وهو أصغرهم."},{"id":"muallaqat:5","bookId":"muallaqat","type":"section","seq":5,"chapter":"مدخل","title":"حياته","page":"ج1 ص17","text":"كان امرؤ القيس ذكيا متوقد الفهم. فلما ترعرع أخذ يقول الشعر، فبرز فيه إلى أن تقدم على سائر شعراء وقته بالإجماع. وكان مع صغر سنه يحب اللهو، ويستتبع صعاليك العرب ويتنقل في أحيائها فيغير بهم، وكان يكثر من وصف الخيل ويبكي على الدمن ويذكر الرسوم والأطلال وغير ذلك."},{"id":"muallaqat:6","bookId":"muallaqat","type":"section","seq":6,"chapter":"مدخل","title":"أسطورة أمر أبيه بذبحه","page":"ج1 ص17","text":"...\nأسطورة أمر أبيه يذبحه:\nقيل: إن أول شعر نظمه قوله:\nأذود القوافي عني ذيادا ... ذياد غلام جريء جودا1\nفلما كثرن وعنينه ... تخير منهن ستا جيادا2\nفأعزل مرجانها جانبا ... وآخذ من درها المستجادا\nفبلغ قوله إلى والده فغضب عليه لقوله الشعر، وكانت الملوك تأنف من ذلك. فأمر رجلا يقال له ربيعة أن يذبحه، فحمله ربيعة حتى أتى به جبلا فتركه فيه وأخذ عيني جؤذر3، فجاء بهما إلى أبيه. فآسف حجر لذلك وحزن عليه، فلما رأى ذلك ربيعة قال: ما قتلته. قال: فجئني به. فرجع إليه فوجده يقول:\nولا تسلمني يا ربيع لهذه ... وكنت أراني قبلها، بك واثقا\nمخالفة نوى أسير بقرية ... قرى عربيات يشمن البوارقا4\nفإما تريني اليوم في رأس شاهق ... فقد أغتدي أقود أجرد تائقا5\nوقد أذعر الوحش الرتاع بغرة ... وقد أجتلي بيض الخدور الروائقا6"},{"id":"muallaqat:7","bookId":"muallaqat","type":"section","seq":7,"chapter":"مدخل","title":"تشرده","page":"ج1 ص18","text":"فعاد امرؤ القيس إلى والده إلا أنه لم يكف عن قول الشعر، فطرده أبوه وأبى أن يقيم معه أنفة من قول الشعر، وقيل: بل طرده لما تغزل بفاطمة وكان لها عاشقا، فكان يسير في أحياء العرب، ومعه أخلاط من شذاذهم من طيئ وكلب وبكر بن وائل، فإذا صادف غديرا أو روضة أو موضع صيد أقام فذبح لمن معه في كل يوم وخرج إلى\nالصيد، فتصيد ثم عاد، فأكل وأكلوا معه وشرب الخمر وسقاهم وغنته قيانه، ولا يزال كذلك حتى ينفد ماء ذلك الغدير، ثم ينتقل عنه إلى غيره."},{"id":"muallaqat:8","bookId":"muallaqat","type":"section","seq":8,"chapter":"مدخل","title":"أسطورة زواجه","page":"ج1 ص19","text":"أخبر محمد بن القاسم أن امرأ القيس آلى بألية ألا يتزوج امرأة حتى يسألها عن ثمانية وأربعة واثنتين. فجعل يخطب النساء، فإذا سألهن عن هذا قلن: أربعة عشر. فبينا هو يسير في جوف الليل، إذا هو برجل يحمل ابنة له صغيرة فأعجبته. فقال لها يا جارية: ما ثمانية وأربعة واثنتان؟\nفقالت: أما ثمانية فأطباء الكلبة. وأما أربعة فأخلاف الناقة. واثنتان فثديا المرأة.\nفخطبها إلى أبيها فزوجه إياها وشرطت هي عليه أن تسأله عن ثلاث خصال فجعل لها ذلك وعلى أن يسوق إليها مائة من الإبل، وعشرة أعبد، وعشر وصائف، وثلاثة أفراس، ففعل ذلك.\nثم إنه بعث عبدا له إلى المرأة وأهدى إليها نحيا1 من سمن ونحيا من عسل وحلة من عصب2، فنزل العبد ببعض المياه فنشر الحلة ولبسها فتعلقت بشعره فانشقت، وفتح النحيين فطعم أهل الماء منهما فنقصا، ثم قدم على حي المرأة، وهم خلوف3، فسألها عن أبيها وأمها وأخيها ودفع إليها هديتها فقالت له: أعلم مولاك: أن أبي ذهب يقرب بعيدا ويبعد قريبا، وأن أمي ذهبت تشق النفس نفسين، وأن أخي يراعي الشمس، وأن سماءكم انشقت، وأن وعائيكم نضبا.\nفقدم الغلام على مولاه وأخبره. فقال: أما قولها إن أبي يقرب بعيدا ويبعد قريبا. فإن أباها ذهب يحالف قوما على قومه، وأما قولها ذهبت أمي تشق النفس نفسين. فإن أمها ذهبت تقبل4 امرأة نفساء، وأما قولها إن أخي يراعي الشمس، فإن\nأخاها في سرح1 له يرعاه فهو ينتظر وجوب الشمس ليروح2 به، وأما قولها إن سماءكم انشقت، فإن البرد الذي بعثت به انشق، وأما قولها إن وعائيكم نضبا، فإن النحيين اللذين بعثت بهما نقصا. فاصدقني.\nفقال: يا مولاي: إني نزلت بماء من مياه العرب، فسألوني عن نفسي وأخبرتهم أني ابن عمك، ونشرت الحلة فانشقت وفتحت النحيين، فأطعمت منهما أهل الماء.\nفقال: أولى لك3.\nثم ساق مائة من الإبل وخرج نحوها ومعه الغلام فنزلا منزلا، فخرج الغلام يسقي الإبل فعجز، فأعانه امرؤ القيس، ورمى به الغلام في البئر وخرج حتى جاء قوم المرأة بالإبل وأخبرهم أنه زوجها. فقيل لها: قد جاء زوجك.\nفقالت: والله ما أدري أزوجي هو أم لا. وكن انحروا له جزورا وأطعموه من كرشها وذنبها.\nففعلوا. فقالت: اسقوه لبنا حازرا، وهو الحامض.\nفسقوه فشرب.\nفقالت: افرشوا له عند الفرث4 والدم.\nففرشوا له فنام. فلما أصبحت أرسلت إليه: إني أريد أن أسألك. فسألته عن أشياء لم يحسن جوابها. قالت: عليكم بالعبد فشدوا أيديكم به ففعلوا.\nقال: ومر قوم فاستخرجوا امرؤ القيس من البئر فرجع إلى حيه فاستاق مائة من الإبل وأقبل على امرأته. فقيل لها. قد جاء زوجك.\nفقالت: والله ما أدري أهو زوجي أم لا. ولكن انحروا له جزورا فأطعموه من كرشها وذنبها.\nففعلوا: فلما أتوه بذلك قال: وأين الكبد والسنام والملحاء1؟\nفأبى أن يأكل فقالت: اسقوه لبنا حازرا.\nفأبى أن يشربه وقال: فأين الصريف والرثيئة2؟\nفقالت: افرشوا له عند الفرث والدم. فأبى أن ينام وقال: افرشوا لي فوق التلعة3 الحمراء واضربوا لي عليها خباء.\nثم أرسلت إليه: هلم شريطتي عليك في المسائل الثلاث.\nفقال لها: سلي عما شئت. فقالت: مم يختلج كشحاك4؟\nقال: للبسي الحبرات5.\nقالت: فمم تختلج فخذاك؟\nقال: لركضي المطيات6.\nقالت: هذا زوجي لعمري فعليكم به واقتلوا العبد.\nفقتلوه وتزوج بالجارية."},{"id":"muallaqat:9","bookId":"muallaqat","type":"section","seq":9,"chapter":"مدخل","title":"تصعلكه","page":"ج1 ص21","text":"ثم لم يزل امرؤ القيس مع صعاليك العرب حتى أتاه خبر مقتل أبيه وهو بدمون من أرض اليمن وقيل: من الشام. وأخبر ابن السكيت: أن حجرا أباه لما طعنه بعض\nبني أسد ولم يجهز عليه أوصى ودفع كتابه إلى رجل من بني عجل، يقال له عامر الأعور، وقال له: انطلق إلى ابني نافع، فإن بكى وجزع، فاله عنه واستقر أولادي، واحدا واحدا حتى تأتي امرأ القيس، وكان أصغرهم، فإن لم يجزع فادفع إليه سلاحي وخيلي ووصيتي. وقد كان بين في وصيته من قتله وكيف كان خبره.\nفانطلق الرجل بوصيته إلى نافع ابنه، فأخذ التراب، فوضعه على رأسه، ثم استقراهم واحدا واحدا، فكلهم فعل ذلك، حتى أتى امرأ القيس، فوجده في دمون مع نديم له يشرب ويلاعبه بالنرد، فقال له: قتل حجر.\nفلم يلتفت إلى قوله وأمسك نديمه. فقال له امرؤ القيس: اضرب فضرب حتى إذا فرغ قال: ما كنت لأفسد عليك دستك.\nثم سأل الرسول عن أمر أبيه كله فأخبره فقال:\nتطاول الليل علينا، دمون ... دمون! إنا معشر يمانون\nوإننا لأهلنا محبون\nوقال أيضا:\nخليلي ما في الدار مصحى لشارب ... ولا في غد إذ ذاك ما كان مشرب\nثم قال: ضيعني أبي صغيرا وحملني دمه كبيرا. لا صحو اليوم ولا سكر غدا اليوم خمر وغدا أمر1. اليوم قحاف، وغدا نقاف2.\nفذهب القولان مثلا:\nثم شرب سبعا. فلما صحا آلى أن لا يأكل لحما، ولا يشرب خمرا، ولا يدهن بدهن، ولا يلهو بلهو، ولا يغسل رأسه من جنابة، حتى يدرك بثأر أبيه فيقتل من بني آله مائة ويجز نواصي مائة، وفي ذلك يقول:\nأرقت ولم يأرق لما بي نافع ... وهاج لي الشوق الهموم الروادع1\nولما جنه الليل رأى برقا فقال:\nأرقت لبرق بليل أهل ... يضيء سناه بأعلى الجبل2\nأتاني حديث فكذبته ... بأمر تزعزع منه القلل3\nبقتل بني أسد ربهم ... ألا كل شيء سواه جلل4\nفأين ربيعة عن ربها ... وأين تميم، وأين الخول5\nألا يحضرون لدى بابه ... كما يحضرون، إذا ما استهل6"},{"id":"muallaqat:10","bookId":"muallaqat","type":"section","seq":10,"chapter":"مدخل","title":"تأهبه للأخذ بالثأر","page":"ج1 ص23","text":"ثم أخذ يعد العدد ويجهز الأسلحة لمحاربة بني أسد. فبلغ بني أسد ما يعده فأوفدوا عليه رجالا من قبائلهم كهولا وشبانا، فيهم المهاجر بن خداش ابن عم عبيد بن الأبرص وقبيصة بن نعيم، وكان في بني أسد مقيما، وكان ذا بصيرة بمواقع الأمور وردا وإصدارا، يعرف ذلك له من كان محيطا بأكناف بلده من العرب. فلما علم امرؤ القيس بمكانهم أمر بإنزالهم وتقدم بإكرامهم والإفضال عليهم واحتجب عنهم ثلاثا. فسألوا من حضرهم من رجال كندة. فقال: هو في شغل بإخراج ما في خزائن أبيه حجر من السلاح والعدة.\nفقالوا: اللهم غفرا. إنما قدمنا في أمر نتناسى به ذكر ما سلف، ونستدرك به ما فرط فليبلغ ذلك عنا.\nفخرج عليهم في قباء7، وخف وعمامة سوداء، وكانت العرب لا تعتم بالسواد\nإلا في الترات1. فلما نظروا إليه قاموا له وبدر إليه قبيصة: إنك في المحل والقدر والمعرفة بتصرف الدهر، وما تحدثه أيامه، وتتنقل به أحواله، بحيث لا تحتاج إلى تبصير واعظ، ولا تذكرة مجرب، ولك من سؤدد منصبك وشرف أعراقك، وكرم أصلك في العرب محتمل يحتمل ما حمل عليه من إقالة العثرة ورجوع عن هفوة. ولا تتجاوز الهمم إلى غاية إلا رجعت إليك. فوجدت عندك من فضيلة الرأي وبصيرة الفهم وكرم الصفح في الذي كان من الخطب الجليل، الذي عمت رزيته نزارا واليمن، ولم تخصص كندة بذلك دوننا، للشرف البارع.\nكان لحجر التاج والعمة فوق الجبين الكريم، وإخاء الحمد وطيب الشيم، ولو كان يفدى هالك بالأنفس بعده لما بخلت كرائمنا على مثله ببذل ذلك ولفديناه منه. ولكن مضى به سبيل لا يرجع أولاه على أخراه، ولا يلحق أقصاه أدناه، إما أن اخترت من بني أسد أشرفها بيتا وأعلاها في بناء المكرمات صوتا، فقدناه إليك بنسعه2 يذهب مع شفرات حسامك فيقال: رجل امتحن بهلك عزيز، فلم تستل سخيمته3 إلا بتمكينه من الانتقام، أو فداء بما يروح من بني أسد من نعمها، فهي ألوف تجاوز الحسبة، فكان ذلك فداء رجعت به القضب إلى أجفانها4، لم يردده تسليط الإحن على البراء5، وإما أن توادعنا حتى تضع الحوامل فنسدل الأزر، ونعقد الخمر فوق الرايات.\nفبكى امرؤ القيس ساعة ثم رفع رأسه فقال: لقد علمت العرب أن لا كفء لحجر في دم، وإني لن أعتاض به جملا أو ناقة، فأكتسب بذلك سبة الأبد وفت العضد. وأما النظرة، فقد أوجبتها الأجنة في بطون أمهاتها، ولن أكون لعطبها سببا، وستعرفون طلائع كندة، من بعد ذلك، تحمل القلوب حنقا، وفوق الأسنة علقا6.\nإذا جالت الخيل في مأزق ... تدافع فيه المنايا النفوسا\nأتقيمون أم تنصرفون؟ قالوا: بل ننصرف بأسوأ الاختيار، وأبلى الاجترار1، لمكروه وأذية وحرب وبلية، ثم نهضوا عنه وقبيصة يقول متمثلا:\nلعلك أن تستوخم الموت، إن غدت ... كتائبنا في مأزق الموت، تمطر2\nفقال امرؤ القيس: لا والله لا استوخمه، فرويدا ينكشف لك دجاها عن فرسان كندة وكتائب حمير، ولقد كان ذكر غير هذا أولى بي إذ كنت نازلا بربعي، ولكنك قلت، فأجبت.\nفقال قبيصة: ما نتوقع فوق قدر المعاتبة والإعتاب.\nقال امرؤ القيس: فهو ذاك."},{"id":"muallaqat:11","bookId":"muallaqat","type":"section","seq":11,"chapter":"مدخل","title":"إيقاعه ببني أسد","page":"ج1 ص25","text":"ثم ارتحل امرؤ القيس حتى نزل بكرا وتغلب، وعليهم إخوته شرحبيل وسلمة، فسألهم النصر على بني أسد. ثم بعث عليهم فنذروا بالعيون3، ولجئوا إلى بني كنانة وكان الذي أنذرهم بهم علباء بن الحارث. فلما كان الليل قال لهم علباء: يا معشر بني أسد تعلمون والله أن عيون امرئ القيس قد أتتكم ورجعت إليه بخبركم، فارحلوا بليل ولا تعلموا بني كنانة ففعلوا.\nوأقبل امرؤ القيس بمن معه من بكر وتغلب، حتى انتهى إلى بني كنانة، وهو يحسبهم بني أسد، فوضع السلاح فيهم وقال: يا لثارات الملك! يا لثارات الهمام! فخرجت إليه عجوز من بني كنانة فقالت: أبيت اللعن لسنا لك بثأر، نحن من كنانة فدونك ثأرك، فاطلبهم فإن القوم قد ساروا بالأمس.\nفتبع بني أسد ففاتوه ليلتهم فقال في ذلك:\nألا يا لهف هند إثر قوم ... هم كانوا الشفاء، فلم يصابوا1\nوقاهم جدهم ببني أبيهم ... وبالأشقين ما كان العقاب2\nوأفلتهن علباء جريضا ... ولو أدركنه صفر الوطاب3\nثم سار وراء بني أسد سيرا حثيثا إلى أن أدركهم، وقد تقطعت خيله، وقطع أعناقهم العطش، وبنو أسد جامون4 على الماء. فنهد إليهم5، فقاتلهم حتى كثرت الجرحى والقتلى فيهم، وحجز الليل بينهم. وهربت بنو أسد. فلما أصبحت بكر وتغلب أبوا أن يتبعوه وقالوا له: قد أصبت ثأرك.\nقال: والله ما فعلت ولا أصبت من بني كاهل، ولا من غيرهم من بني أسد أحدا. قالوا: بلى ولكنك رجل مشئوم. وكرهوا قتالهم بني كنانة وانصرفوا عنه."},{"id":"muallaqat:12","bookId":"muallaqat","type":"section","seq":12,"chapter":"مدخل","title":"استنصاره اليمن","page":"ج1 ص26","text":"فلما امتنعت بكر بن وائل وتغلب من اتباع بني أسد، خرج من فوره ذلك إلى اليمن فاستنصر أزد شنوءة، فأبوا أن ينصروه وقالوا: إخواننا وجيراننا فنزل بقيل يدعى مرثد الخير بن ذي جدن الحميري وكانت بينهما قرابة، فاستنصره واستمده على بني أسد، فأمده بخمسمائة رجل من حمير. ومات مرثد قبل رحيل امرئ القيس بهم وقام بالمملكة بعده رجل من حمير يقال له: قرمل بن الحميم، وكانت أمه سوداء، فردد امرأ القيس وطول عليه حتى هم بالانصراف وقال:\nوإذ نحن ندعو مرثد الخير ربنا ... وإذ نحن لا ندعى عبيدا لقرمل\nفأنفذ له ذلك الجيش. وتبعه شذاذ من العرب واستأجر من القبائل رجالا فسار بهم إلى بني أسد، ومر بتبالة وبها للعرب صنم تعظمه يقال له ذو الخلصة. فاستقسم عنده بقداحه وهي ثلاثة: الآمر، والناهي، والمتربص، فأجالها، فخرج الناهي، ثم أجالها فخرج الناهي. ثم أجالها، فخرج الناهي فجمعها وكسرها وضرب بها وجه الصنم وقال: ويحك لو أبوك قتل ما عقتني. ثم خرج فظفر ببني أسد، وقال في نيله منهم ما أراد من ثأره، أبياتا مطلعها:\nيا دار ماوية بالحائل ... فالسهب فالخبتين من عاقل"},{"id":"muallaqat:13","bookId":"muallaqat","type":"section","seq":13,"chapter":"مدخل","title":"إلحاح المنذر في طلبه","page":"ج1 ص27","text":"وألح المنذر في طلب امرئ القيس ووجه الجيوش في طلبه من إياد وبهراء وتنوخ، ولم تكن لهم به طاقة. فأمدهم أنوشروان بجيش من الأساورة1، فسرحهم في طلبه، وتفرق حمير ومن كان مع امرئ القيس، فنجا في عصبة من بني آكل المرار، حتى نزل بالحرث بن شهاب من بني يربوع بن حنظلة ومعه أدرع خمس: الفضفاضة، والضافية، والمحصنة والخريق وأم الذيول2 كن لبني آكل المرار يتوارثونها ملكا عن ملك. فما لبثوا عند الحرث بن شهاب حتى بعث إليه المنذر مائة من أصحابه يوعده بالحرب إن لم يسلم إليه بني آكل المرار، فأسلمهم ونجا امرؤ القيس ومعه يزيد بن معاوية بن الحرث وبنته هند -أي: بنت امرئ القيس- والأدرع والسلاح ومال كان بقي معه."},{"id":"muallaqat:14","bookId":"muallaqat","type":"section","seq":14,"chapter":"مدخل","title":"تنقله في القبائل","page":"ج1 ص27","text":"خرج امرؤ القيس على وجهه، وأقبل على فرسه الشقراء لاجئا إلى ابن عمته عمرو بن المنذر، وأمه هند بنت عمرو بن حجر بن آكل المرار، وذلك بعد قتل أبيه وأعمامه وتفرق ملك أهل بيته، وكان عمرو يومئذ خليفة لأبيه المنذر ببقة، وهي بين\nالأنبار، وهيت؛ فمدحه وذكر صهره ورحمه، وأنه قد تعلق بحباله، ولجأ إليه فأجاره عمرو ومكث عنده زمانا. ثم بلغ المنذر مكانه عند، فطلبه وأنذره عمرو، فهرب إلى هانئ بن مسعود بن عامر أحد رؤساء بني شيبان. فاستجاره فلم يجره وقال له: أنا في دين الملك. فأتى سعد بن ضباب الإيادي سيد قومه، فأجاره وكان سعد من أنسبائه، فقال يمدح سعدا، ويهجو ابن مسعود -وكان أفوه1 شاخص الأسنان- بقصيدة مطلعها:\nلعمرك ما قلبي إلى أهله بحر ... ولا مقصر يوما فيأتيني بقر\nثم تحول عن سعد بن ضباب فوقع في أرض طيئ فنزل برجل من بني جديلة يقال له المعلى بن تيم من بني ثعلبة فأجاره من المنذر، فقال فيه أبياتا مطلعها:\nكأني إذ نزلت على المعلى ... نزلت على البواذخ من شمام\nقالوا: فلبث عنده واتخذ إبلا هناك، فإذا قوم من بني جديلة يقال لهم بنو زيد، فطردوا الإبل. وكانت لامرئ القيس رواحل مقيدة عند البيوت خوفا من أن يدهمه أمر ليسبق عليهن. فخرج حينئذ فنزل ببني نبهان من طيئ. فخرج نفر منهم فركبوا الرواحل ليطلبوا له الإبل فأخذتهن جديلة فرجعوا إليه بلا شيء، فقال في ذلك قصيدة مطلعها:\nدع عنك نهبا صيح في حجراته ... ولكن حديثا ما حديث الرواحل\nففرقت عليه بنو نبهان فرقا من معزى يحلبها، فقال أبياتا مطلعها:\nألا إلا تكن إبل فمعزى ... كأن قرون جلتها العصي"},{"id":"muallaqat:15","bookId":"muallaqat","type":"section","seq":15,"chapter":"مدخل","title":"زواجه في بني طي","page":"ج1 ص28","text":"ئ:\nوبينا كان امرؤ القيس عند بني طيئ، زوجوه منهم أم جندب، إلا أنه كان مفركا2 وبقي عندهم ما شاء الله."},{"id":"muallaqat:16","bookId":"muallaqat","type":"section","seq":16,"chapter":"مدخل","title":"ذهابه إلى السموأل","page":"ج1 ص28","text":"بعد أن طلق امرؤ القيس أم جندب لتفضيلها شعر علقمة بن عبدة التيمي على شعره كما سيأتي في مكانه خرج من عند طيئ فنزل بعامر بن جوين، واتخذ عنده إبلا، وعامر يومئذ أحد الخلعاء الفتاك1، قد تبرأ قومه من جرائره2، فكان عنده ما شاء الله ثم هم أن يغلبه على أهله وماله، ففطن امرؤ القيس بشعر كان عامر ينطق به وهو قوله:\nفكم بالسعيد من هجان مؤبله ... تسير صحاحا، ذات قيد، ومرسله3\nأردت بها فتكا فلم أرتض له ... ونهنهت نفسي بعدما كدت أفعله4\nوكان عامر أيضا يقول الشعر ويعرض بهند بنت امرئ القيس.\nقالوا: فلما عرف امرؤ القيس ذلك منه خافه على أهله وماله، فتغفله وانتقل إلى رجل من بني ثعل يقال له حارثة بن مر، فاستجاره. فوقعت الحرب بين عامر وبين الثعلي، فكانت في ذلك أمور كثيرة.\nقال دارم بن عقال في خبره: فلما وقعت الحرب بين طيئ من أجله خرج من عندهم فنزل برجل من بني فزارة يقال له عمرو بن جابر بن مازن فطلب منه الجوار حتى يرى ذات غيبه، فقال له الفزاري: يابن حجر إني أراك في خلل من قومك, وأنا أنفس بمثلك من أهل الشرف. وقد كدت بالأمس تؤكل في دار طيئ وأهل البادية أهل بر لا أهل حصون تمنعهم، وبينك وبين اليمن ذؤبان من قيس، أفلا أدلك على بلد تلجأ إليه فقد جئت قيصر وجئت النعمان، فلم أر لضعيف نازل ولا لمجتهد مثله ولا مثل صاحبه.\nقال: من هو وأين منزله؟\nقال: السموأل بتيماء وسوف أضرب لك مثله: هو يمنع ضعفك حتى ترى ذات غيبك. وهو في حصن حصين وحسب كبير.\nفقال له امرؤ القيس: وكيف لي به؟\nقال: أوصلك إلى من يوصلك إليه.\nفصحبه إلى رجل من بني فزارة يقال له الربيع بن ضبع الفزاري ممن يأتي السموأل، فيحمله ويعطيه.\nثم مضى القوم حتى قدموا على السموأل، فأنشده امرؤ القيس شعرا وكان السموأل يحب الشعر فعرف له حقه، فأنزل هندا ابنته في قبة أدم، وأنزل القوم في مجلس له براح1، فكان عنده ما شاء الله."},{"id":"muallaqat:17","bookId":"muallaqat","type":"section","seq":17,"chapter":"مدخل","title":"أسطورة الحلة المسمومة وموته","page":"ج1 ص30","text":"ثم إنه طلب إليه أن يكتب له إلى الحارث بن أبي شمر الغساني بالشام، ليوصله إلى قيصر، ثم استودعه هندا والأدرع والمال، وأقام معها يزيد بن الحارث بن معاوية ابن عمه، ومضى حتى انتهى إلى قيصر. فقبله وأكرمه وكانت له عنده منزلة، فاندس رجل من بني أسد يقال له الطماح، وكان امرؤ القيس قتل أخا له من بني أسد، حتى أتى بلاد الروم فأقام مستخفيا. ثم إن قيصر منحه جيشا كثيفا وفيهم جماعة من أبناء الملوك. فلما فصل، قال لقيصر، قوم من أصحابه: إن العرب قوم غدر ولا نأمن أن يظفر هذا بما يريد ثم يغزوك بمن بعثت معه.\nوقال ابن الكلبي: بل قال له الطماح: إن امرأ القيس غوي فاجر. وإنه لما انصرف عنك بالجيش ذكر أنه كان يراسل ابنتك، وهو قائل في ذلك أشعارا يشهرها بها في العرب، فيفضحها ويفضحك. فبعث إليه حينئذ بحلة وشي مسمومة منسوجة بالذهب وقال له: إني أرسلت إليك بحلتي التي كنت ألبسها تكرمة لك، فإذا وصلت إليك فالبسها باليمن والبركة، واكتب إلي بخبرك من منزل منزل.\nفلما وصلت إليه اشتد سروره بها، ولبسها في يوم صائف، فتناثر لحمه، وتفطر جسده، وكان يحمله جابر بن حنين التغلبي، فلذلك سمي ذا القروح كما سمي بالملك\nالضليل لتشرده، في تنقله من قبيلة إلى أخرى، وقال في ذلك قصيدة مطلعها:\nتأوبني دائي القديم فغلسا ... أحاذر أن يرتد دائي فأنكسا\nقال: فلما صار إلى بلدة من بلاد الروم تدعى أنقرة احتضر بها فقال:\nرب طعنة مثعنجرة ... وجفنة متحيرة1\nوقصيدة متخيرة ... تبقى غدا في أنقرة\nورأى قبر امرأة من أبناء الملوك ماتت هناك فدفنت في سفح جبل يقال له عسيب، فسأل عنها فأخبر بقصتها فقال:\nأجارتنا إن المزار قريب ... وإني مقيم ما أقام عسيب\nأجارتنا إن غريبان ههنا ... وكل غريب للغريب نسيب\nثم مات فدفن إلى جنب المرأة فقبره هناك."},{"id":"muallaqat:18","bookId":"muallaqat","type":"section","seq":18,"chapter":"مدخل","title":"امرؤ القيس في تواريخ الروم","page":"ج1 ص31","text":"وقد جاء ذكر امرئ القيس في تواريخ الروم: مثل نونوز وبركوب وغيرهما، وهم يسمونه قيسا. وقد ذكروا أنه قبل وروده على قيصر يوستينيانس، أرسل إليه وفدا يطلب منه النجدة على بني أسد وعلى المنذر ملك العراق، وكان مع الوفد ابنه معاوية، سيره امرؤ القيس إلى قيصر ليبقى عنده كرهن، فكتب قيصر إلى النجاشي يأمره أن يجند الجنود ويسير إلى اليمن ويعيد الملك لصاحبه. ولعل هذا الوفد أرسله امرؤ القيس لما كان عند بني طيئ. وطال عندهم مكثه.\nثم أخبر المؤرخون المومأ إليهم أن امرأ القيس لم يلبث أن سار بنفسه إلى قسطنطينية فرغبه قيصر ووعده."},{"id":"muallaqat:19","bookId":"muallaqat","type":"section","seq":19,"chapter":"مدخل","title":"موته بالجدري","page":"ج1 ص31","text":"وقد ذكر نونوز المؤرخ أن يوستينيانس قلده إمرة فلسطين. إلا أنه لم يسع في\nإصلاح أمره وإعادة ملكه، فضجر امرؤ القيس وعاد إلى بلده، وكانت وفاته نحو سنة 565م. أصابه مرض كالجدري في طريقه كان سبب موته.\nوذكر في كتاب قديم مخطوط أن ملك قسطنطينية لما بلغه وفاة امرئ القيس أمر بأن ينحت له تمثال وينصب على ضريحه. ففعلوا وكان تمثال امرئ القيس هناك إلى أيام المأمون. وقد شاهده هذا الخليفة عند مروره هناك لما دخل بلاد الروم ليغزو الصائفة."},{"id":"muallaqat:20","bookId":"muallaqat","type":"section","seq":20,"chapter":"مدخل","title":"وفاء السموأل","page":"ج1 ص32","text":"ولما مات امرؤ القيس جاء الملك الحارث بن أبي شمر الغساني المعروف بالأعرج إلى السموأل، وقيل: بل كان الحارث بن ظالم. فطلب منه دروع امرئ القيس وأسلحته، فأبى السموأل، وتحصن بحصنه فأخذ الحارث ابنا له وناداه: إما أن تسلم الأدرع لي، وإما قتلت ولدك. فأبى أن يسلم الأدرع، فضرب وسط الغلام بالسيف فقطعه وأبوه يراه وانصرف. ثم جاء السموأل إلى ورثة امرئ القيس وسلمهم الأدرع فضرب به المثل في الوفاء."},{"id":"muallaqat:21","bookId":"muallaqat","type":"section","seq":21,"chapter":"مدخل","title":"شاعرية امرئ القيس","page":"ج1 ص32","text":"امرؤ القيس من فحول شعراء الجاهلية يعد من المقدمين بين ذوي الطبقة الأولى وفي شعره رقة اللفظ وجودة السبك وبلاغة المعاني، سبق الشعراء إلى أشياء ابتدعها واستحسنها العرب واتبعته عليها الشعراء كوقوفه واستيقافه صحبه في الديار ورقة النسيب، وقرب المأخذ وجودة التشبيه وتفننه فيه، ودقة الوصف، وبراعته فيه وما في وصفه من حياة وحركة، وفي شعره من رمز وتلميح ومن موافقة الألفاظ للمعاني.\nقيل: سأل العباس بن عبد المطلب عمر بن الخطاب عن الشعراء وأميرهم فقال: امرؤ القيس سابقهم خسف1 لهم عين الشعر فافتقر عن معان عور أصح بصر2.\nوفضله الإمام علي بأن قال: رأيت امرأ القيس أحسن الشعراء نادرة وأسبقهم بادرة وإنه لم يقل لرغبة ولا لرهبة.\nوقيل: إن امرأ القيس لم يسبق الشعراء؛ لأنه قال ما لم يقولوا، ولكنه سبق إلى أشياء فاستحسنها الشعراء واتبعوه فيه؛ لأنه أول من لطف المعاني ومن استوقف على الطلول وقرب مآخذ الكلام فقيد الأوابد وأجاد الاستعارة والتشبيه، منها ذكر الطلول والالتفات إلى الأحباب والتفنن في الأوصاف، وقد ترك امرؤ القيس مذهبا شعريا هو الوقوف على الأطلال والبكاء عليها، سار عليه الشعراء من بعده."},{"id":"muallaqat:22","bookId":"muallaqat","type":"section","seq":22,"chapter":"مدخل","title":"1- قفا نبك من ذكرى حبيب ومنزل","page":"ج1 ص33","text":"قفا نبك من ذكرى حبيب ومنزل ... بسقط اللوى بين الدخول فحومل\nقيل: خاطب صاحبيه، وقيل: بل خاطب واحدا وأخرج الكلام مخرج الخطاب مع الاثنين؛ لأن العرب من عادتهم إجراء خطاب الاثنين على الواحد والجمع، فمن ذلك قول الشاعر سويد بن كراع العكلي: [الطويل] :\nفإن تزجراني يا بن عفان أنزجر ... وإن ترعياني أحم عرضا ممنعا\nخاطب الواحد خطاب الاثنين، وإنما فعلت العرب ذلك لأن الرجل يكون أدنى أعوانه اثنين: راعي إبله وراعي غنمه، وكذلك الرفقة أدنى ما تكون ثلاثة، فجرى خطاب الاثنين على الواحد لمرون ألسنتهم عليه، ويجوز أن يكون المراد به: قف قف، فإلحاق الألف أمارة دالة على أن المراد تكرير اللفظ كما قال أبو عثمان المازني في قوله تعالى: {قال رب ارجعون} [المؤمنون: 99] المراد منه: أرجعني أرجعني أرجعني، جعلت الواو علما مشعرا بأن المعنى تكرير اللفظ مرارا، وقيل: أراد قفن على جهة التأكيد فقلب النون ألفا في حال الوصل؛ لأن هذه النون تقلب ألفا في حال الوقف فحمل الوصف على الوقف، ألا ترى أنك لو وقفت على قوله تعالى: {لنسفعا} [العلق: 15] قلت: لنسفعا؟ ومنه قول الأعشى: [الطويل] :\nوصل على حين العشيات والضحى ... ولا تحمد المثرين والله فاحمدا\nأراد فاحمدن فقلب نون التأكيد ألفا، يقال بكى يبكي بكاء وبكى، ممدودا ومقصورا، أنشد ابن الأنباري لحسان بن ثابت شاهدا له: [الوافر] :\nبكت عيني وحق لها بكاها ... وما يغني البكاء ولا العويل\nفجمع بين اللغتين؛ السقط: منقطع الرمل حيث يستدق من طرفه، والسقط أيضا\nما يتطاير من النار، والسقط أيضا المولود لغير تمام، وفيه ثلاث لغات: سقط وسقط وسقط في هذه المعاني الثلاثة اللوى: رمل يعوج ويلتوي. الدخول وحومل: موضعان.\nيقول: قفا وأسعداني وأعيناني، أو قف وأسعدني على البكاء عند تذكري حبيبا فارقته ومنزلا خرجت منه، وذلك المنزل أو ذلك الحبيب أو ذلك البكاء بمنقطع الرمل المعوج بين هذين الموضعين."},{"id":"muallaqat:23","bookId":"muallaqat","type":"section","seq":23,"chapter":"مدخل","title":"2- فتوضح فالمقراة لم يعف رسمها","page":"ج1 ص35","text":"فتوضح فالمقراة لم يعف رسمها ... لما نسجتها من جنوب وشمأل\nتوضح والمقراة موضعان وسقط اللوي بين هذه المواضع الأربعة، قوله: لم يعف رسمه، أي لم ينمح أثرها. الرسم ما لصق بالأرض من آثار الدار مثل البعر والرماد وغيرهما. والجمع أرسم ورسوم، قوله: وشمأل فيها ست لغات: شمال وشمأل وشأمل وشمول وشمل وشمل. نسج الريحين: اختلافهما عليها وستر إحداهما إياها بالتراب وكشف الأخرى التراب عنها.\nيقول: لم ينمح ولم يذهب أثرها؛ لأنه إذا غطته إحدى الريحين بالتراب كشف الأخرى التراب عنها، وقيل: بل معناه لم يقتصر سبب محوها على نسج الريحين بل كان له أسباب منها هذا السبب ومر السنين وترادف الأمطار وغيرها، وقيل: بل معناه لم يعف رسم حبها من قلبي وإن نسجتها الريحان، والمعنيان الأولان أظهر من الثالث وقد ذكرها كلها أبو بكر ابن الأنباري."},{"id":"muallaqat:24","bookId":"muallaqat","type":"section","seq":24,"chapter":"مدخل","title":"3- ترى بعر الأرآم في عرصاتها","page":"ج1 ص35","text":"ترى بعر الأرآم في عرصاتها ... وقيعانها كأنه حب فلفل\nالأرآم: الظباء البيض الخالصة البياض، واحدها رئم، بالكسر، وهي تسكن الرمل. عرصات في \"المصباح\": عرصة الدار ساحتها، وهي البقعة الواسعة التي ليس فيها بناء والجمع عراص مثل كلب وكلاب، وعرصات مثل سجدة وسجدات وعن الثعالبي كل بقعة ليس فيها بناء فهي عرصة، وفي \"التهذيب\": وسميت ساحة الدار عرصة؛ لأن الصبيان يعرصون فيها أي: يلعبون ويمرحون. قيعان جمع قاع وهو المستوي من الأرض، وقيعة مثل القاع، وبعضهم يقول: هو جمع، وقاعة الدار ساحتها. الفلفل قال في القاموس: كهدهد وزبرج، حب هندي، ونسب الصاغاني،\nالكسر للعامة، وفي المصباح: الفلفل بضم الفاءين من الأبزار، قالوا: لا يجوز فيه الكسر.\nيقول: انظر بعينيك تر هذه الديار التي كانت مأهولة مأنوسة بهم خصبة الأرض، كيف غادرها أهلها وأقفرت من بعدهم أرضها وسكنت رملها الظباء، ونثرت في ساحاتها بعرها حتى تراه كأنه حب الفلفل في مستوى رحباتها. \"هذا الشرح ليس للزوزني\"."},{"id":"muallaqat:25","bookId":"muallaqat","type":"section","seq":25,"chapter":"مدخل","title":"4- كأني غداة البين يوم تحملوا","page":"ج1 ص36","text":"كأني غداة البين يوم تحملوا ... لدى سمرات الحي ناقف حنظل\nغداة في \"المصباح\": والغداة الضحوة، وهي مؤنثة قال ابن الأنباري: ولم يسمع تذكيرها، ولو حملها حامل على معنى أول النهار جاز له التذكير، والجمع غدوات. البين: الفرقة وهو المراد هنا، وفي \"القاموس\": البين يكون فرقة ووصلا، قال الشارح: بان يبين بينا وبينونة، وهو من الأضداد. اليوم: معروف، مقداره، من طلوع الشمس إلى غروبها، وقد يراد باليوم الوقت مطلقا، ومنه الحديث: \"تلك أيام الهرج\"، أي: وقته, ولا يختص بالنهار دون الليل. تحملوا واحتملوا بمعنى: أي ارتحلوا. لدى بمعنى عند. سمرات جمع سمرة، بضم الميم: من شجر الطلح. الحي: القبيلة من الأعراب، والجمع أحياء. نقف الحنظل: شقة عن الهبيد، وهو الحب، كالإنقاف والانتقاف، وهو، أي الحنظل، نقيف ومنقوف، وناقفه الذي يشقه.\nيقول: كأني عند سمرات الحي يوم رحيلهم ناقف حنظل، يريد وقف بعد رحيلهم في حيرة وقفة جاني الحنظلة ينقفها بظفره ليستخرج منها حبها، \"هذا الشرح ليس للزوزني\"."},{"id":"muallaqat:26","bookId":"muallaqat","type":"section","seq":26,"chapter":"مدخل","title":"5- وقوفا بها صحبي علي مطيهم","page":"ج1 ص36","text":"وقوفا بها صحبي علي مطيهم ... يقولون لا تهلك أسى وتجمل\nنصب وقوفا على الحال، يريد قفا نبك في حال وقف أصحابي مطيهم علي، والوقوف جمع واقف بمنزلة الشهود والركوع في جمع شاهد وراكع، الصحب: جمع صاحب، ويجمع الصاحب على الأصحاب والصحب والصحاب والصحابة والصحبة والصحبان، ثم يجمع الأصحاب على الأصاحيب أيضا ثم يخفف فيقال الأصاحب. المطي: المراكب، واحدتها مطية، وتجمع المطية على المطايا والمطي والمطيات،\nسميت مطية؛ لأنه يركب مطاها أي ظهرها، وقيل: بل هي مشتقة من المطو وهو المد في السير، يقال: مطاه يمطوه، فسميت به لأنها تمد في السير: نصب أسى؛ لأنه مفعول له.\nيقول: قد وقفوا علي أي: لأجلي أو على رأسي وأنا قاعد عند رواحلهم ومراكبهم، يقولون لي: لا تهلك من فرط الحزن وشدة الجزع وتجمل بالصبر، وتلخيص المعنى: أنهم وقفوا عليه رواحلهم يأمرونه بالصبر وينهونه عن الجزع."},{"id":"muallaqat:27","bookId":"muallaqat","type":"section","seq":27,"chapter":"مدخل","title":"6- وإن شفائي عبرة مهراقة","page":"ج1 ص37","text":"وإن شفائي عبرة مهراقة ... فهل عند رسم دارس من معول\nالمهراق والمراق: المصبوب، وقد أرقت الماء وهرقته وأهرقته أي صببته: المعول: المبكى، وقد أعول الرجل وعول إذا بكى رافعا صوته به، والمعول: المعتمد والمتكل عليه أيضا. العبرة: الدمع، وجمعها عبرات، وحكى \"ثعلب\" في جمعها العبر مثل بدرة وبدر.\nيقول: وإن برئي من دائي ومما أصابني وتخلصي مما دهمني يكون بدمع أصبه ثم قال: وهل من معتمد ومفزع عند رسم قد درس، أو هل موضع بكاء عند رسم دارس؟ وهذا استفهام يتضمن معنى الإنكار، والمعنى عند التحقيق: ولا طائل في البكاء في هذا الموضع؛ لأنه لا يرد حبيبا، ولا يجدي على صاحبه بخير، أو لا أحد يعول عليه ويفزع إليه في مثل هذا الموضع، وتلخيص المعنى: وإن مخلصي مما بي بكائي، ثم قال: ولا ينفع البكاء عند رسم دارس، أو ولا معتمد عند رسم دارس."},{"id":"muallaqat:28","bookId":"muallaqat","type":"section","seq":28,"chapter":"مدخل","title":"7- كدأبك من أم الحويرث قبلها","page":"ج1 ص37","text":"كدأبك من أم الحويرث قبلها ... وجارتها أم الرباب بمأسل\nالدأب والدأب، بتسكين الهمزة وفتحها: العادة، وأصلها متابعة العمل والجد في السعي، دأب يدأب دأبا ودئابا ودءوبا، وأدأبت السير: تابعته. مأسل، بفتح السين: جبل بعينه، ومأسل، بكسر السين: ماء بعينه والرواية فتح السين.\nيقول: عادتك في حب هذه كعادتك من تينك، أي: قلة حظك من وصال هذه ومعاناتك الوجد بها كقلة حظك من وصالهما، ومعاناتك الوجد بهما، قوله: قبلها أي: قبل هذه التي شغفت بها الآن."},{"id":"muallaqat:29","bookId":"muallaqat","type":"section","seq":29,"chapter":"مدخل","title":"8- إذا قامتا تضوع المسك منهما","page":"ج1 ص38","text":"إذا قامتا تضوع المسك منهما ... نسيم الصبا جاءت بريا القرنفل\nضاع الطيب وتضوع إذا انتشرت رائحته. الريا: الرائحة الطيبة.\nيقول: إذا قامت أم الحويرث وأم الرباب فاحت ريح المسك منهما كنسيم الصبا إذا جاءت بعرف القرنفل ونشره. شبه طيب رياهما بطيب نسيم هب على قرنفل وأتى برياه، ثم لما وصفهما بالجمال وطيب النشر وصف حاله بعد بعدهما."},{"id":"muallaqat:30","bookId":"muallaqat","type":"section","seq":30,"chapter":"مدخل","title":"9- ففاضت دموع العين مني صبابة","page":"ج1 ص38","text":"ففاضت دموع العين مني صبابة ... على النحر حتى بل دمعي محملي\nالصبابة: رقة الشوق، وقد صب الرجل يصب صبابة فهو صب، والأصل صبب فسكنت العين وأدغمت في اللام. المحمل: حمالة السيف، والجمع المحامل، والحمائل جمع الحمالة.\nيقول: فسالت دموع عيني من فرط وجدي بهما وشدة حنيني إليهما حتى بل دمعي حمالة سيفي. ونصب صبابة على أنه مفعول له كقولك: زرتك طمعا في برك، قال الله تعالى: {من الصواعق حذر الموت} [البقرة: 19] أي: لحذر الموت، وكذلك زرتك للطمع في برك، وفاضت دموع العين مني للصبابة."},{"id":"muallaqat:31","bookId":"muallaqat","type":"section","seq":31,"chapter":"مدخل","title":"10- ألا رب يوم لك منهن صالح","page":"ج1 ص38","text":"ألا رب يوم لك منهن صالح ... ولا سيما يوم بدارة جلجل\nفي رب لغات: وهي رب ورب ورب ورب ثم تلحق التاء فتقول ربة وربت، ورب موضوع في كلام العرب للتقليل وكم موضوع للتكثير، ثم ربما حملت رب على كم في المعنى فيراد بها التكثير، وربما حملت كم على رب في المعنى فيراد بها التقليل، ويروى: ألا رب يوم كان منهن صالح، والسي: المثل: يقال هما سيان أي مثلان. ويجوز في يوم الرفع والجر، فمن رفع جعل ما موصولة بمعنى الذي، والتقدير: ولا سي اليوم الذي هو بدارة جلجل، ومن خفض جعل ما زائدة، وخفضه بإضافة سي إليه فكأنه قال: ولا سي يوم أي ولا مثل يوم. دارة جلجل غدير بعينه. يقول: رب يوم فزت فيه بوصال النساء وظفرت بعيش صالح ناعم منهن ولا يوم من تلك الأيام مثل يوم دارة جلجل، يريد أن ذلك اليوم كان أحسن الأيام وأتمها، فأفادت لا سيما التفضيل والتخصيص."},{"id":"muallaqat:32","bookId":"muallaqat","type":"section","seq":32,"chapter":"مدخل","title":"11- ويوم عقرت للعذارى مطيتي","page":"ج1 ص39","text":"ويوم عقرت للعذارى مطيتي ... فيا عجبا من كورها المتحمل\nالعذراء من النساء: البكر التي لم تفتض، والجمع العذارى. الكور: الرحل بأداته، والجمع الأكوار والكيران؛ ويروى: من رحلها المتحمل، المتحمل: الحمل. فتح يوم مع كونه معطوفا على مجرور أو مرفوع وهو يوم أو يوم بدارة جلجل؛ لأنه بناه على الفتح لما أضافه إلى مبني وهو الفعل الماضي، وذلك قوله: عقرت، وقد يبنى المعرب إذا أضيف إلى مبني، ومنه قوله تعالى: {إنه لحق مثل ما أنكم تنطقون} [الذاريات: 23] ؛ فبنى مثل على الفتح مع كونه نعتا لمرفوع لما أضافه إلى ما وكانت مبنية، ومنه قراءة من قرأ: {ومن خزي يومئذ} [هود: 66] بنى يوم على الفتح لما أضافه إلى إذ وهي مبنية وإن كان مضافا إليه؛ ومثله قول النابغة الذبياني: [الطويل] :\nعلى حين عاتبت المشيب على الصبا ... فقلت ألما تصح والشيب وازع1\nبنى حين على الفتح لما أضافه إلى الفعل الماضي؛ فضل يوم دارة جلجل ويوم عقر مطيته للأبكار على سائر الأيام الصالحة التي فاز بها من حبائبه، ثم تعجب من حملهن رحل مطيته وأداته بعد عقرها واقتسامهن متاعه بعد ذلك. قوله: فيا عجبا، الألف فيه بدل من ياء الإضافة، وكان الأصل فيا عجبي، وياء الإضافة يجوز قلبها ألفا في النداء نحو يا غلاما في يا غلامي، فإن قيل: كيف نادى العجب وليس مما يعقل؟ قيل في جوابه: إن المنادى محذوف، والتقدير: يا هؤلاء أو يا قوم اشهدوا عجبي من كورها المتحمل فتعجبوا منه، فإنه قد جاوز المدى والغاية القصوى؛ وقيل: بل نادى العجب اتساعا ومجازا، فكأنه قال: يا عجبي تعال واحضر فإن هذا أو إن إتيانك وحضورك."},{"id":"muallaqat:33","bookId":"muallaqat","type":"section","seq":33,"chapter":"مدخل","title":"12- فظل العذارى يرتمين بلحمها","page":"ج1 ص39","text":"فظل العذارى يرتمين بلحمها ... وشحم كهداب الدمقس المفتل\nيقال: ظل زيد قائما إذا أتى عليه النهار وهو قائم، وبات زيد نائما إذا أتى عليه الليل وهو نائم، وطفق زيد يقرأ القرآن إذا أخذ فيه ليلا ونهارا. الهداب والهدب: اسمان لما استرسل من الشيء نحو ما استرسل من الأشفار من الشعر ومن أطراف\nالأثواب، الواحدة هدابة وهدبة، ويجمع الهدب على الأهدب. الدمقس والمدقس: الإبريسم1، وقيل: هو الأبيض منه خاصة.\nيقول: فجعلن يلقي بعضهن إلى بعض شواء المطية استطابة أو توسعا فيه طول نهارهن؛ وشبه شحمها بالإبريسم الذي أجيد فتله وبولغ فيه، وقيل هو القز. الشحم: السمن."},{"id":"muallaqat:34","bookId":"muallaqat","type":"section","seq":34,"chapter":"مدخل","title":"13- ويوم دخلت الخدر خدر عنيزة","page":"ج1 ص40","text":"ويوم دخلت الخدر خدر عنيزة ... فقالت لك الويلات إنك مرجلي\nالخدر: الهودج، والجمع الخدور، ويستعار للستر والحجلة2 وغيرهما، ومنه قولهم: خدرت الجارية، وجارية مخدرة أي: مقصورة في خدرها لا تبرز منه، ومنه قولهم: خدر الأسد يخدر خدرا وأخدر إخدارا إذا لزم عرينه؛ ومنه قول ليلى الأخيلية: [الطويل] :\nفتى كان أحيا من فتاة حيية ... وأشجع من ليث بخفان3 خادر\nوقول الشاعر: [الرجز] :\nكالأسد الورد غدا من مخدره\nوالمراد بالخدر في البيت الهودج. عنيزة: اسم عشيقته وهي ابنة عمه، وقيل: هو لقب لها واسمها فاطمة، وقيل: بل اسمها عنيزة وفاطمة غيرها. قوله: فقالت لك الويلات، أكثر الناس على أن هذا دعاء منها عليه، والويلات: جمع ويلة، والويلة والويل: شدة العذاب، وزعم بعضهم أنه دعاء منها له في معرض الدعاء عليه، والعرب تفعل ذلك صرفا لعين الكمال عن المدعو عليه. ومنه قولهم: قاتله الله ما أفصحه! ومنه قول جميل: [الطويل] :\nرمى الله في عيني بثنية بالقذى ... وفي الغر من أنيابها بالقوادح\nويقال: رجل الرجل يرجل رجلا فهو راجل، وأرجلته أنا صيرته راجلا. خدر\nعنيزة بدل من الخدر الأول، والمعنى: يوم دخلت خدر عنيزة، وهذا مثل قوله تعالى: {لعلي أبلغ الأسباب، أسباب السموات} [غافر: 36، 37] ومنه قول الشاعر: [البسيط] :\nيا تيم تيم عدي لا أبا لكمو ... لا يلفينكمو في سوأة1 عمر\nوصرف عنيزة لضرورة الشعر وهي لا تنصرف في غير الشعر للتأنيث والتعريف.\nيقول: ويوم دخلت هودج عنيزة فدعت علي أو دعت لي في معرض الدعاء علي، وقالت: إنك تصيرني راجلة لعقرك ظهر بعيري، يريد أن هذا اليوم كان من محاسن الأيام الصالحة التي نلتها منهن أيضا."},{"id":"muallaqat:35","bookId":"muallaqat","type":"section","seq":35,"chapter":"مدخل","title":"14- تقول وقد مال الغبيط بنا معا","page":"ج1 ص41","text":"تقول وقد مال الغبيط بنا معا ... عقرت بعيري يا امرأ القيس فانزل\nالغبيط: ضرب من الرحال، وقيل: بل ضرب من الهوادج، الباء في قوله: بنا للتعدية، وقد أمالنا الغبيط جميعا. عقرت بعيري أي: أدبرت ظهره، من قولهم: سرج معقر وعقر وعقرة يعقر الظهر. ومنه قولهم: كلب عقور، ولا يقال في ذي الروح إلا عقور.\nيقول: كانت هذه المرأة تقول لي في حال إمالة الهودج أو الرحل إيانا: قد أدبرت ظهر بعيري فانزل عن البعير."},{"id":"muallaqat:36","bookId":"muallaqat","type":"section","seq":36,"chapter":"مدخل","title":"15- فقلت لها سيري وأرخي زمامه","page":"ج1 ص41","text":"فقلت لها سيري وأرخي زمامه ... ولا تبعديني من جناك المعلل\nجعل العشيقة بمنزلة الشجرة، وجعل ما نال من عناقها وتقبيلها وشمها بمنزلة الثمرة لتناسب الكلام. المعلل: المكرر، من قولهم: عله يعله ويعله إذا كرر سقيه وعلله للتكثير والتكرير. المعلل: الملهي، من قولك: عللت الصبي بفاكهة أي ألهيته بها، وقد روي في البيت بكسر اللام وفتحها، والمعنى على ما ذكرنا.\nيقول: فقلت للعشيقة بعد أمرها إياي بالنزول سيري وأرخي زمام البعير ولا تبعديني مما أنال من عناقك وشمك وتقبيلك الذي يلهيني أو الذي أكرره، ويقال لمن\nعلى الدابة سار يسير كما قال للماشي كذلك؛ قال: سيري وهي راكبة. الجنى: اسم لما يجتني من الشجر، والجني المصدر، يقال: جنيت الثمرة واجتنيتها."},{"id":"muallaqat:37","bookId":"muallaqat","type":"section","seq":37,"chapter":"مدخل","title":"16- فمثلك حبلى قد طرقت ومرضع","page":"ج1 ص42","text":"فمثلك حبلى قد طرقت ومرضع ... فألهيتها عن ذي تمائم محول\nخفض فمثلك بإضمار رب، أراد فرب امرأة حبلى. الطروق: الإتيان ليلا، والفعل طرق يطرق. المرضع: التي لها ولد رضيع، إذا بنيت على الفعل أنثت فقيل: أرضعت فهي مرضعة، وإذا حملوها على أنها بمعنى ذات إرضاع أو ذات رضيع لم تلحقها تاء التأنيث، ومثلها حائض وطالق وحامل، لا فصل بين هذه الأسماء فيما ذكرنا، وإذا حملت على أنها من المنسوبات لم تلحقها علامة التأنيث، وإذا حملت على الفعل لحقتها علامة التأنيث، ومعنى المنسوب في هذا الباب أن يكون الاسم بمعنى ذي كذا أو ذات كذا، والاسم إذا كان من هذا القبيل عرته العرب من علامة التأنيث كما قالوا: امرأة لابن وتامر أي: ذات لبن وذات تمر، ورجل لابن تامر أي: ذو لبن وذو تمر، ومنه قوله تعالى: {السماء منفطر به} [المزمل: 18] نص الخليل على أن المعنى: السماء ذات انفطار به، لذلك تجرد منفطر عن علامة التأنيث. وقوله تعالى: {لا فارض ولا بكر عوان} [البقرة: 68] أي: لا ذات فرض، وتقول العرب: جمل ضامر وناقة ضامر، وجمل شائل1 وناقة شائل، ومنه قول الاعشى: [السريع] :\nعهدي بها في الحي قد سربلت ... بيضاء مثل المهرة الضامر\nأي: ذات الضمور، وقول الآخر: [مجزوء الكامل] :\nوغررتني وزعمت أنك ... لابن في الصيف تامر\nأي: ذات لبن وذات تمر؛ وقول الآخر: [الرجز] :\nورابعتني تحت ليل ضارب ... بساعد فعم وكف خاضب\nأي: ذات خضاب، وقال أيضا: [الرجز] :\nيا ليت أم العمر كانت صاحبي ... مكان من أمسى على الركائب\nأي ذات صحبتي، وأنشد النحويون: [الطويل] :\nوقد تخذت رجلي لدى جنب غرزها ... نسيفا كأفحوص القطاة المطرق1\nأي ذات الطريق، والمعول في هذا الباب على السماع إذ هو غير منقاد للقياس. لهيت عن الشيء ألهى عنه لهيا إذا شغلت عنه وسلوت، وألهيته إلهاء إذا شغلته. التميمة: العوذة2، والجمع التمائم. يقال: أحول الصبي إذا تم له حول فهو محول؛ ويروى: عن ذي تمائم مغيل؛ يقال: غالت المرأة ولدها تغيل غيلا وأغالت تغيل إغيالا إذا أرضعته وهي حبلى. ويروى: مرضع بالعطف على حبلى. ويروى: ومرضعا على تقدير طرقتها. ومرضعا تكون معطوفة على ضمير المفعول.\nيقول: فرب امرأة حبلى قد أتيتها ليلا ورب امرأة ذات رضيع أتيتها ليلا فشغلتها عن ولدها الذي علقت على العوذة وقد أتى عليه حول كامل، أو قد حبلت أمه بغيره فهي ترضعه على حبلها، وإنما خص الحبلى والمرضع؛ لأنهما أزهد النساء في الرجال وأقلهن شغفا بهم وحرصا عليهم، فقال: خدعت مثلهما مع اشتغالهما بأنفسهما فكيف تتخلصين مني؟ قوله: فمثلك، يريد به فرب امرأة مثل عنيزة في ميله إليها وحبه لها؛ لأن عنيزة في هذا الوقت كانت عذراء غير حبلى ولا مرضع."},{"id":"muallaqat:38","bookId":"muallaqat","type":"section","seq":38,"chapter":"مدخل","title":"17- إذا ما بكى من خلفها انصرفت له","page":"ج1 ص43","text":"إذا ما بكى من خلفها انصرفت له ... بشق وتحتي شقها لم يحول\nشق الشيء: نصفه. يقول: إذا ما بكى الصبي من خلف المرضع انصرفت إليه بنصفها الأعلى فأرضعته وأرضته وتحتي نصفها الأسفل لم تحوله عني، وصف غاية ميلها إليه وكلفها3 به حيث لم يشغلها عن مرامه ما يشغل الأمهات عن كل شيء."},{"id":"muallaqat:39","bookId":"muallaqat","type":"section","seq":39,"chapter":"مدخل","title":"18- ويوما على ظهر الكثيب تعذرت","page":"ج1 ص43","text":"ويوما على ظهر الكثيب تعذرت ... علي وآلت حلفة لم تحلل\nالكثيب: رمل كثير، والجمع أكثبة وكثب وكثبان. التعذر: التشدد والالتواء والإيلاء والائتلاء والتألي: الحلف، يقال: آلى وائتلى وتألى إذا حلف، واسم اليمين\nالألية والألوة والألوة معا، والحلف المصدر. والحلف بكسر اللام. الاسم. الحلفة: المرة. التحلل في اليمين: الاستثناء. نصب حلفة لأنها حلت محل الإيلاء كأنه قال: وآلت إيلاء والفعل يعمل فيما وافق مصدره في المعنى كعمله في مصدر نحو قولهم: إني لأشنؤه1 بغضا وإني لأبغضه كراهية. يقول: وقد تشددت العشيقة والتوت، وساءت عشرتها يوما على ظهر الكثيب المعروف، وحلفت حلفا لم تستثن فيه أنها تصارمني وتهاجرني، هذا، ويحتمل أن يكون صفة حال اتفقت له مع عنيزة، ويحتمل أنها اتفقت مع المرضع التي وصفها."},{"id":"muallaqat:40","bookId":"muallaqat","type":"section","seq":40,"chapter":"مدخل","title":"19- أفاطم مهلا بعض هذا التدلل","page":"ج1 ص44","text":"أفاطم مهلا بعض هذا التدلل ... وإن كنت قد أزمعت صرمي فأجملي\nمهلا: أي رفقا. الإدلال والتدليل: أي يثق الإنسان بحب غيره إياه فيؤذيه على حسب ثقته به، والاسم الدالة والدال والدلال. أزمعت الأمر وأزمعت عليه: وطنت نفسي عليه.\nيقول: يا فاطمة دعي بعض دلالك وإن كنت وطنت نفسك على فراقي فأجملي في الهجران. نصب بعض؛ لأن مهلا ينوب مناب دع. الصرم: المصدر، يقال: صرمت الرجل أصرمه صرما إذا قطعت كلامه، والصرم الاسم. فاطمة: اسم المرضع أو عنيزة، وعنيزة لقب لها فيما قيل."},{"id":"muallaqat:41","bookId":"muallaqat","type":"section","seq":41,"chapter":"مدخل","title":"20- أغرك مني أن حبك قاتلي","page":"ج1 ص44","text":"أغرك مني أن حبك قاتلي ... وأنك مهما تأمري القلب يفعل\nيقول: قد غرك مني كون حبك قاتلي وكون قلبي منقادا لك بحيث مهما أمرته بشيء فعله. وألف الاستفهام دخلت على هذا القول للتقرير لا للاستفهام والاستخبار، ومنه قول جرير: [الوافر] :\nألستم خير من ركب المطايا ... وأندى العالمين بطون راح\nيريد أنهم خير هؤلاء، وقيل: بل معناه قد غرك مني أنك علمت أن حبك مذللي، والقتل التذليل، وأنك تملكين فؤادك فمهما أمرت قلبك بشيء أسرع مرادك فتحسبين أني أملك عنان قلبي كما ملكت عنان قلبك حتى يسهل علي فراقك\nكما سهل عليك فراقي، ومن الناس من حمله على مقتضى الظاهر وقال: معنى البيت: أتوهمت وحسبت أن حبك يقتلني أو أنك مهما أمرت قلبي بشيء فعله؟ قال: يريد أن الأمر ليس على ما خيل إليك فإني مالك زمام قلبي، والوجه الأمثل هو الوجه الأول وهذا القول أرذل الأقوال، لأن مثل هذا الكلام لا يستحسن في النسيب بالحبيب."},{"id":"muallaqat:42","bookId":"muallaqat","type":"section","seq":42,"chapter":"مدخل","title":"21- وإن تك قد ساءتك مني خليقة","page":"ج1 ص45","text":"وإن تك قد ساءتك مني خليقة ... فسلي ثيابي من ثيابك تنسل\nمن الناس من جعل الثياب في هذا البيت بمعنى القلب، كما حملت الثياب على القلب في قول عنترة: [الكامل] :\nفشككت بالرمح الأصم ثيابه ... ليس الكريم على القنا بمحرم\nوقد حملت الثياب في قوله تعالى: {وثيابك فطهر} [المدثر: 4] على أن المراد به القلب، فالمعنى على هذا القول: إن ساءك خلق من أخلاقي وكرهت خصلة من خصالي فردي على قلبي أفارقك، ولا معنى على هذا القول: استخرجي قلبي من قلبك يفارقه. النسول: سقوط الريش والوبر والصوف والشعر، يقال: نسل ريش الطائر ينسل نسولا، واسم ما سقط النسيل والنسال؛ ومنهم من رواه تنسلي وجعل الانسلاء بمعنى التسلي، والرواية الأولى أولاهما بالصواب، ومن الناس من حمل الثياب في البيت على الثياب الملبوسة وقال: كنى بتباين الثياب وتباعدها عن تباعدهما، وقال: إن ساءك شيء من أخلاقي فاستخرجي ثيابي من ثيابك أي: ففارقيني وصارميني كما تحبين فإني لا أوثر إلا ما أثرت ولا أختار إلا ما اخترت لانقيادي لك وميلي إليك، فإذا آثرت فراقي آثرته وإن كان سبب هلاكي وجالب موتي."},{"id":"muallaqat:43","bookId":"muallaqat","type":"section","seq":43,"chapter":"مدخل","title":"22- وما ذرفت عيناك إلا لتضربي","page":"ج1 ص45","text":"وما ذرفت عيناك إلا لتضربي ... بسهميك في أعشار قلب مقتل\nذرف الدمع ذريفا وذرفانا وتذرافا إذا سال، ثم يقال: ذرفت [عينه] ، كما يقال: دمعت عينه، وللأئمة في البيت قولان، قال الأكثرون: استعار للحظ عينيها ودمعهما اسم السهم لتأثيرهما في القلوب وجرحهما إياها كما أن السهام تجرح الأجسام وتؤثر فيها. والأعشار من قولهم: برمة أعشار إذا كانت قطعا، ولا واحد لها من لفظها. المقتل: المذلل غاية التذليل، والقتل في الكلام التذليل، ومنه قولهم: قتلت الشراب إذا قللت غرب سورته بالمزاج، ومنه قول الأخطل: [الطويل] :\nفقلت اقتلوها عنكم بمزاجها ... وحب بها مقتولة حين تقتل\nوقال حسان: [الكامل] :\nإن التي ناولتني فرددتها ... قتلت قتلت فهاتها لم تقتل\nومنه: قتلت أرض جاهلها وقتل أرضا عالمها، ومنه قوله تعالى: {وما قتلوه يقينا} [النساء: 157] عند أكثر الأئمة: أي ما ذللوا قولهم بالعلم اليقين. وتلخيص المعنى على هذا القول: وما دمعت عيناك وما بكيت إلا لتصيدي قلبي بسهمي دمع عينيك وتجرحي قطع قلبي الذي ذللته بعشقك غاية التذليل، أي نكايتهما في قلبي نكاية السهم في المرمى، وقال آخرون: أراد بالسهمين المعلى والرقيب من سهام الميسر. والجزور1 يقسم على عشرة أجزاء، فللمعلى سبعة أجزاء وللرقيب ثلاثة أجزاء، فمن فاز بهذين القدحين فقد فاز بجميع الأجزاء وظفر بالجزور، وتلخيص المعنى على هذا القول: وما بكيت إلا لتملكي قلبي كله وتفوزي بجميع أعشاره وتذهبي بكله والأعشار على هذا القول جمع عشر؛ لأن أجزاء الجزور عشرة، والله أعلم."},{"id":"muallaqat:44","bookId":"muallaqat","type":"section","seq":44,"chapter":"مدخل","title":"23- وبيضة خدر لا يرام خباؤها","page":"ج1 ص46","text":"وبيضة خدر لا يرام خباؤها ... تمتعت من لهو بها غير معجل\nأي: ورب بيضة خدر، يعني: ورب امرأة لزمت خدرها، ثم شبهها بالبيض، والنساء يشبهن بالبيض من ثلاثة أوجه: أحدها بالصحة والسلامة عن الطمث2، ومنه قول الفرزذق: [الوافر] :\nخرجن إلي لم يطمثن قبلي ... وهن أصح من بيض النعام\nويروى: دفعن إلي، ويروى: برزن إلي؛ والثاني: في الصيانة والستر؛ لأن الطائر يصون بيضه ويحضنه، والثالث: في صفاء اللون ونقائه؛ لأن البيض يكون صافي اللون نقيه إذا كان تحت الطائر، وربما شبهت النساء ببيض النعام، وأريد أنهن بيض تشوب ألوانهن صفرة يسيرة وكذلك لون بيض النعام، ومنه قول ذي الرمة: [البسيط] :\nكأنها فضة قد مسها الذهب\nالروم: الطلب والفعل منه يروم: الخباء: البيت إذا كان من قطن أو وبر أو صوف أو شعر، والجمع الأخبية. التمتع: الانتفاع. وغير يروى بالنصب والجر فالجر على صفة لهو، والنصب على الحال من التاء في تمتعت.\nويقول: ورب امرأة كالبيض في سلامتها من الافتضاض، أو في الصون والستر أو في صفاء اللون ونقائه، أو في بياضها المشوب بصفرة يسيرة ملازمة خدرها غير خراجة ولاجة انتفعت باللهو بها على تمكث وتلبث لم أعجل عنها ولم أشغل عنها بغيرها."},{"id":"muallaqat:45","bookId":"muallaqat","type":"section","seq":45,"chapter":"مدخل","title":"24- تجاوزت أحراسا إليها ومعشرا","page":"ج1 ص47","text":"تجاوزت أحراسا إليها ومعشرا ... علي حراصا لو يسرون مقتلي\nالأحراس يجوز أن يكون جمع حارس بمنزلة صاحب وأصحاب وناصر وأنصار وشاهد وأشهاد، ويجوز أن يكون جمع حرس بمنزلة جبل وأجبال وحجر وأحجار، ثم يكون الحرس جمع حارس بمنزلة خادم وخدم وغائب وغيب وطالب وطلب وعابد وعبد. والمعشر: القوم. والجمع المعاشر. الحراص: جمع حريص، مثل ظراف وكرام ولئام في جمع ظريف وكريم ولئيم. الإسرار: الإظهار والإضمار جميعا؛ وهو من الأضداد، ويروى: لو يشرون مقتلي بالشين المعجمة وهو الإظهار لا غير.\nيقول: تجاوزت في ذهابي إليها وزيارتي إياها أهوالا كثيرة وقوما يحرسونها وقوما حراصا على قتلي لو قدروا عليه في خفية؛ لأنهم لا يجترئون على قتلي جهارا، أو حراصا على قتلي لو أمكنهم قتلي ظاهرا لينزجر ويرتدع غيري عن مثل صنيعي؛ وحمله على الأول أولى؛ لأنه كان ملكا والملوك لا يقدر على قتلهم علانية."},{"id":"muallaqat:46","bookId":"muallaqat","type":"section","seq":46,"chapter":"مدخل","title":"25- إذا ما الثريا في السماء تعرضت","page":"ج1 ص47","text":"إذا ما الثريا في السماء تعرضت ... تعرض أثناء الوشاح المفصل\nالتعرض: الاستقبال، والتعرض إبداء العرض، وهو الناحية، والتعرض الأخذ في الذهاب عرضا. الأثناء: النواحي، والأثناء: الأوساط، واحدها ثنى مثل عصى وثنى مثل معى وثني مثل نحي1، وكذلك الآناء بمعنى الأوقات والآلاء بمعنى النعم في واحدها. هذه اللغات الثلاث ذكرها كلها ابن الأنباري. المفصل: الذي فصل بين خرزه بالذهب أو غيره.\nيقول: تجاوزت إليها في وقت إبداء الثريا عرضها في السماء كإبداء الوشاح الذي فصل بين جواهره وخرزه بالذهب أو غيره عرضه.\nيقول: أتيتها عند رؤية نواحي كواكب الثريا في الأفق الشرقي، ثم شبه نواحيها بنواحي جواهر الوشاح، هذا أحسن الأقوال في تفسير البيت، ومنهم من قال: شبه كواكب الثرايا بجواهر الوشاح؛ لأن الثريا تأخذ وسط السماء كما أن الوشاح يأخذ وسط المرأة المتوشحة، ومنه من زعم أنه أراد الجوزاء فغلط وقال: الثريا لأن التعرض للجوزاء دون الثريا، وهو قول محمد بن سلام الجمحي، وقال بعضهم: تعرض الثريا أنها إذا بلغت كبد السماء في العرض ذاهبة ساعة كما أن الوشاح يقع مائلا إلى أحد شقي المتوشحة به."},{"id":"muallaqat:47","bookId":"muallaqat","type":"section","seq":47,"chapter":"مدخل","title":"26- فجئت وقد نضت لنوم ثيابها","page":"ج1 ص48","text":"فجئت وقد نضت لنوم ثيابها ... لدى الستر إلا لبسة المتفضل\nنضا الثياب ينضوها نضوا إذا خلعها، ونضاها ينضيها إذا أراد المبالغة، اللبسة: حالة اللابس وهيئة لبسه الثياب بمنزلة الجلسة والقعدة والركبة والردية والإزرة1. المتفضل: اللابس ثوبا واحدا إذا أراد الخفة في العمل والفضلة والفضل اسمان لذلك.\nيقول: أتيتها وقد خلعت ثيابها عند النوم غير ثوب واحد تنام فيه وقد وقفت عند الستر مترقبة ومنتظرة، وإنما خلعت الثياب لتري أهلها أنها تريد النوم."},{"id":"muallaqat:48","bookId":"muallaqat","type":"section","seq":48,"chapter":"مدخل","title":"27- فقالت","page":"ج1 ص48","text":"فقالت: يمين الله ما لك حيلة ... وما إن أرى عنك الغواية تنجلي\nاليمين: الحلف. الغواية والغي: الضلالة، والفعل: غوي يغوى غواية، ويروى العماية وهي العمى. الانجلاء: الانكشاف، وجلوته: كشفته فانجلى. الحيلة أصلها حولة فأبدلت الواو ياء لسكونها وانكسار ما قبلها. وإن في قوله وما إن زائدة، وهي تزاد مع ما النافية ومنه قول الشاعر: [الوافر]\nوما إن طبنا جبن ولكن ... منايانا ودولة آخرينا2\nيقول: فقالت الحبيبة: أحلف بالله ما لك حيلة، أي: ما لي لدفعك عني حيلة، وقيل: بل معناه ما لك حجة في أن تفضحني بطروقك إياي وزيارتك ليلا، يقال: ما له حيلة أي: ما له عذر وحجة، وما أرى ضلال العشق وعماه منكشفا عنك، تحرير المعنى أنها قالت: ما لي سبيل إلى دفعك أو ما لك عذر في زيارتي وما أراك نازعا عن هواك وغيك، ونصب يمين الله كقولهم: الله لأقومن، على إضمار الفعل، وقال الرواة: هذا أغنج بيت في الشعر."},{"id":"muallaqat:49","bookId":"muallaqat","type":"section","seq":49,"chapter":"مدخل","title":"28- خرجت بها أمشي تجر وراءنا","page":"ج1 ص49","text":"خرجت بها أمشي تجر وراءنا ... على أثرينا ذيل مرط مرحل\nخرجت بها أفادت الباء تعدي الفعل، والمعنى: أخرجتها من خدرها، الأثر والإثر واحد، وأما الأثر. بفتح الهمزة وسكون الثاء. فهو فرند السيف. ويروى: على إثرنا أذيال، والذيل يجمع على الأذيال والذيول. المرط عند العرب. كساء من خز أو مرعزى1 أو من صوف، وقد تسمى الملاءة مرطا أيضا، والجمع المروط. المرحل: المنقش بنقوش تشبه رحال الإبل، يقال: ثوب مرحل وفي هذا الثوب ترحيل.\nيقول: فأخرجتها من خدرها وهي تمشي وتجر مرطها على أثرنا لتعفي به آثار أقدامنا، والمرط كان موشي بأمثال الرحال، ويروى: نير مرط، والنير: علم الثوب."},{"id":"muallaqat:50","bookId":"muallaqat","type":"section","seq":50,"chapter":"مدخل","title":"29- فلما أجزنا ساحة الحي وانتحى","page":"ج1 ص49","text":"فلما أجزنا ساحة الحي وانتحى ... بنا بطن خبت ذي حقاف عقنقل\nيقال: أجزت المكان وجزته إذا قطعته إجازة وجوازا، الساحة تجمع على الساحات والساح والسوح مثل قارة وقارات وقار وقور. والقارة: الجبيل الصغير. الحي: القبيلة، والجمع الأحياء، وقد تسمى الحلة حيا. الانتحاء والتنحي والنحو: الاعتماد على الشيء، ذكره ابن الاعرابي. البطن: مكان مطمئن حوله أماكن مرتفعة والجمع أبطن وبطون وبطنان. الخبت: أرض مطمئنة. الحقف: رمل مشرف معوج، والجمع أحقاف وحقاف، ويروى ذي قفاف وهي جمع قف: وهو ما غلظ وارتفع من الأرض ولم يبلغ أن يكون جبلا. العقنقل: الرمل المنعقد المتلبد. وأصله من العقل وهو الشد وزعم أبو عبيدة وأكثر الكوفيين أن الواو في وانتحى مقحمة زائدة\nوهو عندهم جواب لما، وكذلك قولهم في الواو في قوله تعالى: {وناديناه أن يا إبراهيم} [الصافات: 104] والواو لا تقحم زائدة في جواب لما عند البصريين، والجواب يكون محذوفا في مثل هذا الموضع تقديره في هذا البيت: فلما كان كذا وكذا تنعمت وتمتعت بها، أو الجواب قوله هصرت، وفي الآية فازا وظفرا بما أحبا، وحذف جواب لما كثير في التنزيل وكلام العرب.\nيقول: فلما جاوزنا ساحة الحلة وخرجنا من بين البيوت وصرنا إلى أرض مطمئنة بين حقاف، يريد مكانا مطمئنا أحاطت به حقاف أو قفاف منعقدة؛ والعقنقل من صفة الخبث لذلك لم يؤنثه، ومنهم من جعله من صفة الحقاف وأحله محل الأسماء وعطله من علامة التأنيث لذلك. وقوله: انتحى بنا بطن خبت أسند الفعل إلى بطن خبت والفعل عند التحقيق لهما ولكنه ضرب من الاتساع في الكلام، والمعنى صرنا إلى مثل هذا المكان؛ وتلخيص المعنى: فلما خرجنا من مجمع بيوت القبيلة وصرنا إلى مثل هذا الموضع طاب حالنا وراق عيشنا."},{"id":"muallaqat:51","bookId":"muallaqat","type":"section","seq":51,"chapter":"مدخل","title":"30- هصرت بفودي رأسها فتمايلت","page":"ج1 ص50","text":"هصرت بفودي رأسها فتمايلت ... علي هضيم الكشح ريا المخلخل\nالهصر: الجذب والفعل هصر يهصر. الفودان جانبا الرأس. تمايلت أي: مالت. ويروى بغصني دومة، والدوم: شجر المقل1، واحدتها دومة، شبهها بشجرة الدوم وشبه ذؤابتيها2 بغصنين وجعل ما نال منها كالثمر الذي يجتنى من الشجر، ويروى إذا قلت هاتي ناوليني تمايلت، والنول والإنالة والتنويل: الإعطاء، ومنه قيل للعطية نوال. هضيم الكشح: ضامر الكشح، والكشح: منقطع الأضلاع، والجمع كشوح وأصل الهضم الكسر، والفعل هضم يهضم، وإنما قيل لضامر البطن هضيم الكشح؛ لأنه يدق بذلك الموضع من جسده فكأنه هضيم عن قرار الردف والجنبين والوركين. ريا: تأنيث الريان. المخلخل: موضع الخلخال من الساق، والمسور: موضع السوار من الذراع، والمقلد: موضع القلادة من العنق, والمقرط: موضع القرط من الأذن. عبر عن كثرة لحم الساقين وامتلائهما بالري. هصرت جواب لما من البيت\nالأول عن البصريين، وأما الرواية الثالثة وهي: إذا قلت فإن الجواب مضمر محذوف عن تلك الرواية على ما مر ذكره في البيت الذي قبله.\nيقول: لما خرجنا من الحلة وأمنا الرقباء جذبت ذؤابتيها إلي فطاوعتني فيما رمت منها ومالت علي مسعفة بطلبتي في حال ضمر كشحيها وامتلاء ساقيها باللحم، والتفسير على الرواية الثالثة: إذا طلبت منها ما أحببت وقلت: أعطيني سؤلي كان ما ذكرنا، ونصب هضيم الكشح على الحال ولم يقل هضيمة الكشح؛ لأن فعيلا إذا كان بمعنى مفعول لم تلحقه علامة التأنيث للفصل بين فعيل إذا كان بمعنى الفاعل وبين فعيل إذا كان بمعنى المفعول من قوله تعالى: {إن رحمة الله قريب من المحسنين} [الأعراف: 56] ."},{"id":"muallaqat:52","bookId":"muallaqat","type":"section","seq":52,"chapter":"مدخل","title":"31- مهفهفة بيضاء غير مفاضة","page":"ج1 ص51","text":"مهفهفة بيضاء غير مفاضة ... ترائبها مصقولة كالسجنجل\nالمهفهفة: اللطيفة الخصر الضامرة البطن. المفاضة: المرأة العظيمة البطن المسترخية اللحم. الترائب جمع التريبة: وهي موضع القلادة من الصدر. السقل والصقل، بالسين الصاد: إزالة الصدأ والدنس وغيرهما. والفعل منه سقل يسقل وصقل يصقل. السجنجل: المرآة، لغة رومية عربتها العرب، وقيل بل هو قطع الذهب والفضة.\nيقول: هي امرأة دقيقة الخصر ضامرة البطن غير عظيمة البطن ولا مسترخيته، وصدرها براق اللون متلألئ الصفاء كتلألؤ المرآة."},{"id":"muallaqat:53","bookId":"muallaqat","type":"section","seq":53,"chapter":"مدخل","title":"32- كبكر المقاناة البياض بصفرة","page":"ج1 ص51","text":"كبكر المقاناة البياض بصفرة ... غذاها نمير الماء غير المحلل\nالبكر من كل صنف: ما لم يسبقه مثله. المقاناة: الخلط يقال: قانيت بين الشيئين إذا خلطت أحدهما بالآخر، والمقاناة في البيت مصوغة للمفعول دون المصدر. النمير: الماء النامي في الجسد. المحلل ذكر أنه من الحلول، وذكر أنه من الحل، ثم إن للأئمة في تفسير البيت ثلاثة أقوال، أحدها: أن المعنى كبكر البيض التي قوني بياضها بصفرة، يعني بيض النعام وهي بيض تخالط بياضها صفرة يسيرة، شبه لون العشيقة بلون بيض النعام في أن في كل منهما بياضا خالطته صفرة، ثم رجع إلى صفتها فقال: غذاها نمير عذب لم يكثر حلول الناس عليه فيكدره ذلك، يريد أنه\nعذب صاف، وإنما شرط هذا؛ لأن الماء من أكثر الأشياء تأثيرا في الغذاء لفرط الحاجة إليه فإذا عذب وصفا حسن موقعه في غذاء شاربه؛ وتلخيص المعنى على هذا القول: إنها بيضاء تشوب بياضها صفرة وقد غذاها ماء نمير عذب صاف، والبياض الذي شابته صفرة أحسن ألوان النساء عند العرب.\nوالثاني: أن المعنى كبكر الصدفة التي خولط بياضها بصفرة، وأراد ببكرها درتها التي لم ير مثلها، ثم قال: قد غذا هذه الدرة ماء نمير وهي غير محللة لمن رامها؛ لأنها في قعر البحر لا تصل إليها الأيدي، وتلخيص المعنى على هذا القول: إنه شبهها في صفاء اللون ونقائه بدرة فريدة تضمنتها صدفة بيضاء شابت بياضها صفرة وكذلك لون الصدفة، ثم ذكر أن الدرة التي أشبهتها حصلت في ماء نمير لا تصل إليها أيدي طلابها، وإنما شرط النمير والدر لا يكون إلا في الماء الملح؛ لأن الملح له بمنزلة العذب لنا إذ صار سبب نمائه كما صار العذب سبب نمائنا.\nوالثالث: أنه أراد كبكر البردي1 التي شاب بياضها صفرة وقد غذا البردي ماء نمير لم يكثر حلول الناس عليه، وشرط ذلك ليسلم الماء عن الكدر وإذا كان كذلك لم يغير لون البردي، والتشبيه من حيث أن بياض العشيقة خالطته صفرة كما خالطته بياض البردي. ويروى البيت بنصب البياض وخفضه، وهما جيدان، بمنزلة قولهم: زيد الحسن الوجه، والحسن الوجه، بالخفض على الإضافة والنصب على التشبيه كقولهم: زيد الضارب الرجل."},{"id":"muallaqat:54","bookId":"muallaqat","type":"section","seq":54,"chapter":"مدخل","title":"33- تصد وتبدي عن أسيل وتتقي","page":"ج1 ص52","text":"تصد وتبدي عن أسيل وتتقي ... بناظرة من وحش وجرة مطفل\nالصد والصدود: الإعراض والصد أيضا الصرف والدفع، والفعل منه صد يصد، والإصداد الصرف أيضا. الإبداء: الإظهار. الأسالة: امتداد وطول في الخد وقد أسل أسالة فهو أسيل. الاتقاء: الحجز بين الشيئين، يقال: اتقيته بترس أي: جعلت الترس حاجزا بيني وبينه. وجرة: موضع، المطفل: التي لها طفل. الوحش: جمع وحشي مثل زنج وزنجي وروم ورومي.\nيقول: تعرض العشيقة عني وتظهر خدا أسيلا، وتجعل بيني وبينها عينا ناظرة من نواظر وحش هذا الموضع التي لها أطفال، شبهها في حسن عينيها بظبية مطفل أو بمهاة مطفل، وتلخيص المعنى: أنها تعرض عنا فتظهر في إعراضها خدا أسيلا وتسقبلنا بعين مثل عيون ظباء وجرة أو مهاها واللواتي لها أطفال، وخصهن لنظرهن إلى أولادهن بالعطف والشفقة وهي أحسن عيونا في تلك الحال منهن في سائر الأحوال. قوله: عن أسيل، أي عن خد أسيل، فحذف الموصوف لدلالة الصفة عليه كقوله: مررت بعاقل، أي: بإنسان عاقل، وقوله: من وحش وجرة، أي: من نواظر وحش وجرة، فحذف المضاف وأقام المضاف إليه مقامه كقوله تعالى: {واسأل القرية} [يوسف: 82] أي: أهل القرية."},{"id":"muallaqat:55","bookId":"muallaqat","type":"section","seq":55,"chapter":"مدخل","title":"34- وجيد كجيد الرئم ليس بفاحش","page":"ج1 ص53","text":"وجيد كجيد الرئم ليس بفاحش ... إذا هي نصته ولا بمعطل\nالرئم: الظبي الأبيض الخالص البياض، والجمع آرام. النص: الرفع، ومنه سمي ما تجلى عليه العروس منصة، ومنه النص في السير وهو حمل البعير على سير شديد، ونصصت الحديث أنصه نصا: رفعته. الفاحش: ما جاوز القدر المحمود من كل شيء.\nيقول: وتبدي عن عنق كعنق الظبي غير متجاوز قدره المحمود إذا ما رفعت عنقها، وهو غير معطل، عن الحلي، فشبه عنقها بعنق الظبية في حال رفعها عنقها، ثم ذكر أنه لا يشبه عنق الظبي في التعطل عن الحلي."},{"id":"muallaqat:56","bookId":"muallaqat","type":"section","seq":56,"chapter":"مدخل","title":"35- وفرع يزين المتن أسود فاحم","page":"ج1 ص53","text":"وفرع يزين المتن أسود فاحم ... أثيت كقنو النخلة المتعثكل\nالفرع: الشعر التام، والجمع فروع، ورجل أفرع وامرأة فرعاء. الفاحم: الشديد السواد، مشتق من الفحم، يقال: هو فاحم بين الفحومة. الأثيث: الكثير، والأثاثة: الكثرة، يقال: أث الشعر والنبت. القنو يجمع على الأقناء والقنوان. العثكول والعثكال قد يكونان بمعنى القنو وقد يكونان بمعنى قطعة من القنو1، والنخلة المتعثكلة: التي خرجت عثاكيلها أي: قنوانها.\nيقول: وتبدي عن شعر طويل تام يزين ظهرها إذا أرسلته عليه، ثم شبه ذؤابتيها بقنو نخلة أخرجت قنوانها، والذوائب تشبه بالعناقيد، والقنوان يراد به تجعدها وأثاثتها."},{"id":"muallaqat:57","bookId":"muallaqat","type":"section","seq":57,"chapter":"مدخل","title":"36- غدائره مستشزرات إلى العلا","page":"ج1 ص54","text":"غدائره مستشزرات إلى العلا ... تضل العقاص في مثنى ومرسل\nالغدائر: جمع الغديرة: وهي الخصلة من الشعر، الاستشزار: الارتفاع والرفع جميعا، فيكون الفعل منه مرة لازما ومرة متعديا، فمن روى مستشزرات بكسر الزاي جعله من اللازم، ومن روى بفتح الزاي جعله من المتعدي. العقيصة: الخصلة المجموعة من الشعر، والجمع عقص وعقائص، والفعل من الضلال والضلالة ضل يضل ويضل جميعا.\nيقول: ذوائبها وغدائرها مرفوعات أو مرتفعات إلى فوق، يراد به شدها على الرأس بخيوط، ثم قال: تغيب تعاقيصها في شعر مثنى وبعضه مرسل، أراد به وفور شعرها، والتعقيص التجعيد."},{"id":"muallaqat:58","bookId":"muallaqat","type":"section","seq":58,"chapter":"مدخل","title":"37- وكشح لطيف كالجديل مخصر","page":"ج1 ص54","text":"وكشح لطيف كالجديل مخصر ... وساق كأنبوب السقي المذلل\nالجديل: خطام1 يتخذ من الأدم، والجمع جدل. المخصر: الدقيق الوسط، ومنه نعل مخصرة. الأنبوب: ما بين العقدتين من القصب وغيره، والجمع الأنابيب السقي ههنا: بمعنى المسقي كالجريح بمعنى المجروح، والجني بمعنى المجني.\nيقول: وتبدي عن كشح ضامر يحكي في دقته خطاما متخذا من الأدم، وعن ساق يحكي في صفاء لونه أنابيب بردي بين نخل وقد ذللت بكثرة الحمل فأظلت أغصانها هذا البردي، شبه ضمور بطنها بمثل هذا الخطام، وشبه صفاء لون ساقها ببردي بين نخيل تظله أغصانها، وإنما شرط ذلك ليكون أصفى لونا وأنقى رونقا وتقدير قوله كأنبوب السقي كأنبوب النخل المسقي، ومنهم من جعل السقي نعتا للبردي أيضا؛ والمعنى على هذا القول: كأنبوب البردي المسقي المذلل بالإرواء."},{"id":"muallaqat:59","bookId":"muallaqat","type":"section","seq":59,"chapter":"مدخل","title":"38- وتضحي فتيت المسك فوق فراشها","page":"ج1 ص54","text":"وتضحي فتيت المسك فوق فراشها ... نؤوم الضحى لم تنتطق عن تفضل\nالإضحاء: مصادفة الضحى، وقد يكون بمعنى الصيرورة أيضا، ويقال أضحى زيد غنيا أي: صار ولا يراد به أنه صادف الضحى على صفة الغنى، ومنه قول عدي بن زيد:\nثم أضحوا كأنهم ورق جف ... فألوت به الصبا والدبور1\nأي صاروا. الفتيت والفتات: اسم لدقائق الشيء الحاصل بالفت. قوله: نؤوم الضحى، عطل نؤوما عن علامة التأنيث لأن فعولا إذا كان بمعنى الفاعل يستوي لفظ صفة المذكر والمؤنث فيه، يقال: رجل ظلوم وامرأة ظلوم ومنه قوله تعالى: {توبة نصوحا} [التحريم: 8] قوله: لم تنتطق عن تفضل، أي بعد تفضل كما يقال: استغنى فلان عن فقره أي: بعد فقره؛ والتفضل: لبس الفضلة، وهي ثوب واحد يلبس للخفة في العمل.\nيقول: تصادف العشيقة الضحى ودقائق المسك فوق فراشها الذي باتت عليه، وهي كثيرة النوم في وقت الضحى، ولا تشد وسطها بنطاق بعد لبسها ثوب المهنة، يريد أنها مخدومة منعمة تخدم، ولا تخدم، وتلخيص المعنى: أن فتات المسك يكثر على فراشها وأنها تكفى أمورها فلا تباشر عملا بنفسها. وصفها بالدعة والنعمة وخفض العيش وأن لها من يخدمها ويكفيها أمورها."},{"id":"muallaqat:60","bookId":"muallaqat","type":"section","seq":60,"chapter":"مدخل","title":"39- وتعطو برخص غير شثن كأنه","page":"ج1 ص55","text":"وتعطو برخص غير شثن كأنه ... أساريع ظبي أو مساويك إسحل\nالعطو: التناول والفعل عطا يعطو عطوا، والإعطاء المناولة، والتعاطي التناول، والمعاطاة الخدمة، والتعطية مثلها. الرخص: اللين الناعم. الشثن: الغليظ الكز2، وقد شن شثونة الأسروع واليسروع دود يكون في البقل3 والأماكن الندية، تشبه أنامل النساء به، والجمع الأساريع واليساريع. ظبي: موضع بعينه. المساويك جمع المسواك. الإسحل: شجرة تدق أغصانها في استواء، تشبه الأصابع بها في الدقة والاستواء.\nيقول: وتتناول الأشياء ببنان رخص لين ناعم غير غليظ ولا كز، كأن تلك الأنامل تشبه هذا الصنف من الدود أو هذا الضرب من المساويك وهو المتخذ من أغصان هذا الشجر المخصوص المعين."},{"id":"muallaqat:61","bookId":"muallaqat","type":"section","seq":61,"chapter":"مدخل","title":"40- تضيء الظلام بالعشاء كأنها","page":"ج1 ص56","text":"تضيء الظلام بالعشاء كأنها ... منارة ممسى راهب متبتل\nالإضاءة: قد يكون الفعل المشتق منها لازما وقد يكون متعديا، تقول: أضاء الله الصبح فأضاء، والضوء والضوء واحد، والفعل ضاء ضوءا، وهو لازم. المنارة: المسرجة، الجمع المناور والمنائر. الممسى: بمعنى: الإمساء والوقت جميعا؛ ومنه قول أمية: [البسيط] :\nالحمد لله ممسانا ومصبحنا ... بالخير صبحنا ربي ومسانا\nالراهب يجمع على الرهبان، مثل راكب وركبان وراع ورعيان، وقد يكون الرهبان واحد ويجمع حينئذ على الرهابنة والرهابين كما يجمع السلطان على السلاطنة والسلاطين، أنشد الفراء: [الرجز] :\nلو أبصرت رهبان دير في جبل ... لانحدر الرهبان يسعى ويصل\nجعل الرهبان واحدا، لذلك قال: يسعى، ولم يقل: يسعون. المتبتل: المنقطع إلى الله بنيته وعمله، والبتل: القطع، ومنه قيل: مريم البتول لانقطاعها عن الرجال واختصاصها بطاعة الله تعالى، فالتبتل إذن الانقطاع عن الخلق والاختصاص بطاعة الله تعالى ومنه قوله تعالى: {وتبتل إليه تبتيلا} [المزمل: 8] .\nيقول: تضيء العشيقة بنور وجهها ظلام الليل فكأنها مصباح راهب منقطع عن الناس، وخص مصباح الراهب؛ لأنه يوقده ليهتدي به عند الضلال فهو يضيئه أشد الإضاءة، يريد أن نور وجهها يغلب ظلام الليل كما أن نور مصباح الراهب يغلبه,"},{"id":"muallaqat:62","bookId":"muallaqat","type":"section","seq":62,"chapter":"مدخل","title":"41- إلى مثلها يرنو الحليم صبابة","page":"ج1 ص56","text":"إلى مثلها يرنو الحليم صبابة ... إذا ما اسبكرت بين درع ومجول\nالاسبكرار: الطول والامتداد. الدرع: هو قميص المرأة، وهو مذكر، ودرع الحديد مؤنثة، والجمع أدرع ودروع. المجول: ثوب تلبسه الجارية الصغيرة.\nيقول: إلى مثلها ينبغي أن ينظر العاقل كلفا بها وحنينا إليها إذا طال قدها\nوامتدت قامتها بين من تلبس الدرع وبين من تلبس المجول، أي بين اللواتي أدركن الحلم وبين اللواتي لم يدركن الحلم، يريد أنها طويلة القد مديدة القامة وهي بعد لم تدرك الحلم وقد ارتفعت عن سن الجواري الصغار، قوله: بين درع ومجول، تقديره: بين لابسة درع ولابسة مجول، فحذف المضاف وأقام المضاف إليه مقامه."},{"id":"muallaqat:63","bookId":"muallaqat","type":"section","seq":63,"chapter":"مدخل","title":"42- تسلت عمايات الرجال عن الصبا","page":"ج1 ص57","text":"تسلت عمايات الرجال عن الصبا ... وليس فؤادي عن هواك بمنسل\nسلا فلان عن حبيبه يسلو سلوا، وسلى يسلي سليا، وتسلى تسليا، وانسلى انسلاء أي زال حبه من قلبه أو زال حزنه. العماية والعمى واحد والفعل عمي يعمى. زعم أكثر الأئمة أن في البيت قلبا تقديره: تسلت الرجالات عن عمايات الصبا أي خرجوا من ظلماته وليس فؤادي بخارج من هواها.\nوزعم بعضهم أن عن في البيت بمعنى بعد، تقديره: انكشفت وبطلت ضلالات الرجال بعد مضي صباهم، وفؤادي بعد في ضلالة هواها، وتلخيص المعنى: أنه رغم أن عشق العشاق قد بطل وزال وعشقه إياها باق ثابت ولا يزول ولا يبطل."},{"id":"muallaqat:64","bookId":"muallaqat","type":"section","seq":64,"chapter":"مدخل","title":"43- ألا رب خصم فيك ألوى رددته","page":"ج1 ص57","text":"ألا رب خصم فيك ألوى رددته ... نصيح على تعذاله غير مؤتل\nالخصم لا يثنى ولا يجمع لا يؤنث في لغة شطر من العرب، ومنه قوله تعالى: {وهل أتاك نبأ الخصم إذ تسوروا المحراب} [ص: 21] ويثنى ويجمع في لغة الشطر الآخر من العرب، ويجمع على الخصام والخصوم. الألوى: الشديد الخصومة كأنه يلوي خصمه عن دعواه. النصيح: الناصح. التعذال والعذل والعذل: اللوم، والفعل عذل يعذله. الألو والائتلاء: التقصير، والفعل: ألا يألوا وائتلى يأتلي.\nيقول: ألا رب خصم شديد الخصومة كان ينصحني على فرط لومه إياي على هواك غير مقصر في النصيحة واللوم رددته ولم أنزجر عن هواك بعذله ونصحه. وتحرير المعنى أنه يخبرها ببلوغ حبه إياها الغاية القصوى، حتى أنه لا يرتدع عنه بردع ناصح ولا ينجع1 فيه لوم لائم، وتقدير لفظ البيت: ألا رب خصم ألوى نصيح على تعذاله غير مؤتل رددته."},{"id":"muallaqat:65","bookId":"muallaqat","type":"section","seq":65,"chapter":"مدخل","title":"44- وليل كموج البحر أرخى سدوله","page":"ج1 ص58","text":"وليل كموج البحر أرخى سدوله ... علي بأنواع الهموم ليبتلي\nشبه ظلام الليل في هوله وصعوبته ونكارة أمره بأمواج البحر. السدول: الستور، الواحد منها سدل. الإرخاء: إرسال الستر وغيره. الابتلاء: الاختبار. الهموم جمع الهم. بمعنى الحزن وبمعنى الهمة. الباء في قوله: بأنواع الهموم بمعنى مع.\nيقول: ورب ليل يحاكي أمواج البحر في توحشه ونكارة أمره وقد أرخى علي ستور ظلامه مع أنواع الأحزان، أو مع فنون الهم، ليختبرني أأصبر على ضروب الشدائد وفنون النوائب أم أجزع منها. لما أمعن في النسيب من أول القصيدة إلى هنا انتقل منه إلى التمدح بالصبر والجلد."},{"id":"muallaqat:66","bookId":"muallaqat","type":"section","seq":66,"chapter":"مدخل","title":"45- فقلت له لما تمطي بصلبه","page":"ج1 ص58","text":"فقلت له لما تمطي بصلبه ... وأردف أعجازا وناء بكلكل\nتمطى أي: تمدد، ويجوز أن يكون التمطي مأخوذا من المطا، وهو الظهر، فيكون التمطي مد الظهر، ويجوز أن يكون منقولا من التمطط فقلبت إحدى الطاءين ياء كما قالوا: تظني تظنيا والأصل تظنن تظننا، وقالوا: تقضى1 البازي تقضيا أي: تقضض تقضضا، والتمطط التفعل من المط، وهو المد. وفي الصلب ثلاث لغات مشهورة، وهي: الصلب، بضم الصاد وسكون اللام، والصلب بضمهما، والصلب بفتحهما؛ ومنه قول العجاج يصف جارية: [الرجز] :\nريا العظام فخمة المخدم ... في صلب مثل العنان المؤدم\nولغة عربية وهي الصالب، وقال العباس عم النبي -صلى الله عليه وسلم- يمدح النبي عليه السلام: [المنسرح] :\nتنقل من صالب إلى رحم ... إذا مضى عالم بدا طبق\nالإرداف: الإتباع والاتباع وهو بمعنى الأول ههنا. الأعجاز: المآخير، الواحد عجز وعجز وعجز. ناء: مقلوب نأى بمعنى بعد، كما قالوا: راء بمعنى رأى وشاء بمعنى شأى2. الكلكل: الصدر والجمع كلاكل. الباء في قوله ناء بكلكل.\nللتعدية، وكذلك هي في قوله: تمطى بصلبه، استعار لليل صلبا واستعار لطوله لفظ التمطي ليلائم الصلب واستعار لأوائله لفظ الكلكل ولمآخيره لفظ الأعجاز\nيقول: فقلت لليل لما مد صلبه يعني لما أفرط طوله، وأردف أعجازا يعني ازدادت مآخيره امتدادا وتطاولا، وناء بكلكل يعني أبعد صدره، أي: بعد العهد بأوله، وتلخيص المعنى: قلت لليل لما أفرط طوله وناءت أوائله وازدادت أواخره تطاولا، وطول الليل ينبئ عن مقاساة الأحزان والشدائد والسهر المتولد منها؛ لأن المغموم يستطيل ليله، والمسرور يستقصر ليله."},{"id":"muallaqat:67","bookId":"muallaqat","type":"section","seq":67,"chapter":"مدخل","title":"46- ألا أيها الليل الطويل ألا انجلي","page":"ج1 ص59","text":"ألا أيها الليل الطويل ألا انجلي ... بصبح وما الإصباح منك بأمثل\nالانجلاء: الانكشاف، يقال: جلوته فانجلى أي: كشفته فانكشف. الأمثل: الأفضل، والمثلى الفضلى، والأماثل الأفاضل.\nيقول: قلت له ألا أيها الليل الطويل انكشف وتنح بصبح، أي: ليزل ظلامك بضياء من الصبح، ثم قال: وليس الصبح بأفضل منك عندي لأني أقاسي الهموم نهارا كما أعانيها ليلا، أو لأن نهاري أظلم في عيني لازدحام الهموم علي حتى حكى الليل، وهذا إذا رويت: وما الإصباح منك بأمثل، وإن رويت: فيك بأفضل، كان المعنى وما الإصباح في جنبك أو في الإضافة إليك أفضل منك لما ذكرنا من المعنى لما ضجر بتطاول ليله خاطبه وسأله الانكشاف، وخطابه ما لا يعقل يدل على فرط الوله وشدة التحير، وإنما يستحسن هذا الضرب في النسيب والمراثي وما يوجب حزنا وكآبة ووجدا وصبابة."},{"id":"muallaqat:68","bookId":"muallaqat","type":"section","seq":68,"chapter":"مدخل","title":"47- فيا لك من ليل كأن نجومه","page":"ج1 ص59","text":"فيا لك من ليل كأن نجومه ... بأمراس كتان إلى صم جندل\nالأمراس جمع مرس: وهو الحبل، وقد يكون المرس جمع مرسة وهو الحبل أيضا، فتكون الأمراس حينئذ جمع الجمع، وقوله: بأمراس كتان، من إضافة البعض إلى الكل، أي: بأمراس من كتان، كقولهم: باب حديد، وخاتم فضة، وجبة خز. الأصم: الصلب، وتأنيثه الصماء، والجمع الصم. الجندل: الصخرة، والجمع جنادل.\nيقول مخاطبا الليل: فيا عجبا لك من ليل كأن نجومه شدت بحبال من الكتان إلى صخور صلاب، وذلك أنه استطال الليل فيقول: إن نجومه لا تزول من أماكنها ولا تغرب، فكأنها مشدودة بحبال إلى صخور صلبة، وإنما استطال الليل لمعاناته الهموم ومقاساته الأحزان فيه، وقوله: بأمراس كتان، يعني ربطت، فحذف الفعل لدلالة الكلام على حذفه؛ ومنه قول الشاعر: [الطويل] :\nمسنا من الآباء شيئا فكلنا ... إلى حسب في قومه غير واضع\nيعني فكلنا يعتزي أو ينتمي أو ينتسب إلى حسب، فحذف الفعل لدلالة باقي الكلام عليه، ويروى: كأن نجومه بكل مغار الفتل شدت بيذبل، وهذا أعرف الروايتين وأسيرهما. الإغارة: إحكام الفتل. يذبل: جبل بعينه.\nيقول: كأن نجومه قد شدت إلى يذبل بكل حبل محكم الفتل."},{"id":"muallaqat:69","bookId":"muallaqat","type":"section","seq":69,"chapter":"مدخل","title":"48- وقربة أقوام جعلت عصامها","page":"ج1 ص60","text":"وقربة أقوام جعلت عصامها ... على كاهل مني ذلول مرحل\nلم يرو جمهور الأئمة هذه الأبيات الأربعة في هذه القصيدة وزعموا أنها لتأبط شرا أعني: وقربة أقوام إلى قوله: وقد أغتدي، ورواها بعضهم في هذه القصيدة هنا. العصام: وكاء1 القربة، الجمع العصم. الكاهل: أعلى الظهر عند مركب العنق فيه والجمع الكواهل. الترحيل: مبالغة الرحل، يقال: رحلته إذا كررت رحله.\nيقول: ورب قربة أقوام جعلت وكاءها على كاهل ذلول قد رحل مرة بعد مرة أخرى مني، وفي معنى البيت قولان: أحدهما أن تمدح أثقال الحقوق ونوائب الأقوام من قرى الأضياف وإعطاء العفاة2 والعقل3 عن القاتلين وغير ذلك، وزعم أنه قد تعود التحمل للحقوق والنوائب، واستعار حمل القربة لتحمل الحقوق ثم ذكر الكاهل؛ لأنه موضع القربة من حاملها وعبر بكون الكاهل ذلولا مرحلا عن اعتياده تحمل الحقوق. والقول الآخر أنه تمدح بخدمته الرفقاء في السفر وحمله سقاء الماء على كاهل قد مرن عليه."},{"id":"muallaqat:70","bookId":"muallaqat","type":"section","seq":70,"chapter":"مدخل","title":"49- وواد كجوف العير قفر قطعته","page":"ج1 ص61","text":"وواد كجوف العير قفر قطعته ... به الذئب يعوي كالخليع المعيل\nالوادي يجمع على الأودية والأوداية. الجوف: باطن الشيء، والجمع أجواف. العير: الحمار، والجمع الأعيار. القفر: المكان الخالي، والجمع القفار، ويقال أقفر المكان إقفارا إذا خلا، ومنه خبز قفار لا إدام معه. الذئب يجمع على الذئاب والذياب والذؤبان ومنه قيل ذؤبان العرب للخبثاء المتلصصين. وأرض مذأبة: كثيرة الذئاب، وقد تذأبت الريح وتذاءبت إذا هبت من كل ناحية كالذئب إذا حذر من ناحية أتى من غيرها. الخليع: الذي قد خلعه أهله لخبثه، وكان الرجل منهم يأتي بابنه إلى الموسم ويقول: ألا إني قد خلعت ابني فإن جر1 لم أضمن وإن جر عليه لم أطلب فلا يؤخذ بجرائره، وزعم الأئمة أن الخليع في هذا البيت المقامر. المعيل: الكثير العيال، وقد عيل تعييلا فهو معيل إذا كثر عياله. العواء: صوت الذئب وما أشبهه من السباع، والفعل عوى يعوي عواء.\nزعم صنف من الأئمة أنه شبه الوادي في خلائه من الإنس ببطن العير، وهو الحمار الوحشي إذا خلا من العلف وقيل: بل شبهه في قلة الانتفاع به بجوف العير؛ لأنه لا يركب ولا يكون له در، وزعم صنف منهم أنه أراد كجوف الحمار فغير اللفظ إلى ما وافقه في المعنى لإقامة الوزن، وزعموا أن حمارا كان رجلا من بقية عاد وكان متمسكا بالتوحيد، فسافر بنوه فأصابتهم صاعقة فأهلكتهم، فأشرك بالله وكفر بعد التوحيد، فأحرق الله أمواله وواديه الذي كان يسكن فيه فلم ينبت بعده شيئا فشبه امرؤ القيس هذا الوادي بواديه في الخلاء من النبات والإنس.\nيقول: ورب واد يشبه وادي الحمار في الخلاء من النبات والإنس أو يشبه بطن الحمار فيما ذكرنا طويته سيرا وقطعته، وكان الذئب فيه من فرط الجوع كالمقامر الذي كثر عياله ويطالبه عياله بالنفقة، وهو يصيح بهم ويخاصمهم إذ لا يجد ما يرضيهم به."},{"id":"muallaqat:71","bookId":"muallaqat","type":"section","seq":71,"chapter":"مدخل","title":"50- فقلت له لما عوى","page":"ج1 ص61","text":"فقلت له لما عوى: إن شأننا ... قليل الغنى إن كنت لما تمول\nقوله: إن شأننا قليل الغنى، يريد: إن شأننا أننا قليل الغنى، ومن روى طويل الغنى فمعناه طويل طلب الغنى. وقد تمول الرجل إذا صار ذا مال. لما بمعنى لم في البيت كما كانت في قوله تعالى: {ولما يعلم الله الذين جاهدوا منكم} [التوبة: 16] .\nكذلك يقول: قلت للذئب لما صاح إن شأننا وأمرنا يقل غنانا إن كنت غير متمول كما كنت غير متمول، وإذا روي طويل الغنى، فالمعنى: قلت له إن شأننا أننا نطلب الغنى، ثم لا نظفر به إن كنت قليل المال كما كنت قليل المال."},{"id":"muallaqat:72","bookId":"muallaqat","type":"section","seq":72,"chapter":"مدخل","title":"51- كلانا إذا ما نال شيئا أفاته","page":"ج1 ص62","text":"كلانا إذا ما نال شيئا أفاته ... ومن يحترث حرثي وحرثك يهزل\nأصل الحرث إصلاح الأرض وإلقاء البذر فيها، ثم يستعار للسعي والكسب كقوله تعالى: {من كان يريد حرث الآخرة} [الشورى: 20] الآية. وهو في البيت مستعار. والاحتراث والحرث واحد.\nيقول: كل واحد منا إذا ظفر بشيء فوته على نفسه أي: إذا ملك شيئا أنفقه وبذره ثم قال: ومن سعى سعيي وسعيك افتقر وعاش مهزول العيش."},{"id":"muallaqat:73","bookId":"muallaqat","type":"section","seq":73,"chapter":"مدخل","title":"52- وقد أغتدي والطير في وكناتها","page":"ج1 ص62","text":"وقد أغتدي والطير في وكناتها ... بمنجرد قيد الأوابد هيكل\nغدا يغدو غدوا واغتدى اغتداء واحدا. الطير جمع طائر مثل الشرب في جمع شارب والتجر في جمع تاجر والركب في جمع راكب. ثم يجمع على الطيور مثل بيت وبيوت وشيخ وشيوخ. الوكنات: مواقع الطير، واحدتها وكنة، وتقلب الواو همزة فيقال أكنة، ثم تجمع الوكنة على الوكنات، بضم الفاء والعين، وعلى الوكنات، بضم الفاء وفتح العين، وعلى الوكنات، بضم الفاء وسكون العين، وتكسر على الوكن، وهذا حكم فعلة نحو ظلمة وظلمات وظلمات وظلم. المنجرد: الماضي في السير، وقيل: بل هو القليل الشعر. الأوابد: الوحوش، وقد أبد الوحش يأبد أبودا، ومنه تأبد الموضع إذا توحش وخلا من القطان، ومنه قيل للفذ آبدة لتوحشه عن الطباع. الهيكل، قال ابن دريد: هو الفرس العظيم الجرم، والجمع الهياكل.\nيقول: وقد أغتدي والطير بعد مستقرة على مواقعها التي باتت عليها على فرس ماض في السير قليل الشعر، يقيد الوحوش بسرعة لحاقه إياها عظيم الألواح والجرم؛\nوتحرير المعنى: أنه تمدح بمعاناة دجى الليل وأهواله، ثم تمدح بتحمل حقوق العفاة والأضياف والزوار، ثم تمدح بطي الفيافي والأودية، ثم أنشأ الآن يتمدح بالفروسية. يقول: وربما باكرت الصيد قبل نهوض الطير من أوكارها على فرس هذه صفته. وقوله: قيد الأوابد جعل لسرعة إدراكه الصيد كالقيد لها لأنها لا يمكنها الفوت منه كما أن المقيد غير متمكن من الفوت والهرب."},{"id":"muallaqat:74","bookId":"muallaqat","type":"section","seq":74,"chapter":"مدخل","title":"53- مكر مفر مقبل مدبر معا","page":"ج1 ص63","text":"مكر مفر مقبل مدبر معا ... كجلمود صخر حطه السيل من عل\nالكر: العطف، يقال: كر فرسه على عدوه أي: عطفه عليه، والكر والكرور جميعا الرجوع، يقال: كر على قرنه يكر كرا وكرورا، والمكر مفعل من كر يكر، ومفعل يتضمن مبالغة كقولهم: فلان مسعر حرب وفلان مقول ومصقع، وإنما جعلوه متضمنا مبالغة؛ لأن مفعلا قد يكون من أسماء الأدوات نحو المعول والمكتل1 والمخرز، فجعل كأنه أداة للكرور وآلة لسعر الحرب وغير ذلك. مفر: مفعل من فر يفر فرارا، والكلام فيه نحو الكلام في مكر. الجلمود والجلمد: الحجر العظيم الصلب، والجمع جلامد وجلاميد. الصخر: الحجر، الواحدة صخرة، وجمع الصخر صخور. الحط: إلقاء الشيء من علو إلى سفل، يقال: حطه يحطه فانحط. وقوله: من عل أي: من فوق، وفيه سبع لغات، يقال: أتيته من عل، مضمومة اللام، ومن علو بفتح الواو وضمها وكسرها، ومن علي، بياء ساكنة ومن عال مثل قاض، ومن معال، مثل معاد، ولغة ثامنة يقال من علا، وأنشد الفراء.\nباتت تنوش الحوض نوشا من علا ... نوشا به تقطع أجواز الفلا\nوقوله: كجلمود صخر، من إضافة بعض الشيء إلى كله مثل باب حديد وجبة خز، أي: كجلمود من صخر.\nيقول: هذا الفرس مكر إذا أريد منه الكر، ومفر إذا أريد منه الفر، ومقبل إذا أريد منه إقباله، ومدبر إذا أريد منه إدباره، وقوله: معا، يعني أن الكر والفر والإقبال والإدبار مجتمعة في قوته لا في فعله؛ لأن فيها تضادا، ثم شبهه في سرعة مره وصلابة خلقه بحجر عظيم ألقاه السيل من مكان عال إلى حضيض.\nكميت يزل اللبد عن حال متنه ... كما زلت الصفواء بالمتنزل\nزل الشيء يزل زليلا، وأزللته أنا. الحال: مقعد الفارس من ظهر الفرس. الصفواء والصفوان والصفا: الحجر الصلب. الباء في قوله بالمتنزل للتعدية.\nيقول: هذا الفرس الكميت1 يزل لبده عن متنه لانملاس ظهره واكتناز لحمه، وهما يحمدان من الفرس، كما يزل الحجر الصلب الأملس المطر النازل عليه، وقيل: بل أراد الإنسان النازل عليه، والتنزل والنزول واحد، والمتنزل في البيت صفة لمحذوف وتقديره بالمطر المتنزل أو بالإنسان المتنزل، وتحرير المعنى: أنه لاكتناز لحمه وانملاس صلبه يزل لبده عن متنه كما أن الحجر الصلب يزل المطر أو الإنسان عن نفسه. وجر كميتا وما قبله من الأوصاف؛ لأنها نعوت لمنجرد."},{"id":"muallaqat:75","bookId":"muallaqat","type":"section","seq":75,"chapter":"مدخل","title":"55- على الذبل جياش كأن اهتزامه","page":"ج1 ص64","text":"على الذبل جياش كأن اهتزامه ... إذا جاش فيه حميه غلي مرجل\nالذبل والذبول واحد، والفعل ذبل يذبل. الجياش مبالغة جائش، وهو فاعل من جاشت القدر تجيش جيشا وجيشانا إذا غلت، وجاش البحر جيشا وجيشانا إذا هاجت أمواجه. الاهتزام: التكسر. الحمي: حرارة القيظ2 وغيره والفعل حمي يحمى. المرجل: القدر من صفر3 أو حديد أو نحاس أو شبهه، والجمع المراجل، وروى ابن الأنباري وابن مجاهد عن ثعلب أنه قال: كل قدر من حديد أو صفر أو حجر أو خزف أو نحاس أو غيرها فهو مرجل.\nيقول: تغلي فيه حرارة نشاطه على ذبول خلقه وضمر بطنه، وكأن تكسر صهيله في صدره غليان قدر، جعله ذكي القلب نشيطا في السير والعدو على ذبول خلقه وضمر بطنه ثم شبه تكسر صهيله في صدره بغليان القدر."},{"id":"muallaqat:76","bookId":"muallaqat","type":"section","seq":76,"chapter":"مدخل","title":"56- مسح إذا ما السابحات على الوني","page":"ج1 ص64","text":"مسح إذا ما السابحات على الوني ... أثرن الغبار بالكديد المركل\nسح يسح: قد يكون بمعنى صب يصب وقد يكون بمعنى انصب ينصب، فيكون\nمرة لازما ومرة متعديا، ومصدره إذا كان متعديا السح، وإذا كان لازما السح والسحوح تقول: سح الماء فسح هو، ومسح مفعل من المتعدي، وقد قررنا أن مفعلا في الصفات يقتضي مبالغة، فالمعنى أنه يصب الجري والعدو صبا بعد صب. السابح من الخيل: الذي يمد يديه في عدوه، شبه بالسابح في الماء. الونى: الفتور، ونى يني ونيا وونى. الكديد: الأرض الصلبة المطمئنة. المركل من الركل: وهو الدفع بالرجل والضرب بها، والفعل منه ركل يركل ومنه قوله عليه الصلاة والسلام: \"فركلني جبريل\" 1. والتركيل التكرير والتشديد، والمركل الذي يركل مرة بعد أخرى.\nيقول: يصب هذا الفرس عدوه وجريه صبا بعد صب، أي يجيء به شيئا بعد شيء، إذا أثارت جياد الخيل التي تمد أيديها في عدوها الغبار في الأرض الصلبة التي وطئت بالأقدام والمناسم2 والحوافر مرة بعد أخرى في حال فتورها في السير وكلالها؛ وتحرير المعنى: أنه يجيء بجري بعد جري إذا كلت الخيل السوابح وأعيت وأثارت الغبار في مثل هذا الموضع. وجر مسحا لأنه صفة الفرس المنجرد ولو رفع لكان صوابا وكان حينئذ خبر مبتدأ محذوف تقديره هو مسح، ولو نصب لكان صوابا أيضا وكان انتصابه على المدح، والتقدير: أذكر مسحا أو أعني: مسحا، وكذلك القول فيما قبله من الصفات نحو كميت، يجوز في كل هذه الألفاظ الأوجه الثلاثة من الإعراب. ويروى المرحل."},{"id":"muallaqat:77","bookId":"muallaqat","type":"section","seq":77,"chapter":"مدخل","title":"57- يزل الغلام الخف على صهواته","page":"ج1 ص65","text":"يزل الغلام الخف على صهواته ... ويلوي بأثواب العنيف المثقل\nالخف: الخفيف. الصهوة: مقعد الفارس من ظهر الفرس، والجمع الصهوات وفعله تجمع على فعلات، بفتح العين، إذا كانت اسما، نحو شعرة وشعرات وضربة وضربات، إلا إذا كانت عينها واوا أو ياء أو مدغمة في اللام فإنها تسكن حينئذ، نحو\nبيضة وبيضات وعورة وعورات وحبة وحبات، فإذا كانت صفة تجمع على فعلات، مسكنة العين أيضا، نحو ضخمة وضخمات وخدلة1، وخدلات. ألوى بالشيء: رمى به، وألوى به ذهب به. العنيف: ضد الرقيق.\nيقول: إن هذا الفرس يزل ويزلق الغلام الخفيف عن مقعده من ظهره ويرمي بثياب الرجل العنيف الثقيل، يريد أنه يزلق عن ظهره من لم يكن جيد الفروسية عالما بها ويرمي بأثواب الماهر الحاذق في الفروسية لشدة عدوه وفرط مرحه في جريه، وإنما عبر بصهواته ولا يكون له إلا صهوة واحدة؛ لأنه لا لبس فيه، فجرى الجمع والتوحيد مجرى واحدا عند الاتساع؛ لأن إضافتها إلى ضمير الواحد تزيل اللبس كما يقال: رجل عظيم المناكب وغليظ المشافر، ولا يكون له إلا منكبان وشفتان، ورجل شديد مجامع الكتفين، ولا يكون له إلا مجمع واحد. ويروى: يطير الغلام، أي يطيره، ويروى: يزل الغلام الخف، بفتح الياء من يزل ورفع الغلام فيكون فعلا لازما."},{"id":"muallaqat:78","bookId":"muallaqat","type":"section","seq":78,"chapter":"مدخل","title":"58- درير كخذروف الوليد أمره","page":"ج1 ص66","text":"درير كخذروف الوليد أمره ... تتابع كفيه بخيط موصل\nالدرير: من در يدر، وقد يكون در لازما ومتعديا يقال: درت الناقة اللبن فدر اللبن، ثم الدرير ههنا يجوز أن يكون بمعنى الدار من دار إذا كان متعديا، والفعل يكثر مجيئه بمعنى الفاعل نحو قادر وقدير وعالم وعليم، ويجوز أن يكون بمعنى المدر من الإدرار وهو جعل الشيء دارا، وقد يكثر الفعيل بمعنى المفعل كالحكيم بمعنى المحكم والسميع بمعنى المسمع، ومنه قوله عمرو بن معديكرب: [الوافر] :\nأمن ريحانة الداعي السميع ... يؤرقني وأصحابي هجوع2\nأي المسمع. الخذروف: حصاة مثقوبة يجعل الصبيان فيه خيطا فيديرها الصبي على رأسه. شبه سرعة هذا الفرس بسرعة دوران الحصان على رأس الصبي. الوليد: الصبي، والجمع الولدان، وجمع خذاريف، والوليدة: الصبية، وقد يستعار للأمة، والجمع الولائد. الإمرار: إحكام الفتل.\nيقول: هو يدر العدو والجري أي: يديمهما ويواصلهما ويتابعهما ويسرع فيهما إسراع خذورف الصبي إذا أحكم فتل خيطه وتتابعت كفاه في فتله، وإدارته بخيط قد انقطع ثم وصل، وذلك أشد لدورانه لانملاسه ومرونه على ذلك، وتحرير المعنى: أنه مديم السير والعدو متابع لهما، ثم شبهه في سرعة مره وشدة عدوه بالخذروف في دورانه إذا بولغ في فتل خيطه موصلا؛ ويسوغ في إعراب درير ما ساغ في إعراب مسح من الأوجه الثلاثة."},{"id":"muallaqat:79","bookId":"muallaqat","type":"section","seq":79,"chapter":"مدخل","title":"59- له أيطلا ظبي وساقا نعامة","page":"ج1 ص67","text":"له أيطلا ظبي وساقا نعامة ... وإرخاء سرحان وتقريب تتفل\nالأيطل والإطل والإطل: الخاصرة، والجمع الأياطل والآطال، أجمع البصريون على أنه لم يأت على فعل من الأسماء إلا إبل، ومن الصفات إلا بلز وهي الجارية التارة1 السمينة الضخمة، وحكى الكوفيون إطلا من الأسماء أيضا مثل إبل، فقد اتفق الفريقان على اقتصار فعل على هذه الثلاثة. الظبي يجمع أظب وظباء، والساق على الأسؤق والسوق. والنعامة تجمع على النعامات والنعام والنعائم. الإرخاء ضرب من عدو الذئب يشبه خبب الدواب، السرحان: الذئب، والتقريب: وضع الرجلين موضع اليدين في العدو. التتفل: ولد الثعلب: شبه خاصرتي هذا الفرس بخاصرتي الظبي في الضمر، وشبه ساقيه بساقي النعامة في الانتصاب والطول، وعدوه بإرخاء الذئب، وتقريبه بتقريب ولد الثعلب، فجمع أربعة تشبيهات في هذا البيت."},{"id":"muallaqat:80","bookId":"muallaqat","type":"section","seq":80,"chapter":"مدخل","title":"60- ضليع إذا استدبرته سد فرجه","page":"ج1 ص67","text":"ضليع إذا استدبرته سد فرجه ... بضاف فويق الأرض ليس بأعزل\nالضليع: العظيم الأضلاع المنتفخ الجنبين، والجمع الضلعاء والمصدر الضلاعة والفعل ضلع يضلع. والاستدبار: النظر إلى دبر الشيء، وهو مؤخره، وتتبع دبر الشيء. الفرج: الفضاء بين اليدين والرجلين، والجمع الفروج، الضفو. السبوغ والتمام والفعل ضفا يضفو، أراد بذنب ضاف فحذف الموصوف اجتزاء بدلالة الصفة عليه، كقولهم: مررت بكريم، أي: بإنسان كريم. فويق: تصغير فوق وهو تصغير التقريب مثل قبيل وبعيد في تصغير قبل وبعد. الأعزل: الذي يميل عظم ذنبه إلى أحد الشقين.\nيقول: هذا الفرس عظيم الأضلاع منتفخ الجنبين إذا نظرت إليه من خلفه رأيته قد سد الفضاء الذي بين رجليه بذنبه السابغ1 التام الذي قرب من الأرض وهو غير مائل إلى أحد الشقين فسبوغ ذنبه من دلائل عتقه وكرمه، وشرط كونه فويق الأرض؛ لأنه إذا بلغ الأرض وطئه برجليه وذلك عيب؛ لأنه ربما عثر به، واستواء عسيب2 ذنبه أيضا من دلائل العتق والكرم."},{"id":"muallaqat:81","bookId":"muallaqat","type":"section","seq":81,"chapter":"مدخل","title":"61- كأن على المتنين منه إذا انتحى","page":"ج1 ص68","text":"كأن على المتنين منه إذا انتحى ... مداك عروس أو صلاية حنظل\nالمتنان: تثنية متن وهما ما عن يمين الفقار وشماله. الانتحاء: الاعتماد والقصد. المداك: الحجر الذي يسحق به الطيب وغيره، والذي يسحق عليه أيضا مداك، والدوك: السحق، الفعل منه داك يدوك دوكا، الصلاية: الحجر الأملس الذي يسحق عليه شيء كالهبيد وهو حب الحنظل. ويروى: كأن سراته لدى البيت قائما. السراة: أعلى الظهر، والجمع السروات، ويستعار لعلية الناس، وسراة النهار أعلى مداه، والسرو الارتفاع في المجد والشرف، والفعل منه سرا يسرو وسرى يسري وسرو يسرو، ونصب قائما على الحال. شبه انملاس ظهره واكتنازه باللحم، بالحجر الذي تسحق العروس به أو عليه الطيب، أو بالحجر الذي يكسر عليه الحنظل ويستخرج حبه، وخص مداك العروس لحدثان عهدها بالسحق للطيب."},{"id":"muallaqat:82","bookId":"muallaqat","type":"section","seq":82,"chapter":"مدخل","title":"62- كأن دماء الهاديات بنحره","page":"ج1 ص68","text":"كأن دماء الهاديات بنحره ... عصارة حناء بشيب مرجل\nتثنية الدم الدمان والدميان؛ ومنه قول الشاعر: [الوافر] :\nفلو أنا على حجر ذبحنا ... جرى الدميان بالخبر اليقين\nوالجمع دماء ودمي، والتصغير دمي، والقطعة منه دمة، حكاها الليث، وقد دمي الشيء يدمي إذا تلطخ بالدم، وأدميته أنا ودميته. الهاديات المتقدمات والأوائل، وسمي المتقدم هاديا؛ لأن هادي القوم يتقدمهم، ومنه قيل لعنق الفرس هاد؛ لأنه يتقدم على سائر جسده. عصارة الشيء: ما خرج منه عند عصره. الترجيل: تسريح الشعر. المرجل: المسرح بالمشط.\nيقول: كأن دماء أوائل الصيد والوحش على نحر هذا الفرس عصارة حناء خضب بها شيب مسرح، شبه الدم الجامد على نحره من دماء الصيد بما جف من عصارة الحناء عن شعر الأشيب، وأتى بالمرجل لإقامة القافية."},{"id":"muallaqat:83","bookId":"muallaqat","type":"section","seq":83,"chapter":"مدخل","title":"63- فعن لنا سرب كأن نعاجه","page":"ج1 ص69","text":"فعن لنا سرب كأن نعاجه ... عذارى دوار في ملاء مذيل\nعن أي: عرض وظهر. السرب: القطيع من الظباء أو النساء أو القطا أو المها أو البقر أو الخيل، والجمع الأسراب. النعاج: اسم لإناث الضأن وبقر الوحش وشاء الجبل، والواحدة نعجة، وجمع التصحيح نعجات، والمراد بالنعاج في هذا البيت إناث بقر الوحش، وبالسرب القطيع منها. العذراء: البكر التي لم تمس، والجمع عذارى. الدوار: حجر كان أهل الجاهلية ينصبونه ويطوفون حوله تشبيها بالطائفين حول الكعبة إذا نأوا عن الكعبة. الملاء: جمع ملاءة، وإنما تسمى ملاءة إذا كانت لفقين1. المذيل: الذي أطيل ذيله وأرخي.\nيقول: فعرض لنا وظهر قطيع من بقر الوحش كأن إناث ذلك القطيع نساء عذارى يطفن حول حجر منصوب يطاف حوله في ملاء طويل ذيولها، وشبه المها في بياض ألوانها بالعذارى لأنهن مصونات في الخدور لا يغير ألوانهن حر الشمس وغيره، وشبه طول أذيالها وسبوغ شعرها بالملاء المذيل. وشبه حسن مشيها بحسن تبختر العذارى في مشيهن."},{"id":"muallaqat:84","bookId":"muallaqat","type":"section","seq":84,"chapter":"مدخل","title":"64- فأدبرن كالجزع المفصل بينه","page":"ج1 ص69","text":"فأدبرن كالجزع المفصل بينه ... بجيد معم في العشيرة مخول\nالجزع: الخرز اليماني. الجيد: العنق، والجمع الأجياد، ورجل أجيد طويل العنق، وجمعه جود، المعم: الكريم الأعمام. المخول: الكريم الأخوال، وقد أعم وأخول إذا كرم أعمامه وأخواله، وهذان من الشواذ؛ لأن القياس من أفعل فهو مفعل، وهما أفعل فهو مفعل.\nيقول: فأدبرت النعاج كالخرز اليماني الذي فصل بينه بغيره من الجواهر في عنق صبي كرم أعمامه وأخواله، وشبه بقر الوحش بالخرز اليماني؛ لأنه يسود طرفه وسائره\nأبيض، وكذلك بقر الوحش تسود أكارعها وخدودها وسائرها أبيض، وشرط كونه في جيد معم مخول؛ لأن جواهر قلادة مثل هذا الصبي أعظم من جواهر قلادة غيره، وشرط كونه مفصلا لتفرقهن عند رؤيته."},{"id":"muallaqat:85","bookId":"muallaqat","type":"section","seq":85,"chapter":"مدخل","title":"65- فألحقنا بالهاديات ودونه","page":"ج1 ص70","text":"فألحقنا بالهاديات ودونه ... جواحرها في صرة لم تزيل\nالهاديات: الأوائل المتقدمات. الجواحر: المتخلفات، وقد جحر أي: تخلف الصرة: الجماعة، والصرة الصيحة، ومنه صرير القلم وغيره. الزيل والتزييل: التفريق، والتزيل والانزيال: التفرق.\nيقول: فألحقنا هذا الفرس بأوائل الوحش ومتقدماته وجاوز بنا متخلفاته فهي دونه أي أقرب منه في جماعة لم تتفرق أو في صيحة؛ وتلخيص المعنى: أنه يلحقنا بأوائل الوحش ويدع متخلفاته ثقة بشدة جريه وقوة عدوه فيدرك أوائلها وأواخرها مجتمعة لم تتفرق بعد، يريد أنه يدرك أوائلها قبل تفرق جماعتها، يصفه بشدة عدوه."},{"id":"muallaqat:86","bookId":"muallaqat","type":"section","seq":86,"chapter":"مدخل","title":"66- فعادى عداء بين ثور ونعجة","page":"ج1 ص70","text":"فعادى عداء بين ثور ونعجة ... دراكا ولم ينضح بماء فيغسل\nالمعاداة والعداء: الموالاة. الثور يجمع على الثيران والثيرة والثورة والثيارة والأثوار والثيار. الدراك: المتابعة.\nيقول: فوالى بين ثور ونعجة من بقر الوحش في طلق1 واحد ولم يعرق عرقا مفرطا يغسل جسده، يريد أنه أدركهما وقتلهما في طلق واحد قبل أن يعرق عرقا مفرطا، أي: أدركهما دون معاناة مشقة ومقاساة شدة، نسب فعل الفارس إلى الفرس؛ لأنه حامله وموصله إلى مرامه، يقول: صاد هذا الفرس ثورا ونعجة في طلق واحد. ودراكا أي مداركة."},{"id":"muallaqat:87","bookId":"muallaqat","type":"section","seq":87,"chapter":"مدخل","title":"67- فظل طهاة اللحم من بين منضج","page":"ج1 ص70","text":"فظل طهاة اللحم من بين منضج ... صفيف شواء أو قدير معجل\nالطهو والطهي: الإنضاج، والفعل طها يطهو ويطهي، والطهاة جمع طاه كالقضاة جمع قاض والكفاة جمع كاف. الإنضاج: يشتمل على طبخ اللحم وشيه.\nالصفيف: المصفوف على الحجارة لينضج. القدير: اللحم المطبوخ في القدر.\nيقول: ظل المنضجون اللحم وهم صنفان صنف ينضجون شواء مصفوفا على الحجارة في النار، وصنف يطبخون اللحم في القدر؛ يقول كثر الصيد فأخصب القوم فطبخوا واشتووا؛ ومن في قوله: من بين منضج للتفصيل والتفسير، كقولهم: هم من بين عالم وزاهد، يريد أنهم لا يعدون الصنفين، كذلك أراد لم يعد طهاة اللحم الشاوين والطابخين."},{"id":"muallaqat:88","bookId":"muallaqat","type":"section","seq":88,"chapter":"مدخل","title":"68- ورحنا يكاد الطرف يقصر دونه","page":"ج1 ص71","text":"ورحنا يكاد الطرف يقصر دونه ... متى ما ترق العين فيه تسفل\nالطرف: اسم لما يتحرك من أشفار العين، وأصله التحرك، والفعل منه طرف يطرف. القصور: العجز، والفعل قصر يقصر. الترقي والارتقاء والرقي واحد، والفعل من الرقي رقي يرقى، وأما رقى يرقي فهو من الرقية، وقد رقيته أنا أي حملته على الرقي.\nيقول: ثم أمسينا وتكاد عيوننا تعجز عن ضبط حسنه واستقصاء محاسن خلقه، ومتى ما ترقت العين في أعالي وشخصه نظرت إلى قوائمه، وتلخيص المعنى أنه كامل الحسن رائع الصورة تكاد العيون تقصر عن كنه حسنه ومهما نظرت العيون إلى أعالي خلقه اشتهت النظر إلى أسافله."},{"id":"muallaqat:89","bookId":"muallaqat","type":"section","seq":89,"chapter":"مدخل","title":"69- فبات عليه سرجه ولجامه","page":"ج1 ص71","text":"فبات عليه سرجه ولجامه ... وبات بعيني قائما غير مرسل\nيقول: بات مسرجا ملجما قائما بين يدي غير مرسل إلى المرعى"},{"id":"muallaqat:90","bookId":"muallaqat","type":"section","seq":90,"chapter":"مدخل","title":"70- أصاح ترى برقا أريك وميضه","page":"ج1 ص71","text":"أصاح ترى برقا أريك وميضه ... كلمع اليدين في حبي مكلل\nأصاح: أراد أصاحب أي: يا صاحب، فرخم كما تقول في ترخيم حارث يا حار، وفي ترخيم مالك يا مال، ومنه قراءة من قرأ: {ونادوا يا مالك ليقض علينا ربك} [الزخرف: 77] ومنه قول زهير: [البسيط] :\nيا حار لا أرمين منكم بداهية ... لم يلقها سوقة قبلي ولا ملك1\nأراد يا حارث، والألف نداء للقريب دون البعيد، تقول: أزيد إذا كان زيد حاضرا قريبا منك، ويا نداء للبعيد والقريب، وأي وأيا وهيا لنداء البعيد دون القريب. الوميض والإيماض: اللمعان، تقول: ومض البرق يمض وأومض إذا لمع وتلألأ. اللمع: التحريك والتحرك جميعا. الحبي: السحاب المتراكم، سمي بذلك لأنه حبا بعضه إلى بعض فتراكم، وجعله مكللا لأنه صار أعلاه كالإكليل لأسفله، ومنه قولهم: كللت الرجل إذا توجته وكللت الجفنة ببضعات اللحم إذا جعلتها كالإكليل لها، ويروى مكلل، بكسر اللام، وقد كلل تكليلا، وانكل انكلالا إذا تبسم.\nيقول: يا صاحبي هل ترى برقا أريك لمعانه وتلألؤه وتألقه في سحاب متراكم صار أعلاه كالإكليل لأسفله أو في سحاب متبسم بالبرق يشبه برقه تحريك اليدين؟ أراد أنه يتحرك تحركهما؛ وتقدير البيت: أريك وميضه في حبي مكلل كلمع اليدين؛ شبه لمعان البرق وتحركه بتحرك اليدين. فرغ من وصف الفرس والآن قد أخذ في وصف المطر فقال:"},{"id":"muallaqat:91","bookId":"muallaqat","type":"section","seq":91,"chapter":"مدخل","title":"71- يضيء سناه أو مصابيح راهب","page":"ج1 ص72","text":"يضيء سناه أو مصابيح راهب ... أمال السليط بالذبال المفتل\nالسنا: الضوء، والسناء: الرفعة. السليط: الزيت، ودهن السمسم سليط أيضا، وإنما سمي سليطا لإضاءتهما السراج، ومنه السلطان لوضوح أمره. الذبال: جمع ذبالة وهي الفتيلة. وقد يثقل فيقال ذبال.\nيقول: هذا البرق يتلألأ ضوؤه فهو يشبه في تحركه لمع اليدين أو مصابيح الرهبان أمليت فتائلها بصب الزيت عليها في الإضاءة، يريد أن تحرك البرق يحكي تحرك اليدين وضوءه يحكي ضوء مصباح الراهب إذا أفعم1 صب الزيت عليه فيضيء. وزعم أكثر الناس أن قوله أمال السليط بالذبال المفتل من المقلوب، وتقديره: أمال الذبال بالسليط إذا صبه عليه، وقال بعضهم: إن تقديره أمال السليط مع الذبال المفتل، يريد أن يميل المصباح إلى جانب فيكون أشد إضاءة لتلك الناحية من غيرها."},{"id":"muallaqat:92","bookId":"muallaqat","type":"section","seq":92,"chapter":"مدخل","title":"72- قعدت له وصحبتي بين ضارج","page":"ج1 ص72","text":"قعدت له وصحبتي بين ضارج ... وبين العذيب بعد ما متأملي\nضارج والعذيب: موضعان. بعد ما: أصله بعد ما فخففه فقال بعد، وما زائدة وتقديره: بعد متأملي.\nيقول: قعدت وأصحابي للنظر إلى السحاب بين هذين الموضعين، وكنت معهم فبعد متأملي وهو المنظور إليه، أي بعد السحاب الذي كنت أنظر إليه وأرقب مطره وأشيم1 برقه، يريد أنه نظر إلى هذا السحاب من مكان بعيد فتعجب من بعد نظره، وقال بعضهم: إن ما في البيت بمعنى الذي، وتقديره، بعد ما هو متأملي، فحذف المبتدا الذي هو هو، وتقديره على هذا القول: بعد السحاب الذي هو متأملي."},{"id":"muallaqat:93","bookId":"muallaqat","type":"section","seq":93,"chapter":"مدخل","title":"73- على قطن بالشيم أيمن صوبه","page":"ج1 ص73","text":"على قطن بالشيم أيمن صوبه ... وأيسره على الستار فيذبل\nويروى: علا قطنا، من علو يعلو علوا، أي علا هذا السحاب. القطن: جبل، وكذلك الستار ويذبل جبلان، وبينهما وبين قطن مسافة بعيدة. الصوب: المطر، وأصله مصدر صاب يصوب صوبا أي نزل من علو إلى سفل. الشيم: النظر إلى البرق مع ترقب المطر.\nيقول: أيمن هذا السحاب على قطن وأيسره على الستار ويذبل، يصف عظم السحاب، وغزارته وعموم جوده، وقوله: بالشيم، أراد: إني ما أحكم به حدسا وتقديرا لأنه لا يرى ستارا ويذبل وقطن معا."},{"id":"muallaqat:94","bookId":"muallaqat","type":"section","seq":94,"chapter":"مدخل","title":"74- فأضحى يسح الماء حول كتيفة","page":"ج1 ص73","text":"فأضحى يسح الماء حول كتيفة ... يكب على الأذقان دوح الكنهبل\nالكب: إلقاء الشيء على وجهه، والفعل كب يكب. وأما الإكباب فهو خرور الشيء على وجهه، وهذا من النوادر؛ لأن أصله متعد إلى المفعول به ثم لما نقل بالهمزة إلى باب الأفعال قصر عن الوصول إلى المفعول به، وهذا عكس القياس المطرد؛ لأن ما لم يتعد إلى المفعول في الأصل يتعدى إليه عند النقل بالهمزة من باب الأفعال نحو: قعد وأقعدته وقام وأقمته وجلس وأجلسته، ونظير كب وأكب عرض وأعرض؛ لأن عرض متعد إلى المفعول به؛ لأن معناه أظهر، وأعرض لازم، لأن معناه ظهر ولاح؛ ومنه قول عمرو بن كلثوم: [الوافر] :\nفأعرضت اليمامة واشمخرت ... كأسياف بأيدي مصلتينا\nالذقن: مجتمع اللحيين، والجمع الأذقان، والأذقان مستعار في البيت للشجر، الدوحة: الشجرة العظيمة، والجمع دوح. الكنهبل، بضم الباء وفتحها: ضرب من شجر البادية.\nيقول: فأضحى هذا الغيث أو السحاب يصب الماء فوق هذا الموضع المسمى بكتيفة ويلقي الأشجار العظام من هذا الضرب الذي يسمى كنهبلا على رءوسها، وتلخيص المعنى: أن سيل هذا الغيث ينصب من الجبال والآكام1، فيقلع الشجر العظام. ويروى: يسح الماء من كل فيقة، أي: بعد كل فيقة، والفيقة من الفواق: وهو مقدار ما بين الحلبتين، ثم استعاره لما بين الدفعتين من المطر."},{"id":"muallaqat:95","bookId":"muallaqat","type":"section","seq":95,"chapter":"مدخل","title":"75- ومر على القنان من نفيانه","page":"ج1 ص74","text":"ومر على القنان من نفيانه ... فأنزل منه العصم من كل منزل\nالقنان: اسم جبل لبني أسد. النفيان: ما يتطاير من قطر المطر وقطر الدلو ومن الرمل عند الوطء ومن الصوف عند النفش وغير ذلك. العصم: جمع أعصم، وهو الذي في إحدى يديه بياض من الأوعال2 وغيرها. المنزل: موضع الإنزال.\nيقول: ومر على هذا الجبل مما تطاير وانتشر وتناثر من رشاش هذا الغيث فأنزل الأوعال العصم من كل موضع من هذا الجبل، لهولها من وقع قطره على الجبل وفرط انصبابه."},{"id":"muallaqat:96","bookId":"muallaqat","type":"section","seq":96,"chapter":"مدخل","title":"76- وتيماء لم يترك بها جذع نخلة","page":"ج1 ص74","text":"وتيماء لم يترك بها جذع نخلة ... ولا أطما إلا مشيدا بجندل\nتيماء: قرية عادية في بلاد العرب. الجذع يجمع على الأجذاع والجذوع، والنخلة على النخلات والنخل والنخيل. الأطم: القصر، والأطم الأزج3، والجمع الآطام. الشيد: الجص، والشيد الرفع وعلو البنيان، والفعل منه شاد يشيد. الجندل: الصخر، والجمع الجنادل.\nيقول: لم يترك هذا الغيث شيئا من جذوع النخل بقرية تيماء، ولا شيئا من القصور والأبنية إلا ما كان منها مرفوعا بالصخور أو مجصصا، يعني أنه قلع الأشجار وهدم الأبنية إلا ما كان منها مرفوعا بالحجارة والجص."},{"id":"muallaqat:97","bookId":"muallaqat","type":"section","seq":97,"chapter":"مدخل","title":"77- كأن ثبيرا في عرانين وبله","page":"ج1 ص75","text":"كأن ثبيرا في عرانين وبله ... كبير أناس في بجاد مزمل\nثبير: جبل بعينه. العرنين: الأنف، وقال جمهور الأئمة: هو معظم الأنف، والجمع العرانين، ثم استعار العرانين لأوائل المطر؛ لأن الأنوف تتقدم الوجوه. البجاد: كساء مخطط، والجمع البجد. التزميل: التلفيف بالثياب، وقد زملته بثياب فتزمل بها أي: لففته فتلفف بها. وجر مزملا على جوار بجاد وإلا فالقياس يقتضي رفعه؛ لأنه وصف كبير أناس، ومثله ما حكي عن العرب من قولهم: جحر ضب خرب، جر خرب بمجاورة ضب، ومنه قول الأخطل: [الطويل] :\nجزى الله عني الأعورين ملامة ... وفروة ثفر الثورة المتضاجم\nجر المتضاجم على جوار الثورة والقياس نصبه؛ لأنه صفة ثفر، ونظائرها كثيرة. الوبل: جمع وابل وهو المطر الغزير العظيم القطر، ومثله شارب وشرب وراكب وركب وغيرهما، والوبل أيضا مصدر، وبلت السماء تبل وبلا إذا أتت بالوابل.\nيقول: كأن ثبيرا في أوائل مطر هذا السحاب سيد أناس قد تلفف بكساء مخطط شبه تغطيته بالغثاء بتغطي هذا الرجل بالكساء."},{"id":"muallaqat:98","bookId":"muallaqat","type":"section","seq":98,"chapter":"مدخل","title":"78- كأن ذرى رأس المجيمر غدوة","page":"ج1 ص75","text":"كأن ذرى رأس المجيمر غدوة ... من السيل والأغثاء فلكة مغزل\nالذروة: أعلى الشيء، والجمع الذرى. المجيمر: أكمة بعينها، الغثاء ما جاء به السيل من الحشيش والشجر والكلأ والتراب وغير ذلك، والجمع الأغثاء. المغزل بضم الميم وفتحها وكسرها معروف، والجمع المغازل. فلكة المغزل مفتوحة الفاء.\nيقول: كأن هذه الأكمة غدوة مما أحاط بها من أغثاء السيل فلكة مغزل شبه استدارة هذه الأكمة بما حاط بها من الأغثاء باستدارة فلكة المغزل وإحاطتها بها بإحاطة المغزل."},{"id":"muallaqat:99","bookId":"muallaqat","type":"section","seq":99,"chapter":"مدخل","title":"79- وألقى بصحراء الغبيط بعاعه","page":"ج1 ص75","text":"وألقى بصحراء الغبيط بعاعه ... نزول اليماني ذي العياب المحمل\nالصحراء تجمع على الصحارى والصحاري معا، الغبيط هنا: أكمة قد انخفض وسطها وارتفع طرفاها، سميت غبيطا تشبيها بغبيط البعير. البعاع: الثقل. قوله: نزول اليماني، أي: نزول التاجر اليماني. العياب: جمع عيبة1 الثياب.\nيقول: ألقى هذا الحيا2 ثقله بصحراء الغبيط فأنبت الكلأ وضروب الأزهار, وألوان النبات، فصار نزول المطر به كنزول التاجر اليماني صاحب العياب المحمل من الثياب حين نشر ثيابه يعرضها على المشترين؛ شبه نزول هذا المطر بنزول التاجر وشبه ضروب النبات الناشئة من هذا المطر بصنوف الثياب التي نشرها التاجر عند عرضها للبيع؛ وتقدير البيت: وألقى ثقله بصحراء الغبيط فنزل به نزولا مثل نزول التاجر اليماني صاحب العياب من الثياب."},{"id":"muallaqat:100","bookId":"muallaqat","type":"section","seq":100,"chapter":"مدخل","title":"80- كأن مكاكي الجواء غدية","page":"ج1 ص76","text":"كأن مكاكي الجواء غدية ... صبحن سلافا من رحيق مفلفل\nالمكاء: ضرب من الطير، والجمع المكاكي. الجواء: الوادي، والجمع أجوية. غدية: تصغير غدوة أو غداة. الصبح: سقي الصبوح، والاصطباح والتصبح: شرب الصبوح. السلاف: أجود الخمر وهو ما انعصر من العنب من غير عصر. المفلفل: الذي ألقي فيه الفلفل، يقال: فلفلت الشراب أفلفله فلفلة فأنا مفلفل والشراب مفلفل.\nيقول: كأن هذا الضرب من الطير سقي هذا الضرب من الخمر صباحا في هذه الأودية، وإنما جعلها كذلك لحدة ألسنتها وتتابع أصواتها ونشاطها في تغريدها؛ لأن الشراب المفلفل يحذي اللسان ويسكر، فجعل نشاط الطير كالسكر وتغريدها بحدة ألسنتها من حذي الشراب المفلفل إياها."},{"id":"muallaqat:101","bookId":"muallaqat","type":"section","seq":101,"chapter":"مدخل","title":"81- كأن السباع فيه غرقي عشية","page":"ج1 ص76","text":"كأن السباع فيه غرقي عشية ... بأرجائه القصوى أنابيش عنصل\nالغرقى: جمع غريق مثل مرضى ومريض وجرحى وجريح. العشي والعشية: ما بعد الزوال إلى طلوع الفجر وكذلك العشاء. الأرجاء: النواحي، الواحد رجا،\nمقصور، والتثنية رجوان. القصوى والقصيا تأنيث الأقصى: وهو الأبعد: والياء لغة نجد والواو لغة سائر العرب. الأنابيش: أصول النبت، سميت بذلك لأنها ينبش عنها، واحدتها أنبوشة. العنصل: البصل البري.\nيقول: كأن السباع حين غرقت في سيول هذا المطر عشيا أصول البصل البري؛ شبه تلطخها بالطين والماء الكدر بأصول البصل البري؛ لأنها متلطخة بالطين والتراب."},{"id":"muallaqat:102","bookId":"muallaqat","type":"section","seq":102,"chapter":"مدخل","title":"مدخل","page":"ج1 ص78","text":"...\nطرفة بن العبد\nحدث المفضل بن محمد بن يعلى الضبي أن طرفة بن العبد بن سفيان بن سعد بن مالك بن ضبيعة بن قيس بن ثعلبة بن عكابة بن صعب بن علي بن بكر بن وائل بن قاسط بن هنب بن أفصى بن دعمي بن جديلة بن أسد بن ربيعة بن نزار بن معد بن عدنان، كان في حسب كريم وعدد كثير، وكان شاعرا جريئا على الشعر، وكانت أخته عند عبد عمرو بن بشر بن عمرو بن مرثد بن سعد بن مالك بن ضبيعة بن قيس، وكان عبد عمرو سيد أهل زمانه وكان من أكرم الناس على عمرو بن هند الملك، فشكت أخت طرفة شيئا من أمر زوجها إلى طرفة فعاب عبد عمرو وهجاه، وكان من هجائه إياه أن قال: [الطويل] :\nولا خير فيه غير أن له غني ... وأن له كشحا إذا قام أهضما1\nتظل نساء الحي يعكفن حوله ... يقلن: عسيب من سرارة ملهما\nيعكفن: أي يطفن. العسيب: أغصان النخل. سرارة الوادي: قرارته وأنعمه وأجوده نبتا. الملهم: قرية باليمامة؛ فبلغ ذلك عمرو بن هند الملك وما رواه، فخرج يتصيد ومعه عبد عمرو فرمى حمارا فعقره2 فقال لعبد عمرو: انزل فاذبحه، فعالجه فأعياه فضحك الملك وقال: لقد أبصرك طرفة حيث يقول، وأنشد: ولا خير فيه وكان طرفة هجا قبل ذلك عمرو بن هند فقال فيه: [الوافر] :\nفليت لنا مكان الملك عمرو ... رغوثا حول قبتنا تخور\nمن الزمرات أسبل قادماها ... وضرتها مركنة درور\nلعمرك! إن قابوس بن هند ... ليخلط ملكه نوك كثير\nقسمت الدهر في زمن رخي ... كذاك الحكم يقصد أو يجور\nفلما قال عمرو بن هند لعبد عمرو ما قال طرفة قال: أبيت اللعن! ما قال فيك أشد مما قال في، فأنشده الأبيات فقال عمرو بن هند: أوقد بلغ من أمره أن يقول في مثل هذا الشعر؟ فأمر عمرو فكتب إلى رجل من عبد القيس بالبحرين وهو المعلى ليقتله، فقال له بعض جلسائه: إنك إن قتلت طرفة هجاك المتلمس، رجل مسن مجرب، وكان حليف طرفة وكان من بني ضبيعة. فأرسل عمرو إلى طرفة والمتلمس فأتياه فكتب لهما إلى عامله بالبحرين ليقتلهما وأعطاهما هدية من عنده وحملهما وقال: قد كتبت لكما بحباء1، فأقبلا حتى نزلا الحيرة، فقال المتلمس لطرفة: تعلمن والله أن ارتياح عمرو لي ولك لأمر عندي مريب، وأن انطلاقي بصحيفة لا أدري ما فيها؟ فقال طرفة: إنك لتسيء الظن، وما نخاف من صحيفة إن كان فيها الذي وعدنا وإلا رجعنا فلم نترك منه شيئا؟ فأبى أن يجيبه إلى النظر فيها، ففك المتلمس ختمها ثم جاء إلى غلام من أهل الحيرة فقال له: أتقرأ يا غلام؟ فقال: نعم، فأعطاه الصحيفة فقرأها فقال الغلام: أنت المتلمس؟ قال: نعم، قال: النجاء! قد أمر بقتلك فأخذ الصحيفة فقذفها في البحيرة ثم أنشأ يقول: [الطويل] :\nوألقيتها بالثني من جنب كافر ... كذلك ألقي كل رأي مضلل\nرضيت لها بالماء لما رأيتها ... يجول بها التيار في كل جدول\nفقال المتلمس لطرفة: تعلمن والله أن الذي في كتابك مثل الذي في كتابي، فقال طرفة: لئن كان اجترأ عليك، ما كان بالذي يجترئ علي، وأبى أن يطيعه، فسار المتلمس من فوره ذلك حتى أتى الشام فقال في ذلك: [الكامل] :\nمن مبلغ الشعراء عن أخويهم ... نبأ فتصدقهم بذاك الأنفس\nأودى الذي علق الصحيفة منهما ... ونجا حذار حياته المتلمس\nألقى صحيفته ونجت كوره ... وجنا محمرة المناسم عرمس1\nعيرانة طبخ الهواجر لحمها ... فكأن نقبتها أديم أملس2\nوخرج طرفة حتى أتى صاحب البحرين بكتابه، فقال له صاحب البحرين: إنك في حسب كريم وبيني وبين أهلك إخاء قديم وقد أمرت بقتلك فاهرب إذا خرجت من عندي فإن كتابك إن قرئ لم أجد بدا من أن أقتلك، فأبى طرفة أن يفعله، فجعل شبان عبد القيس يدعونه ويسقونه الخمر حتى قتل.\nوقد كان قال في ذلك قصيدته التي أولها: \"لخولة أطلال\"؛ انقضى حديث طرفة برواية المفضل؛ وذكر العتبي سببا آخر في قتله، وذلك أنه كان ينادم عمرو بن هند يوما فأشرفت أخته فرأى طرفة ظلها في الجام3 الذي في يده فقال: [الهزج] :\nألا يا ثاني الظبي ... الذي يبرق شنفاه\nولولا الملك القاعد ... قد ألثمني فاه\nفحقد ذلك عليه، قال: ويقال إن اسمه عمرو وسمي طرفة ببيت قاله؛ وأمه وردة، وكان من أحدث الشعراء سنا وأقلهم عمرا، قتل وهو ابن عشرين سنة فيقال له ابن العشرين. ورأيت أنا مكتوبا في قصته في موضع آخر أنه لما قرأ العامل الصحيفة عرض عليه فقال: اختر قتلة أقتلك بها، فقال: اسقني خمرا فإذا ثملت فافصد أكحلي، ففعل حتى مات، فقبره بالبحرين، وكان له أخ يقال له معبد بن العبد فطالب بديته فأخذها من الحوافر4."},{"id":"muallaqat:103","bookId":"muallaqat","type":"section","seq":103,"chapter":"مدخل","title":"من هو طرفة","page":"ج1 ص81","text":"1؟\nلم يكن طرفة مجرد شاب غرير قال الشعر، وهو يافع، وظل يقوله حتى علق على خشب الصلب، ويد المنية تلتف حول عنقه.\nكذلك لم يكن طرفة مجرد شاعر قتله الشعر في ريعان صباه وهو ابن العشرين ربيعا.\nإنما كان طرفة نموذجا فريدا لتجربة حياتية عميقة، غنية، صادقة التمثيل لما هو عليه إنسان الجاهلية الضائع بين متطلبات عيش كثيرة يقابلها شح في الموارد كبير، وبين حياة اجتماعية شديدة الحرية ظاهرا، مكبلة عمليا بقيود العرف والعادات والتقاليد يصعب على نفس جياشة وقلب متوقد، الالتزام بها دون صدام، دون تمرد، دون كلمة احتجاج أو سخرية مرة.\nلقد اشتهر طرفة بمعلقته التي عدت ثاني معلقات الجاهلية أهمية ... وعرف طرفة بالصورة التي أعطاها عن نفسه في هذه المعلقة، صورة المظلوم يعتب على ظالميه من أهله ويتألم من جفوتهم، في حين لا يريد لهم إلا الخير، ويقدم لهم شعره وسيفه يذودان عنهم ويطعنان في أعدائهم؛ وصورة الشاب المقبل على الحياة يعب منها وكأنه مع العمر في سباق، أو كأنه استشعر قصر العمر فأحب أن يستغل كل دقيقة\nمنه في استنفاد المتع"},{"id":"muallaqat:104","bookId":"muallaqat","type":"section","seq":104,"chapter":"مدخل","title":"....","page":"ج1 ص83","text":"لكن هذه الصورة تمثل جانبا واحدا من شخصية طرفة. لأن هذا الشاعر يجسد خير تجسيد عنفوان العربي وإباءه، كما يمثل تعلقه بقومه وحفاظه عليهم واستخفافه بكل كبير وإن ملكا، لثقته بأن قومه يصنعون الملوك وقد يهزون عرشا أو يدكون قصرا."},{"id":"muallaqat:105","bookId":"muallaqat","type":"section","seq":105,"chapter":"مدخل","title":"حياة طرفة في سطور","page":"ج1 ص84","text":"- ولد طرفة بن العبد حوالي عام: 543م، لأب بكري وأم غير بكرية.\nاسمه الحقيقي عمرو. وطرفه لقب غلب عليه ببيت قاله وهو:\nلا تعجلا بالبكاء اليوم مطرفا ... ولا أميريكما بالدار إذ وقفا\n- توفي والده وهو صغير.\n- حاول أعمامه وضع يدهم على إرث والده فهجاهم، فحذروه.\n- راح ينفق على لهوه وملذاته وعلى رفقة السوء بلا حساب، فزجره أهله. وإذ لم يمتنع تحاشوه وابتعدوا عن التعامل معه.\n- حين أفلس وافتقر توجه إلى أهله فخذلوه.\n- انطلق في الأرض يسعى بحثا عن غنى سريع لم يحصل عليه.\n- عاد إلى أهله متبرما بحياة التشرد، قانعا بالعمل لأخيه معبد راعيا لإبله.\n- أنشد معلقته وذكر فيها بالخير قيس بن خالد وعمرو بن مرثد، فمدحهما بكثرة المال والولد. فقاسمه عمرو بن مرثد ماله ومال أولاده.\n- رد إبل أخيه وأنفق ما تبقى له.\n- افتقر من جديد وعاد يبحث عن غنى سريع.\n- قصد عمرو بن هند ملك الحيرة وأخاه قابوسا.\n- نادمهما كما كان يفعل صهره عبد عمرو بن بشر، ومدحهما كما كان يفعل خاله المتلمس.\n- في لحظة طيش وعجرفة هجاهما هو وخاله، فوصلهما الهجاء في قصة طويلة.\n- صمم الملك على الانتقام من الشاعرين طويلي اللسان، فأرسلهما إلى عامله في البحرين مع رسالة بيد كل منهما أقنعهما أنها أمر لعامله بمكافأتهما.\n- شك المتلمس في فحوى الكتاب وعرضه على صبي يقرأ من صبيان الحيرة، فعرف أنه أمر للعامل بقتله، لا بإجازته، فألقى كتابه وفر.\n- لم يفعل طرفة فعل خاله، معتقدا أن الملك لا يجرؤ على الغدر ببكري بين أهله.\n- لكن الملك غدر، وأودى بطرفة غروره فسعى إلى حتفه بظلفه.\n- تلقى عامل البحرين، ربيعة بن الحارث العبد، كتاب الملك وأطلع طرفة على ما فيه معطيا إياه فرصة للهرب. لكن طرفة رفض الهرب ولم يصدق العامل وأصر على قبض الجائزة.\n- حبسه عامل البحرين ورفض تنفيذ الحكم به، فأرسل عمرو بن هند التغلبي عبد بن هند بن جرذ عاملا على البحرين وأمره بقتل العامل السابق وطرفة معا.\n- انتدب العامل الجديد رجلا من الحواثر يقال له أبو ريشة فقتله.\n- يذكر الأصفهاني أن العامل هو المكعبر، عامل البحرين وعمان، وأنه نفذ تعليمات الملك فقطع يدي طرفة ورجليه ودفنه حيا.\n- يذكر الجهشياري أن طرفة قتل مصلوبا وأنه قال قبل موته:\nمن مبلغ أحياء بكر بن وائل ... بأن ابن كعب راكب، غير راجل\nعلى ناقة لم يركب الفحل ظهرها ... مشذبة أطرافها بالمناجل\n- بعث الحواثر بدية الشاعر إلى أهله فقبلوها وذلك سبة بحق طرفة.\n- يذكر الزوزني أن العامل خيره في ميتته فقال: اسقني خمرا فإذا ثملت فأفصد كاحلي. ففعل حتى مات."},{"id":"muallaqat:106","bookId":"muallaqat","type":"section","seq":106,"chapter":"مدخل","title":"1- علاقته بالرفاق","page":"ج1 ص85","text":"علاقته بالرفاق:\nمن المعروف أن طرفة أنفق ماله الموروث إنفاق غر جاهل، مقبل على الحياة مستنفد متع اليوم، هاربا من التفكير بغد لا يضمن فيه لنفسه شيئا. وظل كذلك: ينفق عن سعة والأصدقاء يتحلقون حوله، إلى أن افتقر ونفد ماله. تلفت حواليه فوجد الأصدقاء يبتعدون والرفاق يتخلون، والأهل الذين كانوا يلومون وينصحون باتوا ناقمين متجنبين. لقد غدا وحيدا، وحيدا، فتألم وندت عنه صيحة أسى: \"أفردت إفراد البعير المعبد\". وكانت التجربة قاسية، تركت أثرا عميقا في نفسه، وتجلت في شعره."},{"id":"muallaqat:107","bookId":"muallaqat","type":"section","seq":107,"chapter":"مدخل","title":"2- علاقته بأخيه معبد","page":"ج1 ص85","text":"علاقته بأخيه معبد:\nإننا لا نعرف الكثير عن علاقة طرفة بوالده، لكن إذا صح افتراضنا أن العبد كان متزوجا من امرأة أخرى بكرية هي أم معبد، غير وردة أم طرفة، وقبل زواجه من هذه، فإن تمييزا في المعاملة، لا شك واقع بين طرفة وأخيه: فهذا بالنسبة إلى البكريين هو أصيل الجذرين، وبصفته الولد البكر يستقطب العناية ويكون له نوع من السلطة على الأخ الصغير.\nوالواقع أن طرفة، حين احتاج إلى مساعدة معبد أخيه لم يبادر هذا إلى تقديم مساعدة عفوية، بل عرض عليه عملا عنده وهو عمل غير ذي شأن ولا بمستوى طموح الشاعر، بل إنه أقرب إلى عمل السوقة والخدم والخاملين، نقصد به رعي الإبل.\nوحين أحس معبد من أخيه تقصيرا في رعاية إبله، وانشغالا عنها بالركض خلف القوافي الشاردة، قرعه وأنبه وهدده بأنه لن يتهاون معه إذا فقدت الإبل، وأن الشعر لن تكون له أدنى شفاعة عنده.\nوحين فقدت الإبل، لم يتهاون معبد مع الشاعر، بل حقق فعلا تهديده وتطلب إعادة إبله بأية وسيلة: لم يرق، ولم يسامح كما يفعل الأخ، ولم يقدم قط مساعدة بل بقي متفرجا مع المتفرجين منتظرا شأن الأغراب البعداء.\nووجد طرفة نفسه يدق الأبواب ويسعى إلى باب كل جواد كريم من عائلته طلبا لعون، ولا عون. ليس إلا اللوم والتقريع والتهرب.\nويجد طرفة نفسه مرة أخرى فريسة للأسى والتخلي، ويأسف على أنه لم يكن من ذوي اليسار ولا من السادة الكثيري الخير، الكثيري الولد، ويتمنى لو أنه كان قيس بن خالد أو عمرو بن مرثد.\nويسمع السيدان الكريمان بالأمنية، فيعدانها مدحا يتوجب عليهما إثابته فيثيبان.\nهكذا ابتسم الحظ لطرفة إذ وجد من يقبض عملة الشعر ويقايضها بالإبل، فخامره الزهو بموهبته الشعرية إذ غدت رأسمالا مؤكد الربح ... رد الإبل لمعبد وبقي له منها ما يغذي مرحلة جديدة من اللهو والإنفاق والتبذير، إلى أن يفتقر] ."},{"id":"muallaqat:108","bookId":"muallaqat","type":"section","seq":108,"chapter":"مدخل","title":"1- لخولة أطلال ببرقة ثهمد","page":"ج1 ص87","text":"لخولة أطلال ببرقة ثهمد ... تلوح كباقي الوشم في ظاهر اليد\nخولة: اسم امرأة كلبية، ذكر ذلك هشام بن الكلبي. الطلل: ما شخص من رسوم الدار، والجمع أطلال وطلول، البرقة والأبرق والبرقاء: مكان اختلط ترابه بحجارة أو حصى، والجمع الأبارق والبراق والبرق والبرقاوات، إذا حمل على معنى البقعة أو الأرض قيل البرقاء، وإذا حمل على المكان أو الموضع قيل الأبرق. ثهمد: موضع. تلوح: تلمع، واللوح اللمعان. الوشم: غرز ظاهر اليد وغيره بإبرة وحشو المغارز بالكحل أو النقش بالنيلج، والفعل منه وشم يشم وشما، ثم جعل اسما لتلك النقوش، وتجمع بالوشام والوشوم. ومنه قوله عليه الصلاة والسلام: \" لعن الله الواشمة والمستوشمة \"1 فالواشمة هي التي تشم اليد، والمستوشمة هي التي يفعل بها ذلك، ثم تبالغ فتقول: وشم يوشم توشيما إذا تكرر ذلك منه وكثر.\nيقول: لهذه المرأة أطلال ديار بالموضع الذي يخالط أرضه حجارة وحصى من ثهمد، فتلمع تلك الأطلال لمعان بقايا الوشم في ظاهر الكف، شبه لمعان آثار ديارها ووضوحها بلمعان آثار الوشم في ظاهر الكف."},{"id":"muallaqat:109","bookId":"muallaqat","type":"section","seq":109,"chapter":"مدخل","title":"2- وقوفا بها صحبي على مطيهم","page":"ج1 ص87","text":"وقوفا بها صحبي على مطيهم ... يقولون لا تهلك أسى وتجلد\nتفسير البيت هنا كتفسيره في قصيدة امرئ القيس. التجلد: تكلف الجلادة وهو التصبر."},{"id":"muallaqat:110","bookId":"muallaqat","type":"section","seq":110,"chapter":"مدخل","title":"3- كأن حدوج المالكية غدوة","page":"ج1 ص87","text":"كأن حدوج المالكية غدوة ... خلايا سفين بالنواصف من دد\nالحدج: مركب من مراكب النساء، والجمع حدوج وأحداج، والحداجة مثله، وجمعها حدائج. المالكية: منسوبة إلى بني مالك قبيلة من كلب. الخلايا: جمع الخلية وهي السفينة العظيمة. السفين: جمع سفينة، ثم يجمع السفين على السفن، وقد يكون السفين واحدا، وتجمع السفينة على السفائن. النواصف: جمع الناصفة وهي أماكن تتسع من نواحي الأودية مثال السكك وغيرها. دد، قيل: هو اسم واد في هذا البيت وقيل دد مثل يد، وددا مثل عصا، وددن مثل بدن، وهذه الثلاثة بمعنى اللهو واللعب.\nيقول: كأن مراكب العشيقة المالكية غدوة فراقها بنواحي وادي دد سفن عظام، شبه الإبل وعليها الهوادج بالسفن العظام، وقيل: بل حسبها سفنا عظاما من فرط لهوه وولهه، وهذا إذا حملت ددا على اللهو، وإن حملته على أنه واد بعينه فمعناه على القول الأول."},{"id":"muallaqat:111","bookId":"muallaqat","type":"section","seq":111,"chapter":"مدخل","title":"4- عدولية أو من سفين ابن يامن","page":"ج1 ص89","text":"عدولية أو من سفين ابن يامن ... يجور به الملاح طورا ويهتدي\nعدولي: قبيلة من أهل البحرين، وابن يامن: رجل من أهلها، وروى أبو عبيدة: ابن نبتل، وهو رجل آخر منها. الجور: العدول عن الطريق، والباء هنا للتعدية. الطور: التارة، والجمع الأطوار.\nيقول: هذه السفن التي تشبهها هذه الإبل من هذه القبيلة أو من سفن هذا الرجل، والملاح يجريها مرة على استواء واهتداء، وتارة يعدل بها فيميلها عن سنن الاستواء، وكذلك الحداة1، تارة يسوقون هذه الإبل على سمت الطريق، وتارة يميلونها عن الطريق ليختصروا المسافة، وخص سفن هذه القبيلة وهذا الرجل لعظمها وضخمها، ثم شبه سوق الإبل تارة على الطريق وتارة على غير الطريق بإجراء الملاح السفينة مرة على سمت الطريق ومرة عادلا عن ذلك السمت."},{"id":"muallaqat:112","bookId":"muallaqat","type":"section","seq":112,"chapter":"مدخل","title":"5- يشق حباب الماء حيزومها بها","page":"ج1 ص89","text":"يشق حباب الماء حيزومها بها ... كما قسم الترب المفايل باليد\nحباب الماء: أمواجه، الواحدة حبابة. الحيزوم: الصدر، والجمع: الحيازيم. الترب والتراب والترباء والتورب والتيرب والتيراب والتوراب واحد، ثم يجمع التراب\nعلى أتربة وتربان وتربات، والتربة على الترب، ذكر هذا كله ابن الأنباري. الفيال: ضرب من اللعب، وهو أن يجمع التراب فيدفن فيه شيء، ثم يقسم التراب نصفين، ويسأل عن الدفين في أيهما هو، فمن أصاب قمر ومن أخطأ قمر. يقال: فايل هذا الرجل يفايل مفايلة وفيالا إذا لعب بهذا الضرب من اللعب، شبه شق السفن الماء بشق المفايل التراب المجموع بيده."},{"id":"muallaqat:113","bookId":"muallaqat","type":"section","seq":113,"chapter":"مدخل","title":"6- وفي الحي أحوى ينفض المرد شادن","page":"ج1 ص90","text":"وفي الحي أحوى ينفض المرد شادن ... مظاهر سمطي لؤلؤ وزبرجد\nالأحوى: الذي في شفتيه سمرة، والأنثى الحواء، والجمع الحو. وأيضا الأحوى ظبي في لونه حوة، والشادن أحوى لشدة سواد أجفانه ومقلتيه، قال الأصمعي: الحوة: حمرة تضرب إلى السواد، يقال: حوي الفرس مال إلى السواد، فعلى هذا شادن صفة أحوى، وقيل: بدل من أحوى، وينفض المرد صفة أحوى. الشادن: الغزال الذي قوي واستغنى عن أمه. المظاهر الذي لبس ثوبا فوق ثوب أو درعا فوق درع أو عقدا فوق عقد. السمط: الخيط الذي نظمت فيه الجواهر والجمع سموط.\nيقول: وفي الحي حبيب يشبه ظبيا أحوى في كحل العينين وسمرة الشفتين في حال نفض الظبي ثمر الأراك؛ لأنه يمد عنقه في تلك الحال، ثم صرح بأنه يريد إنسانا، وقال: قد لبس عقدين أحدهما من اللؤلؤ والآخر من الزبرجد، شبهه بالظبي في ثلاثة أشياء: في كحل العينين، وحوة الشفتين، وحسن الجيد1، ثم أخبر أنه متحل بعقدين من لؤلؤ وزبرجد."},{"id":"muallaqat:114","bookId":"muallaqat","type":"section","seq":114,"chapter":"مدخل","title":"7- خذول تراعي ربربا بخميلة","page":"ج1 ص90","text":"خذول تراعي ربربا بخميلة ... تناول أطراف البرير وترتدي\nخذول: أي خذلت أولادها. تراعي ربربا. أي ترعى معه. الربرب: القطيع من الظباء وبقر الوحش. الخميلة: رملة منبتة، قال الأصمعي: هي أرض ذات شجر، والجمع الخمائل. البرير: ثمر الأراك المدرك البالغ، الواحدة بريرة، الارتداء والتردي: لبس الرداء.\nيقول: هذه الظبية التي أشبهها الحبيب ظبية خذلت أولادها وذهبت مع صواحبها في قطيع من الظباء ترعى معها في أرض ذات شجر أو ذات رملة منبتة تتناول أطراف الأراك وترتدي بأغصانه، وإنما خص تلك الحال لمدها عنقها إلى ثمر الشجرة، شبه طول عنق الحبيب وحسنه بذلك."},{"id":"muallaqat:115","bookId":"muallaqat","type":"section","seq":115,"chapter":"مدخل","title":"8- وتبسم عن ألمى كأن منورا","page":"ج1 ص91","text":"وتبسم عن ألمى كأن منورا ... تخلل حر الرمل دعص له ند\nالألمى: الذي يضرب لون شفتيه إلى السواد، والأنثى لمياء، والجمع لمي، والمصدر اللمى، والفعل لمي يلمى. البسم والتبسم والابتسام واحد. كأن منورا يعني أقحوانا منورا، فحذف الموصوف اجتزاء بدلالة الصفة عليه. نور النبت إذا خرج نوره فهو منور. حر كل شيء: خالصه. الدعص: الكثيب من الرمل، والجمع الأدعاص. الندى يكون دون الابتلال، والفعل ندي يندى ندى، ونديته تندية.\nيقول: وتبسم الحبيبة عن ثغر ألمى الشفتين كأنه أقحوان خرج نوره في دعص ند يكون ذلك الدعص فيما بين رمل خالص لا يخالطه تراب، وإنما جعله نديا ليكون الأقحوان غضا ناضرا، شبه به ثغرها وشرط لمى الشفتين ليكون أبلغ في بريق الثغر. وشرط كون الأقحوان في دعص ند لما ذكرنا، وتقدير الكلام كأن به أقحوانا منورا تخلل دعص له ند حر الرمل ثغرها، فحذف الخبر."},{"id":"muallaqat:116","bookId":"muallaqat","type":"section","seq":116,"chapter":"مدخل","title":"9- سقته إياة الشمس إلا لثاته","page":"ج1 ص91","text":"سقته إياة الشمس إلا لثاته ... أسف ولم تكدم عليه بإثمد\nإياة الشمس وإياها: شعاعها. اللثة: مغرز الأسنان، والجمع اللثات. الإسفاف: إفعال من سففت الشيء أسفه سفا. الإثمد: الكحل. الكدم: العض. ثم وصف ثغرها فقال: سقاه شعاع الشمس، أي: كأن الشمس أعارته ضوءها. ثم قال: إلا لثاته، يستثني اللثات؛ لأنه لا يستحب بريقها. ثم قال: أسف عليه الإثمد، أي ذر الإثمد على اللثة، ولم تكدم بأسنانها على شيء يؤثر فيها، وتقديره: أسف بإثمد ولم تكدم عليه بشيء. ونساء العرب تذر الإثمد على الشفاه واللثات فيكون ذلك أشد للمعان الأسنان."},{"id":"muallaqat:117","bookId":"muallaqat","type":"section","seq":117,"chapter":"مدخل","title":"10- ووجه كأن الشمس ألقت رداءها","page":"ج1 ص91","text":"ووجه كأن الشمس ألقت رداءها ... عليه نقي اللون لم يتخدد\nالتخدد: التشنج والتغضن.\nيقول: وتبسم عن وجه كأن الشمس كسته ضياءها وجمالها، فاستعار لضياء الشمس اسم الرداء ثم ذكر أن وجهها نقي اللون غير متشنج متغضن، وصف وجهها بكمال الضياء والنقاء والنضارة، وجر الوجه عطفا على ألمى."},{"id":"muallaqat:118","bookId":"muallaqat","type":"section","seq":118,"chapter":"مدخل","title":"11- وإني لأمضي الهم عند احتضاره","page":"ج1 ص92","text":"وإني لأمضي الهم عند احتضاره ... بعوجاء مرقال تروح وتغتدي\nالاحتضار والحضور واحد. العوجاء: الناقة التي لا تستقيم في سيرها لفرط نشاطها. المرقال: مبالغة مرقل من الإرقال: وهو بين السير والعدو.\nيقول: وإني لأمضي همي وأنفذ إرادتي عند حضورها بناقة نشيطة في سيرها تخب1 خببا وتذمل2 ذميلا في رواحها واغتدائها، يريد أنها تصل سير الليل بسير النهار، وسير النهار بسير الليل؛ يقول: وإني لأنفذ همي عند حضوره بإتعاب ناقة مسرعة في سيرها."},{"id":"muallaqat:119","bookId":"muallaqat","type":"section","seq":119,"chapter":"مدخل","title":"12- أمون كألواح الإران نضأتها","page":"ج1 ص92","text":"أمون كألواح الإران نضأتها ... على لاحب كأنه ظهر برجد\nالأمون: التي يؤمن عثارها. الإران: التابوت العظيم. نصأتها، بالصاد: زجرتها ونسأتها، بالسين، أي: ضربتها بالمنسأة، وهي العصا. اللاحب: الطريق الواضح. البرجد: كساء مخطط.\nيقول: هذه الناقة الموثقة الخلق يؤمن عثارها في سيرها وعدوها وعظامها كألواح التابوت العظيم ضربتها بالمنسأة على طريق واضح كأنه كساء مخطط في عرضه. يريد أنه يمضي همه بناقة موثقة الخلق يؤمن عثارها. ثم شبه عرض عظامها بألواح التابوت، ثم ذكر سوقه إياها بالعصا، ثم شبه الطريق بالكساء المخطط؛ لأن فيه أمثال الخطوط العجيبة."},{"id":"muallaqat:120","bookId":"muallaqat","type":"section","seq":120,"chapter":"مدخل","title":"13- جمالية وجناء تردي كأنها","page":"ج1 ص92","text":"جمالية وجناء تردي كأنها ... سفنجة تبري لأزعر أربد\nالجمالية: الناقة التي تشبه الجمل في وثاقة الخلق. الوجناء: المكتنزة اللحم،\nأخذت من الوجين وهي الأرض الصلبة، والوجناء العظيمة الوجنات أيضا. الرديان: عدو الحمار بين متمرغه وآريه1, هذا هو الأصل ثم يستعار للعدو، والفعل ردى يردي. السفنجة: النعامة. تبري: تعرض، والبري والانبراء واحد وكذلك التبري. الأزعر: القليل الشعر. الأربد: الذي لونه لون الرماد.\nيقول: أمضي همي بناقة تشبه الجمل في وثاقة الخلق مكتنزة اللحم تعدو كأنها نعامة تعرض لظليم2 قليل الشعر يضرب لونه إلى لون الرماد. شبه عدوها بعدو النعامة في هذه الحال."},{"id":"muallaqat:121","bookId":"muallaqat","type":"section","seq":121,"chapter":"مدخل","title":"14- تباري عتاقا ناجيات وأتبعت","page":"ج1 ص93","text":"تباري عتاقا ناجيات وأتبعت ... وظيفا وظيفا فوق مور معبد\nباريت الرجل: فعلت مثل فعله مغالبا له. العتاق: جمع عتيق: وهو الكريم. الناجيات: المسرعات في السير، نجا ينجو نجا ونجاء أي: أسرع في السير. الوظيف: ما بين الرسغ إلى الركبة وهو وظيف كله. المور: الطريق. المعبد: المذلل، والتعبيد: التذليل والتأثير.\nيقول: هي تباري إبلا كراما مسرعات في السير وتتبع وظيف رجلها وظيف يدها فوق طريق مذلل بالسلوك والوطء بالأقدام والحوافر والمناسم في السير."},{"id":"muallaqat:122","bookId":"muallaqat","type":"section","seq":122,"chapter":"مدخل","title":"15- تربعت القفين في الشول ترتعي","page":"ج1 ص93","text":"تربعت القفين في الشول ترتعي ... حدائق مولي الأسرة أغيد\nالتربع: رعي الربيع والإقامة بالمكان واتخاذه ربعا. القف: ما غلظ من الأرض وارتفع لم يبلغ أن يكون جبلا، والجمع قفاف. الشول: النوق التي جفت ضروعها وقلت ألبانها، الواحدة شائلة، بالتاء لا غير. وأما الشول جمع شائل، من شال البعير بذنبه إذا رفعه، يشول شولا، ويقال: ناقة شائل وجمل شائل. والشول: الارتفاع، ويعدى بالباء، والإشالة: الرفع. الارتعاء: الرعي، إذا اقتصر على مفعول واحد عنى الرعي. الحدائق: جمع حديقة وهي كل روضة ارتفعت أطرافها وانخفض وسطها. الحديقة: البستان أيضا، سميت بها لإحداق الحائط بها، والإحداق الإحاطة.\nالمولي: الذي أصابه الولي وهو المطر الثاني من أمطار السنة، سمي به لأنه يلي الأول، والأول الوسمي، سمي به لأنه يسم الأرض بالنبات، يقال: ولي المكان يولى فهو مولي إذا مطر الولي. سر الوادي وسرارته. خيره وأفضله كلأ، والجمع الأسرة والسرار. الأغيد: الناعم الخلق، وتأنيثه غيداء، والجمع الغيد، ومصدره الغيد.\nيقول: قد رعت هذه الناقة أيام الربيع كلأ القفين، وأراد بهما قفين معروفين، بين نوق جفت ضروعها وقلت ألبانها، ترعى هي حدائق واد قد وليت أسرتها وهو مع ذلك ناعم التربة، وصف الناقة برعيها أيام الربيع ليكون ذلك أوفر للحمها وأشد تأثيرا في سمنها، ثم وصفها بأنها كانت في صواحب لها، وهي إذا رأت صواحبها ترعى كان ذلك أدعى إلى الرعي، ثم وصف مرعاها بأنه في واد اعتادته الأمطار وهو مع ذلك طيب التربة، وقوله: حدائق مولي الأسرة، تقديره وحدائق واد مولي الأسرة فحذف الموصوف ثقة بدلالة الصفة عليه."},{"id":"muallaqat:123","bookId":"muallaqat","type":"section","seq":123,"chapter":"مدخل","title":"16- تريع إلى صوت المهيب وتتقي","page":"ج1 ص94","text":"تريع إلى صوت المهيب وتتقي ... بذي خصل روعات أكلف ملبد\nالريع: الرجوع، والفعل راع، يريع. الإهابة: دعاء الإبل وغيرها، يقال: أهاب ناقته إذا دعاها. الاتقاء: الحجز بين شيئين، يقال: اتقى قرنه بترسه إذا جعل حاجزا بينه وبينه، وقوله: بذي خصل، أراد بذنب ذي خصل، فحذف الموصوف اكتفاء بدلالة الصفة عليه، والخصل جمع خصلة من الشعر وهي قطعة منه. الروع: الإفزاع، والروعة فعلة منه، وجمعها الروعات. الأكلف. الذي يضرب إلى السواد. الملبد: ذو وبر متلبد من البول والثلط1 وغيره. روعات أكلف أي: روعات فحل أكلف، فحذف الموصوف.\nيقول: هي ذكية القلب ترجع إلى راعيها وتجعل ذنبها حاجزا بينها وبين فحل تضرب حمرته إلى السواد متلبد الوبر، يريد أنها لا تمكنه من ضرابها2 وإذا لم يصل الفحل إلى ضرابها لم تلقح، وإذا لم تلقح كانت مجتمعة القوى وافرة اللحم قوية على السير والعدو."},{"id":"muallaqat:124","bookId":"muallaqat","type":"section","seq":124,"chapter":"مدخل","title":"17- كأن جناحي مضرحي تكنفا","page":"ج1 ص95","text":"كأن جناحي مضرحي تكنفا ... حفافيه شكا في العسيب بمسرد\nالمضرحي: الأبيض من النسور، وقيل: هو العظيم منها. التكنف: الكون في كنف الشيء وهو ناحيته. الحفاف: الجانب، والجمع الأحفة. الشك: الغرز. العسيب: عظم الذنب، والجمع العسب. والمسرد المسراد: الإشفى1، والجمع المسارد والمساريد.\nيقول: كأن جناحي نسر أبيض غرزا بإشفى في عظم ذنبها فصارا في ناحية، شبه شعر ذنبها بجناحي نسر أبيض في الباطن."},{"id":"muallaqat:125","bookId":"muallaqat","type":"section","seq":125,"chapter":"مدخل","title":"18- فطورا به خلف الزميل وتارة","page":"ج1 ص95","text":"فطورا به خلف الزميل وتارة ... على حشف كالشن ذاو مجدد\nقوله: فطورا به، يعني فطورا تضرب بالذنب، الزميل: الرديف، الحشف: الأخلاف التي جف لبنها فتشنجت، الواحدة حشفة، وهو مستعار من حشف التمر أو من الحشيف وهو الثوب الخلق. الشن: القربة الخلق2، والجمع الشنان. الذوي: الذبول، والفعل ذوى يذوي وذوي يذوى لغة أيضا. المجدد الذي جد لبنه أي قطع.\nيقول: تارة تضرب هذه الناقة ذنبها على عجزها خلف رديف راكبها وتارة تضرب على أخلاف متشنجة خلقة كقربة بالية وقد انقطع لبنها."},{"id":"muallaqat:126","bookId":"muallaqat","type":"section","seq":126,"chapter":"مدخل","title":"19- لها فخذان أكمل النحض فيهما","page":"ج1 ص95","text":"لها فخذان أكمل النحض فيهما ... كأنهما بابا منيف ممرد\nالنحض: اللحم. وقوله بابا منيف، أي: بابا قصر منيف، فحذف الموصوف والمنيف: العالي، والإنافة العلو. الممرد: المملس، من قولهم: وجه أمرد وغلام أمرد لا شعر عليه، وشجرة مرداء لا ورق لها، والممرد المطول أيضا، وقد أول قوله تعالى: {صرح ممرد من قوارير} [النمل: 44] بهما.\nيقول: لهذه الناقة فخذان أكمل لحمهما فشابها مصراعي باب قصر عال مملس أو مطول في العرض"},{"id":"muallaqat:127","bookId":"muallaqat","type":"section","seq":127,"chapter":"مدخل","title":"20- وطي محال كالحني خلوفه","page":"ج1 ص95","text":"وطي محال كالحني خلوفه ... وأجرنة لزت بدأي منضد\nمن دلاء الدالجين الأقوياء، شبهها بسقاء حمل دلوين إحداهما بيمناه والأخرى بيسراه فبانت يداه عن جنبيه، شبه بعد مرفقيها عن جنبيها ببعد هاتين الدلوين عن جنبي حاملهما القوي الشديد."},{"id":"muallaqat:128","bookId":"muallaqat","type":"section","seq":128,"chapter":"مدخل","title":"23- كقنطرة الرومي أقسم ربها","page":"ج1 ص96","text":"كقنطرة الرومي أقسم ربها ... لتكتنفن حتى تشاد بقرمد\nالقرمد: الآجر وقيل هو الصاروج1، الواحدة قرمدة. الاكتناف: الكون في أكناف الشيء وهي نواحيه، شبه الناقة في تراصف عظامها وتداخل أعضائها بقنطرة تبنى لرجل رومي قد حلف صاحبها ليحاطن بها حتى ترفع أو تجصص بالصاروج أو بالآجر. الشيد: الرفع والطالي بالشيد وهو الجص. قوله: كقنطرة الرومي، أي كقنطرة الرجل الرومي وقوله لتكتنفن، أي والله لتكتنفن."},{"id":"muallaqat:129","bookId":"muallaqat","type":"section","seq":129,"chapter":"مدخل","title":"24- صهابية العثنون موجدة القرا","page":"ج1 ص96","text":"صهابية العثنون موجدة القرا ... بعيدة وخد الرجل موارة اليد\nالعثنون: شعرات تحت لحيها الأسفل. يقول: فيها صهبة أي: حمرة. القرا: الظهر، والجمع الأقراء. الموجدة: المقواة، والإيجاد التقوية، ومنه قولهم: بعير أجد، أي: شديد الخلق قوي. الوخد والوخدان والوخيد: الذميل2، والفعل وخد يخد. المور: الذهاب والمجيء. والموارة مبالغة المائرة، وقد مارت تمور مورا فهي مائرة.\nيقول: في عثنونها صهبة وفي ظهرها قوة وشدة، ويبعد ذميل رجليها ومور يديها في السير، ويجوز جر صهابية العثنون على الصفة لعوجاء. ويجوز رفعها على أنه خبر مبتدأ محذوف تقديره: هي صهابية العثنون."},{"id":"muallaqat:130","bookId":"muallaqat","type":"section","seq":130,"chapter":"مدخل","title":"25- أمرت يداها فتل شزر وأجنحت","page":"ج1 ص96","text":"أمرت يداها فتل شزر وأجنحت ... ألها عضداها في سقيف مسند\nالإمرار: إحكام الفتل. الفتل الشزر: ما أدير عن الصدر، والنظر الشزر والطعن الشزر، ما كان في أحد الشقين. الإجناح: الإمالة، والجنوح الميل، السقف والسقيف واحد والجمع السقف. المسند: الذي أسند بعضه إلى بعض.\nمن دلاء الدالجين الأقوياء، شبهها بسقاء حمل دلوين إحداهما بيمناه والأخرى بيسراه فبانت يداه عن جنبيه، شبه بعد مرفقيها عن جنبيها ببعد هاتين الدلوين عن جنبي حاملهما القوي الشديد."},{"id":"muallaqat:131","bookId":"muallaqat","type":"section","seq":131,"chapter":"مدخل","title":"23- كقنطرة الرومي أقسم ربها","page":"ج1 ص97","text":"كقنطرة الرومي أقسم ربها ... لتكتنفن حتى تشاد بقرمد\nالقرمد: الآجر وقيل هو الصاروج1، الواحدة قرمدة. الاكتناف: الكون في أكناف الشيء وهي نواحيه، شبه الناقة في تراصف عظامها وتداخل أعضائها بقنطرة تبنى لرجل رومي قد حلف صاحبها ليحاطن بها حتى ترفع أو تجصص بالصاروج أو بالآجر. الشيد: الرفع والطالي بالشيد وهو الجص. قوله: كقنطرة الرومي، أي كقنطرة الرجل الرومي وقوله لتكتنفن، أي والله لتكتنفن."},{"id":"muallaqat:132","bookId":"muallaqat","type":"section","seq":132,"chapter":"مدخل","title":"24- صهابية العثنون موجدة القرا","page":"ج1 ص97","text":"صهابية العثنون موجدة القرا ... بعيدة وخد الرجل موارة اليد\nالعثنون: شعرات تحت لحيها الأسفل. يقول: فيها صهبة أي: حمرة. القرا: الظهر، والجمع الأقراء. الموجدة: المقواة، والإيجاد التقوية، ومنه قولهم: بعير أجد، أي: شديد الخلق قوي. الوخد والوخدان والوخيد: الذميل2، والفعل وخد يخد. المور: الذهاب والمجيء. والموارة مبالغة المائرة، وقد مارت تمور مورا فهي مائرة.\nيقول: في عثنونها صهبة وفي ظهرها قوة وشدة، ويبعد ذميل رجليها ومور يديها في السير، ويجوز جر صهابية العثنون على الصفة لعوجاء. ويجوز رفعها على أنه خبر مبتدأ محذوف تقديره: هي صهابية العثنون."},{"id":"muallaqat:133","bookId":"muallaqat","type":"section","seq":133,"chapter":"مدخل","title":"25- أمرت يداها فتل شزر وأجنحت","page":"ج1 ص97","text":"أمرت يداها فتل شزر وأجنحت ... ألها عضداها في سقيف مسند\nالإمرار: إحكام الفتل. الفتل الشزر: ما أدير عن الصدر، والنظر الشزر والطعن الشزر، ما كان في أحد الشقين. الإجناح: الإمالة، والجنوح الميل، السقف والسقيف واحد والجمع السقف. المسند: الذي أسند بعضه إلى بعض.\nيقول: فتلت يداها فتلا بعدتا به عن كركرتها1، وأميلت عضداها تحت جنبين كأنهما سقف أسند بعض لبنه إلى بعض."},{"id":"muallaqat:134","bookId":"muallaqat","type":"section","seq":134,"chapter":"مدخل","title":"26- جنوح دفاق عندل ثم أفرعت","page":"ج1 ص98","text":"جنوح دفاق عندل ثم أفرعت ... لها كتفاها في معالى مصعد\nالجنوح مبالغة الجانحة: وهي التي تميل في أحد الشقين لنشاطها في السير. الدفاق: المندفقة في سيرها أي المسرعة غاية الإسراع. العندل: العظيمة الرأس. الإفراع: التعلية، يقال: فرعت الجبل أفرعه فرعا إذا علوته، وتفرعته أيضا وأفرعته غيري أي: جعلته يعلوه، المعالاة والإعلاء والتعلية واحد، والتصعيد مثلها.\nيقول: هذه الناقة شديدة الميلان عن سمت الطريق لفرط نشاطها في السير مسرعة غاية الإسراع عظيمة الرأس، وقد عليت كتفاها في خلق معالي مصعد. وقوله: في معالى، يريد في خلق معالى أو ظهر معالى، فحذف الموصوف اجتزاء بدلالة الصفة عليه. ويجوز في الجنوح الرفع والجر على ما مر."},{"id":"muallaqat:135","bookId":"muallaqat","type":"section","seq":135,"chapter":"مدخل","title":"27- كأن علوب النسع في دأياتها","page":"ج1 ص98","text":"كأن علوب النسع في دأياتها ... موارد من خلقاء في ظهر قردد\nالعلب: الأثر، والجمع العلوب، وقد علبت الشيء علبا إذا أثرت فيه. والنسع: سير كهيئة العنان تشد به الأحمال، وكذلك النسعة، والجمع الأنساع والنسوع والنسع. الموارد: جمع المورد وهو الماء الذي يورد. الخلقاء: الملساء، والأخلق الأملس، وأراد من خلقاء، أي من صخرة خلقاء، فحذف الموصوف. القردد: الأرض الغليظة الصلبة التي فيها وهاد2 ونجاد3.\nيقول: كأن آثار النسع في ظهر هذه الناقة وجنبيها نقر فيها ماء من صخرة ملساء في أرض غليظة متعادية فيها وهاد ونجاد. شبه آثار النسع أو الأنساع بالنقر التي فيها الماء في بياضها. وجعل جنبها صلبا كالصخرة الملساء، وجعل خلقها في الشدة والصلابة كالأرض الغليظة."},{"id":"muallaqat:136","bookId":"muallaqat","type":"section","seq":136,"chapter":"مدخل","title":"28- تلاقى وأحيانا تبين كأنها","page":"ج1 ص99","text":"تلاقى وأحيانا تبين كأنها ... بنائق غر في قميص مقدد"},{"id":"muallaqat:137","bookId":"muallaqat","type":"section","seq":137,"chapter":"مدخل","title":"29- وأتلع نهاض إذا صعدت به","page":"ج1 ص99","text":"وأتلع نهاض إذا صعدت به ... كسكان بوصي بدجلة مصعد\nالأتلع: الطويل العنق. النهاض: مبالغة الناهض. البوصي: ضرب من السفن، السكان: ذنب السفينة.\nيقول: هي طويلة العنق فإذا رفعت عنقها أشبه ذنب سفينة في دجلة تصعد. قوله: إذا صعدت به أي: بالعنق، والباء للتعدية، جعل عنقها طويلا سريع النهوض ثم شبهه في الارتفاع والانتصاب بسكان السفينة في حال جريها في الماء."},{"id":"muallaqat:138","bookId":"muallaqat","type":"section","seq":138,"chapter":"مدخل","title":"30- وجمجمة مثل العلاة كأنما","page":"ج1 ص99","text":"وجمجمة مثل العلاة كأنما ... وعى الملتقى منها إلى حرف مبرد\nالوعي: الحفظ والاجتماع والانضمام، وهو في البيت على المعنى الثاني. الحرف: الناحية، والجمع الأحرف والحروف.\nيقول: ولها جمجمة تشبه العلاة في الصلابة فكأنما انضم طرفها إلى حد عظم يشبه المبرد في الحدة والصلابة. الملتقى: موضع الالتقاء وهو طرف الجمجمة لأنه يلتقي به فراش الرأس1."},{"id":"muallaqat:139","bookId":"muallaqat","type":"section","seq":139,"chapter":"مدخل","title":"31- وخذ كقرطاس الشآمي ومشفر","page":"ج1 ص99","text":"وخذ كقرطاس الشآمي ومشفر ... كسبت اليماني قده لم يحرد\nقوله: كقرطاس الشآمي يعني كقرطاس الرجل الشآمي، فحذف الموصوف اكتفاء بدلالة الصفة. المشفر للبعير: بمنزلة الشفة للإنسان، والجمع المشافر. السبت: جلود البقر المدبوغة بالقرظ2. وقوله: كسبت اليماني، يريد كسبت الرجل اليماني، التحريد: اضطراب القطع وتفاوته.\nشبه خدها في الانملاس بالقرطاس ومشفرها بالسبت في اللين واستقامة القطع."},{"id":"muallaqat:140","bookId":"muallaqat","type":"section","seq":140,"chapter":"مدخل","title":"32- وعينان كالماويتين استكنتا","page":"ج1 ص99","text":"وعينان كالماويتين استكنتا ... بكهفي حجاجي صخرة قلت مورد\nالماوية: المرآة. الاستكنان: طلب الكن3. الكهف: الغار. الحجاج: العظيم\nالمشرف على العين الذي هو منبت شعر الحاجب، والجمع الأحجة. القلت: النقرة في الجبل يستنقع فيها الماء، والجمع القلات. المورد: الماء هنا.\nيقول: لها عينان تشبهان مرآتين في الصفاء والنقاء والبريق, وتشبهان ماء في القلت في الصفاء، وشبه عينيها بكهفين في غؤورهما، وحجاجيها بالصخرة في الصلابة. قول: حجاجي صخرة أي: حجاجين من صخرة كقولهم: باب حديد أي: باب من حديد."},{"id":"muallaqat:141","bookId":"muallaqat","type":"section","seq":141,"chapter":"مدخل","title":"33- طحوران عوار القذى فتراهما","page":"ج1 ص100","text":"طحوران عوار القذى فتراهما ... كمكحولتي مذعورة أم فرقد\nالطرح والطحر1 والدحر واحد، والطحور مبالغة الطاحر، والفعل طحر يطحر. العوار والقذى واحد، والجمع العواوير، أراد بالمكحولتين العينين, لا تكحل بقر الوحش ولكن العين محل الكحل على الإطلاق. الذعر: الإخافة، الفرقد: ولد البقر الوحشية، والجمع الفراقد.\nيقول: عيناها تطرحان وتبعدان القذى عن أنفسهما ثم شبههما بعيني بقرة وحشية لها ولد وقد أفزعها صائد أو غيره. وعين الوحشية في هذه الحالة أحسن ما تكون."},{"id":"muallaqat:142","bookId":"muallaqat","type":"section","seq":142,"chapter":"مدخل","title":"34- وصادقتا سمع التوجس للسرى","page":"ج1 ص100","text":"وصادقتا سمع التوجس للسرى ... لهجس خفي أو لصوت مندد\nالتوجس: التسمع. السرى: سير الليل. الهجس: الحركة. التنديد: رفع الصوت.\nيقول: ولها أذنان صادقتا الاستماع في حال سير الليل لا يخفى عليهما السر الخفي ولا الصوت الرفيع."},{"id":"muallaqat:143","bookId":"muallaqat","type":"section","seq":143,"chapter":"مدخل","title":"35- مؤللتان تعرف العتق فيهما","page":"ج1 ص100","text":"مؤللتان تعرف العتق فيهما ... كسامعتي شاة بحومل مفرد\nالتأليل: التحديد والتدقيق من الآلة وهي الحربة وجمعها آل وإلال، وقد أله يؤله ألا إذا طعنه بالآلة، والدقة والحدة تحمدان في آذان الإبل. العتق: الكرم والنجابة. السامعتان: الأذنان. الشاة: الثور الوحش. حومل: موضع بعينه.\nيقول: لها أذنان محددتان تحديد الآلة تعرف نجابتها فيهما، وهي كأذني ثور وحشي منفرد في الموضع المعين، وخص المفرد لأنه أشد فزعا وتيقظا واحترازا."},{"id":"muallaqat:144","bookId":"muallaqat","type":"section","seq":144,"chapter":"مدخل","title":"36- وأروع نباض أحذ ململم","page":"ج1 ص101","text":"وأروع نباض أحذ ململم ... كمرداة صخر في صفيح مصمد\nالأروع: الذي يرتاع لكل شيء لفرط ذكائه. النباض: الكثير الحركة، مبالغة النابض من نبض ينبض نبضانا. الأحذ: الخفيف السريع. الململم: المجتمع الخلق الشديد الصلب. المرداة: الصخرة التي تكسر بها الصخور. الصفيحة: الحجر العريض، والجمع الصفائح والصفيح، المصمد: المحكم الموثق.\nيقول: لها قلب يرتاع لأدنى شيء لفرط ذكائه، سريع الحركة خفيف صلب مجتمع الخلق، يشبه صخرة يكسر بها الصخور في الصلابة فيما بين أضلاع تشبه حجارة عراضا موثقة محكمة، شبه القلب بين الأضلاع بحجر صلب بين حجارة عراض. وقوله: كمرداة صخر، أي كمرداة من صخر، مثل قولهم: هذا ثوب خز. وقوله: في صفيح، أي فيما بين صفيح. والمصمد نعت للصفيح على لفظه دون معناه."},{"id":"muallaqat:145","bookId":"muallaqat","type":"section","seq":145,"chapter":"مدخل","title":"37- وأعلم مخروت من الأنف مارن","page":"ج1 ص101","text":"وأعلم مخروت من الأنف مارن ... عتيق متى ترجم به الأرض تزدد\nالأعلم: المشقوق الشفة العليا. المخروت: المثقوب، والخرت الثقب. المارن: ما لان من الأنف.\nيقول: ولها مشفر مشقوق، ومارن أنفها مثقوب، وهي عندما ترمي الأرض بأنفها ورأسها تزداد في سيرها."},{"id":"muallaqat:146","bookId":"muallaqat","type":"section","seq":146,"chapter":"مدخل","title":"38- وإن شئت لم ترقل وإن شئت أرقلت","page":"ج1 ص101","text":"وإن شئت لم ترقل وإن شئت أرقلت ... مخافة ملوي من القد محصد\nالإرقال: دون العدو وفوق السير، والإحصاد: الإحكام والتوثيق.\nيقول: هي مذللة مروضة، فإن شئت أسرعت في سيرها، وإن شئت لم تسرع مخافة سوط ملوي من القد1 موثق."},{"id":"muallaqat:147","bookId":"muallaqat","type":"section","seq":147,"chapter":"مدخل","title":"39- وإن شئت سامى واسط الكور رأسها","page":"ج1 ص101","text":"وإن شئت سامى واسط الكور رأسها ... وعامت بضبعيها نجاء الخفيدد\nالمساماة: المباراة في السمو وهو العلو. الكور: الرحل بأداته، والجمع الأكوار والكيران، وواسطه له كالقربوس1 للسرج. العوم: السباحة. والفعل: عام يعوم عوما. الضبع: العضد. النجاء: الإسراع. الخفيدد: الظليم، ذكر النعام.\nيقول: إن شئت جعلت رأسها موازيا لواسط رحلها في العلو من فرط نشاطها وجذبي زمامها إلي، وأسرعت في سيرها حتى كأنها تسبح بعضديها إسراعا مثل إسراع الظليم."},{"id":"muallaqat:148","bookId":"muallaqat","type":"section","seq":148,"chapter":"مدخل","title":"40- على مثلها أمضي إذا قال صاحبي","page":"ج1 ص102","text":"على مثلها أمضي إذا قال صاحبي ... ألا ليتني أفديك منها وأفتدي\nيقول: على مثل هذه الناقة أمضي في أسفاري حتى بلغ الأمر غايته، يقول صاحبي: ألا ليتني أفديك من مشقة هذه الشقة فأخلصك منها وأنجي نفسي."},{"id":"muallaqat:149","bookId":"muallaqat","type":"section","seq":149,"chapter":"مدخل","title":"41- وجاشت إليه النفس خوفا وخاله","page":"ج1 ص102","text":"وجاشت إليه النفس خوفا وخاله ... مصابا ولو أمسى على غير مرصد\nخاله: أي ظنه، والخيلولة الظن. المرصد: الطريق، والجمع المراصد، وكذلك المرصاد. يقول: وارتفعت نفسه أي زال قلبه عن مستقره لفرط خوفه فظنه هالكا وإن أمسى على غير الطريق.\nيقول: إن صعوبة هذه الفلوات جعلته يظن أنه هالك، وإن لم يكن على طريق يخاف قطاع الطريق."},{"id":"muallaqat:150","bookId":"muallaqat","type":"section","seq":150,"chapter":"مدخل","title":"42- إذا القوم قالوا من فتى خلت أنني","page":"ج1 ص102","text":"إذا القوم قالوا من فتى خلت أنني ... عنيت فلم أكسل ولم أتبلد\nيقول: إذا القوم قالوا من فتى يكفي مهما أو يدفع شرا؟ خلت أنني المراد بقولهم فلم أكسل في كفاية المهم ودفع الشر ولم أتبلد فيهما. وعنيت من قولهم: عنى يعني عنيا بمعنى أراد، ومنه قولهم: يعني كذا أي يريده، وأيش تعني بهذا أي أيش تريد بهذا، ومنه المعنى وهو المراد، والجمع المعاني."},{"id":"muallaqat:151","bookId":"muallaqat","type":"section","seq":151,"chapter":"مدخل","title":"43- أحلت عليها بالقطيع فأجذمت","page":"ج1 ص102","text":"أحلت عليها بالقطيع فأجذمت ... وقد خب آل الأمعز المتوقد\nالإحالة: الإقبال هنا. القطيع: السوط، الإجذام: الإسراع في السير. الآل: ما\nيرى شبه السراب طرفي النهار، والسراب ما كان نصف النهار، الأمعز: مكان يخالط ترابه حجارة أو حصى، وإذا حمل على الأرض أو البقعة قيل المعزاء، والجمع الأماعز.\nيقول: أقبلت على الناقة أضربها بالسوط، فأسرعت في السير في حال خبب آل الأماكن التي اختلطت بتربتها بالحجارة والحصى."},{"id":"muallaqat:152","bookId":"muallaqat","type":"section","seq":152,"chapter":"مدخل","title":"44- فذالت كما ذالت وليدة مجلس","page":"ج1 ص103","text":"فذالت كما ذالت وليدة مجلس ... تري ربها أذيال سحل ممدد\nالذيل: التبختر، والفعل ذال يذيل، الوليدة: الصبية والجارية، وهي في البيت بمعنى الجارية. السحل: الثوب الأبيض من القطن وغيره.\nيقول: فتبخترت هذه الناقة كما تتبختبر جارية ترقص بين يدي سيدها فتريه ذيل ثوبها الأبيض الطويل في رقصها، شبه تبخترها في السير بتبختبر الجارية في الرقص وشبه طول ذنبها بطول ذيلها."},{"id":"muallaqat:153","bookId":"muallaqat","type":"section","seq":153,"chapter":"مدخل","title":"45- ولست بحلال التلاع مخافة","page":"ج1 ص103","text":"ولست بحلال التلاع مخافة ... ولكن متى يسترفد القوم أرفد\nالحلال: مبالغة الحال من الحلول. التلعة: ما ارتفع من مسيل الماء وانخفض عن الجبال إلى قرار الأرض، والجمع التلعات والتلاع. الرفد والإرفاد. الإعانة، والاسترفاد الاستعانة.\nيقول: أنا لا أحل التلاع مخافة حلول الأضياف بي أو غزو الأعداء إياي، ولكني أعين القوم إذا استعانوا بي إما في قرى الأضياف، وإما في قتال الأعداء والحساد."},{"id":"muallaqat:154","bookId":"muallaqat","type":"section","seq":154,"chapter":"مدخل","title":"46- فإن تبغني في حلقة القوم تلقني","page":"ج1 ص103","text":"فإن تبغني في حلقة القوم تلقني ... وإن تقتنصني في الحوانيت تصطد\nالبغاء: الطلب، والفعل بغى يبغي. الحلقة تجمع على الحلق بفتح الحاء واللام، وهذا من الشواذ، وقد تجمع عى الحلق مثل بدرة1 وبدر وثلة2 وثلل. الحانوت، بيت الخمار، والجمع الحوانيت. الاصطياد: الاقتناص.\nيقول: وإن تطلبني في محفل القوم تجدني هناك، وإن تطلبني في بيوت الخمارين تصطدني هناك. يريد أن يجمع بين الجد والهزل."},{"id":"muallaqat:155","bookId":"muallaqat","type":"section","seq":155,"chapter":"مدخل","title":"47- وإن يلتق الحي الجميع تلاقني","page":"ج1 ص104","text":"وإن يلتق الحي الجميع تلاقني ... إلى ذروة البيت الشريف المصمد\nالصمد: القصد، والفعل صمد يصمد، والتصميد مبالغة الصمد.\nيقول: وإن اجتمع الحي للافتخار تلاقني أنتمي وأعتزي إلى ذروة البيت الشريف أي إلى أعلى الشرف. يريد أنه أوفاهم حظا من الحسب وأعلاهم سهما من النسب، قوله: تلاقني إلى، يريد أعتزي إلى، فحذف الفعل لدلالة الحرف عليه."},{"id":"muallaqat:156","bookId":"muallaqat","type":"section","seq":156,"chapter":"مدخل","title":"48- نداماي بيض كالنجوم وقينة","page":"ج1 ص104","text":"نداماي بيض كالنجوم وقينة ... تروح علينا بين برد ومجسد\nالندامى: جمع الندمان وهو النديم، وجمع النديم ندام وندماء، وصفهم بالبياض تلويحا إلى أنهم أحرار ولدتهم حرائر، ولم تعرف الإماء فيهم فتورثهم ألوانهن، أو وصفهم بالبياض لإشراق ألوانهم وتلألؤ غررهم في الأندية والمقامات، إذ لم يلحقهم عار يعيرون به فتتغير ألوانهم لذلك، أو وصفهم بالبياض لنقائهم من العيوب؛ لأن البياض يكون نقيا من الدرن والوسخ، أو لاشتهارهم، لأن الفرس الأغر مشهور فيما بين الخيل. والمدح بالبياض في كلام العرب لا يخرج من هذه الوجوه، القينة: الجارية المغنية، والجمع القينات والقيان. المجسد: الثوب المصبوغ بالجساد وهو الزعفران. ويقال: بل هو الثوب الذي أشبع صبغه فيكاد يقوم من إشباع صبغة، والمجسد لغة فيه، وقال جماعة من الأئمة: بل المجسد الثوب الذي يلي الجسد، والمجسد ما ذكرنا، والجمع المجاسد.\nيقول: نداماي أحرار كرام تتلألأ ألوانهم وتشرق وجوههم، ومغنية تأتينا رواحا1 لابسة بردا أو ثوبا مصبوغا بالزعفران أو ثوبا مشبع الصبغ."},{"id":"muallaqat:157","bookId":"muallaqat","type":"section","seq":157,"chapter":"مدخل","title":"49- رحيب قطاب الجيب منها رفيقة","page":"ج1 ص104","text":"رحيب قطاب الجيب منها رفيقة ... بجس الندامى بضة المتجرد\nالرحب والرحيب واحد، والفعل رحب رحبا ورحابة ورحبا، قطاب الجيب:\nمخرج الرأس منه، الغضاضة والبضاضة: نعومة البدن ورقة الجلد. والفعل غض يغض وبض يبض. المتجرد: حيث تجرد أي تعرى.\nيقول: هذه القينة واسعة الجيب لإدخال الندامى أيديهم في جيبها للمسها، ثم قال: هي رفيقة على جس الندامى إياها، وما يعرى من جسدها ناعم اللحم رقيق الجلد صافي اللون. والجس: اللمس، والفعل جس يجس جسا."},{"id":"muallaqat:158","bookId":"muallaqat","type":"section","seq":158,"chapter":"مدخل","title":"50- إذا نحن قلنا أسمعينا انبرت لنا","page":"ج1 ص105","text":"إذا نحن قلنا أسمعينا انبرت لنا ... على رسلها مطروقة لم تشدد\nأسمعينا: أي غنينا. البري والانبراء والتبري: الاعتراض للشيء والأخذ فيه. على رسلها، أي: على تؤدتها ووقارها. المطروقة: التي بها ضعف ويروى مطروفة وهي التي أصيب طرفها بشيء أي: كأنها أصيب طرفها لفتور نظرها.\nيقول: إذا سألناها الغناء عرضت تغنينا متئدة في غنائها على ضعف نغمتها لا تشدد فيها، أراد لم تتشدد فحذف إحدى التاءين استثقالا لهما في صدر الكلمة، ومثله: {تنزل الملائكة} [القدر: 4] ، {نارا تلظى} [الليل: 14] ، {فأنت عنه تلهى} [عبس: 10] وما أشبه ذلك."},{"id":"muallaqat:159","bookId":"muallaqat","type":"section","seq":159,"chapter":"مدخل","title":"51- إذا رجعت في صوتها خلت صوتها","page":"ج1 ص105","text":"إذا رجعت في صوتها خلت صوتها ... تجاوب أظآر على ربع رد\nالترجيع: ترديد الصوت وتغريده. الظئر: التي لها ولد، والجمع الأظآر، الربع من ولد الإبل: ما ولد في أول النتاج. الردى: الهلاك والفعل ردي يردى، والإرداء الإهلاك، والتردي مثل الردى.\nيقول: إذا طربت في صوتها ورددت نغمتها حسبت صوتها أصوات نوق تصيح عند جؤارها1 على هالك، شبه صوتها بصوتهن في التخزين، ويجوز أن يكون الأظآر النساء، والربع مستعار لولد الإنسان، فشبه صوتها في التحزين والترقيق بأصوات النوادب والنوائح على صبي هالك."},{"id":"muallaqat:160","bookId":"muallaqat","type":"section","seq":160,"chapter":"مدخل","title":"52- وما زال تشرابي الخمور ولذتي","page":"ج1 ص105","text":"وما زال تشرابي الخمور ولذتي ... وبيعي وإنفاقي طريفي ومتلدي\nالتشراب: الشرب، وتفعال من أوزان المصادر مثل التقتال بمعنى القتل التنقاد بمعنى النقد، الطريف والطارف: المال الحديث. التليد والتلاد والمتلد: المال القديم الموروث.\nيقول: لم أزل أشرب الخمر وأشتغل باللذات وبيع الأعلاق1 النفيسة وإتلافها حتى كأن هذه الأشياء لي بمنزلة المال المستحدث والمال الموروث، يريد أنه التزم القيام بهذه الأشياء لزوم غيره القيام باقتنائه المال وإصلاحه."},{"id":"muallaqat:161","bookId":"muallaqat","type":"section","seq":161,"chapter":"مدخل","title":"53- إلى أن تحامتني العشيرة كلها","page":"ج1 ص106","text":"إلى أن تحامتني العشيرة كلها ... وأفردت إفراد البعير المعبد\nالتحامي: التجنب والاعتزال، البعير المعبد: المذلل المطلي بالقطران، والبعير يستلذ ذلك فيذل له.\nيقول: فتجنبتني عشيرتي كما يتجنب البعير المطلي بالقطران. وأفردتني لما رأت أني لا أكف عن إتلاف المال والاشتغال باللذات."},{"id":"muallaqat:162","bookId":"muallaqat","type":"section","seq":162,"chapter":"مدخل","title":"54- رأيت بني غبراء لا ينكرونني","page":"ج1 ص106","text":"رأيت بني غبراء لا ينكرونني ... ولا أهل هذاك الطراف الممدد.\nالغبراء: صفة الأرض جعلت كالاسم لها. الطراف: البيت من الأدم2، والجمع الطروف، وكنى بتمديده من عظمه.\nيقول: لما أفردتني العشيرة رأيت الفقراء الذين لصقوا بالأرض من شدة الفقر لا ينكرون إحساني وإنعامي عليهم، ورأيت الأغنياء الذين لهم بيوت الأدم لا ينكرونني لاستطابتهم صحبتي ومنادمتي.\nيقول: إن هجرتني الأقارب وصلتني الأباعد، وهم الفقراء والأغنياء، فهؤلاء لطلب المعروف وهؤلاء لطلب العلا."},{"id":"muallaqat:163","bookId":"muallaqat","type":"section","seq":163,"chapter":"مدخل","title":"55- ألا أيهذا اللائمي أحضر الوغى","page":"ج1 ص106","text":"ألا أيهذا اللائمي أحضر الوغى ... وأن أشهد اللذات هل أنت مخلدي؟\nالوغى: أصله صوت الأبطال في الحرب ثم جعل اسما للحرب. الخلود: البقاء والفعل خلد يخلد، والإخلاد والتخليد الإبقاء.\nيقول: ألا أيها الإنسان الذي يلومني على حضور الحرب وحضور اللذات هل تخلدني إن كففت عنها؟"},{"id":"muallaqat:164","bookId":"muallaqat","type":"section","seq":164,"chapter":"مدخل","title":"56- فإن كنت لا تسطيع دفع منيتي","page":"ج1 ص107","text":"فإن كنت لا تسطيع دفع منيتي ... فدعني أبادرها بما ملكت يدي\nاسطاع يسطيع، لغة في استطاع.\nيقول: فإن كنت لا تستطيع أن تدفع موتي عني فدعني أبادر الموت بإنفاق أملاكي، يريد أن الموت لا بد منه فلا معنى للبخل بالمال وترك اللذات وامتناع الذوق."},{"id":"muallaqat:165","bookId":"muallaqat","type":"section","seq":165,"chapter":"مدخل","title":"57- ولولا ثلاث هن من عيشة الفتى","page":"ج1 ص107","text":"ولولا ثلاث هن من عيشة الفتى ... وجدك لم أحفل متى قام عودي\nالجد: الحظ والبخت، والجمع الجدود وقد جد الرجل يجد جدا فهو جديد وجد يجد جدا فهو مجدود إذا كان ذا جد، وقد أجده الله إجدادا جعله ذا جد، وقوله: وجدك قسم. الحفل المبالاة. العود جمع عائد من العيادة.\nيقول: فلولا حبي ثلاث خصال هن من لذة الفتى الكريم لم أبال متى قام عودي من عندي آيسين من حياتي، أي لم أبال متى مت."},{"id":"muallaqat:166","bookId":"muallaqat","type":"section","seq":166,"chapter":"مدخل","title":"58- فمنهن سبقي العاذلات بشربة","page":"ج1 ص107","text":"فمنهن سبقي العاذلات بشربة ... كميت متى ما تعل بالماء تزبد\nيقول: إحدى تلك الخلال أني أسبق العواذل بشربة من الخمر كميت1 اللون متى صب الماء عليها أزبدت، يريد أن يباكر شرب الخمر قبل انتباه العواذل."},{"id":"muallaqat:167","bookId":"muallaqat","type":"section","seq":167,"chapter":"مدخل","title":"59- وكري إذا نادى المضاف محنبا","page":"ج1 ص107","text":"وكري إذا نادى المضاف محنبا ... كسيد الغضا نبهته المتورد\nالكر: العطف. والكرور: الانعطاف. المضاف: الخائف والمذعور، والمضاف الملجأ. المحنب: الذي في يده انحناء، والمجنب الذي في رجله انحناء. السيد: الذئب والجمع السيدان. الغضا: شجر. الورد والتورد واحد.\nيقول: والخصلة الثانية عطفي -إذا ناداني الملجأ إلي والخائف عدوه مستغيثا إياي- فرسا في يده انحناء، يسرع في عدوه إسراع ذئب يسكن فيما بين الغضا إذا نبهته وهو يريد الماء، جعل الخصلة الثانية إغاثته المستغيث وإعانته اللاجئ إليه فقال:\nأعطف في إغاثته فرسي الذي في يده انحناء وهو محمود في الفرس إذا لم يفرط، ثم شبه فرسه بذئب اجتمع له ثلاث خلال: إحداها كونه فيما بين الغضا، وذئب الغضا أخبث الذئاب، والثانية إثارة الإنسان إياه، والثالثة وروده الماء، وهما يزيدان في شدة العدو."},{"id":"muallaqat:168","bookId":"muallaqat","type":"section","seq":168,"chapter":"مدخل","title":"60- وتقصير يوم الدجن والدجن معجب","page":"ج1 ص108","text":"وتقصير يوم الدجن والدجن معجب. ... ببهكنة تحت الطراف المعمد\nقصرت الشيء: جعلته قصيرا. الدجن: إلباس الغيم آفاق السماء. البهكنة: المرأة الحسنة الخلق السمينة الناعمة. المعمد: المرفوع بالعمد.\nيقول: والخصلة الثالثة أني أقصر يوم الغيم بالتمتع بامرأة ناعمة حسنة الخلق تحت بيت مرفوع بالعمد، وجعل الخصلة الثالثة استمتاعه بحبائبه، وشرط تقصير اليوم؛ لأن أوقات اللهو والطرب أقصر الأوقات؛ ومنه قول الشاعر؛ [الوافر] :\nشهور ينقضين وما شعرنا ... بأنصاف لهن ولا سرار\nوقوله: والدجن معجب أي: يعجب الإنسان."},{"id":"muallaqat:169","bookId":"muallaqat","type":"section","seq":169,"chapter":"مدخل","title":"61- كأن البرين والدماليج علقت","page":"ج1 ص108","text":"كأن البرين والدماليج علقت ... على عشر أو خروع لم يخضد\nالبرة: حلقة من صفر أو شبه أو غيرهما تجعل في أنف الناقة، والجمع البرا والبرات والبرون في الرفع والبرين في النصب والجر، استعارة للأسورة والخلاخيل. الدملج والدملوج: المعضد1، والجمع الدماليج والدمالج. العشر والخروع: ضربان من الشجر. التخضيد: التشذيب من الأغصان والأوراق. والعشر وصف البهكنة.\nيقول: كأن خلاخيلها وأسورتها ومعاضدها معلقة على أحد هذين الضربين من الشجر، وجعله غير مخضد ليكون أغلظ، شبه ساعديها وساقيها بأحد هذين الشجرين في الامتلاء والنعمة والضخامة."},{"id":"muallaqat:170","bookId":"muallaqat","type":"section","seq":170,"chapter":"مدخل","title":"62- كريم يروي نفسه في حياته","page":"ج1 ص108","text":"كريم يروي نفسه في حياته ... ستعلم إن متنا غدا أينا الصدي\nيقول: أنا كريم يروي نفسه أيام حياته بالخمر، ستعلم إن متنا غدا أينا العطشان، يريد أنه يموت ريان وعاذله يموت عطشان."},{"id":"muallaqat:171","bookId":"muallaqat","type":"section","seq":171,"chapter":"مدخل","title":"63- أرى قبر نحام بخيل بماله","page":"ج1 ص109","text":"أرى قبر نحام بخيل بماله ... كقبر غوي في البطالة مفسد\nالنحام: الحريص على الجمع والمنع. الغوي: الغاوي الضال، والغي والغواية الضلالة، وقد غوى يغوي.\nيقول: لا فرق بين البخيل والجواد بعد الوفاة فلم أبخل بأعلاقي، فقال: أرى قبر البخيل والحريص بماله كقبر الضال في بطالته المفسد بماله."},{"id":"muallaqat:172","bookId":"muallaqat","type":"section","seq":172,"chapter":"مدخل","title":"64- ترى جثوتين من تراب عليهما","page":"ج1 ص109","text":"ترى جثوتين من تراب عليهما ... صفائح صم من صفيح منضد\nالجثوة: الكومة من التراب وغيره، والجمع الجثى. التنضيد: مبالغة النضد.\nيقول: أرى قبري البخيل والجواد كومتين من التراب عليهما حجارة عراض صلاب، فيما بين قبور عليها حجارة عراض قد نضدت."},{"id":"muallaqat:173","bookId":"muallaqat","type":"section","seq":173,"chapter":"مدخل","title":"65- أرى الموت يعتام الكرام ويصطفي","page":"ج1 ص109","text":"أرى الموت يعتام الكرام ويصطفي ... عقيلة مال الفاحش المتشدد\nالاعتيام: الاختيار. العقائل: كرائم المال والنساء، الواحدة عقيلة، الفاحش: البخيل.\nيقول: أرى الموت يختار الكرام بالإفناء، ويصطفي كريمة مال البخيل المتشدد بالإبقاء، وقيل: بل معناه أن الموت يعم الأجواد والبخلاء، فيصطفي الكرام، وكرائم أموال البخلاء؛ يريد أنه لا تخلص منه لواحد من الصنفين، فلا يجدي البخل على صاحبه بخير فالجود أحرى لأنه أحمد."},{"id":"muallaqat:174","bookId":"muallaqat","type":"section","seq":174,"chapter":"مدخل","title":"66- أرى العيش كنزا ناقصا كل ليلة","page":"ج1 ص109","text":"أرى العيش كنزا ناقصا كل ليلة ... وما تنقص الأيام والدهر ينفد\nشبه البقاء بكنز ينقص كل ليلة، وما لا يزال ينقص فإن مآله إلى النفاد، فقال: وما تنقصه الأيام والدهر ينفد لا محالة، فكذلك العيش صائر إلى النفاد لا محالة؛ والنفاد الفناء، والفعل نفد ينفد، والإنفاد الإفناء."},{"id":"muallaqat:175","bookId":"muallaqat","type":"section","seq":175,"chapter":"مدخل","title":"67- لعمرك إن الموت ما أخطأ الفتى","page":"ج1 ص109","text":"لعمرك إن الموت ما أخطأ الفتى ... لكالطول المرخى وثنياه باليد.\nالعمر والعمر والعمر بمعنى، ولا يستعمل في القسم إلا بفتح العين، قوله: ما أخطأ الفتى، فما مع الفعل هنا بمنزلة مصدر حل محل الزمان، نحو قولهم: آتيك خفوق النجم ومقدم الحاج، أي: وقت خفوق النجم ووقت مقدم الحاج. الطول: الحبل الذي يطول للدابة فترعى فيه. الإرخاء: الإرسال. الثني: الطرف، والجمع الأثناء.\nيقول: أقسم بحياتك أن الموت في مدة إخطائه الفتى، أي: مجاوزته إياه، بمنزلة حبل طول للدابة ترعى فيه وطرفاه بيد صاحبه، يريد أنه لا يتخلص منه، كما أن الدابة لا تفلت ما دام صاحبها آخذا بطرفي طولها، لما جعل الموت بمنزلة صاحب الدابة التي أرخى طولها، قال: متى شاء الموت قاد الفتى لهلاكه، ومن كان في حبل الموت انقاد لقوده."},{"id":"muallaqat:176","bookId":"muallaqat","type":"section","seq":176,"chapter":"مدخل","title":"68- فما لي أراني وابن عمي مالكا","page":"ج1 ص110","text":"فما لي أراني وابن عمي مالكا ... متى أدن منه ينأ عني ويبعد\nالنأي والبعد واحد، فجمع بينهما للتأكيد وإثبات القافية، كقول الشاعر: [الطويل] :\nوهند أتى من دونها النأي والبعد\nيقول: فما لي أراني وابن عمي متى تقربت منه تباعد عني؟ يستغرب هجرانه إياه مع تقربه منه."},{"id":"muallaqat:177","bookId":"muallaqat","type":"section","seq":177,"chapter":"مدخل","title":"69- يلوم وما أدري علام يلومني","page":"ج1 ص110","text":"يلوم وما أدري علام يلومني ... كما لامني في الحي قرط بن معبد\nيلومني مالك وما أدري ما السبب الداعي إلى لومه إياي، كما لامني هذا الرجل في القبيلة، يريد أن لومه إياه ظلم صراح كما كان لوم قرط إياه كذلك."},{"id":"muallaqat:178","bookId":"muallaqat","type":"section","seq":178,"chapter":"مدخل","title":"70- وأيأسني من كل خير طلبته","page":"ج1 ص110","text":"وأيأسني من كل خير طلبته ... كأنا وضعناه إلى رمس ملحد\nالرمس: القبر وأصله الدفن. ألحدت الرجل: جعلت له لحدا.\nيقول: قنطني مالك من كل خير رجوته منه حتى كأنا وضعنا ذلك الطلب إلى قبر رجل مدفون في اللحد، يريد أنه آيسه من كل خير طلبه كما أن الميت لا يرجى خيره."},{"id":"muallaqat:179","bookId":"muallaqat","type":"section","seq":179,"chapter":"مدخل","title":"71- على غير شيء قلته غير أنني","page":"ج1 ص110","text":"على غير شيء قلته غير أنني ... نشدت فلم أغفل حمولة معبد\nالنشدان: طلب المفقود، الإغفال: الترك. الحمولة: الإبل التي تطيق أن يحمل عليها. معبد: أخوه.\nيقول: يلومني على غير شيء قلته وجناية جنيتها، ولكنني طلبت إبل أخي ولم أتركها، فنقم ذلك مني وجعل يلومني، وقوله: غير أنني، استثناء منقطع تقديره ولكنني."},{"id":"muallaqat:180","bookId":"muallaqat","type":"section","seq":180,"chapter":"مدخل","title":"72- وقربت بالقربى وجدك إنني","page":"ج1 ص111","text":"وقربت بالقربى وجدك إنني ... متى يك أمر للنكيثة أشهد\nالقربى: جمع قربة، وقيل: هو اسم من القرب والقرابة، وهو أصح القولين، النكيثة: المبالغة في الجهد وأقصى الطاقة، يقال: بلغت نكيثة البعير أي أقصى ما يطيق من السير.\nيقول: وقربت نفسي بالقرابة التي ضمنا حبلها ونظمنا خيطها، وأقسم بحظك وبختك أنه متى حدث له أمر يبلغ فيه غاية الطاقة ويبذل فيه المجهود أحضره وأنصره."},{"id":"muallaqat:181","bookId":"muallaqat","type":"section","seq":181,"chapter":"مدخل","title":"73- وإن أدع للجلى أكن من حماتها","page":"ج1 ص111","text":"وإن أدع للجلى أكن من حماتها ... وإن يأتك الأعداء بالجهد أجهد\nالجلى: تأنيث الأجل، وهي الخطة العظيمة، والجلاء بفتح الجيم والمد لغة فيها. الحماة: جمع الحامي من الحماية.\nيقول: وإن دعوتني للأمر العظيم والخطب الجسيم أكن من الذين يحمون حريمك، وإن يأتك الأعداء لقتالك أجهد في دفعهم عنك غاية الجهد، والباء في قوله بالجهد زائدة."},{"id":"muallaqat:182","bookId":"muallaqat","type":"section","seq":182,"chapter":"مدخل","title":"74- وإن يقذفوا بالقذع عرضك أسقهم","page":"ج1 ص111","text":"وإن يقذفوا بالقذع عرضك أسقهم ... بكأس حياض الموت قبل التهدد\nالقذع والقذع: الفحش. العرض: موضع المدح والذم من الإنسان، قاله ابن دريد، وقد يفسر بالحسب، والعرض النفس، ومنه قول حسان: [الوافر] :\nفإن أبي ووالده وعرضي ... لعرض محمد منكم وقاء\nأي: نفسي فداء، والعرض: العرق وموضع العرق، والجمع الأعراض في جميع الوجوه، التهدد والتهديد: واحد. القذف: السب.\nيقول: وإن أساء الأعداء القول فيك وأفحشوا الكلام، أوردتهم حياض الموت\nقبل أن أهددهم؛ يريد أنه يبيدهم قبل تهديدهم، أي لا يشتغل بتهديدهم بل يشتغل بإهلاكهم، ومن روى بشرب فهو النصيب من الماء، والشرب بضم الشين، مصدر شرب، يريد أسقهم شرب حياض الموت، فالباء زائدة والمصدر بمعنى المفعول والإضافة بتقدير من."},{"id":"muallaqat:183","bookId":"muallaqat","type":"section","seq":183,"chapter":"مدخل","title":"75- بلا حدث أحدثته وكمحدث","page":"ج1 ص112","text":"بلا حدث أحدثته وكمحدث ... هجائي وقذفي بالشكاة ومطردي\nيقول: أجفى وأهجر وأضام من غير حدث إساءة أحدثته، ثم أهجى وأشكى وأطرد كما يهجى من أحدث إساءة وجر جريرة وجنى جناية ويشكي ويطرد، والشكاية والشكوى، والشكية والشكاة واحد، والمطرد بمعنى الإطراد، وأطردته صيرته طريدا."},{"id":"muallaqat:184","bookId":"muallaqat","type":"section","seq":184,"chapter":"مدخل","title":"76- فلو كان مولاي امرأ هو غيره","page":"ج1 ص112","text":"فلو كان مولاي امرأ هو غيره ... لفرج كربي أو لأنظرني غدي\nيقول: فلو كان ابن عمي غير مالك لفرج كربي أو لأمهلني زمانا. فرجت الأمر وفرجته: كشفته، والفرج انكشاف المكروه. كربه الغم: إذا ملأ صدره، والكربة اسم منه، والجمع كرب. الإنظار: الإمهال، والنظرة اسم بمعنى الإنظار."},{"id":"muallaqat:185","bookId":"muallaqat","type":"section","seq":185,"chapter":"مدخل","title":"77- ولكن مولاي امرؤ هو خانقي","page":"ج1 ص112","text":"ولكن مولاي امرؤ هو خانقي ... على الشكر والتسآل أو أنا مفتد\nخنقت الرجل خنقا: عصرت حلقه. التسآل: السؤال.\nيقول: ولكن ابن عمي رجل يضيق الأمر علي حتى كأنه يأخذ علي متنفسي على حال شكري إياه وسؤالي عوارفه1 وعفوه، أو كنت في حال افتدائي نفسي منه. يقول: هو لا يزال يضيق الأمر علي سواء شكرته على آلائه، أو سألته بره وعطفه، أو طلبت تخليص نفسي منه."},{"id":"muallaqat:186","bookId":"muallaqat","type":"section","seq":186,"chapter":"مدخل","title":"78- وظلم ذوي القربى أشد مضاضة","page":"ج1 ص112","text":"وظلم ذوي القربى أشد مضاضة ... على المرء من وقع الحسام المهند\nمضني الأمر وأمضني: بلغ من قلبي وأثر في نفسي تهييج الحزن والغضب، يقول: ظلم الأقارب أشد تأثيرا في تهييج نار الحزن والغضب من وقع السيف القاطع المحدد أو المطبوع بالهند. الحسام: فعال من الحسم وهو القطع."},{"id":"muallaqat:187","bookId":"muallaqat","type":"section","seq":187,"chapter":"مدخل","title":"79- فذرني وخلقي","page":"ج1 ص113","text":"فذرني وخلقي، إنني لك شاكر ... ولو حل بيتي نائبا عند ضرغد\nضرغد: جبل\nيقول: خل بيني وبين خلقي وكلني إلى سجيتي، فإني شاكر لك وإن بعدت غاية البعد حتى ينزل بيتي عند هذا الجبل الذي سمي بضرغد، وبينهم وبين ضرغد مسافة بعيدة وشقة شاقة وبينونة بليغة."},{"id":"muallaqat:188","bookId":"muallaqat","type":"section","seq":188,"chapter":"مدخل","title":"80- فلو شاء ربي كنت قيس بن خالد","page":"ج1 ص113","text":"فلو شاء ربي كنت قيس بن خالد ... ولو شاء ربي كنت عمرو بن مرثد\nهذان سيدان من سادات العرب مذكوران بوفور المال ونجابة الأولاد، وشرف النسب وعظم الحسب.\nيقول: لو شاء الله بلغني منزلتهما وقدرهما."},{"id":"muallaqat:189","bookId":"muallaqat","type":"section","seq":189,"chapter":"مدخل","title":"81- فأصبحت ذا مال كثير وزارني","page":"ج1 ص113","text":"فأصبحت ذا مال كثير وزارني ... بنون كرام سادة لمسود\nيقول: فصرت حينئذ صاحب مال كثير وزارني بنون موصوفون بالكرم والسؤدد لرجل مسود يعني به نفسه، والتسويد مصدر سودته فساد.\nيقول: لو بلغني الله منزلتهما لصرت وافر المال، كريم العقب وهو الولد."},{"id":"muallaqat:190","bookId":"muallaqat","type":"section","seq":190,"chapter":"مدخل","title":"82- أنا الرجل الضرب الذي تعرفونه","page":"ج1 ص113","text":"أنا الرجل الضرب الذي تعرفونه ... خشاش1 كرأس الحية المتوقد\nالضرب: الرجل الخفيف اللحم.\nيقول: أنا الضرب الذي عرفتموه، والعرب تتمدح بخفة اللحم؛ لأن كثرته داعية إلى الكسل والثقل، وهما يمنعان من الإسراع في دفع الملمات وكشف المهمات ثم قال: أنا دخال في الأمور بخفة وسرعة، شبه تيقظه وذكاء ذهنه بسرعة حركة رأس الحية وشدة توقده."},{"id":"muallaqat:191","bookId":"muallaqat","type":"section","seq":191,"chapter":"مدخل","title":"83- فآليت لا ينفك كشحي بطانة","page":"ج1 ص113","text":"فآليت لا ينفك كشحي بطانة ... لعضب رقيق الشفرتين مهند\nلا ينفك: لا يزال، وما انفك ما زال، البطانة: نقيض الظهارة. العضب:\nالسيف القاطع. شفرتا السيف: حداه، والجمع الشفرات والشفار.\nيقول: ولقد حلفت أن لا يزال كشحي لسيف قاطع رقيق الحدين طبعته الهند بمنزلة البطانة للظهارة."},{"id":"muallaqat:192","bookId":"muallaqat","type":"section","seq":192,"chapter":"مدخل","title":"84- حسام إذا ما قمت منتصرا به","page":"ج1 ص114","text":"حسام إذا ما قمت منتصرا به ... كفى العود منه البدء ليس بمعضد\nالانتصار: الانتقام. المعضد: سيف يقطع به الشجر، والعضد قطع الشجر، والفعل عضد يعضد.\nيقول: لا يزال كشحي بطانة لسيف قاطع إذا ما قمت منتقما به من الأعداء كفى الضربة الأولى به الضربة الثانية فيغني البدء عن العود، وليس سيفا يقطع به الشجر، نفى ذلك؛ لأنه من أردأ السيوف."},{"id":"muallaqat:193","bookId":"muallaqat","type":"section","seq":193,"chapter":"مدخل","title":"85- أخي ثقة لا ينثني عن ضريبة","page":"ج1 ص114","text":"أخي ثقة لا ينثني عن ضريبة ... إذا قيل مهلا قال حاجزه قدي\nأخي ثقة: يوثق به، أي صاحب ثقة. الثني: الصرف، والفعل ثنى يثني والانثناء: الانصراف. الضريبة: ما يضرب بالسيف، والرمية: ما يرمى بالسهم، والجمع الضرائب والرمايا. مهلا: أي كف. قدي وقدني: أي حسبي، وقد جمعهما الراجز في قوله: [الرجز] :\nقدني من نصر الخبيبين قدي\nيقول: هذا السيف سيف يوثق بمضائه كالأخ الذي يوثق بإخائه لا ينصرف عن ضريبة أي لا ينبو عما ضرب به، إذا قيل لصاحبه كف عن ضرب عدوك قال مانع السيف وهو صاحبه: حسبي فإني قد بلغت ما أردت من قتل عدوي، يريد أنه ماض لا ينبو عن الضرائب، فإذا ضرب به صاحبه أغنته الضربة الأولى عن غيرها."},{"id":"muallaqat:194","bookId":"muallaqat","type":"section","seq":194,"chapter":"مدخل","title":"86- إذا ابتدر القوم السلاح وجدتني","page":"ج1 ص114","text":"إذا ابتدر القوم السلاح وجدتني ... منيعا إذا بلت بقائمه يدي\nابتدر القوم السلاح: استبقوه. المنيع: الذي لا يقهر ولا يغلب. بل بالشيء يبل به بلا إذا ظفر به. ويقول: إذا استبق القوم أسلحتهم وجدتني منيعا لا أقهر ولا أغلب إذا ظفرت يدي بقائم هذا السيف."},{"id":"muallaqat:195","bookId":"muallaqat","type":"section","seq":195,"chapter":"مدخل","title":"87- وبرك هجود قد أثارت مخافتي","page":"ج1 ص114","text":"وبرك هجود قد أثارت مخافتي ... بواديها، أمشي بعضب مجرد\nالبرك: الإبل الكثيرة الباركة. الهجود: جمع هاجد وهو النائم، وقد هجد يهجد هجودا. مخافتي مصدر مضاف إلى المفعول، بواديها: أوائلها وسوابقها.\nيقول: ورب إبل كثيرة باركة قد أثارتها عن مباركها مخافتها إياي في حال مشيي مع سيف قاطع مسلول من غمده، يريد أنه أراد أن ينحر بعيرا منها فنفرت منه لتعودها ذلك منه."},{"id":"muallaqat:196","bookId":"muallaqat","type":"section","seq":196,"chapter":"مدخل","title":"88- فمرت كهاة ذات حيف جلالة","page":"ج1 ص115","text":"فمرت كهاة ذات حيف جلالة ... عقيلة شيخ كالوبيل يلندد\nالكهاة والجلالة: الناقة الضخمة السمينة: الخيف: جلد الضرغ، وجمعه أخياف. العقيلة: كريمة المال والنساء والجمع العقائل. الوبيل: العصا الضخمة. اليلندد والألندد والألد: الشديد الخصومة، وقد لد الرجل يلد لددا صار شديد الخصومة وقد لدته ألده لدا غلبته بالخصومة.\nيقول: فمرت بي في حال إثارة مخافتي إياها ناقة ضخمة لها جلد الضرع وهي كريمة مال شيخ قد يبس جلده ونحل جسمه من الكبر حتى صار كالعصا الضخمة يبسا ونحولا، وهو شديد الخصومة؛ قيل: أراد به أباه، يريد أنه نحر كرائم مال أبيه لندمائه، وقيل: بل أراد غيره ممن يغير هو على ماله، والقول الأول أحراهما بالصواب."},{"id":"muallaqat:197","bookId":"muallaqat","type":"section","seq":197,"chapter":"مدخل","title":"89- يقول وقد تر الوظيف وساقها","page":"ج1 ص115","text":"يقول وقد تر الوظيف وساقها ... ألست ترى أن قد أتيت بمؤيد\nتر: أي سقط. المؤيد: الداهية العظيمة الشديدة.\nيقول: قال هذا الشيخ في حال عقري هذه الناقة الكريمة وسقوط وظيفها1 وساقها عند ضربي إياها بالسيف: ألم تر أنك أتيت بداهية شديدة بعقرك مثل هذه الناقة الكريمة النجيبة؟"},{"id":"muallaqat:198","bookId":"muallaqat","type":"section","seq":198,"chapter":"مدخل","title":"90- وقال","page":"ج1 ص115","text":"وقال: ألا ماذا ترون بشارب ... شديد علينا بغيه متعمد\nيقول: قال هذا الشيخ للحاضرين: أي شيء ترون أن يفعل بشارب خمر اشتد بغيه علينا عن تعمد وقصد؟ يريد أنه استشار أصحابه في شأني وقال: ماذا نحتال في\nدفع هذا الشارب الذي يشرب الخمر ويبغي علينا بعقر كرائم أموالنا ونحرها متعمدا قاصدا؟ ترون من الرأي والباء في قوله بشارب صلة محذوف تقديره أن يفعل ونحوه."},{"id":"muallaqat:199","bookId":"muallaqat","type":"section","seq":199,"chapter":"مدخل","title":"91- وقال","page":"ج1 ص116","text":"وقال: ذروه إنما نفعها له ... وإلا تكفوا قاصي البرك يزدد\nذروه: دعوه، والماضي منهما غير مستعمل عند جمهور الأئمة اجتزاء ب: \"ترك\" منهما، وكذلك اسم الفاعل والمفعول لاجتزائهم بالتارك والمتروك. الكف: المنع والامتناع، كفه فكف، والمضارع منهما يكف.\nيقول: ثم استقر رأي الشيخ على أنه قال دعوا طرفة إنما نفع هذه الناقة له. أو أراد إنما نفع هذه الإبل له؛ لأنه ولدي الذي يرثني وإلا تردوا وتمنعوا ما بعد هذه الإبل من الندود يزدد طرفة من عقرها ونحرها، أراد أنه أمرهم برد ما ند لئلا أعقر غير ما عقرت."},{"id":"muallaqat:200","bookId":"muallaqat","type":"section","seq":200,"chapter":"مدخل","title":"92- فظل الإماء يمتللن حوارها","page":"ج1 ص116","text":"فظل الإماء يمتللن حوارها ... ويسعى علينا بالسديف المسرهد\nالإماء: جمع أمة. الامتلال والملل: جعل الشيء في الملة وهي الجمر والرماد الحار. والحوار للناقة: بمنزلة الولد للإنسان يعم الذكر والأنثى، السديف: السنام، وقيل: قطع السنام. المسرهد: المربى، والفعل سرهد يسرهد سرهدة.\nيقول: فظل الإماء يشوين الولد الذي خرج من بطنها تحت الجمر والرماد الحار، ويسعى الخدم علينا بقطع سنامها المقطع، يريد أنهم أكلوا أطايبها وأباحوا غيرها للخدم، وذكر الحوار دال على أنها كانت حبلى وهي من أنفس الإبل عندهم."},{"id":"muallaqat:201","bookId":"muallaqat","type":"section","seq":201,"chapter":"مدخل","title":"93- فإن مت فانعيني بما أنا أهله","page":"ج1 ص116","text":"فإن مت فانعيني بما أنا أهله ... وشقي علي الجيب يا ابنة معبد\nلما فرغ من تعداد مفاخره أوصى ابنة أخيه -ومعبد أخوه- فقال: إذا هلكت فأشيعي خبر هلاكي بثنائي الذي أستحقه وأستوجبه وشقي جيبك1 علي، يوصيها بالثناء عليه والبكاء. النعي: إشاعة خبر الموت، والفعل نعى ينعى، أهله أي مستحقه، كقوله تعالى: {وكانوا أحق بها وأهلها} [الفتح: 26]"},{"id":"muallaqat:202","bookId":"muallaqat","type":"section","seq":202,"chapter":"مدخل","title":"94- ولا تجعليني كامرئ ليس همه","page":"ج1 ص117","text":"ولا تجعليني كامرئ ليس همه ... كهمي ولا يغني غنائي ومشهدي\nيقول: ولا تسوي بيني وبين رجل لا يكون همه مطلب المعالي كهمي، ولا يكفي المهم والملم كفايتي، ولا يشهد الوقائع مشهدي، والهم أصله القصد، يقال: هم بكذا أي قصد له، ثم يجعل الهم والهمة اسما لداعية النفس إلى العلا. الغناء: الكفاية. المشهد في البيت بمعنى الشهود وهو الحضور، أي: ولا يغني غناء مثل غنائي ولا يشهد الوقائع شهودا مثل شهودي.\nيقول: لا تعدلي بي من لا يساويني في هذه الخلال فتجعلي الثناء عليه كالثناء علي والبكاء عليه كالبكاء علي."},{"id":"muallaqat:203","bookId":"muallaqat","type":"section","seq":203,"chapter":"مدخل","title":"95- بطيء عن الجلي سريع إلى الخنا","page":"ج1 ص117","text":"بطيء عن الجلي سريع إلى الخنا ... ذلول بأجماع الرجال ملهد\nالبطء: ضد العجلة، والفعل بطؤ يبطأ، الجلي: الأمر العظيم. الخنا: الفحش. جمع الكف، وجمعها لغتان يقال: ضربه بجمع كفه إذا ضربه بها مجموعة، والجمع الأجماع. التلهيد: مبالغة اللهد وهو الدفع بجمع الكف، يقال: لهده يلهده لهدا. والبيت كله من صفة من ينهى ابنة أخيه أن تعدل غيره به.\nيقول: ولا تجعليني كرجل يبطأ عن الأمر العظيم ويسرع إلى الفحش وكثير ما يدفعه الرجال بأجماع أكفهم فقد ذل غاية الذل."},{"id":"muallaqat:204","bookId":"muallaqat","type":"section","seq":204,"chapter":"مدخل","title":"96- فلو كنت وغلا في الرجال لضرني","page":"ج1 ص117","text":"فلو كنت وغلا في الرجال لضرني ... عداوة ذي الأصحاب والمتوحد\nالوغل: أصله الضعيف يستعار للئيم.\nيقول: لو كنت ضعيفا من الرجال لضرتني معاداة ذي الأتباع والمنفرد الذي لا أتباع له، إياي، ولكنني قوي منيع لا تضرني معاداتهما إياي ويروى وغدا، وهو اللئيم."},{"id":"muallaqat:205","bookId":"muallaqat","type":"section","seq":205,"chapter":"مدخل","title":"97- ولكن نفى عني الرجال جراءتي","page":"ج1 ص117","text":"ولكن نفى عني الرجال جراءتي ... عليهم وإقدامي وصدقي ومحتدي\nالجرأة والجراءة واحد، والفعل جرؤ يجرؤ، والنعت جريء، وقد جرأه على كذا أي شجعه، المحتد: الأصل.\nيقول: ولكن نفى عني مباراة الرجال ومجاراتهم شجاعتي وإقدامي في الحروب وصدق صريمتي1 وكرم أصلي."},{"id":"muallaqat:206","bookId":"muallaqat","type":"section","seq":206,"chapter":"مدخل","title":"98- لعمرك ما أمري علي بغمة","page":"ج1 ص118","text":"لعمرك ما أمري علي بغمة ... نهاري ولا ليلي علي بسرمد\nالغمة والغم واحد، وأصل الغم التغطية، والفعل غم يغم ومنه الغمام؛ لأنه يغم السماء أي يغطيها، ومنه الأغم والغماء، لأن كثرة الشعر تغطي الجبين والقفا.\nيقول: أقسم ببقائك ما يغم أمري رأيي، أي ما تغطي الهموم رأيي في نهاري، ولا يطول علي ليلي حتى كأنه صار دائما سرمدا، وتلخيص المعنى: أنه تمدح بمضاء الصريمة وذكاء العزيمة، يقول: لا تغمني النوائب فيطول ليلي ويظلم نهاري."},{"id":"muallaqat:207","bookId":"muallaqat","type":"section","seq":207,"chapter":"مدخل","title":"99- ويوم حبست النفس عند عراكه","page":"ج1 ص118","text":"ويوم حبست النفس عند عراكه ... حفاظا على عوراته والتهدد\nالعراك والمعاركة: القتال، وأصلهما من العرك وهو الدلك، الحفاظ: المحافظة على ما تجب المحافظة عليه من حماية الحوزة والذب عن الحريم ودفع الذم عن الأحساب.\nيقول: ورب يوم حبست نفسي عن القتال والفزعات وتهدد الأقران محافظة على حسبي."},{"id":"muallaqat:208","bookId":"muallaqat","type":"section","seq":208,"chapter":"مدخل","title":"100- على موطن يخشى الفتى عنده الردى","page":"ج1 ص118","text":"على موطن يخشى الفتى عنده الردى ... متى تعترك فيه الفرائص ترعد\nالموطن: الموضع. الردى: الهلاك، والفعل ردي يردى، والإرداء: الإهلاك. الاعتراك والتعارك واحد. الفرائص: جمع فريصة وهي لحمة عند مجمع الكتف ترعد عند الفزع.\nيقول: حبست نفسي في موضع من الحرب يخشى الكريم هناك الهلاك ومتى تعترك الفرائص فيه أرعدت من فرط الفزع وهول المقام."},{"id":"muallaqat:209","bookId":"muallaqat","type":"section","seq":209,"chapter":"مدخل","title":"101- وأصفر مضبوح نظرت حواره","page":"ج1 ص118","text":"وأصفر مضبوح نظرت حواره ... على النار واستودعته كف مجمد\nضبحت الشيء: قربته من النار حتى أثرت فيه، أضبحه ضبحا. الحوار\nوالمحاورة: مراجعة الحديث، وأصله من قولهم: حار يحور إذا رجع؛ ومنه قول لبيد: [الطويل] :\nوما المرء إلا كالشهاب وضوئه ... يحور رمادا بعد إذ هو ساطع\nنظرت: أي انتظرت، والنظر الانتظار، ومنه قوله تعالى: {انظرونا نقتبس من نوركم} [الحديد: 13] . استودعته وأودعته واحد. المجمد: الذي لا يفوز، وأصله من الجمود.\nيقول: ورب قدح أصفر قد قرب من النار حتى أثرت فيه، وإنما فعل ذلك ليصلب ويصفر، انتظرت مراجعته أي انتظرت فوزه أو خيبته ونحن مجتمعون على النار له، وأودعت القدح كف رجل معروف بالخيبة وقلة الفوز، يفتخر بالميسر وإنما افتخرت العرب به لأنه لا يركن إليه إلا سمح جواد، ثم كمل المفخرة بإيداع قدحه كف مجمد قليل الفوز."},{"id":"muallaqat:210","bookId":"muallaqat","type":"section","seq":210,"chapter":"مدخل","title":"102- ستبدي لك الأيام ما كنت جاهلا","page":"ج1 ص119","text":"ستبدي لك الأيام ما كنت جاهلا ... ويأتيك بالأخبار من لم تزود\nيقول: ستطلعك الأيام على ما تغفل عنه وسينقل إليك الأخبار من لم تزوده."},{"id":"muallaqat:211","bookId":"muallaqat","type":"section","seq":211,"chapter":"مدخل","title":"103- ويأتيك بالأخبار من لم تبع له","page":"ج1 ص119","text":"ويأتيك بالأخبار من لم تبع له ... بتاتا ولم تضرب له وقت موعد\nباع قد يكون بمعنى اشترى، وهو في البيت بهذا المعنى، البتات: كساء المسافر وأداته [والجمع أبتة] . ولم تضرب له أي لم تبين له كقوله تعالى: {ضرب الله مثلا} [النحل: 75] أي بين وأوضح.\nيقول: سينقل إليك الأخبار من لم تشتر له متاع المسافر، ولم تبين له وقتا لنقل الأخبار إليك."},{"id":"muallaqat:212","bookId":"muallaqat","type":"section","seq":212,"chapter":"مدخل","title":"مدخل","page":"ج1 ص120","text":"...\nزهير بن أبي سلمى\nهو: زهير بن أبي سلمى، واسم أبي سلمى: ربيعة بن رياح بن قرة بن الحارث بن مازن، وينتهي نسبه إلى: مضر بن نزار بن معد بن عدنان.\nوهو أحد الثلاثة المقدمين على سائر الشعراء، وإنما اختلفوا في تقديم أحد الثلاثة على صاحبيه. وأما الثلاثة فلا اختلاف فيهم، وهم: امرؤ القيس، وزهير، والنابغة الذبياني.\nوكان من حديث زهير، وأهل بيته أنهم كانوا من \"مزينة\" إحدى قبائل مضر. وكان يقيم هو وأبوه وولده في منازل بني: عبد الله بن غطفان، بالحاجز من نجد، ولذلك كان يذكر في شعره بني مرة وغطفان ويمدحهم.\nنشأ زهير فيهم، وهناك قال قصيدته المعلقة يذكر فيها قتل ورد بن حابس العبسي: هرم بن ضمضم المري، ويمدح فيها هرم بن سنان بن أبي حارثة، والحارث بن عوف، وسعد بن ذبيان المريين لأنهما احتملا ديته من مالهما.\nوكان زهير بعد ذلك يكثر من مدح هرم وأبيه سنان وله فيهما قصائد غر. فحلف هرم ألا يمدحه إلا أعطاه ولا يسأله إلا أعطاه ولا يسلم عليه إلا أعطاه عبدا أو وليدة أو فرسا. فاستحيا زهير من كثرة بذله له على كل حال، وجعل يتجنب مقابلته.\nوكان إذا رآه في محفل قال: \"عموا صباحا غير هرم، وخيركم استثنيت\".\nكان زهير قد رأى في منامه في آخر عمره أن آتيا أتاه فحمله إلى السماء حتى كاد يمسها بيده، ثم تركه فهوى إلى الأرض، فلما احتضر قص رؤياه على ولده.\nكعب. ثم قال: \"إني لا أشك أنه كائن من خبر السماء بعدي، فإن كان فتمسكوا به وسارعوا إليه\". ثم توفي قبل مبعث النبي عليه الصلاة والسلام بسنة.\nوكانت وفاته سنة: 609 لميلاد المسيح عليه الصلاة والسلام.\nامتاز زهير بما نظمه من منثور الحكمة البالغة، وكثرة الأمثال وسني المدح، وتجنب وحشي الكلام، وعدم مدح أحد إلا بما فيه. وقد كان أحسن الشعراء شعرا، وأبعدهم عن سخف الكلام، وأجمعهم لكثير من المعاني في قليل من اللفظ.\nوكان لزهير أخلاق عالية، ونفس كبيرة، مع سعة صدر وحلم وورع، فرفع القوم منزلته وجعلوه سيدا. وكثر ماله واتسعت ثروته. وكان مع ذلك عريقا في الشعر.\nوكان لشعره تأثير كثير في نفوس العرب. وهو واسطة عقد الفحول من شعراء الطبقة الأولى.\nوكان زهير شديد العناية بتنقيح شعره، حتى ضرب به المثل، وسميت قصائده بالحوليات، نسبة إلى الحول أي السنة، وذلك لأنه كان ينظم القصيدة في أربعة أشهر، ويهذبها بنفسه في أربعة أشهر، ويعرضها على أصحابه الشعراء في أربعة أشهر، فلا يشهرها حتى يأتي عليها حول كامل.\nمعلقة زهير أشعر شعره. وقد جمعت ما أشبه كلام الأنبياء، وحكمة الحكماء ففيها الحكمة البالغة، والموعظة الحسنة، والأخلاق الفاضلة، والمعاني العالية والأغراض النبيلة، أضف إلى ذلك ما حوته من الأساليب البلاغية، والكلام الجزل.\nوقد أنشأها يمدح بها: الحارث بن عوف، وهرم بن سنان المريين، ويذكر سعيهما بالصلح بين: عبس وذبيان، وتحملهما ديته من مالهما."},{"id":"muallaqat:213","bookId":"muallaqat","type":"section","seq":213,"chapter":"مدخل","title":"اسمه","page":"ج1 ص122","text":"...\n[ترجمة زهير بن أبي سلمى1: ("},{"id":"muallaqat:214","bookId":"muallaqat","type":"section","seq":214,"chapter":"مدخل","title":".....","page":"ج1 ص122","text":"- 13ق. ه:"},{"id":"muallaqat:215","bookId":"muallaqat","type":"section","seq":215,"chapter":"مدخل","title":".....","page":"ج1 ص122","text":"- 609م) ."},{"id":"muallaqat:216","bookId":"muallaqat","type":"section","seq":216,"chapter":"مدخل","title":"1- اسمه","page":"ج1 ص122","text":"اسمه، هو: \"زهير بن أبي سلمى، واسم أبي سلمى ربيعة بن رياح بن قرة بن الحارث بن مازن بن ثعلبة بن ثور بن هرمة الأصم بن عثمان بن عمرو بن أد بن طابخة بن إلياس بن مضر بن نزار.\nومزينة أم عمرو بن أد هي بنت كلب بن وبرة2.\nولد في بلاد مزينة بنواحي المدينة وكان يقيم في الحاجز من ديار نجد، واستمر بنوه فيه بعد الإسلام3.\nوهو حكيم الشعراء، في الجاهلية، وأحد الثلاثة المقدمين على سائر الشعراء، وإنما اختلف في تقديم أحد الثلاثة على صاحبيه. فأما الثلاثة فلا اختلاف فيهم، وهم: امرؤ القيس، وزهير، والنابغة الذبياني1.\nقال ابن الأعرابي وحدثني أبو زياد الكلابي: أن زهير وأباه وولده كانوا في بني عبد الله بن غطفان، ومنزلهم اليوم بالحاجر، وكانوا فيه في الجاهلية. وكان أبو سلمى تزوج إلى رجل من بني فهر بن مرة بن عوف بن سعد بن ذبيان يقال له الغدير -والغدير هو أبو بشامة الشاعر- فولدت له زهيرا وأوسا، وولد لزهير من امرأة من بني سحيم. وكان زهير يذكر في شعره بني مرة وغطفان ويمدحهم. وكان زهير في الجاهلية سيدا كثير المال حليما معروفا بالورع2.\nقال ابن الاعرابي: \"أم أوفى\" التي ذكرها زهير في شعره كانت امرأته، فولدت منه أولادا ماتوا، ثم تزوج بعد ذلك امرأة أخرى وهي كبشة بنت عمار الغطفانية وهي أم ابنيه كعب وبجير، فغارت من ذلك وآذته فطلقها ثم ندم فقال فيها:\nلعمرك والخطوب مغيرات ... وفي طول المعاشرة التقالي\nلقد باليت مظعن أم أوفى ... ولكن أم أوفى ما تبالي\nفأما إذ نأيت فلا تقولي ... لذي صهر أذلت ولم تذالي\nأصبت بني منك ونلت مني ... من اللذات والحلل الغوالي3\nوقال ابن الأعرابي وأبو عمرو الشيباني: كان من حديث زهير وأهل بيته أنهم كانوا من مزينة، وكانوا بنو عبد الله بن غطفان جيرانهم، وقدما ولدتهم بنو مرة. وكان من أمر أبي سلمى أنه خرج وخاله أسعد بن الغدير بن مرة بن عوف بن سعد بن ذبيان بن بغيض وابنه كعب بن أسعد في ناس من بني مرة يغيرون على طيئ، فأصابوا نعما كثيرة وأموالا فرجعوا حتى انتهوا إلى أرضهم، فقال أبو سلمى لخاله أسعد وابن\nخاله كعب: أفردوا لي سهمي، فأبيا عليه ومنعاه حقه، فكف عنهما، حتى إذا كان الليل أتى أمه، فقال: والذي أحلف به لتقومن إلى بعير من هذه الإبل فلتقعدن عليه أو لأضربن بسيفي تحت قرطيك. فقامت أمه إلى بعير منها سنامه، وساق بها أبو سلمى وهو يرتجز ويقول:\nويل لأجمال العجوز مني ... إذا دنوت ودنون مني\nكأنني سمعمع1 من جن\nوساق الإبل وأمه حتى انتهى إلى قومه مزينة، فذلك حيث يقول:\nولتغدون إبل مجنبة2 ... من عند أسعد وابنه كعب\nالآكلين صريح قومهما ... أكل الحبارى3 برعم الرطب4\nقال: فلبث فيهم حينا، ثم أقبل بمزينة، مغيرا على بني ذبيان، حتى إذا مزينة أسهلت وخلفت بلادها، ونظروا إلى أرض غطفان، تطايروا عنه راجعين، وتركوه وحده، فذلك حين يقول:\nمن يشتري فرسا لخير غزوها ... وأبت عشيرة ربها أن تسهلا\nيعني أن تنزل السهل. قال: وأقبل حين رأى ذلك من مزينة حتى دخل فيه أخواله بني مرة، فلم يزل هو وولده في بني عبد الله بن غطفان إلى اليوم5."},{"id":"muallaqat:217","bookId":"muallaqat","type":"section","seq":217,"chapter":"مدخل","title":"2- حياته ونتاجه","page":"ج1 ص125","text":"ليس بين أيدينا شيء واضح عن نشأة زهير سوى أنه عاش في منازل بني عبد الله بن غطفان وأخواله من بني مرة الذبيانيين، وفي كنف خاله بشامة بن الغدير وكان شاعرا مجيدا كما كان سيدا شريفا ثريا، يقول ابن سلام: \"وكان زهير ممن فقأ\nعين بعير، في الجاهلية، وكان الرجل إذا ملك ألف بعير فقأ عين فحلها\"1.\n\"كان ورد بن حابس العبسي قتل هرم بن ضمضم المري، فتشاجر عبس وذبيان قبل الصلح، وحلف حصين بن ضمضم ألا يغسل حتى يقتل ورد بن حابس أو رجلا من بني عبس ثم من بني غالب، ولم يطلع على ذلك أحدا، وقد حمل الحمالة2 الحارث بن عوف بن أبي حارثة، قيل: بل أخوه حارثة بن سنان، فأقبل رجل من بني عبس ثم أحد بني مخزوم، حتى نزل بحصين بن ضمضم. فقال له حصين: من أنت أيها الرجل؟ قال: عبسي. قال: من أي عبس؟ فلم يزل ينتسب حتى انتسب إلى بني غالب، فقتله حصين. وبلغ ذلك الحارث بن عوف وهرم بن سنان فاشتد عليهما، وبلغ بني عبس فركبوا نحو الحارث. فلما بلغه ركوبهم إليه وما قد اشتد عليهم من قتل صاحبهم وأنهم يريدون قتل الحارث، بعث إليهم بمائة من الإبل معها ابنه وقال للرسول: قل لهم: الإبل إليكم أم أنفسكم؟ فأقبل الرسول حتى قال لهم ذلك فقال لهم الربيع بن زياد: يا قوم إن أخاكم قد أرسل إليكم: الإبل أحب إليكم أم ابني تقتلونه مكان قتيلكم. فقالوا نأخذ الإبل ونصالح قومنا، ونتم الصلح. فذلك حين يقول زهير يمدح الحارث وهرما:\nأمن أم أوفى دمنة لم تكلم ... بحومانة الدراج، فالمتثلم؟\nوهي أول قصيدة مدح بها هرما3، ثم مدح هرما بقصائد كثيرة حتى حلف هرم ألا يمدحه زهير إلا أعطاه، ولا يسأله إلا أعطاه، ولا يسلم عليه إلا أعطاه عبدا أو وليدة أو فرسا، فاستحيا زهير مما كان يقبل منه، فكان إذا رآه في ملأ قال: عموا صباحا غير هرم، وخيركم استثنيت4.\nيقول الرواة: إن أباه ربيعة لم يعش طويلا في عشيرة أخواله، وإن امرأته تزوجت\nمن بعده أوس بن حجر الشاعر التميمي المشهور. وهنا يلمع في حياة زهير اسم خاله بشامة بن الغدير، فقد كفله هو وإخوته، وعرف منهم سلمى والخنساء1.\nقال ابن الأعرابي: وكان بشامة بن الغدير خال زهير بن أبي سلمى، وكان زهير منقطعا إليه وكان معجبا بشعره. وكان بشامة رجلا مقعدا ولم يكن له ولد، وكان مكثرا من المال، ومن أجل ذلك نزل إلى هذا البيت في غطفان لخئولتهم. وكان بشامة أحزم الناس رأيا، وكانت غطفان إذا أرادوا أن يغزوا أتوه فاستشاروا وصدروا عن رأيه، فإذا رجعوا قسموا له مثل ما يقسمون لأفضلهم، فمن أجل ذلك كثر ماله. وكان أسعد غطفان في زمانه. فلما حضره الموت جعل يقسم ماله في أهل بيته وبين إخوته. فأتاه زهير فقال: يا خولاه لو قسمت لي من مالك!! فقال: والله يابن أختي لقد قسمت لك أفضل ذلك وأجزله. قال: وما هو؟ قال: شعري ورثتنيه2. وقد كان زهير قبل ذلك قال الشعر، وقد كان أول ما قال. فقال له زهير: الشعر شيء ما قلته فكيف تعتد به علي؟ فقال بشامة: ومن أين جئت بهذا الشعر! لعلك ترى أنك جئت به من مزينة وقد علمت العرب أن حصاتها وعين مائها في الشعر لهذا الحي من غطفان ثم لي منهم، وقد رويته عني، وأحذاه3. نصيبا من ماله ومات4.\nكان لزهير ابن يقال له: سالم، وكان من أم كعب بن زهير، جميل الوجه حسن الشعر. فأهدى رجل إلى زهير بردين5، فلبسهما الفتى وركب فرسا له، فمر بامرأة من العرب بماء يقال له النتاءة، فقالت: ما رأيت كاليوم قط رجلا ولا بردين ولا فرسا، فعثر به الفرس فاندقت عنقه وعنق الفرس وانشق البردان، فقال زهير يرثيه:\nرأت رجلا لاقى من العيش غبطة ... وأخطأه فيها الأمور العظائم\nفأصبح محبورا 1 ينظر حوله ... بغبطته لو أن ذلك دائم\nوعندي من الأيام ما ليس عنده ... فقلت تعلم إنما أنت حالم2\nلعلك يوما أن تراعي بفاجع ... كما راعني النتاءة سالم3\nوقد برز عنصر التهذيب والتعليم بقوة في شعر زهير، ولا سيما في معاني العتاب والزهد، حتى ظن بعض العلماء أنه خاضع لتأثير النصرانية، نعم كان تأثير النصرانية واسع الانتشار قديما في جزيرة العرب بيد أنه لا يجوز من أجل ذلك عده نصرانيا4.\nويقول ابن قتيبة: كان زهير يتأله ويتعفف في شعره. ومن معلقته ما يحمل على القول إنه كان مؤمنا بالله وبالبعث والحساب بدليل قوله:\nفلا تكتمن الله ما في نفوسكم ... ليخفي ومهما يكتم الله يعلم\nيؤخر فيوضع في كتاب فيدخر ... ليوم الحساب أو يعجل فينقم5\nوكان يعنى بتنقيح شعره وتهذيبه، وقد رويت له أربع قصائد سميت بالحوليات أي السنويات، وزعم رواة أخباره أنه كان ينظم الواحدة منها في أربعة أشهر، وينقحها في أربعة أشهر، ويعرضها على أخصائه في أربعة أشهر، فلا تظهر إلا بعد حول.\nوأشهر شعره معلقته التي مطلعها: \"أمن أم أوفى دمنة لم تكلم\"، ويتميز بمتانة لغته وقوة تركيبه، وكثرة الغريب في شعره، وبتطلبه حقيقة المعنى الوضعي ليخرجه على ماديته الحقيقية، وبتحكيمه عقله ورويته في تصوراته وخياله، فلا يبتعد، إلا في النادر، عن الحقائق الواقعية المحسوسة.\nوهو أشهر شعراء الجاهلية في إعطاء الحكمة وضرب المثل، وعرف في حياته\nبالرصانة والتعقل، وهو شخصية ممتازة من شخصيات الشعر الجاهلي، شخصية فيها بر ورحمة وفيها نزعة قوية إلى الخير.\nوآراؤه ليست إلا من أوليات التفكير الإنساني وتفكير الشعب، وهذه الآراء هي التي جعلته قريبا من الشعب؛ لأنه كان يكلمه فيها بما يعرف ويألف. وتحكيمه عقله في شعره، وإعماله تفكيره فيه، أضعفا عمل خياله، وعمل عاطفته، فلا تجد لهما عنده من الحظ إلا يسيرا، ومما يدل على تعقله وحنكته وسعة صدره حكمه في معلقته.\nوقد جمع خلاصة التقاضي في بيت واحد وهو:\nوإن الحق مقطعه ثلاث ... يمين أو نفار أو جلاء\nولا ريب أن لكبر سنة تأثيرا في خمود عاطفته وضعف خياله، فكل شعره يدلنا على أنه نظمه في حرب داحس والغبراء، وبعدها خاصة عندما بلغ الثمانين على حد قوله، أو تجاوزه، فمن البديهي أن يغلب عليه التعقل والترصن، وأن يكون للعقل العمل المهيمن في نتاجه الشعري.\nوحياة زهير من الوجهة الأدبية طريفة، يقول الأصبهاني: \"كان أبوه شاعرا، وخاله شاعرا، وأخته سلمى شاعرة، وابناه كعب وبجير شاعرين، وأخته الخنساء شاعرة، وهي القائلة ترثيه:\nوما يغني توقي الموت شيئا ... ولا عقد التميم ولا الغضار1\nإذا لاقى منيته فأمسى ... يساق به وقد حق الحذار\nولاقاه من الأيام يوم ... كما من قبل لم يخلد قدار2\nوابن ابنه المضرب بن كعب بن زهير شاعر، وهو القائل:\nإني لأحبس نفسي وهي صادية ... عن مصعب ولقد بانت لي الطرق\nرعوى عليه كما أرعى على هرم ... جدي زهير وفينا ذلك الخلق\nمدح الملوك وسعي في مسرتهم ... ثم الغنى ويد الممدوح تنطلق1\nكان لشعر زهير تأثير في نفوس العرب، وكان مقربا من أمراء ذبيان، وخصوصا هرم بن سنان والحارث بن عوف.\nوزهير عريق في الشعر، كان له فيه ما لم يكن لغيره وليس هذا فحسب فإنه عاش للشعر يعلمه ابنيه بجيرا وكعبا من جهة، وأناسا آخرين من غير بيته أشهرهم الحطيئة، فهو تلميذه وخريجه. وفي أخباره مع ابنه كعب ما يدل على الطريقة التي كان يخرج بها الشعراء، فقد كان يلقنهم شعره فيروونه عنه، وما يزالون يتلقونه حتى ينطبع في أنفسهم طريقة نظم الشعر وصوغه، وهو في أثناء ذلك يمتحن قدرتهم، بما يلقي عليهم من أبيات يطلب إليهم أن يجيزوها بنظم بيت على غرار البيت الذي ينشده في الوزن والقافية، ولابنه كعب قصيدة معروفة في مديح الرسول -صلى الله عليه وسلم- وهي ذائعة مشهورة2.\nويقال: إنه لم يتصل الشعر في ولد أحد من الفحول في الجاهلية ما اتصل في ولد زهير، وفي الإسلام ما اتصل في ولد جرير3.\nوقيل: إن زهيرا كان راوية أوس بن حجر زوج أمه، وكان أوس راوية الطفيل الغنوي وتلميذه4.\nوقد جمعت أشعاره في ديوان شرحه ثعلب المتوفى سنة 291ه. ومنه نسخة خطية في دار الكتب المصرية، وقد طبع سنة 1323ه. وشرحه الشنتمري المعروف بالأعلم المتوفى سنة 476ه. وقد طبع هذا الشرح في ليدن سنة 1306ه. وله شروح أخرى ضاعت أو لم نقف عليها5.\nوقد ترجم كثير من ديوانه إلى الألمانية، وللمستشرق الألماني: ديروف\n\"DYROFF\" كتاب في زهير وأشعاره بالألمانية طبع في منشن سنة 1892م1.\nوقد جمعت أخباره وأقواله في كتاب الأغاني، في ديوانه الستة الجاهليين، وخزانة الأدب، والشعر والشعراء، وجمعت معلقته مع سائر المعلقات، وفي الجمهرة، وقد شرحها كثيرون منهم النحاس وهو أهم شروحها، وقد نشره \"هوسهير\" الألماني سنة 1905م في برلين مع مقدمة ألمانية مفيدة 2] ."},{"id":"muallaqat:218","bookId":"muallaqat","type":"section","seq":218,"chapter":"مدخل","title":"1- أمن أم أوفى دمنة لم تكلم","page":"ج1 ص131","text":"أمن أم أوفى دمنة لم تكلم ... بحومانة الدراج فالمتثلم\nالدمنة: ما اسود من آثار الدار بالبعر والرماد وغيرهما، والجمع الدمن، والدمنة الحقد، والدمنة السرجين1. وهي في البيت بمعنى الأول. حومانة الدراج والمتثلم: موضعان، وقوله: أمن أم أوفى يعني: أمن منازل الحبيبة المكناة بأم أوفى دمنة لا تجيب؟ وقوله: لم تكلم، جزم بلم ثم حرك الميم بالكسر؛ لأن الساكن إذا حرك كان الأحرى تحريكه بالكسر. ولم يكن بد ههنا من تحريكه ليستقيم الوزن ويثبت السجع ثم أشبعت الكسرة بالإطلاق؛ لأن القصيدة مطلقة القوافي.\nيقول: أمن منازل الحبيبة المكناة بأم أوفى دمنة لا تجيب سؤالها بهذين الموضعين. أخرج الكلام في معرض الشك ليدل بذلك على أنه لبعد عهده بالدمنة وفرط تغيرها لم يعرفها معرفة قطع وتحقيق."},{"id":"muallaqat:219","bookId":"muallaqat","type":"section","seq":219,"chapter":"مدخل","title":"2- ودار لها بالرقمتين كأنها","page":"ج1 ص131","text":"ودار لها بالرقمتين كأنها ... مراجيع وشم في نواشر معصم\nالرقمتان: حرتان2 إحداهما قريبة من البصرة والأخرى قريبة من المدينة. المراجيع: جمع المرجوع، من قولهم: رجعه رجعا، أراد الوشم المجدد والمردد. نواشر المعصم: عروقه، الواحد: ناشر، وقيل ناشرة، والمعصم: مواضع السوار من اليد والجمع المعاصم.\nيقول: أمن منازلها دار بالرقمتين؟ يريد أنها تحل الموضعين عند الانتجاع3،\nولم يرد أنها تسكنهما جميعا؛ لأن بينهما مسافة بعيدة، ثم شبه رسوم دارها بهما بوشم في المعصم قد ردد وجدد بعد انمحائه، شبه رسوم الدار عند تجديد السيول إياها بكشف التراب عنها بتجديد الوشم.\nوتلخيص المعنى: أنه أخرج الكلام في معرض الشك في هذه الدار أهي لها أم لا، ثم شبه رسومها بالوشم المجدد في المعصم، وقوله: ودار لها بالرقمتين، يريد: وداران لها بهما، فاجتزأ بالواحد عن التثنية لزوال اللبس إذ لا ريب في أن الدار الواحدة لا تكون قريبة من البصرة والمدينة؛ وقوله: كأنها، أراد كأن رسومها وأطلالها، فحذف المضاف."},{"id":"muallaqat:220","bookId":"muallaqat","type":"section","seq":220,"chapter":"مدخل","title":"3- بها العين والأرآم يمشين خلفة","page":"ج1 ص133","text":"بها العين والأرآم يمشين خلفة ... وأطلاؤها ينهضن من كل مجثم\nقوله: بها العين أي: البقر العين، فحذف الموصوف لدلالة الصفة عليه، والعين: الواسعات العيون، والعين سعة العين. الأرآم: جمع رئم وهو الظبي الأبيض خالص البياض؛ وقوله: خلفة، أي: يخلف بعضها بعضا إذا مضى قطيع منها جاء قطيع آخر ومنه قوله تعالى: {وهو الذي جعل الليل والنهار خلفة} [الفرقان: 62] يريد أن كلا منهما يخلف صاحبه، فإذا ذهب النهار جاء الليل، وإذا ذهب الليل جاء النهار، الأطلاء: جمع الطلا وهو ولد الظبية والبقرة الوحشية، ويستعار لولد الإنسان ويكون هذا الاسم للولد من حين يولد إلى شهر أو أكثر منه. الجثوم للناس والطير والوحوش بمنزلة البروك للبعير، والفعل جثم يجثم، والمجثم: موضع الجثوم، والمجثم الجثوم، فالمفعل من باب فعل يفعل، إذا كان مفتوح العين كان مصدرا، وإذا كان مكسور العين كان موضعا، نحو: المضرب بالفتح والمضرب بالكسر.\nيقول: بهذه الدار بقر وحش واسعات العيون، وظباء بيض يمشين بها خالفات بعضها بعضا وتنهض أولادها من مرابضها لترضعها أمهاتها."},{"id":"muallaqat:221","bookId":"muallaqat","type":"section","seq":221,"chapter":"مدخل","title":"4- وقفت بها من بعد عشرين حجة","page":"ج1 ص133","text":"وقفت بها من بعد عشرين حجة ... فلأيا عرفت الدار بعد توهم\nالحجة: السنة، والجمع الحجج، اللأي: الجهد والمشقة.\nيقول: وقفت بدار أم أوفى بعد مضي عشرين سنة من بينها، وعرفت دارها بعد\nالتوهم بمقاساة جهد ومعاناة مشقة، يريد أنه لم يثبتها إلا بعد جهد ومشقة لبعد العهد بها ودروس أعلامها."},{"id":"muallaqat:222","bookId":"muallaqat","type":"section","seq":222,"chapter":"مدخل","title":"5- أثافي سفعا في معرس مرجل","page":"ج1 ص134","text":"أثافي سفعا في معرس مرجل ... ونؤيا كجذم الحوض لم يتثلم\nالأثفية والإثفية: جمعها الأثافي والأثافي، بتثقيل الياء وتخفيفها، وهي حجارة توضع القدر عليها، ثم إن كان من الحديد سمي منصبا، والجمع المناصب ولا يسمى أثفية. السفع: السود، والأسفع مثل الأسود، والسفاع مثل السواد، المعرس: أصل المنزل، من التعريس وهو النزول في وقت السحر، ثم استعير للمكان الذي تنصب فيه القدر. المرجل: القدر عند ثعلب من أي صنف من الجواهر كانت. النؤي: نهير يحفر حول البيت ليجري فيه الماء الذي ينصب من البيت عند المطر ولا يدخل البيت، الجمع الآناء والنئي. الجذم: الأصل، ويروى: كحوض الجد، والجد: البئر القريبة من الكلأ، وقيل: بل هي البئر القديمة.\nيقول: عرفت حجارة سودا تنصب عليها القدر، وعرفت نهيرا كان حول بيت أم أوفى بقي غير متثلم كأنه أصل حوض، نصب أثافي على البدل في قوله: عرفت الدار؛ يريد أن هذه الأشياء دلته على أنها دار أم أوفى."},{"id":"muallaqat:223","bookId":"muallaqat","type":"section","seq":223,"chapter":"مدخل","title":"6- فلما عرفت الدار قلت لربعها","page":"ج1 ص134","text":"فلما عرفت الدار قلت لربعها: ... ألا انعم صباحا أيها الربع واسلم\nكانت العرب تقول في تحيتها: انعم صباحا، أي طاب عيشك في صباحك، من النعمة وهي طيب العيش، وخص الصباح بهذا الدعاء؛ لأن الغارات والكرائه تقع صباحا، وفيها أربع لغات: انعم صباحا، بفتح العين من نعم ينعم مثل علم يعلم. والثانية: انعم، بكسر العين، من نعم ينعم مثل حسب يحسب، ولم يأت على فعل يفعل من الصحيح وغيرهما، وقد ذكر سيبويه أن بعض العرب أنشده قول امرئ القيس: [الطويل] :\nألا انعم صباحا أيها الطلل البالي ... وهل ينعمن من كان في العصر الخالي؟\nبكسر العين من ينعم. والثالثة: عم صباحا، من وعم يعم مثل وضع يضع. والرابعة: عم صباحا من وعم يعم مثل: وعد يعد.\nيقول: وقفت بدار أم أوفى فقلت لدارها محييا إياها وداعيا لها: طاب عيشك في صباحك وسلمت."},{"id":"muallaqat:224","bookId":"muallaqat","type":"section","seq":224,"chapter":"مدخل","title":"7- تبصر خليلي هل ترى من ظعائن","page":"ج1 ص135","text":"تبصر خليلي هل ترى من ظعائن ... تحملن بالعلياء من فوق جرثم\nالظعائن: جمع ظعينة؛ لأنها تظعن مع زوجها، من الظعن والظعن وهو الارتحال. بالعلياء أي: بالأرض العلياء أي: المرتفعة. جرثم: ماء بعينه.\nيقول: فقلت لخليلي: انظر يا خليلي هل ترى بالأرض العالية من فوق هذا الماء نساء في هوادج على إبل؟ يريد أن الوجد برح به والصبابة ألحت عليه حتى ظن المحال لفرط ولهه؛ لأن كونهن بحيث يراهن خليله بعد مضي عشرين سنة محال. التبصر: النظر. التحمل: الترحل."},{"id":"muallaqat:225","bookId":"muallaqat","type":"section","seq":225,"chapter":"مدخل","title":"8- جعلن القنان عن يمين وحزنه","page":"ج1 ص135","text":"جعلن القنان عن يمين وحزنه ... وكم بالقنان من محل ومحرم\nالقنان: جبل لبني أسد. عن يمين: يريد الظعائن. الحزن: ما غلظ من الأرض وكان مستويا. والحزن ما غلظ من الأرض وكان مرتفعا. من محل ومحرم، يقال: حل الرجل من إحرامه وأحل، وقال الأصمعي: من محل ومحرم يريد من له حرمة ومن لا حرمة له، وقال غيره: يريد دخل في أشهر الحل ودخل في أشهر الحرم.\nيقول: مررت بهم أشهر الحل وأشهر الحرم."},{"id":"muallaqat:226","bookId":"muallaqat","type":"section","seq":226,"chapter":"مدخل","title":"9- علون بأنماط عتاق وكلة","page":"ج1 ص135","text":"علون بأنماط عتاق وكلة ... وراد حواشيها مشاكهة الدم\nالباء في قوله: علون بأنماط، للتعدية. ويروى: وعالين أنماطا. ويروى: وأعلين، وهما بمعنى واحد، والمعالاة قد تكون بمعنى الإعلاء؛ ومنه قول الشاعر: [الرجز] :\nعاليت أنساعي وجلب الكور ... على سراة رائح ممطور\nأنماط: جمع نمط وهو ما يبسط من صنوف الثياب. العتاق الكرام الواحد عتيق. الكلة: الستر الرقيق، والجمع الكلل. الوراد: جمع ورد هو الأحمر والذي يضرب لونه إلى الحمرة. المشاكهة: المشابهة. ويروى وراد الحواشي لونها لون عندم. العندم: البقم، والعندم: دم الأخوين.\nيقول: وأعلين أنماطا كراما ذات أخطار أو سترا رقيقا، أي: ألقينها على الهوادج\nوغشينها بها، ثم وصف تلك الثياب بأنها حمر الحواشي يشبه ألوانها الدم في شدة الحمرة أو البقم أو دم الأخوين."},{"id":"muallaqat:227","bookId":"muallaqat","type":"section","seq":227,"chapter":"مدخل","title":"10- ووركن في السوبان يعلون متنه","page":"ج1 ص136","text":"ووركن في السوبان يعلون متنه ... عليهن دل الناعم المتنعم\nالسوبان: الأرض المرتفعة اسم علم لها. التوريك: ركوب أوراك الدواب. الدل والدلال والدالة واحد، وقد أدلت المرأة وتدللت. النعمة: طيب العيش. والتنعم: تكلف النعمة.\nيقول: وركبت هؤلاء النسوة أوراك ركابهن في حال علوهن متن السوبان، وعليهن دلال الإنسان الطيب العيش الذي يتكلف ذلك."},{"id":"muallaqat:228","bookId":"muallaqat","type":"section","seq":228,"chapter":"مدخل","title":"11- بكرن بكورا واستحرن بسحرة","page":"ج1 ص136","text":"بكرن بكورا واستحرن بسحرة ... فهن ووادي الرس كاليد للفم\nبكر وابتكر وبكر وأبكر: سار بكرة. استحر: سار سحرا. سحرة: اسم للسحر، ولا تصرف سحرة وسحر إذا عنيتهما من يومك الذي أنت فيه، وإن عنيت سحرا من الأسحار صرفتهما. وادي الرس: واد بعينه.\nيقول: ابتدأن السير وسرن سحرا وهن قاصدات لوادي الرس لا يخطئنه، كاليد القاصدة للفم لا تخطئه."},{"id":"muallaqat:229","bookId":"muallaqat","type":"section","seq":229,"chapter":"مدخل","title":"12- وفيهن ملهى للطيف ومنظر","page":"ج1 ص136","text":"وفيهن ملهى للطيف ومنظر ... أنيق لعين الناظر المتوسم\nالملهى: اللهو وموضعه. اللطيف: المتأنق الحسن المنظر. الأنيق: المعجب، فعيل بمعنى المفعل، كالحكيم بمعنى المحكم، والسميع بمعنى المسمع، والأليم بمعنى المؤلم، ومنه قوله عز وجل: {عذاب أليم} [البقرة: 10] ؛ ومنه قول ابن معديكرب: [الوافر] :\nأمن ريحانة الداعي السميع ... يؤرقني وأصحابي هجوع\nأي المسمع. والإيناق: الإعجاب. التوسم: التفرس، ومنه قوله تعالى: {إن في ذلك لآيات للمتوسمين} [الحجر: 75] . وأصله من الوسام والوسامة وهما الحسن، كأن التوسم تتبع محاسن الشيء، وقد يكون من الوسم فيكون تتبع علامات الشيء وسماته.\nيقول: وفي هؤلاء النسوان لهو أو موضع لهو للمتأنق الحسن المنظر، ومناظر معجبة لعين الناظر المتتبع محاسنهن وسمات جمالهن."},{"id":"muallaqat:230","bookId":"muallaqat","type":"section","seq":230,"chapter":"مدخل","title":"13- كأن فتات العهن في كل منزل","page":"ج1 ص137","text":"كأن فتات العهن في كل منزل ... نزلن به حب الفنا لم يحطم\nالفتات: اسم لما انفت من الشيء أي: تقطع وتفرق، وأصله من الفت وهو التقطيع والتفريق، والفعل منه فت يفت، والمبالغة التفتيت، والمطاوع الانفتات والتفتت. الفنا: عنب الثعلب. التحطم: التكسر، والحطم: الكسر. العهن: الصوف المصبوغ، والجمع العهون.\nيقول: كأن قطع الصوف المصبوغ الذي زينت به الهوادج في كل منزل نزلته هؤلاء النسوة حب عنب ثعلب في كل حال غير محطم؛ لأنه إذا حطم زايله لونه، شبه الصوف الأحمر بحب عنب الثعلب قبل حطمه."},{"id":"muallaqat:231","bookId":"muallaqat","type":"section","seq":231,"chapter":"مدخل","title":"14- فلما وردن الماء زرقا جمامه","page":"ج1 ص137","text":"فلما وردن الماء زرقا جمامه ... وضعن عصي الحاضر المتخيم\nالزرقة: شدة الصفاء، ونصل أزرق وماء أزرق إذا اشتد صفاؤهما، والجمع زرق، ومنه زرقة العين. الجمام: جمع جم الماء وجمته وهو ما اجتمع منه في البئر والحوض أو غيرهما. وضع العصى: كناية عن الإقامة؛ لأن المسافرين إذا أقاموا وضعوا عصيهم. التخيم: ابتناء الخيمة.\nيقول: فلما وردت هؤلاء الظعائن الماء وقد اشتد صفاء ما جمع منه في الآبار والحياض، عزمن على الإقامة كالحاضر المبتني الخيمة."},{"id":"muallaqat:232","bookId":"muallaqat","type":"section","seq":232,"chapter":"مدخل","title":"15- ظهرن من السوبان ثم جزعنه","page":"ج1 ص137","text":"ظهرن من السوبان ثم جزعنه ... على كل قيني قشيب ومفأم\nالجزع: قطع الوادي، والفعل جزع يجزع، ومنه قول امرئ القيس: [الطويل] :\nوآخر منهم جازع نجد كبكب\nأي قاطع. القين: كل صانع عند العرب، فالحداد قين، والجزار قين، فالقين هنا الرحال، وجمع القين: قيون، مثل بيت وبيوت، وأصل القين الإصلاح، والفعل منه قان يقين، ثم وضع المصدر موضع اسم الفعل وجعل كل صانع قينا؛ لأنه مصلح، ومنه قول الشاعر: [الطويل] :\nولي كبد مجروحة قد بدا بها ... صدوع الهوى لو أن قينا يقينها\nأي لو أن مصلحا يصلحها. ويروى: على كل حيري، منسوب إلى الحيرة1، وهي بلدة. القشيب: الجديد. المفأم: الموسع.\nيقول: علون من وادي السوبان ثم قطعنه مرة أخرى؛ لأنه اعترض لهن في طريقهن مرتين وهن على كل رحل حيري أو قيني جديد موسع."},{"id":"muallaqat:233","bookId":"muallaqat","type":"section","seq":233,"chapter":"مدخل","title":"16- فأقسمت بالبيت الذي طاف حوله","page":"ج1 ص138","text":"فأقسمت بالبيت الذي طاف حوله ... رجال بنوه من قريش وجرهم\nيقول: حلفت بالكعبة التي طاف حولها من بناها من القبيلتين. جرهم: قبيلة قديمة تزوج فيهم إسماعيل، عليه السلام، فغلبوا على الكعبة والحرم بعد وفاته عليه السلام، وضعف أمر أولاده، ثم استولى عليها بعد جرهم خزاعة إلى أن عادت إلى قريش، وقريش اسم لولد النضر بن كنانة."},{"id":"muallaqat:234","bookId":"muallaqat","type":"section","seq":234,"chapter":"مدخل","title":"17- يمينا لنعم السيدان وجدتما","page":"ج1 ص138","text":"يمينا لنعم السيدان وجدتما ... على كل حال من سحيل ومبرم\nالسحيل: المفتول على قوة واحدة. المبرم: المفتول على قوتين أو أكثر، ثم يستعار السحيل للضعيف والمبرم للقوي.\nيقول: حلفت يمينا، أي: حلفت حلفا، نعم السيدان وجدتما على كل حال ضعيفة وحال قوية، لقد وجدتما كاملين مستوفيين لخلال الشرف في حال يحتاج فيها إلى ممارسة الشدائد وحال يفتقر فيها إلى معاناة النوائب، وأراد بالسيدين هرم بن سنان والحارث بن عوف، مدحهما لإتمامهما الصلح بين عبس وذبيان وتحملهما أعباء ديات القتلى."},{"id":"muallaqat:235","bookId":"muallaqat","type":"section","seq":235,"chapter":"مدخل","title":"18- تداركتما عبسا وذبيان بعدما","page":"ج1 ص138","text":"تداركتما عبسا وذبيان بعدما ... تفانوا ودقوا بينهم عطر منشم\nالتدارك: التلافي، أي تداركتما أمرهما. التفاني: التشارك في الفناء. منشم، قيل فيه: إنه اسم امرأة عطارة اشترى قوم منها جفنة من العطر وتعاقدوا وتحالفوا وجعلوا آية الحلف غمسهم الأيدي في ذلك العطر، فقاتلوا العدو الذي تحالفوا على\nقتاله فقتلوا عن آخرهم، فتطير العرب بعطر منشم وسار المثل به، وقيل: بل كان عطارا يشترى منه ما يحنط به الموتى فسار المثل بعطره.\nيقول: تلافيتما أمر هاتين القبيلتين بعدما أفنى القتال رجالهما وبعد دقهم عطر هذه المرأة أي بعد إتيان القتال على آخرهم كما أتى على آخر المتعطرين بعطر منشم."},{"id":"muallaqat:236","bookId":"muallaqat","type":"section","seq":236,"chapter":"مدخل","title":"19- وقد قلتما","page":"ج1 ص139","text":"وقد قلتما: إن ندرك السلم واسعا ... بمال ومعروف من القول نسلم\nالسلم: الصلح، يذكر ويؤنث.\nيقول: وقد قلتما: إن أدركنا الصلح واسعا، أي إن اتفق لنا إتمام الصلح بين القبيلتين ببذل المال وإسداء معروف من الخير سلمنا من تفاني العشائر."},{"id":"muallaqat:237","bookId":"muallaqat","type":"section","seq":237,"chapter":"مدخل","title":"20- فأصبحتما منها على خير موطن","page":"ج1 ص139","text":"فأصبحتما منها على خير موطن ... بعيدين فيها من عقوق ومأثم\nالعقوق: العصيان، ومنه قوله عليه السلام: \" لا يدخل الجنة عاق لأبويه \". المأثم: الإثم، يقال: أثم الرجل يأثم إذا أقدم على الإثم، وأثمه الله يؤثمه إثاما وإثما إذا جازاه بإثمه، وآثمه إيثاما صيره ذا إثم، وتأثم الرجل تأثما إذا تجنب الإثم، مثل تحرج وتحنث وتحوب إذا تجنب الحرج والحنث والحوب.\nيقول: فأصبحتما على خير موطن من الصلح بعيدين في إتمامه من عقوق الأقارب والإثم بقطيعة الرحم، وتلخيص المعنى: إنكما طلبتما الصلح بين العشائر ببذل الأعلاق وظفرتما به وبعدتما عن قطيعة الرحم والضمير في منها يعود إلى السلم، يذكر ويؤنث."},{"id":"muallaqat:238","bookId":"muallaqat","type":"section","seq":238,"chapter":"مدخل","title":"21- عظيمين في عليا معد هديتما","page":"ج1 ص139","text":"عظيمين في عليا معد هديتما ... ومن يستبح كنزا من المجد يعظم\nالعليا: تأنيث الأعلى، وجمعها العليات والعلى مثل الكبرى في تأنيث الأكبر والكبريات والكبر في جمعها، وكذلك قياس الباب. وقوله: هديتما، دعاء لهما. الاستباحة: وجود الشيء مباحا، وجعل الشيء مباحا، والاستباحة الاستئصال. ويروى يعظم من الإعظام بمعنى التعظيم، ونصب عظيمين على الحال.\nيقول: ظفرتما بالصلح في حال عظمتكما في الرتبة العليا من شرف معد وحسبها، ثم دعا لهما، فقال: هديتما إلى طريق الصلاح والنجاح والفلاح، ثم قال:\nومن وجد كنزا من المجد مباحا واستأصله عظم أمره أو عظم فيما بين الكرام."},{"id":"muallaqat:239","bookId":"muallaqat","type":"section","seq":239,"chapter":"مدخل","title":"22- تعفى الكلوم بالمئين فأصبحت","page":"ج1 ص140","text":"تعفى الكلوم بالمئين فأصبحت ... ينجمها من ليس فيها بمجرم\nالكلوم والكلام: جمع كلم وهو الجرح، وقد يكون مصدرا. التعفية: التمحية من قولهم: عفا الشيء يعفو إذا انمحى ودرس، وعفاه يعفيه وعفاه أيضا عفوا. ينجمها1 أي: يعطيها نجوما. يقول: تمحى وتزال الجراح بالمئين من الإبل، فأصبحت الإبل يعطيها نجوما من هو بريء الساحة بعيدا عن الجرم في هذه الحروب يريد أنهما بمعزل عن إراقة الدماء وقد ضمنا إعطاء الديات ووفيا به وأخرجاها نجوما وكذلك تعطى الديات."},{"id":"muallaqat:240","bookId":"muallaqat","type":"section","seq":240,"chapter":"مدخل","title":"23- ينجمها قوم لقوم غرامة","page":"ج1 ص140","text":"ينجمها قوم لقوم غرامة ... ولم يهريقوا بينهم ملء محجم\nأراق الماء والدم يريقه وهراقه يهريقه وأهراقه يهريقه لغات، والأصل اللغة الأولى، والهاء في الثانية بدل من الهمزة في الأولى، وجمع في الثالثة بين البدل والمبدل توهما أن همزة أفعل لم تلحقه بعد. المحجم: آلة الحجام، والجمع المحاجم.\nيقول: ينجم الإبل قوم غرامة لقوم، أي: ينجمها هذان السيدان غرامة للقتلى؛ لأن الديات تلزمهم دونهما، ثم قال: وهؤلاء الذين ينجمون الديات لم يريقوا مقدار ما يملأ محجما من الدماء، والملء مصدر ملأت الشيء، والملء مقدار الشيء الذي يملأ الإناء وغيره، وجمعه أملاء، يقال: أعطني ملء القدح ومليئه وثلاثة أملائه."},{"id":"muallaqat:241","bookId":"muallaqat","type":"section","seq":241,"chapter":"مدخل","title":"24- فأصبح يجري فيهم من تلادكم","page":"ج1 ص140","text":"فأصبح يجري فيهم من تلادكم ... مغانم شتى من إفال مزنم\nالتلاد والتليد: المال القديم الموروث. المغانم: جمع المغنم وهو الغنيمة. شتى أي: متفرقة. الإفال: جمع أفيل وهو الصغير السن من الإبل. المزنم: المعلم بزنمة2.\nيقول: فأصبح يجري في أولياء المقتولين من نفائس أموالكم القديمة الموروثة\nغنائم متفرقة من إبل وصغار معلمة، وخص الصغار؛ لأن الديات تعطي من بنات اللبون1 والحقاق2 والأجذاع3، ولم يقل المزنمة وإن كان صفة الإفال حملا على اللفظ؛ لأن فعالا من الأبنية التي اشترك فيها الآحاد والجموع، وكل بناء انخرط في هذا السلك ساغ تذكيره حملا على اللفظ."},{"id":"muallaqat:242","bookId":"muallaqat","type":"section","seq":242,"chapter":"مدخل","title":"25- ألا أبلغ الأحلاف عني رسالة","page":"ج1 ص141","text":"ألا أبلغ الأحلاف عني رسالة ... وذبيان هل أقسمتم كل مقسم\nالأحلاف والحلفاء: الجيران، جمع حليف على أحلاف كما جمع نجيب على أنجاب، وشريف على أشراف، وشهيد على أشهاد، أنشد يعقوب: [الرجز] :\nقد أغتدي لفتية أنجاب ... وجهمة الليل إلى ذهاب\nأقسم أي: حلف، وتقاسم القوم أي تحالفوا، والقسم الحلف، والجمع الأقسام، وكذلك القسيمة، هل أقسمتم أي قد أقسمتم، ومنه قوله تعالى: {هل أتى على الإنسان} [الإنسان: 1] أي قد أتى، وأنشد سيبويه: [البسيط] :\nسائل فوارس يربوع بشدتنا ... أهل رأونا بسفح القف ذي الأكم\nأي قد رأونا؛ لأن حرف الاستفهام لا يلحق حرف الاستفهام.\nيقول: أبلغ ذبيان وحلفاءها وقل لهم: قد حلفتم على إبرام حبل الصلح كل حلف فتحرجوا من الحنث وتجنبوا."},{"id":"muallaqat:243","bookId":"muallaqat","type":"section","seq":243,"chapter":"مدخل","title":"26- فلا تكتمن الله ما في نفوسكم","page":"ج1 ص141","text":"فلا تكتمن الله ما في نفوسكم ... ليخفى ومهما يكتم الله يعلم\nيقول: لا تخفوا من الله ما تضمرون من الغدر ونقض العهد ليخفى على الله، ومهما يكتم من شيء يعلمه الله، يريد أن الله عالم بالخفيات والسرائر ولا يخفى عليه شيء من ضمائر العباد، فلا تضمروا الغدر ونقض العهد فإنكم إن أضمرتموه علمه الله؛ وقوله: يكتم الله، أي يكتم من الله."},{"id":"muallaqat:244","bookId":"muallaqat","type":"section","seq":244,"chapter":"مدخل","title":"27- يؤخر فيوضع في كتاب فيدخر","page":"ج1 ص141","text":"يؤخر فيوضع في كتاب فيدخر ... ليوم الحساب أو يعجل فينقم\nأي يؤخر عقابه ويرقم في كتاب فيدخر ليوم الحساب أو يعجل العقاب في الدنيا قبل المصير إلى الآخرة فينتقم من صاحبه، يريد لا مخلص من عقاب الذنب آجلا أو عاجلا."},{"id":"muallaqat:245","bookId":"muallaqat","type":"section","seq":245,"chapter":"مدخل","title":"28- وما الحرب إلا ما علمتم وذقتم","page":"ج1 ص142","text":"وما الحرب إلا ما علمتم وذقتم ... وما هو عنها بالحديث المرجم\nالذوق: التجربة، الحديث المرجم: الذي يرجم فيه بالظنون أي يحكم فيه بظنونها.\nيقول: ليست الحرب إلا ما وعدتموها وجربتموها ومارستم كراهتها، وما هذا الذي أقول بحديث مرجم عن الحرب، أي هذا ما شهدت عليه الشواهد الصادقة من التجارب وليس من أحكام الظنون."},{"id":"muallaqat:246","bookId":"muallaqat","type":"section","seq":246,"chapter":"مدخل","title":"29- متى تبعثوها تبعثوها ذميمة","page":"ج1 ص142","text":"متى تبعثوها تبعثوها ذميمة ... وتضر إذا ضريتموها فتضرم\nالضرى: شدة الحرب واستعار نارها، وكذلك الضراوة، والفعل ضري يضرى، والإضراء والتضرية الحمل على الضراوة، ضرمت النار تضرم ضرما واضطرمت وتضرمت: التهبت، وأضرمتها وضرمتها: ألهبتها.\nيقول: متى تبعثوا الحرب تبعثوها مذمومة أي تذمون على إثارتها، ويشتد ضرمها إذا حملتموها على شدة الضرى فتلهب نيرانها، وتلخيص المعنى: إنكم إذا أوقدتم نار الحرب ذممتم، ومتى أثرتموها ثارت وهيجتموها هاجت. يحثهم على التمسك بالصلح، ويعلمهم سوء عاقبة إيقاد نار الحرب."},{"id":"muallaqat:247","bookId":"muallaqat","type":"section","seq":247,"chapter":"مدخل","title":"30- فتعرككم عرك الرحى بثفالها","page":"ج1 ص142","text":"فتعرككم عرك الرحى بثفالها ... وتلقح كشافا ثم تنتج فتتئم\nثفال الرحى: خرقة أو جلدة تبسط تحتها ليقع عليه الطحين. الباء في قوله بثفالها بمعنى مع. اللقح واللقاح: حمل الولد، يقال: لقحت الناقة، والإلقاح جعلها كذلك. الكشاف: أن تلقح النعجة في السنة مرتين. أنتجت الناقة إنتاجا: إذا ولدت عندي، ونتجت الناقة تنتج نتاجا. الإتآم: أن تلد الأنثى توأمين، وامرأة متآم إذا كان ذلك دأبها، والتوأم يجمع على التؤام، ومنه قول الشاعر: [الرجز] :\nقالت لنا ودمعها تؤام ... كالدر إذ أسلمه النظام\nيقول: وتعرككم الحرب عرك الرحى الحب مع ثفاله، وخص تلك الحالة لأنه لا يبسط إلا عند الطحن، ثم قال: وتلقح الحرب في السنة مرتين وتلد توأمين، جعل إفناء الحرب إياهم بمنزلة طحن الرحى الحب، وجعل صنوف الشر تتولد من تلك الحروب بمنزلة الأولاد الناشئة من الأمهات، وبالغ في وصفها باستتباع الشر شيئين: أحدهما جعله إياها لاقحة كشافا، والآخر إتآمها."},{"id":"muallaqat:248","bookId":"muallaqat","type":"section","seq":248,"chapter":"مدخل","title":"31- فتنتج لكم غلمان أشأم كلهم","page":"ج1 ص143","text":"فتنتج لكم غلمان أشأم كلهم ... كأحمر عاد ثم ترضع فتفطم\nالشؤم: ضد اليمن، ورجل مشئوم ورجال مشائيم كما يقال ميمون ورجال ميامين، والأشأم أفعل من الشؤم وهو مبالغة المشئوم، وكذلك الأيمن مبالغة الميمون وجمعه الأشائم وأراد بأحمر عاد أحمر ثمود وهو عاقر الناقة، واسمه قدار بن سالف.\nيقول: فتولد لكم أبناء في أثناء تلك الحروب كل واحد منهما يضاهي في الشؤم عاقر الناقة ثم ترضعهم الحروب وتفطمهم، أي تكون ولادتهم ونشوؤهم في الحروب فيصبحون مشائيم على آبائهم."},{"id":"muallaqat:249","bookId":"muallaqat","type":"section","seq":249,"chapter":"مدخل","title":"32- فتغلل لكم ما لا تغل لأهلها","page":"ج1 ص143","text":"فتغلل لكم ما لا تغل لأهلها ... قرى بالعراق من قفيز ودرهم\nأغلت الأرض تغل إذا كانت لها غلة، أظهر تضعيف المضاعف في محل الجزم والبناء على الوقف، يتهكم ويهزأ بهم.\nيقول: فتغل لكم الحروب حينئذ ضروبا من الغلات لا تكون تلك الغلات لقرى من العراق التي تغل الدراهم بالقفيزات1؛ وتلخيص المعنى أن المضار المتولدة من هذه الحروب تربي على المنافع المتولدة من هذه القرى، كل هذا حث منه إياهم على الاعتصام بحبل الصلح، وزجر عن الغدر بإيقاد نار الحرب."},{"id":"muallaqat:250","bookId":"muallaqat","type":"section","seq":250,"chapter":"مدخل","title":"33- لعمري لنعم الحي جر عليهم","page":"ج1 ص143","text":"لعمري لنعم الحي جر عليهم ... بما لا يؤاتيهم حصين بن ضمضم\nجر عليهم: جنى عليهم، والجريرة الجناية، والجمع الجزائر، يؤاتيهم:\nيوافقهم، وهذه المؤاتاة قتل ورد بن حابس العبسي هرم بن ضمضم قبل هذا الصلح، فلما اصطلحت القبيلتان عبس وذبيان استتر وتوارى حصين بن ضمضم لئلا يطالب بالدخول في الصلح، وكان ينتهز الفرصة حتى ظفر برجل من عبس بواء بأخيه فشد عليه فقتله فركبت عبس فاستقر الأمر بين القبيلتين على عقل القتيل.\nيقول: أقسم بحياتي لنعمت القبيلة جنى عليهم حصين بن ضمضم، وإن لم يوافقوه في إضمار الغدر ونقض العهد."},{"id":"muallaqat:251","bookId":"muallaqat","type":"section","seq":251,"chapter":"مدخل","title":"34- وكان طوى كشحا على مستكنة","page":"ج1 ص144","text":"وكان طوى كشحا على مستكنة ... فلا هو أبداها ولم يتقدم\nالكشح: منقطع الأضلاع، والجمع كشوح، والكاشح المضمر العداوة في كشحه، وقيل بل هو من قولهم: كشح يكشح كشحا إذا أدبر وولى، وإنما سمي العدو كاشحا لإعراضه عن الود والوفاق، ويقال: طوى كشحه على كذا أي أضمر في صدره. الاستكنان: طلب الكن، والاستكنان الاستتار، وهو في البيت على المعنى الثاني. فلا هو أبداها أي فلم يبدها. ويكون لا مع الفعل الماضي بمنزلة لم مع الفعل المستقبل في المعنى، كقوله تعالى: {فلا صدق ولا صلى} [القيامة: 31] أي فلم يصدق ولم يصل، وقوله تعالى: {فلا اقتحم العقبة} [البلد: 11] أي لم يقتحمها، وقال أمية بن أبي الصلت: [الرجز] :\nإن تغفر اللهم فاغفر جما ... وأي عبد لك لا ألما\nأي لم يلم بالذنب. وقال الراجز:\nوأي أمر سيء لا فعله\nأي: لم يفعله.\nيقول: وكان حصين أضمر في صدره حقدا وطوى كشحه على نية مستترة فيه ولم يظهرها لأحد ولم يتقدم عليها قبل إمكانه الفرصة.\nيقول: لم يتقدم لما أخفى فيجعل به، ولكن أخره حتى يمكنه."},{"id":"muallaqat:252","bookId":"muallaqat","type":"section","seq":252,"chapter":"مدخل","title":"35- وقال سأقضي حاجتي ثم أتقي","page":"ج1 ص144","text":"وقال سأقضي حاجتي ثم أتقي ... عدوي بألف من ورائي ملجم\nيقول: وقال حصين في نفسه: سأقضي حاجتي من قتل قاتل أخي أو قتل كفؤ له، ثم أجعل بيني وبين عدوي ألف فارس ملجم فرسه أو ألفا من الخيل ملجما."},{"id":"muallaqat:253","bookId":"muallaqat","type":"section","seq":253,"chapter":"مدخل","title":"36- فشد فلم يفزع بيوتا كثيرة","page":"ج1 ص145","text":"فشد فلم يفزع بيوتا كثيرة ... لدى حيث ألقت رحلها أم قشعم\nالشدة: الحملة، وقد شد عليه يشد شدا، الإفزاع: الإخافة، أم قشعم: كنية المنية.\nيقول: فحمل حصين على الرجل الذي رام أن يقتله بأخيه، ولم يفزع بيوتا كثيرة أي: لم يتعرض لغيره عند ملقى رحل المنية، وملقى الرحل: المنزل؛ لأن المسافر يلقي به رحله، أراد عند منزل المنية. وجعله منزل المنية لحلولها ثم بمن قتله حصين."},{"id":"muallaqat:254","bookId":"muallaqat","type":"section","seq":254,"chapter":"مدخل","title":"37- لدى أسد شاكي السلاح مقذف","page":"ج1 ص145","text":"لدى أسد شاكي السلاح مقذف ... له لبد أظفاره لم تقلم\nشاكي السلاح وشائك السلاح وشاك السلاح أي: تام السلاح، كله من الشوكة وهي العدة والقوة. مقذف أي: يقذف به كثيرا إلى الوقائع، والتقذيف مبالغة القذف. اللبد: جمع لبدة الأسد وهي ما تلبد من شعره على منكبيه.\nيقول: عند أسد تام السلاح يصلح لأن يرمى به إلى الحروب والوقائع، يشبه أسدا له لبدتان لم تقلم براثنه، يريد أنه لا يعتريه ضعف ولا يعيبه عدم شوكة كما أن الأسد لا يقلم براثنه، والبيت كله من صفة حصين."},{"id":"muallaqat:255","bookId":"muallaqat","type":"section","seq":255,"chapter":"مدخل","title":"38- جريء متى يظلم يعاقب بظلمه","page":"ج1 ص145","text":"جريء متى يظلم يعاقب بظلمه ... سريعا وإلا يبد بالظلم يظلم\nالجرأة والجراءة: الشجاعة، والفعل جرؤ يجرؤ وقد جرأته عليه. بدأت بالشيء أبدأ به مهموز فقلبت الهمزة ألفا ثم حذفت للجازم.\nيقول: وهو شجاع متى ظلم عاقب الظالم بظلمه سريعا وإن لم يظلمه أحد ظلم الناس إظهارا لغنائه وحسن بلائه، والبيت من صفة أسد في البيت الذي قبله وعنى به حصينا ثم أضرب عن قصته ورجع إلى تقبيح صورة الحرب والحث على الاعتصام بالصلح."},{"id":"muallaqat:256","bookId":"muallaqat","type":"section","seq":256,"chapter":"مدخل","title":"39- رعوا ظمأهم حتى إذا تم أوردوا","page":"ج1 ص145","text":"رعوا ظمأهم حتى إذا تم أوردوا ... غمارا تفرى بالسلاح وبالدم\nالرعي يقتصر على مفعول واحد: رعت الماشية الكلأ، وقد يتعدى إلى مفعولين نحو: رعيت الماشية الكلأ ورعى الكلأ نفسه. الظمء: ما بين الوردين والجمع الأظماء، الغمار: جمع غمر وهو الماء الكثير. التفري: التشقق.\nيقول: رعوا إبلهم الكلأ حتى إذا تم الظمء أوردوها مياها كثيرة، وهذا كله استعارة، والمعنى أنهم كفوا عن القتال وأقلعوا عن النزال مدة معلومة كما ترعى الإبل مدة معلومة، ثم عادوا الوقائع كما تورد الإبل بعد الرعي، فالحروب بمنزلة الغمار ولكنها تنشق عنهم باستعمال السلاح وسفك الدماء."},{"id":"muallaqat:257","bookId":"muallaqat","type":"section","seq":257,"chapter":"مدخل","title":"40- فقضوا منايا بينهم ثم أصدروا","page":"ج1 ص146","text":"فقضوا منايا بينهم ثم أصدروا ... إلى كلأ مستوبل متوخم\nقضيت الشيء وقضيته: أحكمته وأتممته. أصدرت: ضد أوردت. استوبلت الشيء: وجدته وبيلا، واستوخمته وتوخمته: وجدته وخيما. والوبيل والوخيم: الذي لا يستمرأ1.\nيقول: فأحكموا وتمموا منايا بينهم، أي: قتل كل واحد من الحيين صنفا من الآخر، فكأنهم تمموا منايا قتلاهم ثم أصدروا إبلهم إلى كلأ وبيل وخيم، أي: ثم أقلعوا عن القتال والقراع واشتغلوا بالاستعداد له ثانيا كما تصدر الإبل فترعى إلى أن تورد ثانيا، وجعل اعتزامهم على الحرب ثانية والاستعداد لها بمنزلة كلأ وبيل وخيم، جعل استعدادهم للحرب أولا وخوضهم غمراتها وإقلاعهم عنها زمانا وخوضهم إياها ثانية بمنزل رعي الإبل أولا وإيرادها وإصدارها ورعيها ثانيا، وشبه تلك الحال بهذه الحال، ثم أضرب عن هذا الكلام وعاد إلى مدح الذين يعقلون القتلى ويدونها."},{"id":"muallaqat:258","bookId":"muallaqat","type":"section","seq":258,"chapter":"مدخل","title":"41- لعمرك ما جرت عليهم رماحهم","page":"ج1 ص146","text":"لعمرك ما جرت عليهم رماحهم ... دم ابن نهيك أو قتل المثلم\nيقول: أقسم ببقائك وحياتك أن رماحهم لم تجن عليهم دماء هؤلاء المسمين، أي لم يسفكوها ولم يشاركوا قاتليهم في سفك دمائهم، والتأنيث في شاركت للرماح يبين براءة ذممهم عن سفك دمهم ليكون ذلك أبلغ في مدحهم بعقلهم القتلى."},{"id":"muallaqat:259","bookId":"muallaqat","type":"section","seq":259,"chapter":"مدخل","title":"42- ولا شاركت في الموت في دم نوفل","page":"ج1 ص146","text":"ولا شاركت في الموت في دم نوفل ... ولا وهب منها ولا ابن المخزم\nمضى شرح هذا البيت في أثناء شرح البيت الذي قبله."},{"id":"muallaqat:260","bookId":"muallaqat","type":"section","seq":260,"chapter":"مدخل","title":"43- فكلا أراهم أصبحوا يعقلونه","page":"ج1 ص146","text":"فكلا أراهم أصبحوا يعقلونه ... صحيحات مال طالعات بمخرم\nعقلت القتيل: وديته، وعقلت عن الرجل أعقل عنه أديت عنه الدية التي لزمته، وسميت الدية عقلا لأنها تعقل الدم عن السفك أي تحقنه وتحبسه، وقيل بل سميت عقلا؛ لأن الوادي كان يأتي بالإبل إلى أفنية القتيل فيعقلها1 هناك بعقلها، فعقل على هذا القول بمعنى المعقول، ثم سميت الدية عقلا وإن كانت دنانير ودراهم، والأصل ما ذكرنا. طلعت الثنية وأطلعتها: علوتها. المخرم: منقطع أنف الجبل والطريق فيه، والجمع المخارم.\nيقول: فكل واحد من القتلى أرى العاقلين يعقلونه بصحيحات إبل تعلو في طرق الجبال عند سوقها في أولياء المقتولين."},{"id":"muallaqat:261","bookId":"muallaqat","type":"section","seq":261,"chapter":"مدخل","title":"44- لحي حلال يعصم الناس أمرهم","page":"ج1 ص147","text":"لحي حلال يعصم الناس أمرهم ... إذا طرقت إحدى الليالي بمعظم\nحلال: جمع حال مثل صاحب وصحاب وصائم وصيام وقائم وقيام، يعصم: يمنع. الطروق: الإتيان ليلا، والباء في قوله بمعظم يجوز كونه بمعنى مع وكونه للتعدية. أعظم الأمر أي سار إلى حال العظم، كقولهم: أجز البر وأجد التمر وأقطف العنب، أي: يعقلون القتلى لأجل حي نازلين يعصم أمرهم جيرانهم وحلفاءهم إذا أتت إحدى الليالي بأمر فظيع وخطب عظيم، أي إذا نابتهم نائبة عصموهم ومنعوهم."},{"id":"muallaqat:262","bookId":"muallaqat","type":"section","seq":262,"chapter":"مدخل","title":"45- كرام فلا ذو الضغن يدرك تبله","page":"ج1 ص147","text":"كرام فلا ذو الضغن يدرك تبله ... ولا الجارم الجاني عليهم بمسلم\nالضغن والضغينة واحد: وهو ما استكن في القلب من العداوة، والجمع الأضغان والضغائن. التبل: الحقد، والجمع التبول، الجارم والجاني واحد والجارم: ذو الجرم، كاللابن والتامر بمعنى ذي اللبن وذي التمر. الإسلام: الخذلان.\nيقول: لحي كرام لا يدرك ذو الوتر2 وتره عندهم ولا يقدر على الانتقام منهم من ظلموه وجنى عليهم من فتيانهم وحلفائهم وجيرانهم."},{"id":"muallaqat:263","bookId":"muallaqat","type":"section","seq":263,"chapter":"مدخل","title":"46- سئمت تكاليف الحياة ومن يعش","page":"ج1 ص147","text":"سئمت تكاليف الحياة ومن يعش ... ثمانين حولا لا أبا لك يسأم\nسمئت الشيء سآمة: مللته. التكاليف: المشاق الشدائد. لا أبا لك: كلمة جافية لا يراد بها الجفاء وإنما يراد بها التنبيه والإعلام.\nيقول: مللت مشاق الحياة وشدائدها، ومن عاش ثمانين سنة مل الكبر لا محالة."},{"id":"muallaqat:264","bookId":"muallaqat","type":"section","seq":264,"chapter":"مدخل","title":"47- وأعلم ما في اليوم والأمس قبله","page":"ج1 ص148","text":"وأعلم ما في اليوم والأمس قبله ... ولكنني عن علم ما في غد عمي\nيقول: وقد يحيط علمي بما مضى وما حضر، ولكني عمي القلب عن الإحاطة بما هو منتظر متوقع."},{"id":"muallaqat:265","bookId":"muallaqat","type":"section","seq":265,"chapter":"مدخل","title":"48- رأيت المنايا خبط عشواء من تصب","page":"ج1 ص148","text":"رأيت المنايا خبط عشواء من تصب ... تمته ومن تخطئ يعمر فيهرم\nالخبط: الضرب باليد، والفعل خبط يخبط. العشواء: تأنيث الأعشى، وجمعها عشو، والياء في عشي منقلبة عن الواو كما كانت في رضي منقلبة عنها، والعشواء: الناقة التي لا تبصر ليلا، ويقال في المثل: هو خابط خبط عشواء، أي قد ركب رأسه في الضلالة كالناقة التي لا تبصر ليلا فتخبط بيديها على عمى، فربما تردت في مهواة وربما وطئت سبعا أو حية أو غير ذلك.\nقوله: ومن تخطئ أي ومن تخطئه، فحذف المفعول، وحذفه سائغ كثير في الكلام والشعر والتنزيل. التعمير: تطويل العمر.\nيقول: رأيت المنايا تصيب الناس على غير نسق وترتيب وبصيرة، كما أن هذه الناقة تطأ على غير بصيرة، ثم قال: من أصابته المنايا أهلكته ومن أخطأته أبقته فبلغ الهرم."},{"id":"muallaqat:266","bookId":"muallaqat","type":"section","seq":266,"chapter":"مدخل","title":"49- ومن لم يصانع في أمور كثيرة","page":"ج1 ص148","text":"ومن لم يصانع في أمور كثيرة ... يضرس بأنياب ويوطأ بمنسم\nيقول: ومن لم يصانع الناس ولم يدارهم في كثير من الأمور قهروه وغلبوه وأذلوه وربما قتلوه، كالذي يضرس بالناب ويوطأ بالمنسم. الضرس: العض على الشيء بالضرس، والتضريس مبالغة. المنسم للبعير: بمنزلة السنبك1 للفرس، والجمع المناسم."},{"id":"muallaqat:267","bookId":"muallaqat","type":"section","seq":267,"chapter":"مدخل","title":"50- ومن يجعل المعروف من دون عرضه","page":"ج1 ص148","text":"ومن يجعل المعروف من دون عرضه ... يفره ومن لا يتق الشتم يشتم\nيقول: ومن جعل معروفة ذابا ذم الرجال عن عرضه، وجعل إحسانه واقيا عرضه وفر مكارمه، ومن لا يتق شتم الناس إياه شتم؛ يريد أن من بذل معروفه صان عرضه، ومن بخل معروفه عرض عرضه للذم والشتم. وفرت الشيء أفره وفرا: أكثرته، ووفرته فوفر وفورا."},{"id":"muallaqat:268","bookId":"muallaqat","type":"section","seq":268,"chapter":"مدخل","title":"51- ومن يك ذا فضل فيبخل بفضله","page":"ج1 ص149","text":"ومن يك ذا فضل فيبخل بفضله ... على قومه يستغن عنه ويذمم\nيقول: من كان ذا فضل ومال فبخل به استغني عنه وذم، فأظهر التضعيف على لغة أهل الحجاز؛ لأن لغتهم إظهار التضعيف في محل الجزم والبناء على الوقف."},{"id":"muallaqat:269","bookId":"muallaqat","type":"section","seq":269,"chapter":"مدخل","title":"52- ومن يوف لا يذمم ومن يهد قلبه","page":"ج1 ص149","text":"ومن يوف لا يذمم ومن يهد قلبه ... إلى مطمئن البر لا يتجمجم\nوفيت بالعهد أفي به وفاء وأوفيت به إيفاء، لغتان جيدتان والثانية أجودهما؛ لأنها لغة القرآن قال الله تعالى: {وأوفوا بعهدي أوف بعهدكم} [البقرة: 40] ويقال: هديته الطريق وهديته إلى الطريق وهديته للطريق.\nيقول: ومن أوفى بعهده لم يلحقه ذم، ومن هدي قلبه إلى بر يطمئن القلب إلى حسنه ويسكن إلى وقوعه موقعه، لم يتتعتع1 في إسدائه وإيلائه."},{"id":"muallaqat:270","bookId":"muallaqat","type":"section","seq":270,"chapter":"مدخل","title":"53- ومن هاب أسباب المنايا ينلنه","page":"ج1 ص149","text":"ومن هاب أسباب المنايا ينلنه ... وإن يرق أسباب السماء بسلم\nرقي في السلم يرقى رقيا: صعد فيه، ورقى المريض يرقيه رقية، ويروى ولو رام أسباب السماء.\nيقول: ومن خاف وهاب أسباب المنايا نالته، ولم يجد عليه خوفه وهيبته إياها نفعا ولو رام الصعود إلى السماء فرارا منها."},{"id":"muallaqat:271","bookId":"muallaqat","type":"section","seq":271,"chapter":"مدخل","title":"54- ومن يجعل المعروف في غير أهله","page":"ج1 ص149","text":"ومن يجعل المعروف في غير أهله ... يكن حمده ذما عليه ويندم\nيقول: ومن وضع أياديه في غير من استحقها، أي من أحسن إلى من لم يكن أهلا للإحسان إليه والامتنان عليه، ذمه الذي أحسن إليه ولم يحمده، وندم المحسن الواضع إحسانه في غير موضعه."},{"id":"muallaqat:272","bookId":"muallaqat","type":"section","seq":272,"chapter":"مدخل","title":"55- ومن يعص أطراف الزجاج فإنه","page":"ج1 ص150","text":"ومن يعص أطراف الزجاج فإنه ... يطيع العوالي ركبت كل لهذم\nالزجاج، جمع زج الرمح: وهو الحديد المركب في أسفله، وإذا قيل: زج الرمح، عني به ذلك والسنان. اللهذم: السنان الطويل. عالية الرمح ضد سافتله، والجمع العوالي، إذا التقت فئتان من العرب سددت كل واحدة منهما زجاج الرماح نحو صاحبتها وسعى الساعون في الصلح، فإن أبتا إلا التمادي في القتال قلبت كل واحدة منها الرماح واقتتلتا بالأسنة.\nيقول: ومن عصى أطراف الزجاج أطاع عوالي الرماح التي ركبت فيها الأسنة الطوال؛ وتحرير المعنى: من أبى الصلح ذللته الحرب ولينته، وقوله: يطيع العوالي، كان حقه أن يقول: يطيع العوالي، بفتح الياء، ولكنه سكن الياء لإقامة الوزن، وحمل النصب على الرفع والجر؛ لأن هذه الياء مسكنة، ومثله قول الراجز: [الرجز] :\nكأن أيديهن بالقاع القرق\nأيدي جوار يتعاطين الورق"},{"id":"muallaqat:273","bookId":"muallaqat","type":"section","seq":273,"chapter":"مدخل","title":"56- ومن لم يذد عن حوضه بسلاحه","page":"ج1 ص150","text":"ومن لم يذد عن حوضه بسلاحه ... يهدم ومن لا يظلم الناس يظلم\nالذود: الكف والردع.\nيقول: ومن لا يكف أعداءه عن حوضه بسلاحه هدم حوضه، ومن كف عن ظلم الناس ظلمه الناس، يعني ومن لم يحم حريمه استبيح واستعار الحوض للحريم."},{"id":"muallaqat:274","bookId":"muallaqat","type":"section","seq":274,"chapter":"مدخل","title":"57- ومن يغترب يحسب عدوا صديقه","page":"ج1 ص150","text":"ومن يغترب يحسب عدوا صديقه ... ومن لم يكرم نفسه لم يكرم\nيقول: من سافر واغترب حسب الأعداء أصدقاء؛ لأنه لم يجربهم فتوقفه التجارب على ضمائر صدورهم، ومن لم يكرم نفسه بتجنب الدنايا لم يكرمه الناس."},{"id":"muallaqat:275","bookId":"muallaqat","type":"section","seq":275,"chapter":"مدخل","title":"58- ومهما تكن عند امرئ من خليقة","page":"ج1 ص150","text":"ومهما تكن عند امرئ من خليقة ... وإن خالها تخفى على الناس تعلم\nيقول: ومهما كان للإنسان من خلق فظن أنه يخفى على الناس علم ولم يخف، والخلق والخليقة واحد، والجمع الأخلاق والخلائق، وتحرير المعنى: أن الأخلاق لا تخفى والتخلق لا يبقى."},{"id":"muallaqat:276","bookId":"muallaqat","type":"section","seq":276,"chapter":"مدخل","title":"59- وكائن ترى من صامت لك معجب","page":"ج1 ص150","text":"وكائن ترى من صامت لك معجب ... زيادته أو نقصه في التكلم.\nفي كائن ثلاث لغات، كأين وكائن وكأي، مثل كعين، وكاعن وكيع. الصمت والصمات والصموت واحد، والفعل صمت يصمت.\nيقول: وكم صامت يعجبك صمته فتستحسنه وإنما تظهر زيادته على غيره ونقصانه عن غيره عند تكلمه."},{"id":"muallaqat:277","bookId":"muallaqat","type":"section","seq":277,"chapter":"مدخل","title":"60- لسان الفتى نصف ونصف فؤاده","page":"ج1 ص151","text":"لسان الفتى نصف ونصف فؤاده ... فلم يبق إلا صورة اللحم والدم\nهذا كقول العرب: المرء بأصغريه لسانه وجنانه."},{"id":"muallaqat:278","bookId":"muallaqat","type":"section","seq":278,"chapter":"مدخل","title":"61- وإن سفاه الشيخ لا حلم بعده","page":"ج1 ص151","text":"وإن سفاه الشيخ لا حلم بعده ... وإن الفتى بعد السفاهة يحلم\nيقول: إذا كان الشيخ سفيها لم يرج حلمه؛ لأنه لا حال بعد الشيب إلا الموت، والفتى وإن كان نزقا سفيها أكسبه شيبه حلما ووقارا، ومثله قول صالح بن عبد القدوس: [الرجز] :\nوالشيخ لا يترك أخلاقه ... حتى يوارى في ثرى رمسه"},{"id":"muallaqat:279","bookId":"muallaqat","type":"section","seq":279,"chapter":"مدخل","title":"62- سألنا فأعطيتم وعدنا فعدتم","page":"ج1 ص151","text":"سألنا فأعطيتم وعدنا فعدتم ... ومن أكثر التسآل يوما سيحرم\nيقول: سألناكم رفدكم ومعروفكم فجدتم بهما، فعدنا إلى السؤال وعدتم إلى النوال، ومن أكثر السؤال حرم يوما لا محالة. والتسآل: السؤال: وتفعال من أبنية المصادر."},{"id":"muallaqat:280","bookId":"muallaqat","type":"section","seq":280,"chapter":"مدخل","title":"مدخل","page":"ج1 ص152","text":"...\nلبيد بن ربيعة\nهو: لبيد بن ربيعة بن مالك بن جعفر بن كلاب العامري، وكنيته: أبو عقيل. وهو صحابي أدرك الجاهلية والإسلام. عاش خمسا وأربعين سنة بعد المائة: 145، وقيل: بل خمسا وخمسين بعد المائة: 155.\nوكان يقال لأبيه: ربيعة المقترين؛ لجوده وسخائه.\nوقد وفد وقومه: بني جعفر بن كلاب، على النبي -صلى الله عليه وسلم- فأسلم وحسن إسلامه، وأسلم قومه.\nوكان لبيد وعلقمة بن علاثة العامريان من المؤلفة قلوبهم، وهو معدود من فحول الشعراء المجيدين.\nكان من شعراء الجاهلية وأجوادهم وفرسانهم.\nأسلم \"لبيد\" قبل الفتح، وحسن إسلامه، وهاجر، ولم يصح عنه أنه قال شيئا من الشعر بعد الإسلام إلا قوله: [الكامل] :\nما عاتب المرء الكريم كنفسه ... والمرء يصلحه القرين الصالح\nوالسبب في عدم قوله الشعر أنه لما أسلم وقرأ القرآن شغل بما فيه من حكمة رائعة، وموعظة حسنة، وبلاغة مدهشة، صرفته عن الشعر.\nوكان \"لبيد\" من الأجواد المشهورين. وكان شريفا في الجاهلية والإسلام، وكان قد نذر أن لا تهب الصبا إلا نحر وأطعم. وكانت له جفنتان يغدو بهما ويروح كل يوم على مسجد قومه فيطعمهم.\nبعد أن وفد \"لبيد\" هو وقومه على النبي -صلى الله عليه وسلم- فأسلم هو وإياهم، رجع قومه إلى\nبلادهم. وقدم هو الكوفة فأقام بها إلى أن مات، وله من العمر مائة وخمس وأربعون سنة، \"145\" على الصحيح. ويقال: إن وفاته كانت في أول مدة معاوية بن أبي سفيان وهو المشهور.\nكان رحمه الله من فحول الشعراء المخضرمين. وقد شهد له النابغة بأنه أشعر العرب؛ لأنه كان يغوص على المعنى الغريب والحكمة البليغة.\nوللبيد أخبار كثيرة وشعر أكثر من أن يحصى. فقد روي عن عائشة أم المؤمنين أنها قالت: \"رويت للبيد اثني عشر ألف بيت\".\nالحق أن معلقة \"لبيد\" لم تحو ما حواه غيرها من الحكمة والمعاني الاجتماعية إلا أنها حوت سبكا متينا، وتشابيه لطيفة، ووصفا رائعا، وحماسة جميلة. سوى أبيات يسيرة من الحكمة الجليلة، وقد افتخر فيها بمآثر قومه، ولم نظفر بالسبب الذي دعاه إلى نظمها."},{"id":"muallaqat:281","bookId":"muallaqat","type":"section","seq":281,"chapter":"مدخل","title":"1- اسمه ونسبه: هو لبيد بن ربيعة بن مالك بن جعفر بن كلاب العامري2. ويكني أبا عقيل وكان يقال لأبيه: ربيعة المقترين؛ لجوده وسخائه. وقتله بنو أس","page":"ج1 ص154","text":"وقيل: قتله منقذ بن طريف الأسدي. وقيل: قتله صامت بن الأفقم، من بني الصيداء، قيل: ضربه خالد بن نضلة وتمم عليه هذا. وأدرك بثأره عامر بن مالك بن جعفر بن كلاب أخوه، وذلك أنه قتل قاتله4.\nوعمه أبو براء عامر بن مالك ملاعب الأسنة، سمي بذلك لقول أوس بن حجر فيه:\nفلاعب أطراف الأسنة عامر ... فراح له حظ الكتيبة أجمع1\nوأم لبيد تامرة2 بنت زنباع العبسية إحدى بنات جذيمة بن رواحة3. ولبيد أحد شعراء الجاهلية المعدودين فيها والمخضرمين ممن أدرك الإسلام، وهو من أشراف الشعراء المجيدين الفرسان القراء المعمرين. يقال: إنه عمر مائة وخمسا وأربعين سنة4. وولد حوالي سنة 560م5. لما قتل والده كان لبيد ما يزال غلاما صغير السن، فتكفل أعمامه -بنو أم البنين- بتربيته، وإلى هذه الكفالة يشير بقوله:\nلعبت على أكتافهم وحجورهم ... وليدا وسموني لبيدا وعاصما\nويذكر لبيد نفسه أن والدته تامرة نشأت يتيمة في حجر الربيع بن زياد، وتزوجت أولا قيس بن جزء بن خالد بن جعفر فولدت له أربد، ثم خلفه عليها ربيعة فولدت لبيد. وعلى هذا فإن أربد يكون أكبر سنا من لبيد. وكان أربد يعطف كثيرا على أخيه الأصغر لبيد. وقد أعجب لبيد فيما بعد بفتوة أخيه من إمعانه في الفروسية والكرم إلى إقباله على لذتي الجاهلية: الخمر والميسر. يفتخر لبيد في أرجوزة له بقوله: \"نحن بنو أم البنين الأربعة\"، وأم البنين هذه هي ليلى بنت عمرو بن عامر فارس الضحياء، تزوجها مالك بن جعفر فولدت له خمسة من الأبناء -لا أربعة كما قال لبيد- وهم: عامر بن مالك ملاعب الأسنة والطفيل فارس قرزل، وسلمى نزال المضيق، ومعاوية معود الحكماء، وربيعة الذي عرف بلقب ربيعة المقترين، أو ربيع المقترين وهو والد لبيد يفتخر به في شعره، دون أن يعرفه إلا عن طريق الذكريات التي كان يقصها عليه أعمامه وأهله؛ لأن ربيعة قتل، كما ذكرنا سابقا، ولبيد إذا ذاك صغير السن."},{"id":"muallaqat:282","bookId":"muallaqat","type":"section","seq":282,"chapter":"مدخل","title":"2- بعض أخباره","page":"ج1 ص156","text":"من مواقف لبيد الأولى مشاركته لقومه بني جعفر في الارتحال عن ديارهم\nقاصدين أرض نجران؛ لأن جواب بن عوف زعيم بني أبي بكر بن كلاب حكم عليهم بالنفي، وفي هذه الحادثة نسمع ليبدا يتهكم بجواب ويسخر من حكمه، ويستغرب نفي بني جعفر:\nأبني كلاب كيف تنفى جعفر ... وبنو ضبينة حاضرو الأحباب\nقال الأصمعي: وفد عامر بن مالك ملاعب الأسنة -وكان يكني أبا البراء- في رهط من بني جعفر ومعه لبيد بن ربيعة ومالك بن جعفر، وعامر بن مالك عم لبيد، على النعمان، فوجدوا عنده الربيع بن زياد العبسي -وأمه فاطمة بنت الخرشب الأنمارية- وكان الربيع نديما للنعمان مع رجل من تجار أهل الشام يقال له: زرجون بن توفيل وكان حريفا للنعمان يبايعه، وكان أديبا حسن الحديث والندام، واستخفه النعمان فكان إذا أراد أن يخلو على شرابه بعث إليه، وإلى النطاسي، متطبب كان له، وإلى الربيع بن زياد، فخلا بهم، فلما قدم الجعفريون كان يحضرون النعمان لحاجتهم فإذا خرجوا من عنده خلا بهم الربيع فطعن فيهم، وذكر معايبهم، وكانوا بنو جعفر له أعداء، فلم يزل بالنعمان حتى صده عنهم، فدخلوا عليه يوما فرأوا منه جفاء، وقد كان يكرمهم ويقربهم، فخرجوا غضابا ولبيد متخلف في رحالهم يحفظ متاعهم ويغدو بإبلهم كل صباح فيرعاها فإذا أمسى انصرف بالإبل، فأتاهم ذات ليلة وهم يتذاكرون أمر الربيع، فسألهم عنه فكتموه، فقال: والله لا حفظت لكم متاعا ولا سرحت لكم بعيرا أو تخبروني فيم أنتم، وكانت أم لبيد يتيمة في حجر الربيع، فقالوا: خالك قد غلبنا على الملك وصد عنا وجهه، قال لبيد: فهل تقدرون على أن تجمعوا بيني وبينه فأزجره عنكم بقول ممض مؤلم لا يلتفت إليه النعمان بعده أبدا؟ قالوا: وهل عندك شيء؟ قال: نعم، قالوا: فإنا نبلوك، قال: وما ذاك؟ قالوا: تشتم هذه البقلة، وقدامهم بقلة دقيقة القضبان، قليلة الورق، لاصقة فرعا، بالأرض تدعى التربة، فقال: هذه التربة التي لا تذكي نارا، ولا تؤهل دارا، ولا تسر جارا، عودها ضئيل، وفرعها كليل، وخيرها قليل، أقبح البقول مرعى، وأقصرها فرعا، وأشدها قلعا، بلدها شاسع، وآكلها جائع، والمقيم عليها قانع، فألقوا بي أخا عبس، أرده عنكم بتعس، وأتركه من أمره في لبس. قالوا: نصبح ونرى رأينا في أمرك، فقال عامر: انظروا إلى غلامكم هذا، يعني لبيدا، فإن رأيتموه نائما فليس أمره بشيء إنما هو يتكلم بما جاء\nعلى لسانه، وإن رأيتموه ساهرا فهو صاحبه. فرمقوه فوجدوه قد ركب رحلا وهو يكدم وسطه حتى أصبح، فقالوا: أنت والله صاحبه، فعمدوا إليه فحلقوا رأسه وتركوا ذؤابته وألبسوه حلة، ثم غدا معهم وأدخلوه على النعمان، فوجدوه يتغدى ومعه الربيع بن زياد وهما يأكلان لا ثالث لهما، والدار والمجالس مملوءة من الوفود، فلما فرغ من الغداء أذن للجعفريين فدخلوا عليه، وقد كان أمرهم تقارب، فذكروا الذي قدموا له من حاجتهم، فاعترض الربيع بن زياد في كلامهم، فقال لبيد:\nأكل يوم هامتي مقزعه1 ... يا رب هيجا هي خير من دعه\nنحن بنو أم البنين الأربعه ... سيوف جن وجفان مترعه\nنحن خيار عامر بن صعصعه ... الضاربون الهام تحت الخيضعه\nوالمطعمون الجفنة المدعدعه2 ... مهلا أبيت اللعن لا تأكل معه\nإن استه من برص ملمعه ... وإنه يدخل فيه إصبعه\nيدخلها حتى يواري أشجعه ... كأنه يطلب شيئا ضيعه\nفرفع النعمان يده عن الطعام وقال: خبثت والله يا غلام علي طعامي، وما رأيت كاليوم قط، فأقبل الربيع على النعمان فقال: كذب والله ابن الفاعلة. ولقد فعلت بأمه كذا وكذا. فقال له لبيد: مثلك فعل ذلك بربيبة بيته والقريبة من أهله، وإن أمي من نساء لم يكن فواعل ما ذكرت.\nوقضى النعمان للجعفريين الحوائج من وقتهم وصرفهم. ومضى الربيع بن زياد إلى منزله من وقته. فبعث إليه النعمان بضعف ما كان يحبوه وأمره بالانصراف إلى أهله، فكتب إليه الربيع: إني قد عرفت أنه قد وقع في نفس الملك ما قال لبيد. وإني لست بارحا حتى تبعث إلي من يجردني فيعلم من حضرك من الناس أني لست كما قال. فأرسل إليه: إنك لست صانعا باتقائك مما قال لبيد شيئا. ولا قادرا على ما زلت به الألسن فالحق بأهلك. فلحق بأهله ثم أرسل إلى النعمان بأبيات شعر قالها وهي:\nلئن رحلت جمالي لا إلى سعة ... ما مثلها سعة عرضا ولا طولا\nبحيث لو وردت لخم بأجمعها ... لم يعدلوا ريشة من ريش سمويلا1\nترعى الروائم أحرار البقول بها ... لا مثل رعيكم ملحا وغسويلا2\nفاثبت بأرضك بعدي واخل متكئا ... مع النطاسي طورا وابن توفيلا\nفأجابه النعمان بقوله:\nشرد برحلك عني حيث شئت ولا ... تكثر علي ودع عنك الأباطيلا\nفقد ذكرت بشيء لست ناسيه ... ما جاورت مصر أهل الشام والنيلا\nفما اتقاؤك منه بعدما جزعت3 ... هوج المطي به نحو ابن سمويلا\nقد قيل ذلك إن حقا وإن كذبا ... فما اعتذارك من قول إذا قيلا\nفالحق بحيث رأيت الأرض واسعة ... فانشر بها الطرف إن عرضا وإن طولا\nقال: وقال لبيد يهجو الربيع بن زياد، ويزعمون أنها مصنوعة:\nربيع لا يسقك نحوي سائق4 ... فتطلب الأذحال5 والحنائق6\nويعلم المعيا به7 والسابق ... ما أنت إن ضم عليك المازق\nإلا كشيء عاقه العوائق ... إنك حاس8 حسوة فذائق\nلابد أن يغمز منك الفائق9 ... غمزا ترى أنك منه نازق\nإنك شيخ خائن منافق ... بالمخزيات ماهر مطابق1، 2\nويقال إن بني عامر أقاموا في منفاهم حولا، ويدل شعر لبيد على أن بعض المشكلات في ذلك المنفى كادت تفرق بينهم، وأنه كان له الفضل في توحيد الكلمة قال:\nويوم منعت الحي أن يتفرقوا ... بنجران فقري ذلك اليوم فاقر3\nوكان زعيم الجعفريين في أيام المنفى هو عم لبيد أبو براء عامر بن مالك ملاعب الأسنة، وقد أبى هذا الزعيم أن يقبل بمصاهرة بني الحارث بن كعب، وأمر قومه بلبس السلاح وركوب الخيل، ثم قال لهم: \"سيروا حتى تقطعوا ثنية القهر -وهي ثنية باليمن- فإذا قطعتموها فانزلوا\". ففعلوا ما أمرهم به، ثم لحق بهم عند الثنية وقال لهم: \"هل أخذت لكم دية أو أبتكم على خسف قط؟ قالوا: لا. قال: والله لتطيعنني أو لأتكئن على سيفي حتى يخرج من ظهري. أتدرون ما أراد القوم؟ أرادوا أن يرتبطوكم فتكونوا فيم أذنابا، ويستعينوا بكم على العرب وأنتم سادة هوزان ورؤساؤهم\". ونصحهم أبو براء بالعودة إلى أوطانهم ومصالحة أقربائهم. فعادوا ونزلوا على حكم جواب، وفي هذه المرة كانت نفس لبيد قد هدأت نحو جواب، ولم يشأ وهو ابن القبيلة أن يخرج على روح الصلح والوئام. وأخذ يتحدث إلى بني أبي بكر بأن المحافظة على علاقات الود والقربى أجدى على الفريقين من الخصام قال:\nفأبلغ بني بكر إذا ما لقيتها ... على خير ما يلقى به من تزغما4\nأبونا أبوكم والأواصر بيننا ... قريب، ولم نأمر منيعا5 ليأثما\nفإن تقبلوا المعروف نصبر لحقكم. ... ولن يعدم المعروف خفا ومنسما6\nوكل هذا يدل على أن لبيدا كان قد أصبح لسان قومه، وأن نجمه في خدمة القبيلة كان في صعود مستمر حتى أصبح اسمه لامعا في مجال الشعر.\nكان لبيد من أجواد العرب، وكان قد آلى في الجاهلية أن لا تهب صبا إلا أطعم، وكانت له جفنتان يغدو بهما ويروح في كل يوم على مسجد قومه فيطعمهم.\nفهبت الصبا يوما ووليد بن عقبة على الكوفة، فصعد الوليد المنبر فخطب الناس ثم قال: إن أخاكم لبيد بن ربيعة قد نذر في الجاهلية، أن لا تهب صبا إلا أطعم، وهذا يوم من أيامه وقد هبت صبا فأعينوه وأنا أول من يفعل، ثم نزل عن المنبر فأرسل إليه بمائة بكرة وكتب إليه بأبيات قالها:\nأرى الجزار يشحذ شفرتيه ... إذا هبت رياح أبي عقيل\nأشم الأنف أصيد عامري ... طويل الباع كالسيف الصقيل\nوفى ابن الجعفري بحلفتيه ... على العلات والمال القليل\nبنحر الكوم1 إذ سحبت عليه ... ذيول صبا تجاوب بالأصيل\nفلما بلغت أبياته لبيدا قال لابنته: أجيبيه فلعمري لقد عشت برهة وما أعيا بجواب شاعر: فقالت ابنته:\nإذا هبت رياح أبي عقيل ... دعونا عند هبتها الوليدا\nأشم الأنف، أروع عبشميا ... أعان على مروءته لبيدا\nبأمثال الهضاب كأن ركبا ... عليها من بني حام قعودا\nأبا وهب جزاك الله خيرا ... نحرناها فأطعمنا الثريدا\nفعد إن الكريم له معاد ... وظني لا أبا لك أن تعودا\nفقال له لبيد: قد أحسنت لولا أنك استطعمته، فقالت: إن الملوك لا يستحيا من مسألتهم، فقال: وأنت يا بنية في هذه أشعر2.\nقيل: وكان لبيد أحد المعمرين، وهو القائل لما بلغ تسعين حجة:\nكأني وقد جاوزت تسعين حجة ... خلعت بها عني عذار لجامي\nرمتني بنات الدهر من حيث لا أرى ... فكيف بمن يرمى، وليس برامي\nولو أنني أرمي بسهم رأيتها ... ولكنني أرمى بغير سهام\nوقال حين بلغ عشرين ومائة:\nوغنيت دهرا قبل مجرى داحس، ... لو كان للنفس اللجوج خلود\nوقال حين بلغ أربعين ومائة:\nولقد سئمت من الحياة وطولها، ... وسؤال هذا الناس كيف لبيد؟\nغلب الزمان، وكان غير مغلب ... دهر طويل دائم ممدود\nيوم إذا يأتي علي، وليلة ... وكلاهما بعد انقضاه1 يعود\nثم أسلم، وحسن إسلامه، وجمع القرآن وترك قول الشعر2 قال أبو عبيدة: لم يقل لبيد في الإسلام إلا بيتا واحدا وهو:\nالحمد لله إذ لم يأتني أجلي ... حتى لبست من الإسلام سربالا3.\nكتب عمر بن الخطاب إلى المغيرة بن شعبة وهو على الكوفة: أن استنشد من قبلك، من شعراء مصرك ما قالوا في الإسلام، فأرسل إلى الأغلب الراجز العجلي فقال له: أنشدني فقال:\nأرجزا تريد أم قصيدا ... لقد طلبت هينا موجودا\nثم أرسل إلى لبيد فقال: أنشدني. فقال: إن شئت ما عفي عنه، يعني الجاهلية، فقال: لا أنشدني ما قلت في الإسلام، فانطلق فكتب سورة البقرة في صحيفة، ثم أتى بها وقال: أبدلني الله هذه في الإسلام مكان الشعر فكتب بذلك المغيرة إلى عمر\nفنقص من عطاء الأغلب خمسمائة وجعلها في عطاء لبيد، فكان عطاؤه ألفين فجعله ألفين وخمسائة، فكتب الأغلب إلى أمير المؤمنين: أتنقص عطائي أن أطعتك؟ فرد عليه خمسمائة وأقر عطاء لبيد على ألفين وخمسمائة. فلما كان في زمن معاوية، قال له معاوية: هذا الفودان1 يعني الألفين، فما بال العلاوة؟ يعني الخمسمائة فقال له لبيد: إنما أنا هامة اليوم أو غد، فأعرني اسمها فلعلي لا أقبضها أبدا، فتبقى لك العلاوة والفودان. فرق له وترك عطاءه على حاله فمات لم يقبضه2.\nوأربد بن قبس الذي أتى النبي -صلى الله عليه وسلم- غادرا هو أخو لبيد لأمه، وكان قدم عليه مع عامر بن الطفيل، فدعا الله عليه، فأصابته بعد منصرفه صاعقة فأحرقته، قال لبيد:\nأخشى على أربد الحتوف3 ولا ... أرهب نوء السماك والأسد\nفجعني الرعد والصواعق بال ... فارس يوم الكريهة النجد4"},{"id":"muallaqat:283","bookId":"muallaqat","type":"section","seq":283,"chapter":"مدخل","title":"3- أقوال القدماء في فنه","page":"ج1 ص163","text":"ومما يستجاد له قوله5:\nفاقطع لبانة من تعرض وصله ... ولخير واصل خلة صرامها6\nويستجاد له قوله أيضا7:\nواكذب النفس إذا حدثتها ... إن صدق النفس يزري بالأمل\nومما يعاب له في هذه القصيدة:\nومقام ضيق فرجته ... بمقامي ولساني وجدل\nلو يقوم الفيل أو فياله ... زل عن مثل مقامي وزحل\nوقالوا: ليس للفيال من الخطابة والبيان، ولا من القوة ما يجعله مثلا لنفسه! وإنما ذهب إلى أن الفيل أقوى البهائم، فظن أن فياله أقوى الناس1!.\nرتب ابن سلام لبيدا في الطبقة الثالثة من الشعر2.\nوجاء في طبقات الشعراء: وكان لبيد بن ربيعة عذب المنطق، رقيق حواشي الكلام، وكان مسلما رجل صدق، وكان في الجاهلية خير شاعر لقومه يمدحهم ويرثيهم، ويعد أيامهم ووقائعهم وفرسانهم3.\nوشعر لبيد من أجود أشعار البدو، واختار حماد قصيدة منه في المعلقات. ولبيد قدير على صياغة موضوعات البداوة صياغة ساحرة، ومما يزيد شعره نفاسة ما يتردد فيه من نغمات دينية. على أن الأدباء لم يتفقوا في تقويم شعر لبيد، فمنهم من رآه سهل المنطق، رقيق الحواشي، ومنهم من عده مثالا لخشونة الكلام وصعوبته، وكل من هذين الفريقين ينظر إلى شعره من زاوية معينة، فأما الذين وصفوه بالرقة والسهولة فقد نظروا إلى أشعاره ذات السمات الدينية، وأما الذين وصفوه بالخشونة فنظروا إلى شعره الذي يصور فيه مناظر الصحراء، ويفتخر فيه بأمجاد وأيام قبيلته. ولم يكن الأصمعي معجبا بشعره فوصفه بأنه: \"طيلسان طبراني\" أي أنه محكم الأصل ولا رونق له، ولم يعده في الفحول، ووصفه بالصلاح تهربا من أن يحكم على شعره الديني؛ لأن الأصمعي كان يرى أن الشعر إذا دخل في باب الخير لان، أي أصابه ضعف. وقال أبو عمرو بن العلاء: \"ما أحد أحب إلي شعرا من لبيد بن ربيعة لذكره الله عز وجل، ولإسلامه، ولذكره الدين والخير، ولكن شعره رحى بزر4\".\nومما سبق إليه فأخذ منه قوله1:\nكعقر الهاجري إذا بناه ... بأشباه حذين على مثال\nأخذه الطرماح فقال:\nحرجا كمجدل هاجري لزه ... بذوات طبخ أطيمة لا تخمد\nقدرت على مثل فهن توائم ... شتى يلائم بينهن القرمد2\nومن ذلك قوله وذكر نوقا:\nلها حجل قد قرعت من رءوسه ... لها فوقه مما تحلب واشل\nأخذ النابغة الجعدي فقال:\nلها حجل قرع الرءوس تحلبت ... على هامة بالصيف حتى تمورا\nيعني بالحجل أولادها الصغار3:\nويستجاد له قوله في النعمان، يصف نظره وشرته:\nفانتضلنا، وابن سلمى قاعد ... كعتيق الطير يغضي ويجل4\nوالهبانيق5 قيام، معهم ... كل محجوم6 إذا صب همل\nتخسر7 الديباج عن أذرعهم ... عند ذي تاج إذا قال فعل\nفتولوا فاترا مشيهم ... كروايا8 الطبع همت بالوحل9\nولبيد أول من شبه الأباريق بالبط، فأخذ منه ذلك، قال يذكر الخمر:\nتضمن بيضا كالإوز ظرفها ... إذا أتاقوا أعناقها والحواصلا\nفأخذه بعض الضبيين فقال:\nويوم كظل الرمح قصر طوله ... دم الزق عنا واصطفاف المزاهر\nكأن أباريق الشمول عشية ... إوز بأعلى الطف عوج المناقر1\nقال الذين قدموا لبيد بن ربيعة: هو أفضلهم في الجاهلية والإسلام، وأقلهم لغوا في شعره. وقد قيل عن عائشة، رضي الله عنها، إنها قالت، رحم الله لبيدا ما أشعره في قوله:\nذهب الذين يعاش في أكنافهم ... وبقيت في خلق كجلد الأجرب\nلا ينفعون، ولا يرجى خيرهم، ... ويعاب قائلهم وإن لم يشغب2.\nثم قالت: كيف لو رأى لبيد خلفنا هذا! ويقول الشعبي: كيف لو رأت أم المؤمنين خلفنا هذا3!.\nوكان لبيد إذا سئل عن أعظم الشعراء حسب تقديره بدأ بامرئ القيس ثم ثنى بطرفة ثم ذكر نفسه. قيل: مر لبيد بالكوفة على مجلس بني نهد وهو يتوكأ على محجن له، فبعثوا إليه رسولا يسأله عن أشعر العرب فسأله فقال: الملك الضليل ذو القروح، فرجع فأخبرهم، فقالوا: هذا امرؤ القيس، ثم رجع إليه فسأله: ثم من؟ فقال له: الغلام المقتول من بني بكر، فرجع فأخبرهم، فقالوا: هذا طرفة، ارجع فاسأله ثم من؛ فسأله، فقال: ثم صاحب المحجن حيث يقول:\nإن تقوى ربنا خير نفل ... وبإذن الله ريثي وعجل\nأحمد الله فلا ند له ... بيديه الخير ما شاء فعل\nمن هداه سبل الخير اهتدى ... ناعم البال ومن شاء أضل\nيعني نفسه1.\nقال عبد الله بن قتادة المحاربي: كنت مع النابغة بباب النعمان بن المنذر، فقال لي النابغة: هل رأيت لبيد بن ربيعة فيمن حضر؟ قلت: نعم، قال: أيهم هو؟ قلت: الفتى الذي رأيت من حاله كيت وكيت. فقال: اجلس بنا حتى يخرج إلينا. قال: فجلسنا، فلما خرج قال له النابغة: إلى يابن أخي، فأتاه، فقال: أنشدني، فأنشده قوله:\nألم تلمم على الدمن الخوالي ... لسلمي بالمذانب فالقفال\nفقال له: أنت أشعر بني عامر، زدني فأنشده قوله:\nطلل لخولة بالرسيس قديم ... فبعاقل فالأنعمين رسوم\nفقال له: أنت أشعر هوازن، زدني فأنشده قوله.\nعفت الديار محلها فمقامها ... بمنى تأبد غولها فرجامها\nفقال له النابغة: اذهب فأنت أشعر العرب2.\nقال ابن البواب: جلس المعتصم يوما للشراب فغناه بعض المغنين قوله:\nوبنو العباس لا يأتون لا ... وعلى ألسنهم خفت نعم\nزينت أحلامهم أحسابهم ... وكذاك الحلم زين للكرم\nفقال: ما أعرف هذا الشعر، فلمن هو؟ قيل: للبيد فقال: وما للبيد وبني العباس؟ فقال المغني: إنما قال:\nوبنو الديان لا يأتون لا\nفجعلته: وبنو العباس. فاستحسن فعله ووصله. وكان يعجب بشعر لبيد، فقال: من منكم يروي قوله:\nبلينا وما تبلى النجوم الطوالع\nقال بعض الجلساء: أنا، فقال: أنشدنيها فأنشد:\nبلينا وما تبلى النجوم الطوالع ... وتبقى الجبال بعدنا والمصانع\nوقد كنت في أكناف جار مضنة ... ففارقني جار بأربد نافع\nفبكى المعتصم حتى جرت دموعه وترحم على المأمون وقال: هكذا كان رحمة الله عليه ينشدها لي، ثم اندفع ينشد هو باقيها ... وقال: فوالله لعجبنا من حسن ألفاظه، وصحة إنشاده، وفصاحته، وجودة اختياره1.\nعندما سمع الفرزدق قول لبيد:\nوخلا السيول عن الطلول كأنها ... زبر2 تجد متونها3 أقلامها\nفسجد الفرزدق، فقيل له: ما هذا يا أبا فراس؟ فقال: أنتم تعرفون سجدة القرآن وأنا أعرف سجدة الشعر4.\nولقد أتيح للقسم الأكبر من شعره، لما فيه من ذخيرة كبيرة من اللغة النجدية، أن يكون صالحا للاستشهاد في كتب اللغة، وهذا الأمر قد ساعد كثيرا على ترديد بعض شعره. وكان البدو الكلابيون، ممن كان العلماء يأخذون برأيهم في اللغة والغريب، ذوي أثر في تقريب شعره إلى الأفهام."},{"id":"muallaqat:284","bookId":"muallaqat","type":"section","seq":284,"chapter":"مدخل","title":"4- موته","page":"ج1 ص168","text":"لما حضرته الوفاة قال لابن أخيه -ولم يكن له ولد ذكر: يا بني إن أباك لم يمت ولكنه فني، فإذا قبض أبوك فأقبله القبلة وسجه بثوبه، ولا تصرخن عليه صارخة وانظر جفنتي، اللتين كنت أصنعهما، فاصنعهما ثم احملهما إلى المسجد. فإذا سلم الإمام فقدمهما إليهم فإذا طعموا فقل لهم فليحضروا جنازة أخيهم، ثم أنشد قوله:\nوإذا دفنت أباك فاج ... عل فوقه خشبا وطينا\nوصفائحا صما روا ... سيها يسددن الغضونا\nليقين وجه المرء سف ... ساف التراب ولن يقينا1.\nوقد اختلف في عمره يوم مات. فقد جاء في الأغاني ما يلي: \"قدم لبيد على رسول الله -صلى الله عليه وسلم- في وفد بني كلاب بعد وفاة أخيه أربد وعامر بن الطفيل فأسلم وهاجر وحسن إسلامه، ونزل الكوفة أيام عمر بن الخطاب -رضي الله تعالى عنه- فأقام بها، ومات هناك في آخر أيام معاوية بن سفيان، فكان عمره مائة وخمسا وأربعين سنة، منها تسعون في الجاهلية وبقيتها في الإسلام2.\nوذكر ابن قتيبة: وأدرك لبيد الإسلام، وقدم على رسول الله -صلى الله عليه وسلم- في وفد بني كلاب، فأسلموا ورجعوا إلى بلادهم. ثم قدم لبيد الكوفة وبنوه، فرجع بنوه إلى البادية بعد ذلك، فأقام لبيد إلى أن مات بها، فدفن في صحراء بني جعفر بن كلاب.\nويقال إن وفاته كانت في أول خلافة معاوية، وأنه مات هو ابن مائة وسبع وخمسين سنة3.\nوهكذا نرى أن لبيدا عمر كثيرا، فعمره في رأي المكثرين مائة وسبع وخمسون سنة، وفي رأي المقللين لا يقل عن مائة وعشر سنوات] ."},{"id":"muallaqat:285","bookId":"muallaqat","type":"section","seq":285,"chapter":"مدخل","title":"1- عفت الديار محلها فمقامها","page":"ج1 ص169","text":"عفت الديار محلها فمقامها ... بمنى تأبد غولها فرجامها\nعفا لازم ومتعد، يقال: عفت الريح المنزل وعفا المنزل نفسه عفوا وعفوا وعفاء، وهو في البيت لازم. المحل من الديار: ما حل فيه لأيام معدودة، والمقام منها: ما طالت الإقامة به. منى: موضع بحمى ضرية غير منى الحرم، ومنى ينصرف ولا ينصرف ويذكر ويؤنث. تأبد: توحش، وكذلك أبد يأبد ويأبد أبودا. الغول والرجام: جبلان معروفان؛ ومنه قول أوس بن حجر: [البسيط] :\nزعمتم أن غولا والرجام لكم ... ومنعجا فاذكروا الأمر مشترك\nيقول: عفت ديار الأحباب وانمحت منازلهم ما كان منها للحلول دون الإقامة وما كان منها للإقامة، وهذه الديار كانت بالموضع المسمى منى، وقد توحشت الديار الغولية، والديار الرجامية منها لارتحال قطانها واحتمال سكانها، والكناية في غولها ورجامها راجعة إلى الديار، قوله: تأبد غولها، أي: ديار غولها وديار رجامها، فحذف المضاف."},{"id":"muallaqat:286","bookId":"muallaqat","type":"section","seq":286,"chapter":"مدخل","title":"2- فمدافع الريان عرى رسمها","page":"ج1 ص169","text":"فمدافع الريان عرى رسمها ... خلقا كما ضمن الوحي سلامها\nالمدافع: أماكن يندفع عنها الماء من الربى والأخياف1، الواحد مدفع. الريان: جبل معروف؛ ومنه قول جرير: [البسيط] :\nيا حبذا جبل الريان من جبل ... وحبذا ساكن الريان من كانا\nالتعرية: مصدر عريته فعري وتعرى. الوحي: الكتابة، والفعل وحى يحي،\nوالوحي الكتاب، والجمع الوحي. السلام: الحجارة والواحدة سلمة، بكسر اللام؛ فمدافع: معطوف على قوله غولها.\nيقول: توحشت الديار الغولية والرجامية، وتوحشت مدافع جبل الريان لارتحال الأحباب منها واحتمال الجيران عنها، ثم قال: وقد توحشت وغيرت رسوم هذه الديار فعريت خلقا وإنما عراها السيول ولم تنمح بطول الزمان، فكأنه كتاب ضمن حجرا، شبه بقاء الآثار لقدم الأيام ببقاء الكتاب في الحجر، ونصب خلقا على الحال، والعامل فيه عري، والمضمر الذي أضيف إليه سلام عائد إلى الوحي."},{"id":"muallaqat:287","bookId":"muallaqat","type":"section","seq":287,"chapter":"مدخل","title":"3- دمن تجرم بعد عهد أنيسها","page":"ج1 ص171","text":"دمن تجرم بعد عهد أنيسها ... حجج خلون حلالها وحرامها\nالتجرم: التكمل والانقطاع، يقال: تجرمت السنة وسنة مجرمة أي مكملة. العهد: اللقاء، والفعل عهد يعهد، الحجج: جمع حجة وهي السنة. وأراد بالحرام الأشهر الحرم، وبالحلال أشهر الحل. الخلو: المضي، ومنه الأمم الخالية، ومنه قوله عز وجل: {وقد خلت القرون من قبلي} [الأحقاف: 17] .\nيقول: هي آثار ديار قد تمت وكملت وانقطعت بعد عهد سكانها بها. سنون مضت أشهر الحرم وأشهر الحل منها؛ وتحرير المعنى: قد مضت بعد ارتحالهم عنها سنون بكمالها. خلون: المضمر فيه راجع إلى الحجج، وحلالها بدل من الحجج، وحرامها معطوف عليها، والسنة لا تعدو أشهر الحرم وأشهر الحل، فعبر عن مضي السنة بمضيهما."},{"id":"muallaqat:288","bookId":"muallaqat","type":"section","seq":288,"chapter":"مدخل","title":"4- رزقت مرابيع النجوم وصابها","page":"ج1 ص171","text":"رزقت مرابيع النجوم وصابها ... ودق الرواعد جودها فرهامها\nمرابيع النجوم: الأنواء الربيعية وهي المنازل التي تحلها الشمس فصل الربيع، الواحد مرباع. الصوب: الإصابة، يقال: صابه أمر كذا وأصابه بمعنى. الودق: المطر، وقد ودقت السماء تدق ودقا إذا أمطرت. الجود: المطر التام العام، وقال ابن الأنباري: هو المطر الذي يرضي أهله، وقد جاد المطر يجود جودا فهو جود. الرواعد: ذوات الرعد من السحاب، واحدتها راعدة. الرهام والرهم: جمعا رهمة وهي المطرة التي فيها لين.\nيقول: رزقت الديار والدمن أمطار الأنواء الربيعية فأمرعت1، وأعشبت وأصابها مطر ذوات الرعود من السحاب ما كان منه عاما بالغا مرضيا أهله، وما كان منه لينا سهلا؛ وتحرير المعنى: أن تلك الديار ممرعة معشبة لترادف الأمطار المختلفة عليها ونزهتها."},{"id":"muallaqat:289","bookId":"muallaqat","type":"section","seq":289,"chapter":"مدخل","title":"5- من كل سارية وغاد مدجن","page":"ج1 ص172","text":"من كل سارية وغاد مدجن ... وعشية متجاوب إرزامها\nالسارية: السحابة الماطرة ليلا، والجمع السواري. المدجن: الملبس آفاق السماء بظلامه لفرط كثافته، والدجن: إلباس الغيم آفاق السماء، وقد أدجن الغيم. الإرزام: التصويت، وقد أرزمت الناقة إذا رغت، والاسم الرزمة، ثم فسر تلك الأمطار فقال: هي من كل مطر سحابة سارية ومطر سحاب غاد يلبس آفاق السماء بكثافته وتراكمه، وسحابة عشية تتجاوب أصواتها، أي كأن رعودها تتجاوب، جمع لها أمطار السنة؛ لأن أمطار الشتاء أكثرها يقع ليلا، وأمطار الربيع أكثرها يقع غداة، وأمطار الصيف أكثرها يقع عشيا؛ كذا زعم مفسرو هذا البيت."},{"id":"muallaqat:290","bookId":"muallaqat","type":"section","seq":290,"chapter":"مدخل","title":"6- فعلا فروع الأيهقان وأطفلت","page":"ج1 ص172","text":"فعلا فروع الأيهقان وأطفلت ... بالجلهتين ظباؤها ونعامها\nالأيهقان، بفتح الهاء وضمها: ضرب من النبت وهو الجرجير البري. أطفلت أي صارت ذوات أطفال. الجلهتان: جانبا الوادي، ثم أخبر عن إخصاب الديار وإعشابها فقال: فعلت بها فروع هذا الضرب من النبت وأصبحت الظباء والنعام ذوات أطفال بجانبي وادي هذه الديار؛ قوله: ظباؤها ونعامها، يريد: وأطفلت ظباؤها وباضت نعامها؛ لأن النعام تبيض ولا تلد الأطفال، ولكنه عطف النعام على الظباء في الظاهر لزوال اللبس؛ ومثله قول الشاعر: [الوافر] :\nإذا ما الغانيات برزن يوما ... وزججن الحواجب والعيونا\nأي وكحلن العيون، وقول الآخر: [الطويل] :\nتراه كأن الله يجدع أنفه ... وعينيه أن مولاه صار له وفر\nأي ويفقأ عينيه، وقول الآخر: [مجزوء الكامل] :\nيا ليت زوجك قد غدا ... متقلدا سيفا ورمحا\nأي وحاملا رمحا، تضبط نظائر ما ذكرنا، وزعم كثير من الأئمة النحويين البصريين والكوفيين أن هذا المذهب سائغ في كل موضع، ولوح أبو الحسن الأخفش إلى أن المعول فيه على السماع."},{"id":"muallaqat:291","bookId":"muallaqat","type":"section","seq":291,"chapter":"مدخل","title":"7- والعين ساكنة على أطلائها","page":"ج1 ص173","text":"والعين ساكنة على أطلائها ... عوذا تأجل بالفضاء بهامها\nالعين: واسعات العيون. الطلا: ولد الوحش حين يولد إلى أن يأتي عليه شهر، والجمع الأطلاء، ويستعار لولد الإنسان وغيره. العوذ: الحديثات النتاج، الواحدة عائذ، مثل عائط1 وعوط وحائل2 وحول وبازل3 وبزل وفاره وفره، وجمع الفاعل على فعل قليل معول فيه على الحفظ. الإجل: القطيع من بقر الوحش، والجمع الآجال والتأجل: صيرورتها إجلا إجلا. الفضاء: الصحراء. البهام: أولاد الضأن إذا انفردت وإذا اختلطت بأولاد الضأن أولاد المعز قيل للجميع بهام، وإذا انفردت أولاد المعز عن أولاد الضأن لم تكن بهاما، وبقر الوحش بمنزلة الضأن وشاء الجبل بمنزلة المعز عند العرب، وواحد البهام بهم، وواحد البهم بهمة، ويجمع البهام على البهامات.\nيقول: والبقر الواسعات العيون قد سكنت وأقامت على أولادها ترضعها حال كونها حديثات النتاج وأولادها تصير قطيعا قطيعا في تلك الصحراء، فالمعنى من هذا الكلام: أنها صارت مغنى الوحوش بعد كونها مغنى الإنس. ونصب عوذا على الحال من العين."},{"id":"muallaqat:292","bookId":"muallaqat","type":"section","seq":292,"chapter":"مدخل","title":"8- وجلا السيول عن الطلول كأنها","page":"ج1 ص173","text":"وجلا السيول عن الطلول كأنها ... زبر تجد متونها أقلامها\nجلا: كشف، يجلو جلاء؛ وجلوت العروس جلوة من ذلك، وجلوت السيف جلاء صقلته، منه أيضا. السيول: جمع سيل مثل بيت وبيوت وشيخ وشيوخ، الطلول:\nجمع الطلل. الزبر: جمع زبور وهو الكتاب والزبر الكتابة، والزبور فعول بمعنى المفعول بمنزلة الركوب والحلوب بمعنى المركوب والمحلوب. الإجداد والتجديد واحد.\nيقول: وكشفت السيول عن أطلال الديار فأظهرتها بعد ستر التراب إياها، فكأن الديار كتب تجدد الأقلام كتابتها، فشبه كشف السيول عن الأطلال التي غطاها التراب بتجديد الكتاب سطور الكتاب الدارس، وظهور الأطلال بعد دروسها بظهور السطور بعد دروسها، وأقلام مضافة إلى ضمير زبر، واسم كأن ضمير الطلول."},{"id":"muallaqat:293","bookId":"muallaqat","type":"section","seq":293,"chapter":"مدخل","title":"9- أو رجع واشمة أسف نئورها","page":"ج1 ص174","text":"أو رجع واشمة أسف نئورها ... كففا تعرض فوقهن وشامها\nالرجع: الترديد والتجديد، وهو من قولهم: رجعته أرجعه رجعا فرجع يرجع رجوعا. وقد فسرنا الواشمة. الإسفاف: الذر وهو من قولهم؛ سف زيد السويق وغيره يسفه سفا وأسففته السويق وغيره، ثم يقال: أسففت الدواء الجرح والكحل العين. النئور: النقش المتخذ من دخان السراج والنار، وقيل النيلج. الكفف: جمع كفة وهي الدارات، وكل شيء مستدير كفة، بكسر الكاف، وجمعها كفف، وكل مستطيل كفة، بضمها، والجمع كفف، كذا حكى الأئمة. تعرض وأعرض: ظهر ولاح. الوشام، جمع وشم؛ شبه ظهور الأطلال بعد دروسها بتجديد الكتابة وتجديد الوشم.\nيقول: كأنها زبر أو ترديد واشمة وشما قد ذرت نئورها في دارات ظهر الوشام فوقها، فأعادتها كما تعيد السيول الأطلال إلى ما كانت عليه، فجعل إظهار السيل الأطلال كإظهار الواشمة الوشم، وجعل دروسها كدروس الوشم. نئورها: اسم ما لم يسم فاعله. وكففا هو المفعول الثاني بقي على انتصابه بعد إسناد الفعل إلى المفعول. وشامها: فاعل تعرض وقد أضيف إلى ضمير الواشمة."},{"id":"muallaqat:294","bookId":"muallaqat","type":"section","seq":294,"chapter":"مدخل","title":"10- فوقفت أسألها وكيف سؤالنا","page":"ج1 ص174","text":"فوقفت أسألها وكيف سؤالنا ... صما خوالد ما يبين كلامها\nالصم: الصلاب، والواحد أصم والواحدة صماء، خوالد: بواق، يبين: يظهر بان يبين بيانا، وأبان قد يكون بمعنى أظهر ويكون بمعنى ظهر، وكذلك بين وتبين قد يكون بمعنى ظهر وقد يكون بمعنى عرف، واستبان كذلك، فالأول لازم والأربعة قد\nتكون لازمة وقد تكون متعدية، وقولهم: أبان الصبح لذي عينين، أي ظهر فهو هنا لازم. ويروى في البيت: ما يبين كلامها وما يبين، بفتح الياء وضمها، وهما بمعنى ظهر.\nيقول: فوقفت أسأل الطلول عن قطانها وسكانها، ثم قال: وكيف سؤالنا حجارة صلابا بواقي لا يظهر كلامها، أي: كيف يجدي هذا السؤال على صاحبه وكيف ينتفع به السائل؟ لوح إلى أن الداعي إلى هذا السؤال فرط الكلف والشغف وغاية الوله، وهذا مستحب في النسيب والمرثية؛ لأن الهوى والمصيبة يدلهان1 صاحبهما."},{"id":"muallaqat:295","bookId":"muallaqat","type":"section","seq":295,"chapter":"مدخل","title":"11- عريت وكان بها الجميع فأبكروا","page":"ج1 ص175","text":"عريت وكان بها الجميع فأبكروا ... منها وغودر نؤيها وثمامها\nبكرت من المكان وأبكرت وابتكرت وبكرت بمعنى، أي سرت منه بكرة. المغادرة: الترك غادرت الشيء تركته وخلفته، ومنه الغدير؛ لأنه ماء تركه السيل وخلفه، والجمع الغدر والغدران والأغدرة. النؤي: نهير يحفر حول البيت لينصب إليه الماء من البيت، والجمع نؤي وأنآء وتقلب فيقال آناء مثل أبآر وآبار وأرآء وآراء. الثمام: ضرب من الشجر رخو يسد به خلل البيوت.\nيقول: عريت الطلول عن قطانها بعد كون جميعهم بها، فساروا منها بكرة وتركوا النؤي والثمام، أي لم يبق بمنازلهم منهم آثار إلا النؤي والثمام، وإنما لم يحملوا الثمام؛ لأنه لا يعوزهم في محالهم."},{"id":"muallaqat:296","bookId":"muallaqat","type":"section","seq":296,"chapter":"مدخل","title":"12- شاقتك ظعن الحي حين تحملوا","page":"ج1 ص175","text":"شاقتك ظعن الحي حين تحملوا ... فتكنسوا قطنا تصر خيامها\nالظعن: بتسكين العين تخفيف الظعن بضمها، وهي جمع الظعون: وهو البعير الذي عليه هودج وفيه امرأة، وقد يكون الظعن جمع ظعينة وهي المرأة الظاعنة مع زوجها، ثم يقال لها وهي في بيتها ظعينة، وقد يجمع بالظعائن أيضا. التكنس: دخول الكنائس2 والاستكنان به. القطن: جمع قطين وهو الجماعة، والقطن واحد. الصرير: صوت الباب والرحل وغير ذلك.\nيقول: حملتك على الاشتياق والحنين ونساء الحي أو مراكبهن يوم ارتحل الحي ودخلوا في الكنس، جعل الهوادج للنساء بمنزلة الكنس للوحش، ثم قال: وكانت خيامهم المحمولة تصر لجدتها. وتلخيص المعنى: دعتك إلى الاشتياق والنزاع وحملتك عليهما نساء القبيلة حين دخلن هوادجهن جماعات في حال صرير خيامهن المحمولة، أو دخلن هوادج غطيت بثياب القطن، والقطن من الثياب الفاخرة عندهم، والضمير في تكنسوا للحي، والمضمر الذي أضيف إليه الخيام للظعن، وقطنا منصوبا على الحال إن جعلته جمع قطين، ومفعول به إن جعلته قطنا."},{"id":"muallaqat:297","bookId":"muallaqat","type":"section","seq":297,"chapter":"مدخل","title":"13- من كل محفوف يظل عصيه","page":"ج1 ص176","text":"من كل محفوف يظل عصيه ... زوج عليه كلة وقرامها\nحف الهودج وغيره بالثياب: إذا غطي بها، وحف الناس حول الشيء أحاطوا به. أظل الجدار الشيء: إذا كان في ظل الجدار. العصي هنا: عيدان الهودج. الزوج: النمط1 من الثياب، والجمع الأزواج. الكلة: الستر الرقيق، والجمع الكلل. القرام: الستر، والجمع القرم، ثم فصل الظعن فقال: هي من كل هودج حف بالثياب يظل عيدانه نمط أرسل عليه، ثم فصل الزوج فقال: هو كلة، وعبر بها عن الستر الذي يلقى فوق الهودج لئلا تؤذي الشمس صاحبته، وعبر بالقرام عن الستر المرسل على جونب الهودج، وتحرير المعنى: الهوادج محفوفة بالثياب فعيدانها تحت ظلال ثيابها، والمضمر بعد القرام للعصى أو الكلة."},{"id":"muallaqat:298","bookId":"muallaqat","type":"section","seq":298,"chapter":"مدخل","title":"14- زجلا كأن نعاج توضح فوقها","page":"ج1 ص176","text":"زجلا كأن نعاج توضح فوقها ... وظباء وجرة عطفا أرآمها\nالزجل: الجماعات، الواحدة زجلة. النعاج: إناث بقر الوحش، الواحدة نعجة. وجرة: موضع بعينه. الطعف: جمع العاطف من العطف الذي هو الترحم أو من العطف الذي هو الثني، الأرآم: جمع الرئم وهو الظبي الخالص البياض.\nيقول: تحملوا جماعات كأن إناث بقر الوحش فوق الإبل، شبه النساء في حسن الأعين والمشي بها أو بظباء وجرة في حال ترحمها على أولادها أو في عطفها أعناقها للنظر إلى أولادها. شبه النساء بالظباء في هذه الحال؛ لأن عيونها أحسن ما\nتكون في هذه الحال لكثرة مائها، وتحرير المعنى: أنه شبه النساء ببقر توضح وظباء وجرة في كحل أعينها؛ نصب زجلا على الحال والعامل فيها تحملوا، ونصب عطفا على الحال، ورفع أرآمها لأنها فاعل والعامل فيها الحال السادة مسد الفعل."},{"id":"muallaqat:299","bookId":"muallaqat","type":"section","seq":299,"chapter":"مدخل","title":"15- حفزت وزايلها السراب كأنها","page":"ج1 ص177","text":"حفزت وزايلها السراب كأنها ... أجزاع بيشة أثلها ورضامها\nالحفز: الدفع، والفعل حفز يحفز. الأجزاع: جمع جزع وهو منعطف الوادي. بيشة: واد بعينه. الأثل: شجر يشبه الطرفاء إلا أنه أعظم منها. الرضام: الحجارة العظام، الواحدة رضمة ورضمة، والجنس رضم ورضم. يقول: دفعت الظعن، أي ضربت الركاب لتجد في السير وفارقها قطع السراب، أي لاحت خلال قطع السراب ولمعت، فكأن الظعن منعطفات وادي بيشة أثلها وحجارتها العظام، شبهها في العظم والضخم بهما، والضمير الذي أضيف إليه أثل ورضام لبيشة."},{"id":"muallaqat:300","bookId":"muallaqat","type":"section","seq":300,"chapter":"مدخل","title":"16- بل ما تذكر من نوار وقد نأت","page":"ج1 ص177","text":"بل ما تذكر من نوار وقد نأت ... وتقطعت أسبابها ورمامها\nنوار: اسم امرأة يشبب بها. النأي: البعد. الرمام: جمع الرمة وهي قطعة من الحبل خلقة ضعيفة. ثم أضرب عن صفة الديار ووصف حال احتمال الأحباب بعد تمامها، وأخذ في كلام آخر من غير إبطال لما سبق. بل، في كلام الله تعالى، لا تكون إلا بهذا المعنى؛ لأنه لا يجوز منه إبطال كلامه وإكذابه. قال مخاطبا نفسه: أي شيء تتذكرين من نوار في حال بعدها وتقطع أسباب وصالها ما قوي منها وما ضعف."},{"id":"muallaqat:301","bookId":"muallaqat","type":"section","seq":301,"chapter":"مدخل","title":"17- مرية حلت بفيد وجاورت","page":"ج1 ص177","text":"مرية حلت بفيد وجاورت ... أهل الحجاز فأين منك مرامها\nمرية: منسوبة إلى مرة. فيد: بلد معروفة، ولم يصرفها لاستجماعها التأنيث والتعريف، وصرفها سائغ أيضا لأنها مصوغة على أخف أوزان الأسماء فعادلت الخفة أحد السببين فصارت كأنه ليس فيها إلا سبب واحد لا يمنع الصرف. وكذلك حكم كل اسم كان على ثلاثة أحرف ساكن الأوسط مستجمعا للتأنيث والتعريف نحو هند ودعد؛ وأنشد النحويون: [المنسرح] :\nلم تتلفع بفضل مئزرها ... دعد ولم تغذ دعد في العلب\nألا ترى الشاعر كيف جمع بين اللغتين في هذا البيت؟\nيقول: نوار امراة من مرة حلت بهذه البلدة وجاورت أهل الحجاز، يريد أنها تحل بفيد أحيانا وتجاور أهل الحجاز أحيانا، وذلك في فصل الربيع وأيام الإنتاج؛ لأن الحال بفيد لا يكون مجاورا أهل الحجاز؛ لأن بينها وبين الحجاز مسافة بعيدة، ثم قال: فأين منك مطلبها، أي تعذر عليك طلبها؛ لأن بين بلادك وفيد والحجاز مسافة بعيدة وتيها قذفا؛ وتلخيص المعنى أنه يقول: هي مرية تتردد بين الموضعين وبينهما وبين بلادك بعد، وكيف يتيسر لك طلبها والوصول إليها؟"},{"id":"muallaqat:302","bookId":"muallaqat","type":"section","seq":302,"chapter":"مدخل","title":"18- بمشارق الجبلين أو بمحجر","page":"ج1 ص178","text":"بمشارق الجبلين أو بمحجر ... فتضمنتها فردة فرخامها\nعنى بالجبلين: جبلي طي أجأ وسلمى. المحجر: جبل آخر. فردة: جبل منفرد عن سائر الجبال سمي بها لانفرادها عن الجبال. رخام: أرض متصلة لذلك أضافها إليها.\nيقول: حلت نوار بمشارق أجأ وسلمى، أي جوانبهما التي تلي المشرق، أو حلت بمحجر فتضمنتها فردة فالأرض المتصلة بها وهي رخام، إنما يحصي منازلها عند حلولها بفيد، وهذه الجبال قريبة منها بعيدة من الحجاز. تضمن الموضع فلانا إذا حصل فيه، وضمنته فلانا إذا حصلته فيه، مثل قولك: ضمنته القبر فتضمنه القبر."},{"id":"muallaqat:303","bookId":"muallaqat","type":"section","seq":303,"chapter":"مدخل","title":"19- فصوائق إن أيمنت فمظنة","page":"ج1 ص178","text":"فصوائق إن أيمنت فمظنة ... فيها وحاف القهر أو طلخامها\nيقال: أيمن الرجل إذا أتى اليمن، مثل أعرق إذا أتى العراق وأخيف إذا أتى خيف منى. مظنة الشيء: حيث يظن كونه فيه، وهو من الظن، بالظاء، وأما قولهم: علق مضنة، هو من الضن، بالضاد، أي هو شيء نفيس يبخل به، صوائق: موضع معروف. وحاف القهر، بالراء غير معجمة: موضع معروف، ومنها من رواه بالزاي معجمة. طلخام: موضع معروف أيضا.\nيقول: وإن انتجعت نحو اليمن فالظن أنها تحل بصوائق، وتحل من بينها بوحاف القهر أو بطلخام، وهما خاصان بالإضافة إلى صوائق؛ وتلخيص المعنى: أنها إن أتت اليمن حلت بوحاف القهر أو طلخام من صوائق."},{"id":"muallaqat:304","bookId":"muallaqat","type":"section","seq":304,"chapter":"مدخل","title":"20- فاقطع لبانة من تعرض وصله","page":"ج1 ص178","text":"فاقطع لبانة من تعرض وصله ... ولشر واصل خلة صرامها\nاللبانة: الحاجة، الخلة: المودة المتناهية، والخليل والخل والخلة واحد.\nالصرام: القطاع، فعال من الصرم وهو القطع، والفعل صرم يصرم، ثم أضرب عن ذكر نوار وأقبل على نفسه مخاطبا إياها فقال: فاقطع أربك وحاجتك ممن كان وصله معرضا للزوال والانتقاض، ثم قال: وشر من وصل محبة أو حبيبا من قطعها، أي شر واصلي الأحباب أو المحبات قطاعها، يذم من كان وصله في معرض الانتكاث والانتقاض. ويروى: ولخير واصل، وهذه أوجه الروايتين وأمثلهما، أي: خير واصلي المحبات أو الأحباب إذا رجا غيرهم قطاعها إذا يئس منه. قوله: لبانة من تعرض، أي لبانتك منه لأن قطع لبانته منك ليس إليك."},{"id":"muallaqat:305","bookId":"muallaqat","type":"section","seq":305,"chapter":"مدخل","title":"21- واحب المجامل بالجزيل وصرمه","page":"ج1 ص179","text":"واحب المجامل بالجزيل وصرمه ... باق إذا ظلعت وزاغ قوامها\nحبوته بكذا أحبوه حباء: إذا أعطيته إياه. المجامل: المصانع، ويروى: المحامل، أي: الذي يتحمل أذاك كما تتحمل أذاه. بالجزيل أي الود الجزيل. الجزالة: الكمال والتمام، وأصله الضخم والغلظ، والفعل جزل يجزل، والنعت جزل وجزيل، ومنه خطب جزل وجزيل وعطاء جزل وجزيل، وقد أجزل عطيته وفرها وكثرها. الصرم: القطيعة. الظلع: غمز1 في الدواب. الزيغ: الميل، والإزاغة الإمالة. قوام الشيء: ما يقوم به.\nيقول: واحب من جاملك وصانعك وداراك بود كامل وافر، ثم قال: وقطيعته باقية إن ظلعت خلته ومال قوامها، أي إن ضعفت أسبابها ودعائمها، أي إن حال المجامل عن كرم العهد فأنت قادر على صرمه وقطيعته، فالمضمر الذي أضيف إليه قوامها للخلة وكذلك المضمر في ظلعت."},{"id":"muallaqat:306","bookId":"muallaqat","type":"section","seq":306,"chapter":"مدخل","title":"22- بطليح أسفار تركن بقية","page":"ج1 ص179","text":"بطليح أسفار تركن بقية ... منها فأحنق صلبها وسنامها\nالطلح والطليح: المعيي، وقد طلحت البعير أطلحه طلحا أعييته، فطليح فعيل بمعنى مفعول بمنزلة الجريح والقتيل، وطلح فعل في معنى مفعول بمنزلة الذبح والطحن بمعنى المذبوح والمطحون. أسفار: جمع سفر. الإحناق: الضمر. الباء في قوله: \"بلطيح\" من صلة \"وصرمة\".\nيقول: إذا زال قوام خلته فأنت تقدر على قطيعته، بركوب ناقة أعيتها الأسفار وتركت بقية من لحمها وقوتها فضمر صلبها وسنامها؛ وتلخيص المعنى: فأنت تقدر على قطيعته بركوب ناقة قد اعتادت الأسفار ومرنت عليها."},{"id":"muallaqat:307","bookId":"muallaqat","type":"section","seq":307,"chapter":"مدخل","title":"23- وإذا تغالى لحمها وتحسرت","page":"ج1 ص180","text":"وإذا تغالى لحمها وتحسرت ... وتقطعت بعد الكلال خدامها\nتغالى لحمها: ارتفع إلى رءوس العظام، من الغلاء وهو الارتفاع، ومنه قولهم: غلا السعر يغلو غلاء، إذا ارتفع، تحسرت أي صارت حسيرا، أي كالة معيية عارية عن اللحم. الخدام: جمع خدم، والخدم جمع خدمة، وهي سيور تشد بها النعال إلى أرساغ الإبل.\nيقول: فإذا ارتفع لحمها إلى رءوس عظامها وأعيت وعريت عن اللحم وتقطعت السيور التي تشد بها نعالها إلى أرساغها بعد إعيائها. وجواب إذا في البيت الذي بعده."},{"id":"muallaqat:308","bookId":"muallaqat","type":"section","seq":308,"chapter":"مدخل","title":"24- فلها هباب في الزمام كأنها","page":"ج1 ص180","text":"فلها هباب في الزمام كأنها ... صهباء خف مع الجنوب جهامها\nالهباب: النشاط. الصبهاء: الحمراء، يريد كأنها سحابة صهباء، فحذف الموصوف. خف يخف خفوفا: أسرع. الجهام: السحاب الذي قد أراق ماءه.\nيقول: فلها في مثل هذه الحال نشاط في السير حال قود زمامها، فكأنها في سرعة سيرها سحابة حمراء قد ذهبت الجنوب بقطعها التي هراقت ماءها فانفردت عنها، وتلك أسرع ذهابا من غيرها."},{"id":"muallaqat:309","bookId":"muallaqat","type":"section","seq":309,"chapter":"مدخل","title":"25- أو ملمع وسقت لأحقب لاحه","page":"ج1 ص180","text":"أو ملمع وسقت لأحقب لاحه ... طرد الفحول وضربها وكدامها\nألمعت الأتان فهي ملمع: أشرق طبياها1 باللبن. وسقت: حملت، تسق وسقا. الأحقب: العير الذي في وركيه بياض أو في خاصرتيه. لاحه ولوحه غيره. ويروى: طرد الفحولة ضربها وعذامها؛ الفحول والفحولة والفحال والفحالة: جموع فحل. الكدام: يجوز أن يكون بمنزلة الكدم وهو العض، وأن يكون بمنزلة المكادمة\nوهي المعاضة. العذام: يجوز أن يكون بمنزلة العذم وهو العض، وأن يكون بمنزلة المعاذمة وهي المعاضة.\nيقول: كأنها صهباء أو أتان أشرقت أطباؤها باللبن وقد حملت تولبا1 لفحل أحقب قد غير وهزل ذلك الفحل طرده الفحول وضربه إياها وعضه، أو طرد الفحول وضربها وعضها إياه. وتلخيص المعنى: أنها تشبه في شدة سيرها هذه السحابة أو هذه الأتان التي حملت تولبا لمثل هذا الفحل الشديد الغيرة عليها، فهو يسوقها سوقا عنيفا."},{"id":"muallaqat:310","bookId":"muallaqat","type":"section","seq":310,"chapter":"مدخل","title":"26- يعلو بها حدب الإكام مسحج","page":"ج1 ص181","text":"يعلو بها حدب الإكام مسحج ... قد رابه عصيانها ووحامها\nالإكام: جمع أكم، وكذلك الآكام والأكم جمع أكمة، ويجمع الآكام على الأكم. حدبها: ما احدودب منها. السحج: القشر والخدش العنيف، والتسحيج مبالغة السحج: الوحام والوحم والوحام: اشتهاء الحبلى الشيء، والفعل وحمت توحم وتاحم وتيحم، وهذا القياس مطرد في فعل يفعل من معتل الفاء.\nيقول: يعلي هذا الفحل الأتان والإكام إتعابا لها وإبعادا بها عن الفحول وقد شككه في أمرها عصيانها إياه في حال حملها واشتهاؤها إياه قبله. والمسحج: العير المعضض."},{"id":"muallaqat:311","bookId":"muallaqat","type":"section","seq":311,"chapter":"مدخل","title":"27- بأحزة الثلبوت يربأ فوقها","page":"ج1 ص181","text":"بأحزة الثلبوت يربأ فوقها ... قفر المراقب خوفها آرامها\nالأحزة: جمع حزيز وهو مثل القف2. ثلبوت: موضع بعينه. ربأت القوم وربأت لهم أربأ ربأ: كنت ربيئة لهم. القفر: الخالي، الجمع القفار. المراقب: جمع مرقبة وهو الموضع الذي يقوم عليه الرقيب، ويريد بالمراقب الأماكن المرتفعة. الآرام: أعلام الطريق، الواحد إرم.\nيقول: يعلو العير بالأتان الإكام في قفاف هذا الموضع، ويكون رقيبا لها فوقها في موضع خالي الأماكن المرتفعة، وإنما يخاف أعلامها، أي يخاف استتار الصيادين.\nبأعلامها، وتلخيص المعنى: أنهما بهذا الموضع والعير يعلو إكامه لينظر إلى أعلامها هل يرى صائدا استتر بعلم منها يريد أن يرميها."},{"id":"muallaqat:312","bookId":"muallaqat","type":"section","seq":312,"chapter":"مدخل","title":"28- حتى إذا سلخا جمادى ستة","page":"ج1 ص182","text":"حتى إذا سلخا جمادى ستة ... جزء فطال صيامه وصيامها\nسلخت الشهر وغيره أسلخه سلخا: مر علي، وانسلخ الشهر نفسه. جمادى: اسم للشتاء، سمي بها لجمود الماء فيه ومنه قول الشاعر: [البسيط] :\nفي ليلة من جمادى ذات أندية ... لا يبصر الكلب من ظلمائها الطنبا\nأي من الشتاء: جزأ الوحش يجزأ جزءا: اكتفى بالرطب عن الماء. الصيام: الإمساك في كلام العرب، ومنه الصوم المعروف؛ لأنه إمساك عن المفطرات.\nيقول: أقاما بالثلبوت حتى مر عليهما الشتاء ستة أشهر وجاء الربيع فاكتفيا بالرطب عن الماء وطال إمساك العير وإمساك الأتان عنه، وستة بدل من جمادى لذلك نصبها، وأراد ستة أشهر فحذف أشهرا لدلالة الكلام عليه."},{"id":"muallaqat:313","bookId":"muallaqat","type":"section","seq":313,"chapter":"مدخل","title":"29- رجعا بأمرهما إلى ذي مرة","page":"ج1 ص182","text":"رجعا بأمرهما إلى ذي مرة ... حصد ونجح صريمة إبرامها\nالباء في بأمرهما زائدة إن جعلت رجعا من الرجع، أي رجعا أمرهما أي أسنداه، وإن جعلته من الرجوع كانت الباء للتعدية. المرة: القوة، والجمع المرر، وأصلها قوة الفتل، والإمرار إحكام الفتل. الحصد: المحكم، والفعل حصد يحصد، وقد أحصدت الشيء أحكمته. النجح والنجاح. حصول المراد. الصريمة: العزيمة التي صرمها صاحبها عن سائر عزائمه بالجد في إمضائها. والجمع الصرائم. الإبرام: الإحكام.\nيقول: أسند العير والأتان أمرهما إلى عزم أو رأي محكم ذي قوة وهو عزم العير على الورود أو رأيه فيه، ثم قال: وإنما يحصل المرام بإحكام العزم."},{"id":"muallaqat:314","bookId":"muallaqat","type":"section","seq":314,"chapter":"مدخل","title":"30- ورمى دوابرها السفا وتهيجت","page":"ج1 ص182","text":"ورمى دوابرها السفا وتهيجت ... ريح المصايف سومها وسهامها\nالدوابر: مآخير الحوافر، السفا: شوك البهمى وهو ضرب من الشوك. هاج الشيء يهيج هيجانا واهتاج اهتياجا وتهيج تهيجا: تحرك ونشأ، وهجته هيجا وهيجته تهييجا. المصايف: جمع المصيف وهو الصيف. السوم: المرور، والفعل سام يسوم، السهام: شدة الحر.\nيقول: وأصاب شوك البهمى مآخير حوافرها، وتحركت ريح الصيف مرورها وشدة حرها، يشير بهذا إلى انقضاء الربيع ومجيء الصيف واحتياجهما إلى ورود الماء."},{"id":"muallaqat:315","bookId":"muallaqat","type":"section","seq":315,"chapter":"مدخل","title":"31- فتنازعا سبطا يطير ظلاله","page":"ج1 ص183","text":"فتنازعا سبطا يطير ظلاله ... كدخان مشعلة يشب ضرامها\nالتنازع: مثل التجاذب. السبط: الممتد الطويل، كدخان مشعلة أي نار مشعلة، فحذف الموصوف. شب النار وإشعالها واحد. والفعل منه شب يشب. الضرام: دقائق الحطب، واحدها ضرم وواحد الضرم ضرمة، وقد ضرمت النار واضطرمت وتضرمت التهبت، وأضرمتها وضرمتها أنا. سبطا أي غبارا سبطا فحذف الموصوف.\nيقول: فتجاذب العير، والأتان في عدوهما نحو الماء غبارا ممتدا طويلا كدخان نار موقدة تشعل النار في دقاق حطبها، وتلخيص المعنى: أنه جعل الغبار الساطع بينهما بعدوهما كثوب يتجاذبانه، ثم شبهه في كثافته وظلمته بدخان نار موقدة."},{"id":"muallaqat:316","bookId":"muallaqat","type":"section","seq":316,"chapter":"مدخل","title":"32- مشمولة غلثت بنابت عرفج","page":"ج1 ص183","text":"مشمولة غلثت بنابت عرفج ... كدخان نار ساطع أسنامها\nمشمولة: هبت عليها ريح الشمال، وقد شمل الشيء أصابته ريح الشمال. الغلت، والعلث: الخلط، والفعل غلث يغلث، بالغين والعين جميعا. النابت: الغض؛ ومنه قول الشاعر: [الكامل] :\nووطئتنا وطأ على حنق ... وطء المقيد نابت الهرم\nأي غضه: العرفج: ضرب من الشجر، ويروى: عليت بنابت، أي: وضع فوقها. الأسنام: جمع سنام، ويروى: بثابت أسنامها، وهو الارتفاع والرفع جميعا.\nيقول: هذه النار قد أصابتها الشمال وقد خلطت بالحطب اليابس والرطب الغض كدخان نار قد ارتفع أعاليها، وسنام الشيء أعلاه، شبه الغبار الساطع من قوائم العير والأتان بنار أوقدت بحطب يابس تسرع فيه النار وحطب غض، وجعلها كذلك ليكون دخانها أكثف فيشبه الغبار الكثيف، ثم جعل هذا الدخان الذي شبه الغبار به كدخان نار قد سطع أعاليها في الاضطرام والالتهاب ليكون دخانه أكثر، وجر مشمولة، لأنه صفة لمشعلة، وقوله: كدخان نار ساطع أسنامها، صفة أيضا، إلا أنه كرر قوله كدخان لتفخيم الشأن وتعظيم القصة، كنظائره، من مثل: [الطويل] :\nأرى الموت لا ينجو من الموت هاربه\nوهو أكثر من أن يحصى."},{"id":"muallaqat:317","bookId":"muallaqat","type":"section","seq":317,"chapter":"مدخل","title":"33- فمضى وقدمها وكانت عادة","page":"ج1 ص184","text":"فمضى وقدمها وكانت عادة ... منه إذا هي عردت إقدامها\nالتعريد: التأخير والجبن: الإقدام هنا بمعنى التقدمة لذلك أنث فعلها فقال: وكانت، أي وكانت تقدمة الأتان عادة من العير، وهذا مثل قول الشاعر: [الطويل] :\nغفرنا وكانت من سجيتنا الغفر\nأي: وكانت المغفرة من سجيتنا، وقال رويشد بن كثير الطائي: [البسيط] :\nيا أيها الراكب المزجي مطيته ... سائل بني أسد ما هذه الصوت\nأي: ما هذه الاستغاثة؛ لأن الصوت مذكر.\nيقول: فمضى العير نحو الماء وقدم الأتان لئلا تتأخر، وكانت تقدمة الأتان عادة من العير إذا تأخرت هي، أي خاف العير تأخيرها."},{"id":"muallaqat:318","bookId":"muallaqat","type":"section","seq":318,"chapter":"مدخل","title":"34- فتوسطا عرض السري وصدعا","page":"ج1 ص184","text":"فتوسطا عرض السري وصدعا ... مسجورة متجاورا قلامها\nالعرض: الناحية. السري: النهر الصغير، والجمع الأسرية. التصديع: التشقيق. السجر: الملء، أي عينا مسجورة، فحذف الموصوف لما دلت عليه الصفة. القلام: ضرب من النبت.\nيقول: فتوسط العير والأتان جانب النهر الصغير وشقا عينا مملوءة ماء قد تجاور قلامها، أي: قد كثر هذا الضرب من النبت عليها؛ وتحرير المعنى: أنهما قد وردا عينا ممتلئة ماء فدخلا فيها من عرض نهرها، وقد تجاوز نبتها."},{"id":"muallaqat:319","bookId":"muallaqat","type":"section","seq":319,"chapter":"مدخل","title":"35- محفوفة وسط اليراع يظلها","page":"ج1 ص184","text":"محفوفة وسط اليراع يظلها ... منه مصرع غابة وقيامها\nاليراع: القصب. الغابة: الأجمة، والجمع الغاب، المصرع: مبالغة المصروع. القيام: جمع قائم.\nيقول: قد شقا عينا قد حفت بضروب النبت والقصب، فهي وسط القصب يظلها من القصب ما صرع من غابتها وما قام منها، يريد أنها في ظل قصب بعضه مصرع وبعضه قائم."},{"id":"muallaqat:320","bookId":"muallaqat","type":"section","seq":320,"chapter":"مدخل","title":"36- أفتلك أم وحشية مسبوعة","page":"ج1 ص185","text":"أفتلك أم وحشية مسبوعة ... خذلت وهادية الصوار قوامها\nمسبوعة أي: قد أصباها السبع بافتراس ولدها. الهادية: المتقدمة والمتقدم أيضا، فتكون التاء إذن للمبالغة، الصوار والصوار والصيار: القطيع من بقر الوحش، والجمع الصيران. قوام الشيء: ما يقوم به هو.\nيقول: أفتلك الأتان المذكورة تشبه ناقتي في الإسراع في السير أم بقرة وحشية قد افترس السبع ولدها حين خذلته وذهبت ترعى مع صواحبها، وقوام أمرها الفحل الذي يتقدم القطيع من بقر الوحش؛ وتحرير المعنى: أناقتي تشبه تلك الأتان أو هذه البقرة التي خذلت ولدها وذهبت ترعى مع صواحبها وجعلت هادية الصوار قوام أمرها، فافترست السباع ولدها فأسرعت في السير طالبة لولدها."},{"id":"muallaqat:321","bookId":"muallaqat","type":"section","seq":321,"chapter":"مدخل","title":"37- خنساء ضيعت الفرير فلم يرم","page":"ج1 ص185","text":"خنساء ضيعت الفرير فلم يرم ... عرض الشقائق طوفها وبغامها\nالخنس: تأخر في الأرنبة1. الفرير: ولد البقرة الوحشية، والجمع فرار على غير قياس. الريم: البراح، والفعل رام يريم، العرض: الناحية. الشقائق: جمع شقيقة وهي أرض صلبة بين رملتين. البغام: صوت رقيق.\nيقول: هذه الوحشية قد تأخرت أرنبتها والبقر كلها خنس وقد ضيعت ولدها، أي خذلته حتى افترسته السباع فذلك تضييعها إياه. ثم قال: ولم يبرح طوفها وخوارها نواحي الأرضين الصلبة في طلبه؛ وتحرير المعنى: ضيعته حتى صادته السباع فطلبته طائفة وصائحة فيما بين الرمال."},{"id":"muallaqat:322","bookId":"muallaqat","type":"section","seq":322,"chapter":"مدخل","title":"38- لمعفر قهد تنازع شلوه","page":"ج1 ص185","text":"لمعفر قهد تنازع شلوه ... غبس كواسب لا يمن طعامها\nالعفو والتعفير: الإلقاء على العفر والعفر وهما أديم الأرض. القهد: الأبيض. التنازع: التجاذب. الشلو: العضو، وقيل هو بقية الجسد، والجمع الأشلاء. الغبس جمع أغبس وغبساء. والغبسة: لون كلون الرماد. المن: القطع والفعل من يمن، ومنه قوله تعالى: {لهم أجر غير ممنون} [فصلت: 8] ؛ ومنه سمي الغبار منينا لانقطاع بعض أجزائه عن بعض، والدهر والمنية منونا لقطعهما أعمار الناس وغيرهما.\nيقول: هي تطوف وتبغم لأجل جؤذر ملقى على الأرض أبيض، قد تجاذبت أعضاءه ذئاب أو كلاب غبس لا يقطع طعامها، أي لا تفتر في الاصطياد فينقطع طعامها، هذا إذا جعلت غبسا من صفة الذئاب، وإن جعلتها من صفة الكلاب فمعناه: لا يقطع أصحابها طعامها؛ وتحرير المعنى: أنها تجد في الطلب لأجل فقدها ولدا قد ألقي على أديم الأرض وافترسته كلاب أو ذئاب صوائد قد اعتادت الاصطياد، وبقر الوحش بيض ما خلا أوجهها وأكارعها، لذلك قال قهد. الكسب: الصيد في البيت."},{"id":"muallaqat:323","bookId":"muallaqat","type":"section","seq":323,"chapter":"مدخل","title":"39- صادفن منها غرة فأصبنها","page":"ج1 ص186","text":"صادفن منها غرة فأصبنها ... إن المنايا لا تطيش سهامها\nالغرة: الغفلة. الطيش: الانحراف والعدول.\nيقول: صادفت الكلاب والذئاب غفلة من البقرة فأصبن تلك الغفلة أو تلك البقرة بافتراس ولدها، أي: وجدتها غافلة عن ولدها فاصطادته، ثم قال: وإن الموت لا تطيش سهامه، أي لا مخلص من هجومه، واستعار له سهاما واستعار للأخطاء لفظ الطيش؛ لأن السهم إذا أخطأ الهدف فقد طاش عنه."},{"id":"muallaqat:324","bookId":"muallaqat","type":"section","seq":324,"chapter":"مدخل","title":"40- باتت وأسبل واكف من ديمة","page":"ج1 ص186","text":"باتت وأسبل واكف من ديمة ... يروي الخمائل دائما تسجامها\nالوكف والوكفان واحد، والفعل منهما، وكف يكف أي قطر. الديمة: مطرة تدوم وأقلها نصف يوم وليلة، والجمع الديم، وقد دومت السحابة إذا كان مطرها ديمة، وأصل ديمة دومة فقلبت الواو لانكسار ما قبلها. ثم قلبت في الديم حملا على القلب في الواحد. الخمائل: جمع خميلة وهي كل رملة ذات نبت عند الأكثر من الأئمة، وقال جماعة منهم: هي أرض ذات شجر: التسجام: في معنى السجم أو السجوم، يقال: سجم الدمع وغيره يسجمه سجما، فسجم هو يسجم سجوما أي صبه فانصب.\nيقول: باتت البقرة عند فقدها ولدها وقد أسبل مطر واكف من مطر دائم يروي الرمال المنبتة والأرضين التي بها أشجار في حال دوام سكبها الماء، أي باتت في مطر دائم الهطلان؛ وواكف يجوز أن يكون صفة مطر ويجوز أن يكون صفة سحاب."},{"id":"muallaqat:325","bookId":"muallaqat","type":"section","seq":325,"chapter":"مدخل","title":"41- يعلو طريقة متنها متواتر","page":"ج1 ص186","text":"يعلو طريقة متنها متواتر ... في ليلة كفر النجوم غمامها\nطريقة المتن: خط من ذنبها إلى عنقها. الكفر: التغطية والستر.\nيقول: يعلو صلبها قطر متواتر في ليلة ستر غمامها نجومها."},{"id":"muallaqat:326","bookId":"muallaqat","type":"section","seq":326,"chapter":"مدخل","title":"42- تجتاف أصلا قالصا متنبذا","page":"ج1 ص187","text":"تجتاف أصلا قالصا متنبذا ... بعجوب أنقاء يميل هيامها\nالاجتياف: الدخول في جوف الشيء، ويروى تجتاب، بالباء أي تلبس. النبيذ: التنحي من النبذة والنبذة من الناحية. العجب: أصل الذنب، والمجمع والعجوب فاستعاره لأصل النقا، والنقا: الكثيب من الرمل، والتثنية نقوان ونقيان، والجموع أنقاء. الهيام: ما لا تماسك به من الرمل، وأصله من هام يهيم.\nيقول: وقد دخلت البقرة الوحشية في جوف أصل شجرة متنح عن سائر الشجر، وقد قلصت أغصانها. وذلك الشجر في أصول كثبان من الرمل يميل ما لا يتماسك منها عليها لهطلان المطر وهبوب الريح؛ وتحرير المعنى: أنها تستتر من البرد والمطر بأغصان الشجر، ولا تقيها البرد والمطر لتقلصها وتنهال كثبان الرمل عليها مع ذلك."},{"id":"muallaqat:327","bookId":"muallaqat","type":"section","seq":327,"chapter":"مدخل","title":"43- وتضيء في وجه الظلام منيرة","page":"ج1 ص187","text":"وتضيء في وجه الظلام منيرة ... كجمانة البحري سل نظامها\nالإضاءة والإنارة: يتعدى فعلهما ويلزم، وهما لازمان في البيت؛ وجه الظلام: أوله وكذلك وجه النهار. الجمان والجمانة: درة مصوغة من الفضة، ثم يستعاران للدرة، وأصله فارسي معرب وهو كمانة.\nيقول: وتضيء هذه البقرة في أول ظلام الليل كدرة الصدف البحري أو الرجل البحري حين سل النظام منها، شبه البقرة في تلألؤ لونها بالدرة، وإنما خص ما يسل نظامها إشارة إلى أنها تعدو ولا تستقر كما تتحرك وتنتقل الدرة التي سل نظامها، وإنما شبهها بها لأنها بيضاء متلألئة ما خلا أكارعها ووجهها."},{"id":"muallaqat:328","bookId":"muallaqat","type":"section","seq":328,"chapter":"مدخل","title":"44- حتى إذا انحسر الظلام وأسفرت","page":"ج1 ص187","text":"حتى إذا انحسر الظلام وأسفرت ... بكرت تزل عن الثرى أزلامها\nالانحسار: الانكشاف والانجلاء. الإسفار: الإضاءة إذا لزم فعلها الفاعل، والأزلام: قوائمها، وجعلها أزلاما لاستوائها، ومنه سميت القداح أزلاما، والتزليم التسوية، وواحد الأزلام زلم وزلم، والزلمة والزلمة والقد، ومنه قولهم: هو العبد زلمة وزلمة، أي: قده قد العبد.\nيقول: حتى إذا انكشف وانجلى ظلام الليل وأضاء، بكرت البقرة من مأواها، فنزلت قوائمها عن التراب الندي لكثرة المطر الذي أصابه ليلا."},{"id":"muallaqat:329","bookId":"muallaqat","type":"section","seq":329,"chapter":"مدخل","title":"45- علهت تردد في نهاء صعائد","page":"ج1 ص188","text":"علهت تردد في نهاء صعائد ... سبعا تؤاما كاملا أيامها\nالعله والهلع: الانهماك في الجزع والضجر، ويروى تبلد، أي: تتحير وتتعمه، النهاء جمع نهي ونهي، بفتح النون وكسرها: وهما الغدير، وكذلك الأنهاء. صعائد: موضع بعينه. التؤام: جمع توأم.\nيقول: أمنعت في الجزع وترددت متحيرة في وهاد هذا الموضع ومواضع غدرانه سبع ليال تؤام للأيام وقد كملت أيام تلك الليالي، أي ترددت في طلب ولدها سبع ليال بأيامها، وجعل أيامها كاملة إشارة إلى أنها كانت من أيام الصيف وشهور الحر."},{"id":"muallaqat:330","bookId":"muallaqat","type":"section","seq":330,"chapter":"مدخل","title":"46- حتى إذا يئست وأسحق حالق","page":"ج1 ص188","text":"حتى إذا يئست وأسحق حالق ... لم يبله إرضاعها وفطامها\nالإسحاق: الإخلاق، والسحق الخلق، الحالق: الضرع الممتلئ لبنا.\nيقول: حتى إذا يئست البقرة من ولدها، وصار ضرعها الممتلئ لبنا خلقا لانقطاع لبنها، ثم قال: ولم يبل ضرعها إرضاعها ولدها ولا فطامها إياه وإنما أبلاه فقدها إياه."},{"id":"muallaqat:331","bookId":"muallaqat","type":"section","seq":331,"chapter":"مدخل","title":"47- فتوجست رز الأنيس فراعها","page":"ج1 ص188","text":"فتوجست رز الأنيس فراعها ... عن ظهر غيب والأنيس سقامها\nالرز: الصوت الخفي. الأنيس والإنس والأناس والناس واحد. راعها: أفزعها. السقام والسقم واحد. والفعل سقم يسقم، والنعت سقيم، وكذلك النعت مما كان من أفعال فعل يفعل من الأدواء والعلل نحو مريض.\nيقول: فتسمعت البقرة صوت الناس فأفزعها ذلك وإنما سمعته عن ظهر غيب، أي لم تر الأنيس، ثم قال: والناس سقام الوحش وداؤها؛ لأنهم يصيدونها وينقصون منها نقص السقم من الجسد؛ وتحرير المعنى: أنها سمعت صوتا ولم تر صاحبه فخافت ولا غرو أن تخاف عند سماعها صوت الناس؛ لأن الناس يبيدونها ويهلكونها، والتقدير: فتسمعت رز الأنيس عن ظهر غيب فراعها والأنيس سقامها."},{"id":"muallaqat:332","bookId":"muallaqat","type":"section","seq":332,"chapter":"مدخل","title":"48- فغدت كلا الفرجين تحسب أنه","page":"ج1 ص188","text":"فغدت كلا الفرجين تحسب أنه ... مولى المخافة خلفها وأمامها\nالفرج: موضع المخافة، والفرج ما بين قوائم الدواب، فما بين اليدين فرج، وما بين الرجلين فرج والجمع فروج، وقال ثعلب: إن المولى في هذا البيت بمعنى الأولى بالشيء، كقوله تعالى: {مأواكم النار هي مولاكم} [الحديد: 15] أي أولى بكم.\nيقول: فغدت البقرة وهي تحسب أن كلا فرجيها مولى المخافة، أي موضعها وصاحبها، أن تحسب أن كل فرج من فرجيها هو الأولى بالمخافة منه، أي بأن يخاف منه، وتحرير المعنى: أنها لم تقف على أن صاحب الرز خلفها أم أمامها، فغدت فزعة مذعورة لا تعرف منجاها من مهلكها، وقال الأصمعي: أراد بالمخافة الكلاب وبمولاها صاحبها، أي غدت وهي لا تعرف أن الكلاب والكلاب خلفها أو أمامها فهي تظن كل جهة من الجهتين موضعا للكلاب والكلاب، والضمير الذي هو اسم إن عائد إلى كلا، وهو مفرد اللفظ وإن كان يتضمن معنى التثنية، ويجوز حمل الكلام بعده على لفظه مرة وعلى معناه أخرى، والحمل على اللفظ أكثر، وتمثيلها، كلا أخويك سبني وكلا أخويك سباني؛ وقال الشاعر: [البسيط] :\nكلاهما حين جد الجري بينهما ... قد أقلعا وكلا أنفيهما رابي\nحمل أقلعا معنى كلا وحمل رابيا على لفظه، وقال الله عز وجل: {كلتا الجنتين آتت أكلها} [الكهف: 33] حملا على لفظ كلتا، ونظير كلا وكلتا في هذين الحكمين كل؛ لأنه مفرد اللفظ وإن كان معناه جمعا، ويحمل الكلام بعده على لفظه ومعناه، وكلاهما كثير، قال الله تعالى: {وكل أتوه داخرين} [النمل: 87] ؛ فهذا محمول على المعنى وقال تعالى: {إن كل من في السموات والأرض إلا آتي الرحمن عبدا} [مريم: 93] ، وهذا محمول على اللفظ. ومولى المخافة في محل الرفع؛ لأنه خبر أن، وخلفها وأمامها خبر مبتدأ محذوف تقديره هو خلفها وأمامها، ويكون تفسير كلا الفرجين، ويجوز أن يكون بدلا من كلا الفرجين وتقديره، فغدت كلا الفرجين خلفها وأمامها تحسب أنه مولى المخافة."},{"id":"muallaqat:333","bookId":"muallaqat","type":"section","seq":333,"chapter":"مدخل","title":"49- حتى إذا يئس الرماة وأرسلوا","page":"ج1 ص189","text":"حتى إذا يئس الرماة وأرسلوا ... غضفا دواجن قافلا أعصامها\nالغضف من الكلاب: المسترخية الآذان، والغضف: استرخاء الأذن، يقال: كلب أغضف وكلبة غضفاء، وهو مستعمل في غير الكلاب استعماله فيها. الدواجن:\nالمعلمات. القفول: اليبس. أعصامها: بطونها وقيل: بل سواجيرها وهي قلائدها من الحديد والجلود وغير ذلك.\nيقول: حتى إذا يئس الرماة من البقرة وعلموا أن سهامهم لا تنالها، أرسلوا كلابا مسترخية الآذان معلمة ضوامر البطون أو يابسة السواجير."},{"id":"muallaqat:334","bookId":"muallaqat","type":"section","seq":334,"chapter":"مدخل","title":"50- فلحقن واعتكرت لها مدرية","page":"ج1 ص190","text":"فلحقن واعتكرت لها مدرية ... كالسمهرية حدها وتمامها\nعكر واعتكر أي عطف. المدرية: طرف قرنها. السمهرية من الرماح: منسوبة إلى سمهر، رجل كان بقرية تسمى خطا من قرى البحرين وكان مثقفا فنسب إليه الرماح الجيدة.\nيقول: فلحقت الكلاب البقرة وعطفت عليها، ولها قرن يشبه الرماح في حدتها وتمام طولها، أي أقبلت البقرة على الكلاب وطعنتها بهذا القرن الذي هو كالرماح."},{"id":"muallaqat:335","bookId":"muallaqat","type":"section","seq":335,"chapter":"مدخل","title":"51- لتذودهن وأيقنت إن لم تذد","page":"ج1 ص190","text":"لتذودهن وأيقنت إن لم تذد ... أن قد أحم مع الحتوف حمامها\nالذود: الكف والرد. الإحمام والإجمام: القرب. الحتف: قضاء الموت، وقد يسمى الهلاك حتفا. الحمام: تقدير الموت يقال حم كذا أي قدر.\nيقول: عطفت البقرة وكرت لترد وتطرد الكلاب عن نفسها، وأيقنت أنها إن لم تذدها قرب موتها من جملة حتوف الحيوان، أي أيقنت إن لم تطرد الكلاب قتلتها الكلاب."},{"id":"muallaqat:336","bookId":"muallaqat","type":"section","seq":336,"chapter":"مدخل","title":"52- فتقصدت منها كساب فضرجت","page":"ج1 ص190","text":"فتقصدت منها كساب فضرجت ... بدم وغودر في المكر سخامها\nأقصد وتقصد: قتل. كساب، مبنية على الكسرة: اسم كلبة، وكذلك سخام وقد روي بالحاء المهملة.\nيقول: فقتلت البقرة كساب من جملة تلك الكلاب فحمرتها بالدم وتركت سخاما في موضع كرها صريعة، أي قتلت هاتين الكلبتين، التضريج: التحمير بالدم، ضرجته فتضرج، ويريد بالمكر موضع كرها."},{"id":"muallaqat:337","bookId":"muallaqat","type":"section","seq":337,"chapter":"مدخل","title":"53- فبتلك إذ رقص اللوامع بالضحى","page":"ج1 ص190","text":"فبتلك إذ رقص اللوامع بالضحى ... واجتاب أردية السراب إكامها\nيقول: فبتلك الناقة إذ رقصت لوامع السراب بالضحى، أي تحركت ولبست الإكام1 أردية من السراب؛ وتحرير المعنى: فبتلك الناقة التي أشبهت البقرة والأتان أقضى حوائجي في الهواجر، ورقص لوامع السراب ولبس الإكام أرديته كناية عن احتدام الهواجر."},{"id":"muallaqat:338","bookId":"muallaqat","type":"section","seq":338,"chapter":"مدخل","title":"54- أقضي اللبانة لا أفرط ريبة","page":"ج1 ص191","text":"أقضي اللبانة لا أفرط ريبة ... أو أن يلوم بحاجة لوامها\nاللبانة: الحاجة. التفريط التضييع وتقدمة العجز. الريبة: التهمة، واللوام: مبالغة اللائم، واللوام جمع اللائم.\nيقول: بركوب هذه الناقة وإتعابها في حر الهواجر أقضي وطري، ولا أفرط في طلب بغيتي، ولا أدع ريبة إلا أن يلومني لائم، وتحرير المعنى: أنه لا يقصر ولكن لا يمكنه الاحتراز عن لوم اللوام إياه، وأو في قوله: أو أن يلوم، بمعنى إلا، ومثله قولهم: لألزمه أو يعطيني حقي، أي إلا أن يعطيني حقي، وقال امرؤ القيس: [الطويل] :\nفقلت له لا تبك عينك إنما ... نحاول ملكا أو نموت فنعذرا\nأي: إلا أن نموت"},{"id":"muallaqat:339","bookId":"muallaqat","type":"section","seq":339,"chapter":"مدخل","title":"55- أولم تكن تدري نوار بأنني","page":"ج1 ص191","text":"أولم تكن تدري نوار بأنني ... وصال عقد حبائل جذامها\nالحبائل: جمع الحبالة وهي مستعارة للعهد والمودة هنا. الجذم: القطع، والفعل جذم يجذم، والجذام مبالغة الجاذم. ثم رجع إلى التشبيب. بالعشيقة فقال: أو لم تكن تعلم نوار أنني وصال عقد العهود والمودات وقطاعها، يريد أنه يصل من استحق الصلة ويقطع من استحق القطيعة."},{"id":"muallaqat:340","bookId":"muallaqat","type":"section","seq":340,"chapter":"مدخل","title":"56- تراك أمكنة إذا لم أرضها","page":"ج1 ص191","text":"تراك أمكنة إذا لم أرضها ... أو يعتلق بعض النفوس حمامها\nيقول: إني تراك أماكن إذا لم أرضها إلا أن يرتبط نفسي حمامها فلا يمكنها البراح، وأراد ببعض النفوس هنا نفسه، هذا أوجه الأقوال وأحسنها، ومن جعل بعض\nالنفوس، بمعنى كل النفوس فقد أخطأ؛ لأن بعضا لا يفيد العموم والاستيعاب، وتحرير المعنى: إني لا أترك الأماكن التي أجتويها1, وأقلوها إلا أن أموت."},{"id":"muallaqat:341","bookId":"muallaqat","type":"section","seq":341,"chapter":"مدخل","title":"57- بل أنت لا تدرين كم من ليلة","page":"ج1 ص192","text":"بل أنت لا تدرين كم من ليلة ... طلق لذيذ لهوها وندامها\nليلة طلق وطلقة: ساكنة لا حر فيها ولا وقر2. الندام: جمع نديم مثل الكرام في جمع كريم، والندام أيضا المنادمة مثل الجدال والمجادلة، والندام في البيت يحتمل الوجهين. أضرب عن الإخبار للمخاطبة فقال: بل أنت يا نوار لا تعلمين كم من ليلة ساكنة غير مؤذية بحر ولا برد لذيذة اللهو والندماء والمنادمة. وتحرير المعنى: بل أنت تجهلين كثرة الليالي التي طابت لي واستلذذت لهوي وندماني فيها أو منادمتي الكرام فيها."},{"id":"muallaqat:342","bookId":"muallaqat","type":"section","seq":342,"chapter":"مدخل","title":"58- قد بت سامرها وغاية تاجر","page":"ج1 ص192","text":"قد بت سامرها وغاية تاجر ... وافيت إذ رفعت وعز مدامها\nالغاية: راية ينصبها الخمار ليعرف مكانه، وأراد بالتاجر الخمار. وافيت المكان: أتيته. المدام والمدامة: الخمر، سميت بها لأنها قد أديمت في دنها.\nيقول: قد بت محدث تلك الليلة، أي كنت سامرا ندمائي ومحدثهم فيها، ورب راية خمار أتيتها حين رفعت ونصبت وغلت خمرها وقل وجودها، يتمدح بكونه لسان أصحابه وبكونه جوادا لاشترائه الخمر غالية لندمائه."},{"id":"muallaqat:343","bookId":"muallaqat","type":"section","seq":343,"chapter":"مدخل","title":"59- أغلي السباء بكل أدكن عاتق","page":"ج1 ص192","text":"أغلي السباء بكل أدكن عاتق ... أو جونة قدحت وفض ختامها\nسبأت الخمر أسبؤها سبأ وسباء: اشتريتها. أغليت الشيء: اشتريته غاليا وصيرته غاليا ووجدته غاليا. الأدكن: الذي فيه دكنة كالخز الأدكن، أراد بكل زق أدكن. الجونة: السوداء، أراد أو خابية سوداء قدحت. القدح: الغرف. الفض: الكسر. الخاتم والخاتم والخاتام والخيتام والختام واحد.\nيقول: أشتري الخمر غالية السعر باشتراء كل زق أدكن أو خابية سوداء قد فض ختامها واغترف منها، وتحرير المعنى: أشتري الخمر للندماء عند غلاء السعر وأشتري\nكل زق مقير1 أو خابية مقيرة، وإنما قيرا لئلا يرشحا بما فيهما، ويسرع صلاحه وانتهاؤه منتهى إداركه وقوله: قدحت وفض ختامها فيه، تقديم تقديره: فض ختامها وقدحت؛ لأنه ما لم يكسر ختامها لا يمكن اغتراف ما فيها من الخمر."},{"id":"muallaqat:344","bookId":"muallaqat","type":"section","seq":344,"chapter":"مدخل","title":"60- وصبوح صافية وجذب كرينة","page":"ج1 ص193","text":"وصبوح صافية وجذب كرينة ... بموتر تأتاله إبهامها\nالكرينة: الجارية العوادة، والجمع الكرائن. الائتيال: المعالجة. أراد بالموتر العود.\nيقول: وكم من صبوح خمر صافية، وجذب عوادة عودا موترا تعالجه إبهام العوادة؛ وتحرير المعنى: كم من صبوح من خمر صافية استمتعت باصطباحها وضرب عوادة عودها استمتعت بالإصغاء إلى أغانيها."},{"id":"muallaqat:345","bookId":"muallaqat","type":"section","seq":345,"chapter":"مدخل","title":"61- باكرت حاجتها الدجاج بسحرة","page":"ج1 ص193","text":"باكرت حاجتها الدجاج بسحرة ... لأعل منها حين هب نيامها\nيقول: باكرت الديوك لحاجتي إلى الخمر، أي تعاطيت شربها قبل أن يصدح الديك، لأسقى منها مرة بعد أخرى حين استيقظ نيام السحرة، والسحرة والسحر بمعنى، والدجاج اسم للجنس يعم ذكوره وإناثه، والواحد دجاجة، وجمع الدجاج دجج، والدجاج، بكسر الدال، لغة غير مختارة؛ وتحرير المعنى: باكرت صياح الديك لأسقى من الخمر سقيا متتابعا."},{"id":"muallaqat:346","bookId":"muallaqat","type":"section","seq":346,"chapter":"مدخل","title":"62- وغداة ريح قد وزعت وقرة","page":"ج1 ص193","text":"وغداة ريح قد وزعت وقرة ... إذ أصبحت بيد الشمال زمامها\nالقرة والقر: البرد.\nيقول: كم من غداة تهب فيها الشمال وهي أبرد الرياح، وبرد قد ملكت الشمال زمامه قد كففت عادية البرد عن الناس بنحر الجزر لهم؛ وتحرير المعنى: وكم من برد كففت غرب2 عاديته بإطعام الناس."},{"id":"muallaqat:347","bookId":"muallaqat","type":"section","seq":347,"chapter":"مدخل","title":"63- ولقد حميت الحي تحمل شكتي","page":"ج1 ص193","text":"ولقد حميت الحي تحمل شكتي ... فرط وشاحي إذ غدوت لجامها\nالشكة: السلاح. الفرط: الفرس المتقدمة السريعة الخفيفة. الوشاح والإشاح بمعنى، والجمع الوشح.\nيقول: ولقد حميت قبيلتي في حال حمل فرس متقدمة سريعة سلاحي ووشاحي لجامها إذا غدوت، يريد أنه يلقي لجام الفرس على عاتقه ويخرج منه يده حتى يصير بمنزلة الوشاح، يريد أنه يتوشح بلجامها لفرط الحاجة إليه حتى إذا ارتفع صراخ ألجم الفرس وركبها سريعا، وتحرير المعنى: ولقد حميت قبيلتي وأنا على فرس أتوشح بلجامها إذا نزلت لأكون متهيئا لركوبها."},{"id":"muallaqat:348","bookId":"muallaqat","type":"section","seq":348,"chapter":"مدخل","title":"64- فعلوت مرتقبا على ذي هبوة","page":"ج1 ص194","text":"فعلوت مرتقبا على ذي هبوة ... حرج إلى أعلامهن قتامها\nالمرتقب: المكان المرتفع الذي يقوم عليه الرقيب. الهبوة: الغبرة. الحرج: الضيق جدا. الأعلام الجبال والرايات. القتام: الغبار.\nيقول: فعلوت عند حماية الحي مكانا عاليا، أي كنت ربيئة لهم على ذي هبوة، أي على جبل ذي هبوة، وقد قرب قتام الهبوة إلى أعلام فرق الأعداء وقبائلهم، أي ربأت لهم على جبل قريب من جبال الأعداء ومن راياتهم."},{"id":"muallaqat:349","bookId":"muallaqat","type":"section","seq":349,"chapter":"مدخل","title":"65- حتى إذا ألقت يدا في كافر","page":"ج1 ص194","text":"حتى إذا ألقت يدا في كافر ... وأجن عورات الثغور ظلامها\nالكافر: الليل، سمي به لكفره الأشياء أي: لستره، والكفر: الستر، والإجنان الستر أيضا. الثغر: موضع المخافة والجمع الثغور، وعورته أشده مخافة.\nيقول: حتى إذا ألقت الشمس يدها في الليل أي ابتدأت في الغروب، وعبر عن هذا المعنى بإلقاء اليد؛ لأن من ابتدأ بالشيء قبل ألقى يده فيه، وستر الظلام مواضع المخافة والضمير الذي بعد ظلامها للعورات؛ وتحرير المعنى: حتى إذا غربت الشمس وأظلم ليلها."},{"id":"muallaqat:350","bookId":"muallaqat","type":"section","seq":350,"chapter":"مدخل","title":"66- أسهلت وانتصبت كجذع منيفة","page":"ج1 ص194","text":"أسهلت وانتصبت كجذع منيفة ... جرداء يحصر دونها جرامها\nأسهل: أتى السهل من الأرض. المنيفة: العالية الطويلة. الجرداء: القليلة السعف والليف، مستعارة من الجرداء من الخيل. الحصر: ضيق الصدر، والفعل حصر يحصر. الجرام: جمع الجارم وهو الذي يجرم النخل أي: يقطع حمله.\nيقول: لما غربت الشمس وأظلم الليل نزلت من المرقب وأتيت مكانا سهلا.\nوانتصبت الفرس، أي رفعت عنقها، كجذع نخلة طويلة عالية تضيق صدور الذين يريدون قطع حملها لعجزهم وضعفهم عن ارتقائها، شبه عنقها في الطول بمثل هذه النخلة وقوله: كجذع منيفة، أي: كجذع نخلة منيفة."},{"id":"muallaqat:351","bookId":"muallaqat","type":"section","seq":351,"chapter":"مدخل","title":"67- رفعتها طرد النعام وشله","page":"ج1 ص195","text":"رفعتها طرد النعام وشله ... حتى إذا سخنت وخف عظامها\nرفعتها: مبالغة رفعت. الطرد والطرد1 بفتح الراء وتسكينها لغتان جديدتان، والشل والشلل الطرد أيضا.\nيقول: حملت فرسي وكلفتها عدوا مثل عدو النعام، أو كلفتها عدوا يصلح لاصطياد النعام، حتى إذا جدت في الجري وخف عظامها في السير."},{"id":"muallaqat:352","bookId":"muallaqat","type":"section","seq":352,"chapter":"مدخل","title":"68- قلقت رحالتها وأسبل نحرها","page":"ج1 ص195","text":"قلقت رحالتها وأسبل نحرها ... وابتل من زبد الحميم حزامها\nالقلق: سرعة الحركة. الرحال: شبه سرج يتخذ من جلود الغنم بأصوافها ليكون أخف في الطلب والهرب، والجمع الرحائل. أسبل: أمطر. الحميم: العرق.\nيقول: اضطربت رحالتها على ظهرها من إسراعها في عدوها ومطر نحرها عرقا وابتل حزامها من زبد عرقها، أي من عرقها."},{"id":"muallaqat:353","bookId":"muallaqat","type":"section","seq":353,"chapter":"مدخل","title":"69- ترقى وتطعن في العنان وتنتحي","page":"ج1 ص195","text":"ترقى وتطعن في العنان وتنتحي ... ورد الحمامة إذ أجد حمامها\nرقي يرقى رقيا: صعد وعلا. الانتحاء الاعتماد. الحمام: ذوات الأطواق من الطير، واحدتها حمامة، وتجمع الحمامة على الحمامات والحمائم أيضا.\nيقول: ترفع عنقها نشاطا عدوها حتى كأنها تظعن بعنقها في عنانها وتعتمد في عدوها الذي يشبه ورد الحمامة حين جد الحمام التي هي في جملتها في الطيران لما ألح عليها من العطش، شبه سرعة عدوها بسرعة طيران الحمائم إذا كانت عشطى، وورد الحمامة نصب على المصدر من غير لفظ الفعل وهي ترقى أو تطعن أو تنتحي2."},{"id":"muallaqat:354","bookId":"muallaqat","type":"section","seq":354,"chapter":"مدخل","title":"70- وكثيرة غربائها مجهولة","page":"ج1 ص195","text":"وكثيرة غربائها مجهولة ... ترجى نوافلها ويخشى ذامها\nالذيم والذام: العيب.\nيقول: ورب مقامة أو قبة أو دار كثرت غرباؤها وغاشيتها وجهلت، أي لا يعرف بعض الغرباء بعضا، ترجى عطاياها ويخشى عيبها، يفتخر بالمناظرة التي جرت بينه وبين الربيع بن زياد في مجلس النعمان بن المنذر ملك العرب، ولها قصة طويلة؛ وتحرير المعنى: رب دار كثرت غاشيتها؛ لأن دور الملك يغشاها الوفود، وغرباؤها يجهل بعضها بعضا، وترجى عطايا الملوك، وتخشى معايب تلحق في مجالسها."},{"id":"muallaqat:355","bookId":"muallaqat","type":"section","seq":355,"chapter":"مدخل","title":"71- غلب تشذر بالذحول كأنها","page":"ج1 ص196","text":"غلب تشذر بالذحول كأنها ... جن البدي رواسيا أقدامها\nالغلب: الغلاظ الأعناق. التشذر: التهدد. الذحول: الأحقاد، الواحد ذحل. البدي: موضع. الرواسي. الثوابت.\nيقول: وهم رجال غلاظ الأعناق كالأسود، أي خلقوا خلقة الأسود، يهدد بعضهم بعضا بسبب الأحقاد التي بينهم، ثم شبههم بجن هذا الموضع في ثباتهم في الخصام والجدال، يمدح خصومه، وكلما كان الخصم أقوى وأشد كان قاهره وغالبه أقوى وأشد."},{"id":"muallaqat:356","bookId":"muallaqat","type":"section","seq":356,"chapter":"مدخل","title":"72- أنكرت باطلها وبؤت بحقها","page":"ج1 ص196","text":"أنكرت باطلها وبؤت بحقها ... عندي ولم يفخر علي كرامها\nباء بكذا: أقر به، ومنه قولهم في الدعاء: أبوء لك بالنعمة أي أقر.\nيقول: أنكرت باطل دعاوى تلك الرجال الغلب وأقررت بما كان حقها منها عندي، أي في اعتقادي ولم يفخر علي كرامها، أي لم يغلبني بالفخر كرامها، من قولهم: فاخرته ففخرته، أي غلبته بالفخر وكان ينبغي أن يقول: ولم تفخرني كرامها، ولكنه ألحق علي حملا على معنى: ولم يتعال علي ولم يتكبر علي."},{"id":"muallaqat:357","bookId":"muallaqat","type":"section","seq":357,"chapter":"مدخل","title":"73- وجزور أيسار دعوت لحتفها","page":"ج1 ص196","text":"وجزور أيسار دعوت لحتفها ... بمغالق متشابه أجسامها\nالأيسار: جمع يسر وهو صاحب الميسر. المغالق: سهام الميسر: سميت بها لأن بها يغلق الخطر، من قولهم: غلق الرهن يغلق غلقا1، إذا لم يوجد له تخلص وفكاك\nيقول: ورب جزور أصحاب ميسر دعوت ندمائي لنحرها وعقرها بأزلام1 متشابهة الأجسام، وسهام الميسر يشبه بعضها بعضا، وتحرير المعنى: ورب جزور أصحاب ميسر كانت تصلح لتقامر الأيسار عليها، دعوت ندمائي لهلاكها أي لنحرها بسهام متشابهة، قال الأئمة: يفتخر بنحره إياها من صلب ماله لا من كسب قماره، والأبيات التي بعده تدل عليه، وإنما أراد السهام ليقرع بها بين إبله أيها ينحر للندماء."},{"id":"muallaqat:358","bookId":"muallaqat","type":"section","seq":358,"chapter":"مدخل","title":"74- أدعو بهن لعاقر أو مطفل","page":"ج1 ص197","text":"أدعو بهن لعاقر أو مطفل ... بذلت لجيران الجميع لحامها\nالعاقر: التي لا تلد. المطفل التي معها ولدها. اللحام: جمع لحم.\nيقول: أدعو بالقداح لنحر ناقة عاقر، أو ناقة مطفل تبذل لحومها لجميع الجيران، أي: إنما أطلب القداح لأنحر مثل هاتين، وذكر العاقر لأنها أسمن وذكر المطفل لأنها أنفس."},{"id":"muallaqat:359","bookId":"muallaqat","type":"section","seq":359,"chapter":"مدخل","title":"75- فالضيف والجار الجنيب كأنما","page":"ج1 ص197","text":"فالضيف والجار الجنيب كأنما ... هبطا تبالة مخصبا أهضامها\nالجنيب: الغريب. تبالة: واد مخصب من أودية اليمن. الهضيم المطمئن من الأرض، والجمع الأهضام والهضوم.\nيقول: فالأضياف والجيران الغرباء عندي كأنهم نازلون هذا الوادي في حال كثرة نبات أماكنه المطمئنة، شبه ضيفه وجاره في الخصب والسعة بنازل هذا الوادي أيام الربيع."},{"id":"muallaqat:360","bookId":"muallaqat","type":"section","seq":360,"chapter":"مدخل","title":"76- تأوي إلى الأطناب كل رذية","page":"ج1 ص197","text":"تأوي إلى الأطناب كل رذية ... مثل البلية قالص أهدامها\nالأطناب: حبال البيت، واحدها طنب. الرذية: الناقة التي ترذي في السفر، أي تخلف لفرط هزالها وكلالها، والجمع الرذايا، استعارها للفقيرة. البلية: الناقة التي تشد على قبر صاحبها حتى تموت، والجمع البلايا. الأهدام: الأخلاق من الثياب، واحدها هدم. قلوصها: قصرها.\nيقول: وتأوي إلى أطناب بيتي كل مسكينة ضعيفة قصيرة الأخلاق التي عليها لما\nبها من الفقر والمسكنة، ثم شبهها بالبلية في قلة تصرفها وعجزها عن الكسب وامتناع الرزق منها."},{"id":"muallaqat:361","bookId":"muallaqat","type":"section","seq":361,"chapter":"مدخل","title":"77- ويكللون إذا الرياح تناوحت","page":"ج1 ص198","text":"ويكللون إذا الرياح تناوحت ... خلجا تمد شوارعا أيتامها\nتناوحت: تقابلت، ومنه قولهم: الجبلان متناوحان، أي متقابلان، ومنه النوائح لتقابلهن، الخلج: جمع خليج وهو نهر صغير يخلج من نهر كبير أو من بحر، والخلج: الجذب. تمد: تزداد. شرع في الماء: خاضه.\nيقول: ونكلل1 للفقراء والمساكين والجيران إذا تقابلت الرياح، أي في كلب2 الشتاء واختلاف هبوب الرياح، جفافا تحكي بكثرة مرقها أنهارا يشرع أيتام المساكين فيها وقد كللت بكسور اللحم، وتلخيص المعنى: ونبذل للمساكين والجيران جفانا عظاما مملوءة مرقا مكللة بكسور اللحم في كلب الشتاء وضنك المعيشة."},{"id":"muallaqat:362","bookId":"muallaqat","type":"section","seq":362,"chapter":"مدخل","title":"78- إنا إذا التقت المجامع لم يزل","page":"ج1 ص198","text":"إنا إذا التقت المجامع لم يزل ... منا لزاز عظيمة جشامها\nرجل لزاز الخصوم، يصلح؛ لأن يلز بهم، أي: يقرن بهم ليقهرهم، ومنه لزاز3 الباب ولزاز الجدار.\nيقول: إذا اجتمعت جماعات القبائل فلم يزل يسودهم رجل منا يقمع الخصوم عند الجدال، ويتجشم عظائم الخصام، أي لا تخلو المجامع من رجال منا يتحلى بما ذكر من قمع الخصوم وتكلف الخصام."},{"id":"muallaqat:363","bookId":"muallaqat","type":"section","seq":363,"chapter":"مدخل","title":"79- ومقسم يعطي العشيرة حقها","page":"ج1 ص198","text":"ومقسم يعطي العشيرة حقها ... ومغذمر لحقوقها هضامها\nالتغذمر: والغذمرة: التغضب مع همهمة. الهضم: الكسر والظلم.\nيقول: يقسم الغنائم، فيوفر على العشائر حقوقها ويتغضب عند إضاعة شيء من حقوقها ويهضم حقوق نفسه يريد أن السيد منا يوفر حقوق عشائره بالهضم من حقوق نفسه؛ قوله: ومغذمرة لحقوقها، أي لأجل حقوقها، هضامها أي هضام الحقوق التي\nتكون له، والكناية في هضامها يجوز أن تكون عائدة على العشيرة أي هضام الأعداء فيهم منا، أي هضامهم للأعداء منا، ويجوز أن تكون عائدة على الحقوق أي المغذمر لحقوق العشيرة والهضام لها منا، والسيد يملك أمور القوم جبرا وهضما في أوقاتها على اختلافها، فإن أساءوا هضم حقهم وإن أحسنوا تغذمر لهم."},{"id":"muallaqat:364","bookId":"muallaqat","type":"section","seq":364,"chapter":"مدخل","title":"80- فضلا وذو كرم يعين على الندى","page":"ج1 ص199","text":"فضلا وذو كرم يعين على الندى ... سمح كسوب رغائب غنامها\nالندى: الجود والفعل ندي يندى ندى، ورجل ند. الرغائب: جمع الرغيبة وهي ما رغب فيه من علق نفيس أو خصلة شريفة أو غيرهما. الغنام: مبالغة الغانم.\nيقول: يفعل ما سبق ذكره تفضلا ولم يزل منا كريم يعين أصحابه على الكرم، أي يعطيهم ما يعطون، جواد يكسب رغائب المعالي ويغتنمها."},{"id":"muallaqat:365","bookId":"muallaqat","type":"section","seq":365,"chapter":"مدخل","title":"81- من معشر سنت لهم آباؤهم","page":"ج1 ص199","text":"من معشر سنت لهم آباؤهم ... ولكل قوم سنة وإمامها\nيقول: هو من قوم سنت لهم أسلافهم كسب رغائب المعالي واغتنامها، ثم قال: ولكل قوم سنة وإمام سنة يؤتم به فيها."},{"id":"muallaqat:366","bookId":"muallaqat","type":"section","seq":366,"chapter":"مدخل","title":"82- لا يطبعون ولا يبور فعالهم","page":"ج1 ص199","text":"لا يطبعون ولا يبور فعالهم ... إذ لا يميل مع الهوى أحلامها\nالطبع: تدنس العرض وتلطخه، والفعل طبع يطبع. البوار: الفساد والهلاك. الفعال: فعل الواحد جميلا كان أو قبيحا، كذا قال ثعلب والمبرد وابن الأنباري وابن الأعرابي.\nيقول: لا تتدنس أعراضهم بعار ولا تفسد أفعالهم إذ لا تميل عقولهم مع أهوائهم."},{"id":"muallaqat:367","bookId":"muallaqat","type":"section","seq":367,"chapter":"مدخل","title":"83- فاقنع بما قسم المليك فإنما","page":"ج1 ص199","text":"فاقنع بما قسم المليك فإنما ... قسم الخلائق بيننا علامها\nيقول: فاقنع أيها العدو بما قسم الله تعالى فإن قسام المعايش والخلائق علامها، يريد أن الله تعالى قسم لكل ما استحقه من كمال ونقص ورفعة وضعة. والقسم مصدر قسم يقسم، والقسم والقسمة اسمان، وجمع القسم أقسام، وجمع القسمة قسم. الملك والملك، بسكون اللام وكسرها، والمليك واحد، وجمع الملك، بكسون اللام، ملوك، وجمع الملك، بكسر اللام أملاك."},{"id":"muallaqat:368","bookId":"muallaqat","type":"section","seq":368,"chapter":"مدخل","title":"84- وإذا الأمانة قسمت في معشر","page":"ج1 ص200","text":"وإذا الأمانة قسمت في معشر ... أوفى بأوفر حظنا قسامها\nمعشر: قوم. قسم وقسم. بالتشديد والتخفيف واحد. أوفى ووفى. كمل ووفر، ووفى يفي وفيا كمل، والوفور الكثرة. بأوفر حظنا أي بأكثره.\nيقول: وإذا قسمت الأمانات بين الأقوام وفر وكمل من الأمانة أي نصيبنا الأكثر منها، يريد أنهم الأقوام أمانة؛ والباء في قوله بأوفر زائدة أي: أوفى أوفر حظنا."},{"id":"muallaqat:369","bookId":"muallaqat","type":"section","seq":369,"chapter":"مدخل","title":"85- فبنى لنا بيتا رفيعا سمكه","page":"ج1 ص200","text":"فبنى لنا بيتا رفيعا سمكه ... فسما إليه كهلها وغلامها\nيقول: بنى الله تعالى بيت شرف ومجد عالي السقف فارتفع إلى ذلك الشرف كهل العشيرة وغلامها، يريد أن كهولهم وشبانهم يسمون إلى المعالي والمكارم. وإذا روي هذا البيت قبل \"فاقنع\"، كان المعنى، فبنى لنا سيدنا بيت مجد وشرف إلى آخر المعنى."},{"id":"muallaqat:370","bookId":"muallaqat","type":"section","seq":370,"chapter":"مدخل","title":"86- وهم السعاة إذا العشيرة أفظعت","page":"ج1 ص200","text":"وهم السعاة إذا العشيرة أفظعت ... وهم فوارسها وهم حكامها\nالسعاة: جمع الساعي. أفظعت: أصيب بأمر فظيع.\nيقول: إذا أصاب العشيرة أمر عظيم سعوا بدفعه وكشفه، وهم فرسان العشيرة عند قتالها وحكامها عند تخاصمها، يريد رهطه الأدنين1."},{"id":"muallaqat:371","bookId":"muallaqat","type":"section","seq":371,"chapter":"مدخل","title":"87- وهم ربيع للمجاور فيهم","page":"ج1 ص200","text":"وهم ربيع للمجاور فيهم ... والمرملات إذا تطاول عامها\nأرمل القوم: إذا نفدت أزوادهم.\nيقول: هم لمن جاورهم ربيع لعموم نفعهم وإحيائهم إياه بجودهم كما يحيي الربيع الأرض؛ وتحرير المعنى: هم لمن جاورهم وللنساء اللواتي نفدت أزوادهن بمنزلة الربيع إذا تطاول عامها لسوء حالها لأن زمان الشدة يستطال."},{"id":"muallaqat:372","bookId":"muallaqat","type":"section","seq":372,"chapter":"مدخل","title":"88- وهم العشيرة أن يبطئ حاسد","page":"ج1 ص200","text":"وهم العشيرة أن يبطئ حاسد ... أو أن يميل مع العدو لئامها\nقوله: أن يبطئ حاسد، معناه على قول البصريين: كراهية أن يبطئ حاسد وكراهية أن يميل، وعند الكوفيين، أن لا يبطئ حاسد وأن لا يميل، كقوله تعالى:\n{يبين الله لكم أن تضلوا} [النساء: 176] ، أي: كراهية أن تضلوا, أو يبين الله لكم أن لا كراهية أن يبطئ حاسد بعضهم عن نصر بعض أو كيلا يبطئ حاسد بعضهم عن نصر بعض وكراهية أن يميل لئام العشيرة وأخساؤها مع العدو، أي أن يظاهر الأعداء على الأقرباء؛ وتحرير المعنى: أنهم يتوافقون ويتعاضدون كراهية أن يبطئ الحساد بعضهم عن نصر بعض وميل لئامهم إلى الأعداء أو مظاهرتهم إياهم على الأقارب."},{"id":"muallaqat:373","bookId":"muallaqat","type":"section","seq":373,"chapter":"مدخل","title":"مدخل","page":"ج1 ص202","text":"...\nعمرو بن كلثوم\nهو: عمرو بن كلثوم بن مالك بن عتاب بن زهير التغلبي، من بني تغلب بن وائل، وينتهي نسبه إلى معد بن عدنان، وأمه هي ليلي بنت مهلهل الذي هو أخو كليب المشهور.\nوقد ساد عمرو بن كلثوم قومه وهو ابن خمسة عشر عاما. ومات وله من العمر مائة وخمسون سنة \"150\".\nوكان فارسا أبيا جريئا، حتى بلغ من أمره أن فتك بالطاغية عمرو بن هند، في بلاط سلطانه.\nوكان عمرو بن كلثوم شجاعا مظفرا مقداما فتاكا. وبه يضرب المثل في الفتك، فيقال: أفتك من عمرو بن كلثوم لفتكه بعمرو بن هند.\nوكانت وفاته سنة 600 لميلاد المسيح عليه السلام، وسنة 52 قبل الهجرة النبوية. وله من العمر خمسون سنة ومائة \"150\".\nكان شاعرا فحلا مطبوعا، صافي الديباجة، كثير الطلاوة، حسن السبك، واضح المعاني، شديد الفخر، قوي الشكيمة في الحماسة.\nمعلقة عمرو بن كلثوم أشهر شعره وأشعره. وهي حماسية فخرية. وما وصل إلينا منها هو جزء يسير منها.\nوقد قام عمرو بها خطيبا في سوق عكاظ، وقام بها في موسم مكة. وبنو تغلب تعظمها جدا، ويرويها صغارهم وكبارهم.\nوالخطب الذي دعا إلى نظمها ليس واحدا على ما يتراءى لمن يتتبع أبيات\nالقصيدة. ويفهم ذلك من اختلاف الرواة في سبب نظمها. ففي \"كتاب الأغاني\" يصرح أنه قالها على أثر ما جرى لأمه عند عمرو بن هند وفي كتاب \"خزانة الأدب\" أنه أنشدها بحضرة الملك عمرو بن هند. فلعله نظمها في الواقعتين."},{"id":"muallaqat:374","bookId":"muallaqat","type":"section","seq":374,"chapter":"مدخل","title":"1- نسبه ونشأته","page":"ج1 ص204","text":"هو أبو عباد عمرو بن كلثوم بن مالك2 بن عتاب بن سعد بن زهير بن جشم بن بكر بن حبيب بن عمرو3 بن غنم بن تغلب4 بن وائل بن قاسط بن هنب5 بن\nأفصى بن دعمي بن جديلة بن أسد بن ربيعة بن نزار بن معد بن عدنان.\nأما تاريخ ولادته فلا نعرف عنه شيئا إذ لم تذكره المصادر التي بين أيدينا، وقد جعل كوسين دي برسفال: Caussin de Perceval، مولده حوالي السنة 525م 1، وكل ما نستطيع تأكيده هو أن الشاعر عاصر عمرو بن هند، 554م- 570م، وأنه أدرك النعمان بن المنذر، 580- 602م، فهجاه.\nوأما مكان ولادته فهو أيضا غير معروف بالتحديد، وأغلب الظن أنه ولد في بلاد ربيعة، أي في شمالي الجزيرة العربية.\nوكان والده من سادات قومه2، فتزوج ليلي بنت المهلهل: عدي بن زيد، الشاعر والفارس الذي اشتهر في حرب تغلب وبكر، فنشأ عمرو يكتنفه الشرف من الطرفين في قبيلة كانت من أقوى القبائل العربية في العصر الجاهلي، إن لم تكن أقواها، وقد قيل فيها: \"لو أبطأ الإسلام قليلا لأكلت بنو تغلب الناس\"3.\nنشأ عمرو بن كلثوم إذن، في بيت من أسياد تغلب، هذه القبيلة المرهوبة الجانب، فكان من الطبيعي أن يكون معجبا بنفسه، فخورا بأهله وقومه، ويظهر أن شاعرنا توافرت لديه من الخصائل الحميدة كالشاعرية، والفروسية، والخطابة والكرم، والشجاعة، ما جعله يسود قومه في سن مبكرة، فقد ذكر أنه ساد قومه وهو ابن خمس عشرة سنة4.\nأما أخباره، فلم يصلنا منها إلا النزر القليل، ومنه أن الشاعر قضي حياته مدافعا عن قومه، مشاركا إياهم في الحروب والغزوات، متنقلا معهم كرا وفرا حتى وافته المنية. وأهم أخباره ثلاثة: إنشاده لمعلقته مدافعا عن قومه عند عمرو بن هند، وقتله لعمرو بن هند، وأسره."},{"id":"muallaqat:375","bookId":"muallaqat","type":"section","seq":375,"chapter":"مدخل","title":"2- إنشاده لمعلقته","page":"ج1 ص206","text":"يروي ابن الأنباري والخطيب التبريزي قصة إنشاد عمرو بن كلثوم لمعلقته، فيقولان: \"جاء ناس من بني تغلب إلى أبي بكر بن وائل يستسقونهم، فطردتهم بكر1، للحقد الذي كان بينهم، فرجعوا فمات منهم سبعون رجلا عطشا، ثم إن بني تغلب اجتمعوا لحرب بكر بن وائل، واستعدت لهم بكر. حتى إذا التقوا كره كل صاحبه، وخافوا أن تعود الحرب بينهم كما كانت، فدعا بعضهم بعضا إلى الصلح، فتحاكموا في ذلك إلى عمرو بن هند. فقال عمرو: ما كنت لأحكم بينكم، حتى تأتوني بسبعين رجلا2 من أشراف بكر بن وائل، فأجعلهم في وثائق عندي، فإن كان الحق لبني تغلب دفعتهم إليهم، وإن لم يكن لهم حق خليت سبيلهم، ففعلوا، وتواعدوا ليوم بعينه يجتمعون فيه. فقال الملك لجلسائه: من ترون تأتي به تغلب لمقامها هذا؟ فقالوا: شاعرهم وسيدهم عمرو بن كلثوم. قال: فبكر بن وائل؟ فاختلفوا عليه، وذكروا غير واحد من أشراف بكر بن وائل. قال: كلا، والله، لا تفرج بكر بن وائل إلا على الشيخ الأصم، يعثر في ريطته3، فيمنعه الكرم من أن يرفعها قائده، فيضعها على عاتقه. فلما أصبحوا، جاءت تغلب يقودها عمرو بن كلثوم، حتى جلس إلى الملك.\nوقال الحارث بن حلزة لقومه: إني قد قلت خطبة، فمن قام بها ظفر بحجته، وفلج4 على خصمه. فرواها ناسا منهم. فلما قاموا بين يديه لم يرضهم. فحين علم أنه لا يقوم بها أحد مقامه. قال لهم: والله إني لأكره أن آتي الملك، فيكلمني من وراء سبعة ستور، وينضح أثري بالماء إذا انصرفت عنه -وذلك لبرص كان به- غير أني لا\nأرى أحدا يقوم بها مقامي، وأنا محتمل ذلك لكم، فانطلق حتى أتى الملك. فلما نظر إليه عمرو بن كلثوم قال للملك: أهذا يناطقني، وهو لا يطيق صدر راحلته؟ فأجابه الملك حتى أفحمه، وأنشد الحارث قصيدته: \"آذنتنا ببينها أسماء\"، وهو من وراء سبعة ستور، وهند تسمع. فلما سمعت قالت: تالله ما رأيت كاليوم قط رجلا يقول مثل هذا القول، يكلم من وراء سبعة ستور! فقال الملك: ارفعوا سترا، ودنا، فما زالت تقول، ويرفع ستر فستر، حتى صار مع الملك على مجلسه. ثم أطعمه من جفنته، وأمر ألا ينضح أثره بالماء، وجز نواصي السبعين الذين كانوا في يديه من بكر، ودفعها إلى الحارث، وأمره ألا ينشد قصيدته إلا متوضئا، فلم تزل تلك النواحي في بني يشكر بعد الحارث1.\nوقام عمرو بن كلثوم، فأنشد جزءا من معلقته2 مفتخرا على خصومه، غير منتبه لمركز الملك، وما يلزم لمداراته واستمالته، فحكم عمرو بن هند على التغلبيين، فانصرف عمرو ورهطه غاضبين. ولعله قال، بعد هذه الحادثة، ما ذكر في ديوانه من هجاء له؛ ثم أكمل معلقته بعد ذلك، وخاصة بعد قتله للملك، كما سنفصل، ثم قام بها خطيبا بسوق عكاظ وقام بها في موسم مكة3."},{"id":"muallaqat:376","bookId":"muallaqat","type":"section","seq":376,"chapter":"مدخل","title":"3- قتله لعمرو بن هند سنة 570م","page":"ج1 ص208","text":"يظهر أن الملك عمرو بن هند أضمر للشاعر عمرو بن كلثوم الحقد لما رأى عنده من شدة فخر، وتباه، وتشامخ فأراد أن يذله بإذلال أمه، وروي أنه قال ذات يوم لندمائه: هل تعلمون أحدا من العرب تأنف أمه من خدمة أمي؟ فقالوا: نعم! أم عمرو بن كلثوم. قال: ولم؟ قالوا: لأن أباها مهلهل بن ربيعة، وعمها كليب وائل أعز العرب، وبعلها كلثوم بن مالك أفرس العرب، وابنها عمرو، وهو سيد قومه. فأرسل\nعمرو بن هند إلى عمرو بن كلثوم يستزيره، ويسأله أن يزير أمه أمه، فأقبل عمرو من الجزيرة إلى الحيرة في جماعة بني تغلب، وأقبلت ليلى بنت مهلهل في ظعن من بني تغلب. وأمر عمرو بن هند برواقه، فضرب فيما بين الحيرة والفرات، وأرسل إلى وجوه أهل مملكته، فحضروا في وجوه بني تغلب. فدخل عمرو بن كلثوم على عمرو بن هند في رواقه1، ودخلت ليلى وهند في قبة من جانب الرواق، وكانت هند عمة امرئ القيس بن حجر الشاعر، وكانت أم ليلى بنت مهلهل بنت أخي فاطمة بنت ربيعة التي هي أم امرئ القيس، وبينهما هذا النسب، وقد كان عمرو بن هند أمر أمه أن تنحي الخدم2 إذا دعا بالطرف3، وتستخدم ليلى. فدعا عمرو بمائدة، ثم دعا بالطرف فقالت هند: ناوليني يا ليلى ذلك الطبق. فقالت ليلى: لتقم صاحبة الحاجة إلى حاجتها. فأعادت عليها، وألحت، فصاحت ليلى: وأذلاه! يا لتغلب! فسمعها عمرو بن كلثوم، فثار الدم في وجهه، ونظر إليه عمرو بن هند، فعرف الشر في وجهه، فوثب عمرو بن كلثوم إلى سيف لعمرو بن هند معلق بالراق ليس هناك سيف غيره، فضرب به رأس عمرو بن هند، ونادى في بني تغلب، فانتهبوا ما في الرواق، وساقوا نجائبه، وساروا نحو الجزيرة4.\nوقد افتخر شعراء تغلب بقتل ابن كلثوم عمرو بن هند، فقال الفرزدق يرد على جرير في هجائه الأخطل \"من الكامل\":\nما ضر تغلب وائل أهجوتها ... أم بلت حيث تناطح البحران\nقوم هم قتلوا ابن هند عنوة ... عمرا، وهم قسطوا على النعمان5\nوقال أفنون التغلبي مفتخرا \"من الطويل\":\nلعمرك ما عمرو بن هند وقد دعا ... لتخدم ليلى أمه بموفق\nفقام ابن كلثوم إلى السيف مصلتا ... فأمسك من ندمانه بالمخنق1\nوجلله عمرو على الرأس ضربة ... بذي شطب صافي الحديدة رونق2\nوكان لعمرو أخ يقال له مرة، فقتل المنذر ابن النعمان وأخاه، وإياه عنى الأخطل بقوله لجرير \"من الكامل\":\nأبني كليب إن عمي اللذا ... قتلا الملوك وفككا الأغلالا3"},{"id":"muallaqat:377","bookId":"muallaqat","type":"section","seq":377,"chapter":"مدخل","title":"4- أسره","page":"ج1 ص210","text":"بعد مقتل عمرو بن هند، أصبح التغلبيون في عداوة مع جميع القبائل الخاضعة للمناذرة أو المحالفة إياهم، ومنهم بنو بكر أعداء التغلبيين الألداء، فاضطروا إلى مقاتلتهم جميعا، وفي إحدى غزواتهم، أغار عمرو بن كلثوم على بني تميم، ثم مر من غزوة ذلك على حي من بني قيس بن ثعلبة فملأ يديه منهم وأصاب أسارى وسبايا، وكان فيمن أصاب أحمد بن جندل السعدي، ثم انتهى إلى بني حنيفة باليمامة وفيهم أناس من عجل، فسمع به أهل حجر4، فكان أول من أتاه من بني حنيفة بنو سحيم عليهم يزيد بن عمرو بن شمر"},{"id":"muallaqat:378","bookId":"muallaqat","type":"section","seq":378,"chapter":"مدخل","title":"....","page":"ج1 ص210","text":"فانتهى إليه يزيد بن عمرو، فطعنه فصرعه عن فرسه، وأسره. وكان يزيد شديدا جسيما، فشده في القد، وقال له: أنت الذي تقول \"من الوافر\":\nمتى نعقد قرينتنا بحبل ... نجذ الحبل أو نقص القرينا\nأما إني سأقرنك إلى ناقتي، فأطردكما جميعا. فنادى عمرو بن كلثوم: يا لربيعة! أمثلة5! قال: فاجتمعت بنو لجيم، فنهوه، ولم يكن يريد ذلك به، فسار به حتى أتى\nقصرا بحجر من قصورهم، وضرب عليه قبة، ونحر له، وكساه، وحمله على نجيبة، وسقاه الخمر1."},{"id":"muallaqat:379","bookId":"muallaqat","type":"section","seq":379,"chapter":"مدخل","title":"5- ديانته وأخلاقه","page":"ج1 ص211","text":"كان عمرو بن كلثوم نصرانيا، على الأغلب2، وذلك لأن نصرانية تغلب ثابتة حتى القرن الثالث والرابع بعد الهجرة3، لكن ليس في ديوانه وأخباره التي وصلت إلينا ما يؤكد ذلك. أما صفاته وأخلاقه، فيظهر من أخباره وشعره، أنه كان فارسا مقداما، سيدا في قومه، شاعرا مفلقا، شديد الأنفة إلى حد الكبرياء، فخورا بنفسه وبقبيلته إلى حد الادعاء الصبياني، كريما سخيا4، فاتكا، وقد ضرب المثل بفتكه، فقيل: \"أفتك من عمرو بن كلثوم\"5 ولعل سبب هذا القول فتكه بالملك عمر بن هند."},{"id":"muallaqat:380","bookId":"muallaqat","type":"section","seq":380,"chapter":"مدخل","title":"6- وفاته","page":"ج1 ص211","text":"لم تذكر لنا المصادر العربية السنة التي توفي فيها عمرو بن كلثوم، مثلما لم تذكر سنة ولادته، لكن من المؤكد أنه عمر طويلا، فقد ذكر الأصفهاني أنه عمر مائة وخمسين سنة6، وقال كوسين دي برسفال: إنه عاش مائة سنة، وتوفي حوالي الهجرة7، وعين الأب لويس شيخو لوفاته السنة 600م دون أن يذكر المصدر الذي\nاستند إليه في هذا التعيين، وذهب خير الدين الزركلي وعمر كحالة إلى أنه توفي حوالي السنة 40 ق ه1.\nوذكر الأصفهاني أنه عندما حضرت ابن كلثوم الوفاة، جمع بنيه، وقال لهم: \"يا بني، قد بلغت من العمر ما لم يبلغه أحد من آبائي، ولا بد أن ينزل بي ما نزل بهم من الموت، وإني، والله، ما عيرت أحدا بشيء إلا عيرت بمثله، إن كان حقا فحقا، وإن كان باطلا فباطلا، ومن سب سب، فكفوا عن الشتم، فإنه أسلم لكم، وأحسنوا جواركم يحسن ثناؤكم، وامنعوا من ضيم الغريب، فرب رجل خير من ألف، ورد خير من خلف. إذا حدثتم فعوا، وإذا حدثتم فأوجزوا، فإن مع الإكثار تكون الأهذار2.\nوأشجع القوم العطوف بعد الكر، كما أن أكرم المنايا القتل. ولا خير فيمن لا روية له عند الغضب، ولا من إذا عوتب لم يعتب3. ومن الناس من لا يرجى خيره، ولا يخاف شره، فبكؤه4 خير من دره، وعقوقه خير من بره. ولا تتزوجوا من حيكم فإنه يؤدي إلى قبيح البغض\"5.\nوقد شكك بعضهم في نسبه هذه الوصية إلى عمرو بن كلثوم أو إلى العصر الجاهلي لما فيها من تكلف البديع اللفظي6."},{"id":"muallaqat:381","bookId":"muallaqat","type":"section","seq":381,"chapter":"مدخل","title":"7- أولاده","page":"ج1 ص212","text":"لم يذكر لنا الأصفهاني، في خبر وصية الشاعر لبنيه، أسماء هؤلاء ولا عددهم. وذكر في موضع أن له ولدا يقال له عباد7. وقد ذكر منهم في ديوانه ثلاثة8، ويظهر أنهم شعراء جميعا، وهم عباد وهو الأكبر، وقد نسب إليه أربعة أبيات، والأسود\nروي له ثلاثة مقاطع شعرية فيها أحد عشر بيتا والثالث عبد الله روي له ثلاثة أبيات وكان عقب الشاعر معروفا حتى عصر أبي الفرج الأصفهاني \"284ه/ 897- 356ه/ 967م\" إذ ذكر منهم كلثوم بن عمرو العتابي الشاعر صاحب الرسائل1."},{"id":"muallaqat:382","bookId":"muallaqat","type":"section","seq":382,"chapter":"مدخل","title":"8- معلقته وشعره","page":"ج1 ص213","text":"تعتبر"},{"id":"muallaqat:383","bookId":"muallaqat","type":"section","seq":383,"chapter":"مدخل","title":"معلقة عمرو بن كلثوم","page":"ج1 ص213","text":"من أجود القصائد العربية. قال أبو عبيدة: \"هو أجودهم واحدة\"2، وكان عيسى بن عمر يقول: \"لله در عمرو بن كلثوم أي حلس شعر3، وأي وعاء علم لو أنه رغب فيما رغب فيه أصحابه من الشعر، وإن واحدته لأجود سبعهم\"4، وقال: \"لو وضعت أشعار العرب في كفة، وقصيدة عمرو في كفة، لمالت بأكثرها\"5.\nوفي هذه المعلقة عدد الشاعر مفاخر قوم التغلبيين ودافع عن حقوقهم، ورد مزاعم أعدائهم، فعظمها بنو تغلب، ورواها صغارهم وكبارهم، حتى هجوا بذلك فقال بعض شعراء بكر بن وائل \"من البسيط\":\nألهى بني تغلب عن كل مكرمة ... قصيدة قالها عمرو بن كلثوم\nيروونها أبدا، مذ كان أولهم ... يا للرجال لشعر غير مسئوم6"},{"id":"muallaqat:384","bookId":"muallaqat","type":"section","seq":384,"chapter":"مدخل","title":"1- ألا هبي بصحنك فاصبحينا","page":"ج1 ص213","text":"ألا هبي بصحنك فاصبحينا ... ولا تبقي خمور الأندرينا\nهب من نومه هبا: إذا استيقظ. الصحن: القدح العظيم، والجمع الصحون. الصبح: سقي الصبوح، والفعل صبح يصبح. أبقيت الشيء وبقيته بمعنى. الأندرون: قرى بالشام.\nيقول: ألا استيقظي من نومك أيتها الساقية واسقيني الصبوح بقدحك العظيم، ولا تدخري خمر هذه القرى."},{"id":"muallaqat:385","bookId":"muallaqat","type":"section","seq":385,"chapter":"مدخل","title":"2- مشعشعة كأن الحص فيها","page":"ج1 ص213","text":"مشعشعة كأن الحص فيها ... إذا ما الماء خالطها سخينا\nشعشعت الشراب: مزجته بالماء. الحص: الورس نبت له نوار أحمر يشبه الزعفران. ومنهم من جعل سخينا صفة ومعناه الحار، من سخن يسخن سخونة، ومنهم من جعله فعلا من سخي يسخى سخاء، وفيه ثلاث لغات: إحداهن ما ذكرنا، والثانية سخو يسخو، والثالثة سخا يسخو سخاوة.\nيقول: اسقينيها ممزوجة بالماء كأنها من شدة حمرتها بعد امتزاجها بالماء ألقي فيها نور هذا النبت الأحمر، وإذا خالطها الماء وشربناها وسكرنا جدنا بعقائل1 أموالنا وسمحنا بذخائر أعلاقنا2، هذا إذا جعلنا سخينا فعلا، وإذا جعلناه صفة كان المعنى: كأنها حال امتزاجها بالماء وكون الماء حارا، نور هذا النبت. ويروى شحينا، بالشين المعجمة، أي إذا خالطها الماء مملوءة به. والشحن: الملء، والفعل شحن.\nيشحن، والشحين، بمعنى المشحون كالقتيل بمعنى المقتول، يريد أنها حال امتزاجها بالماء وكون الماء كثيرا تشبه هذا النور."},{"id":"muallaqat:386","bookId":"muallaqat","type":"section","seq":386,"chapter":"مدخل","title":"3- تجور بذي اللبانة عن هواه","page":"ج1 ص215","text":"تجور بذي اللبانة عن هواه ... إذا ما ذاقها حتى يلينا\nيمدح الخمر ويقول: تميل صاحب الحاجة عن حاجته وهواه إذا ذاقها حتى يلين، أي هي تنسي الهموم والحوائج أصحابها، فإذا شربوها لانوا ونسوا أحزانهم وحوائجهم."},{"id":"muallaqat:387","bookId":"muallaqat","type":"section","seq":387,"chapter":"مدخل","title":"4- ترى اللحز الشحيح إذا أمرت","page":"ج1 ص215","text":"ترى اللحز الشحيح إذا أمرت ... عليه لماله فيها مهينا\nاللحز: الضيق الصدر. الشحيح: البخيل الحريص، والجمع الأشحة والأشحاء، والشحاح أيضا مثل الشحيح، والفعل شح يشح، والمصدر الشح وهو البخل معه حرص.\nيقول: ترى الإنسان الضيق الصدر البخيل الحريص مهينا لماله، فيها أي في شربها إذا أمرت الخمر عليه، أي إذا أديرت عليه."},{"id":"muallaqat:388","bookId":"muallaqat","type":"section","seq":388,"chapter":"مدخل","title":"5- صبنت الكأس عنا أم عمرو","page":"ج1 ص215","text":"صبنت الكأس عنا أم عمرو ... وكان الكأس مجراها اليمينا\nالصبن: الصرف، والفعل صبن يصبن.\nيقول: صرفت الكأس عنا يا أم عمرو، وكان مجرى الكأس على اليمين فأجريتها على اليسار."},{"id":"muallaqat:389","bookId":"muallaqat","type":"section","seq":389,"chapter":"مدخل","title":"6- وما شر الثلاثة أم عمرو","page":"ج1 ص215","text":"وما شر الثلاثة أم عمرو ... بصاحبك الذي لا تصبحينا\nيقول: ليس بصاحبك الذي لا تسقينه الصبوح شر هؤلاء الثلاثة الذين تسقينهم، أي لست شر أصحابي، فكيف أخرتني وتركت سقيي الصبوح؟"},{"id":"muallaqat:390","bookId":"muallaqat","type":"section","seq":390,"chapter":"مدخل","title":"7- وكأس قد شربت ببعلبك","page":"ج1 ص215","text":"وكأس قد شربت ببعلبك ... وأخرى في دمشق وقاصرينا\nيقول: ورب كأس شربتها بهذه البلدة، ورب كأس شربتها بتينك البلدتين."},{"id":"muallaqat:391","bookId":"muallaqat","type":"section","seq":391,"chapter":"مدخل","title":"8- وإنا سوف تدركنا المنايا","page":"ج1 ص215","text":"وإنا سوف تدركنا المنايا ... مقدرة لنا ومقدرينا\nيقول: سوف تدركنا مقادير موتنا، وقد قدرت تلك المقادير لنا وقدرنا لها.\nالمنايا: جمع المنية وهي تقدير الموت."},{"id":"muallaqat:392","bookId":"muallaqat","type":"section","seq":392,"chapter":"مدخل","title":"9- قفي قبل التفرق يا ظعينا","page":"ج1 ص216","text":"قفي قبل التفرق يا ظعينا ... نخبرك اليقينا وتخبرينا\nأراد يا ظعينة فرخم، والظعينة: المرأة في الهودج، سميت بذلك لظعنها مع زوجها، فهي فعيلة بمعنى فاعلة، ثم كثر استعمال هذا الاسم للمرأة حتى يقال لها ظعينة وهي في بيت زوجها.\nيقول: قفي مطيتك أيتها الحبيبة الظاعنة نخبرك بما قاسينا بعدك، وتخبرينا بما لاقيت بعدنا."},{"id":"muallaqat:393","bookId":"muallaqat","type":"section","seq":393,"chapter":"مدخل","title":"10- قفي نسألك هل أحدثت صرما","page":"ج1 ص216","text":"قفي نسألك هل أحدثت صرما ... لوشك البين أم خنت الأمينا\nالصرم: القطيعة. الوشك: السرعة، والوشيك: السريع. الأمين: بمعنى المأمون.\nيقول: قفي مطيتك نسألك هل أحدثت قطيعة لسرعة الفراق، أم هل خنت حبيبك الذي تؤمن خيانته؟ أي هل دعتك سرعة الفراق إلى القطيعة أو إلى الخيانة في مودة من لا يخونك في مودته إياك؟"},{"id":"muallaqat:394","bookId":"muallaqat","type":"section","seq":394,"chapter":"مدخل","title":"11- بيوم كريهة ضربا وطعنا","page":"ج1 ص216","text":"بيوم كريهة ضربا وطعنا ... أقر به مواليك العيونا\nالكريهة: من أسماء الحرب، والجمع الكرائه، سميت لأن النفوس تكرهها، وإنما لحقتها التاء لأنها أخرجت مخرج الأسماء مثل: النطيحة والذبيحة، ولم تخرج مخرج النعوت مثل: امرأة قتيل وكف خضيب، ونصب ضربا وطعنا على المصدر أي يضرب فيه ضربا ويطعن فيه طعنا.\nقولهم: أقر الله عينك قال الأصمعي: معناه أبرد الله دمعك، أي سرك غاية السرور، وزعم أن دمع السرور بارد ودمع الحزن حار، وهو عندهم مأخوذ من القرور وهو الماء البارد، ورد عليه أبو العباس أحمد بن يحيى ثعلب هذا القول وقال: الدمع كله حار جلبه فرح أو ترح. وقال أبو عمرو الشيباني: معناه أنام الله عينك وأزال سهرها لأن استيلاء الحزن داع إلى السهر، فالإقرار على قوله إفعال من قر يقر قرارا، لأن العيون تقر في النوم وتطرف في السهر, وحكى ثعلب عن جماعة من الأئمة أن معناه: أعطاه الله مناك ومبتغاك حتى تقر عينك عن الطموح إلى غيره؛ وتحرير\nالمعنى: أرضاك الله؛ لأن المترقب للشيء يطمح ببصره إليه، فإذا ظفر به قرت عينه عن الطموح إليه.\nيقول: نخبرك بيوم حرب كثير فيه الضرب والطعن، فأقر بنو أعمامك عيونهم في ذلك اليوم، أي فازوا ببغيتهم وظفروا بمناهم من قهر الأعداء."},{"id":"muallaqat:395","bookId":"muallaqat","type":"section","seq":395,"chapter":"مدخل","title":"12- وإن غدا وإن اليوم رهن","page":"ج1 ص217","text":"وإن غدا وإن اليوم رهن ... وبعد غد بما لا تعلمينا\nأي بما لا تعلمين من الحوادث.\nيقول: فإن الأيام رهن بما لايحيط علمك به أي ملازمة له."},{"id":"muallaqat:396","bookId":"muallaqat","type":"section","seq":396,"chapter":"مدخل","title":"13- تريك إذا دخلت على خلاء","page":"ج1 ص217","text":"تريك إذا دخلت على خلاء ... وقد أمنت عيون الكاشحينا\nالكاشح: المضمر العداوة في كشحه1، وخصت العرب الكشح بالعداوة لأنه موضع الكبد، والعداوة عندهم تكون في الكبد، وقيل: بل سمي العدو كاشحا؛ لأنه يكشح عن عدوه أي يعرض عنه فيوليه كشحه، يقال: كشح عنه يكشح كشحا.\nيقول: تريك هذه المرأة إذا أتيتها خالية وأمنت عيون أعدائها."},{"id":"muallaqat:397","bookId":"muallaqat","type":"section","seq":397,"chapter":"مدخل","title":"14- ذراعي عيطل أدماء بكر","page":"ج1 ص217","text":"ذراعي عيطل أدماء بكر ... هجان اللون لم تقرأ جنينا\nالعيطل: الطويلة العنق من النوق. الأدماء: البيضاء منها. والأدمة البياض في الإبل، البكر: الناقة التي حملت بطنا واحدا، ويروى بكر بفتح الباء، وهو الفتي من الإبل وبكسر الباء أعلى الروايتين؛ ويروى: تربعت الأجارع والمتونا. تربعت: رعت ربيعا. الأجارع جمع الأجرع وهو المكان الذي فيه جرع، والجرع: جمع جرعة، وهي دعص2، من الرمل غير منبت شيئا. المتون: جمع متن وهو الظهر من الأرض. الهجان: الأبيض الخالص البياض، يستوي فيه الواحد والتثنية والجمع، وينعت به الإبل والرجال وغيرهما. لم تقرأ جنينا أي لم تضم فيه رحمها ولدا.\nيقول: تريك ذراعين ممتلئتين لحما كذراعي ناقة طويلة لم تلد بعد أو\nرعت أيام الربيع في مثل هذا الموضع، ذكر هذا مبالغة في سمنها، أي ناقة سمينة لم تحمل ولدا قط، بيضاء اللون."},{"id":"muallaqat:398","bookId":"muallaqat","type":"section","seq":398,"chapter":"مدخل","title":"15- وثديا مثل حق العاج رخصا","page":"ج1 ص218","text":"وثديا مثل حق العاج رخصا ... حصانا من أكف اللامسينا\nرخصا: لينا. حصانا: عفيفة.\nيقول: وتريك ثديا مثل حق1 من عاج بياضا واستدارة، محرزة من أكف من يلمسها."},{"id":"muallaqat:399","bookId":"muallaqat","type":"section","seq":399,"chapter":"مدخل","title":"16- ومتني لدنة سمقت وطالت","page":"ج1 ص218","text":"ومتني لدنة سمقت وطالت ... روادفها تنوء بما ولينا\nاللدن: اللين، والجمع لدن، أي ومتني قامة لدنة. السموق: الطول، والفعل سمق يسمق، الرادفتان والرانفتان: فرعا الأليتين، والجمع الروادف والروانف. النوء: النهوض في تثاقل. الولي: القرب، والفعل ولي يلي.\nيقول: وتريك متني قامة طويلة لينة تثقل أرادفها مع ما يقرب منها، وصفها بطول القامة وثقل الأرداف."},{"id":"muallaqat:400","bookId":"muallaqat","type":"section","seq":400,"chapter":"مدخل","title":"17- ومأكمة يضيق الباب عنها","page":"ج1 ص218","text":"ومأكمة يضيق الباب عنها ... وكشحا قد جننت به جنونا\nالمأكمة والمأكمة: رأس الورك والجمع المآكم.\nيقول: وتريك وركا يضيق الباب عنها لعظمها وضخمها وامتلائها باللحم، وكشحا قد جننت بحسنه جنونا."},{"id":"muallaqat:401","bookId":"muallaqat","type":"section","seq":401,"chapter":"مدخل","title":"18- وساريتي بلنط أو رخام","page":"ج1 ص218","text":"وساريتي بلنط أو رخام ... يرن خشاش حليهما رنينا\nالبلنط: العاج. السارية: الأسطوانة والجمع السواري. الرنين: الصوت.\nيقول: وتريك ساقين كأسطوانتين من عاج أو رخام بياضا وضخما يصوت حليهما، أي خلاخيلهما، تصويتا."},{"id":"muallaqat:402","bookId":"muallaqat","type":"section","seq":402,"chapter":"مدخل","title":"19- فما وجدت كوجدي أم سقب","page":"ج1 ص218","text":"فما وجدت كوجدي أم سقب ... أضلته فرجعت الحنينا\nقال القاضي أبو سعيد السيرافي: البعير بمنزلة الإنسان، والجمل بمنزلة الرجل، والناقة بمنزلة المرأة، والسقب1 بمنزلة الصبي، والحائل بمنزلة الصبية، والحوار2 بمنزلة الولد، والبكر بمنزلة الفتى، والقلوص3 بمنزلة الجارية. الوجد: الحزن، والفعل وجد يجد. الترجيع: ترديد الصوت.\nالحنين: صوت المتوجع.\nيقول: فما حزنت حزنا مثل حزني ناقة أضلت ولدها فرددت صوتها مع توجعها في طلبها، يريد أن حزن الناقة دون حزنه فراق حبيبته."},{"id":"muallaqat:403","bookId":"muallaqat","type":"section","seq":403,"chapter":"مدخل","title":"20- ولا شمطاء لم يترك شقاها","page":"ج1 ص219","text":"ولا شمطاء لم يترك شقاها ... لها من تسعة إلا جنينا\nالشمط: بياض الشعر. الجنين: المستور في القبر هنا.\nيقول: ولا حزنت كحزني عجوز لم يترك شقاء جدها لها من تسعة بنين إلا مدفونا في قبره، أي ماتوا كلهم ودفنوا، يريد أن حزن العجوز التي فقدت تسعة بنين دون حزنه عند فراق عشيقته."},{"id":"muallaqat:404","bookId":"muallaqat","type":"section","seq":404,"chapter":"مدخل","title":"21- تذكرت الصبا واشتقت لما","page":"ج1 ص219","text":"تذكرت الصبا واشتقت لما ... رأيت حمولها أصلا حدينا\nالحمول: جمع حامل، يريد إبلها.\nيقول: تذكرت العشق والهوى واشتقت إلى العشيقة لما رأيت حمول إبلها سيقت عشيا."},{"id":"muallaqat:405","bookId":"muallaqat","type":"section","seq":405,"chapter":"مدخل","title":"22- فأعرضت اليمامة واشمخرت","page":"ج1 ص219","text":"فأعرضت اليمامة واشمخرت ... كأسياف بأيدي مصلتينا\nأعرضت: ظهرت، وعرضت الشيء أظهرته، ومنه قوله عز وجل: {وعرضنا جهنم يومئذ للكافرين عرضا} [الكهف: 100] وهذا من النوادر، عرضت الشيء فأعرض، ومثله كببته فأكب، ولا ثالث لهما فيما سمعنا. اشمخرت: ارتفعت. أصلت السيف: سللته.\nيقول: فظهرت لنا قرى اليمامة وارتفعت في أعيننا كأسياف بأيدي رجال سالين سيوفهم، شبه ظهور قراها بظهور أسياف مسلولة من أغمادها."},{"id":"muallaqat:406","bookId":"muallaqat","type":"section","seq":406,"chapter":"مدخل","title":"23- أبا هند فلا تعجل علينا","page":"ج1 ص220","text":"أبا هند فلا تعجل علينا ... وأنظرنا نخبرك اليقينا\nيقول: يا أبا هند لا تعجل علينا وانظرنا نخبرك باليقين من أمرنا وشرفنا، يريد عمرو بن هند فكناه."},{"id":"muallaqat:407","bookId":"muallaqat","type":"section","seq":407,"chapter":"مدخل","title":"24- بأنا نورد الرايات بيضا","page":"ج1 ص220","text":"بأنا نورد الرايات بيضا ... ونصدرهن حمرا قد روينا\nالراية: العلم، والجمع الرايات والراي.\nيقول: نخبرك باليقين من أمرنا بأنا نورد أعلامنا الحروب بيضا، ونرجعها منها حمرا قد روين من دماء الأبطال. هذا البيت تفسير اليقين من البيت الأول."},{"id":"muallaqat:408","bookId":"muallaqat","type":"section","seq":408,"chapter":"مدخل","title":"25- وأيام لنا غر طوال","page":"ج1 ص220","text":"وأيام لنا غر طوال ... عصينا الملك فيها أن ندينا\nيقول: نخبرك بوقائع لنا مشاهير كالغر1 من الخيل عصينا الملك فيها كراهية أن نطيعه ونتذلل له. الأيام: الوقائع هنا. الغر بمعنى المشاهير كالخيل الغر لاشتهارها فيما بين الخيل. قوله: أن ندين، أي كراهية أن ندين، فحذف المضاف، هذا على قول البصريين، وقال الكوفيون: تقديره أن لا ندين، أي لئلا ندين، فحذف لا."},{"id":"muallaqat:409","bookId":"muallaqat","type":"section","seq":409,"chapter":"مدخل","title":"26- وسيد معشر قد توجوه","page":"ج1 ص220","text":"وسيد معشر قد توجوه ... بتاج الملك يحمي المحجرينا\nيقول: ورب سيد قوم متوج بتاج الملك حام للملجئين قهرناه. أحجرته: ألجأته."},{"id":"muallaqat:410","bookId":"muallaqat","type":"section","seq":410,"chapter":"مدخل","title":"27- تركنا الخيل عاكفة عليه","page":"ج1 ص220","text":"تركنا الخيل عاكفة عليه ... مقلدة أعنتها صفونا\nالعكوف: الإقامة، والفعل عكف يعكف. الصفون: جمع صافن، وقد صفن الفرس يصفن صفونا إذا قام على ثلاث قوائم وثنى سنبكه الرابع.\nيقول: قتلناه وحبسنا خيلنا عليه وقد قلدناها أعنتها في حال صفونها عنده."},{"id":"muallaqat:411","bookId":"muallaqat","type":"section","seq":411,"chapter":"مدخل","title":"28- وأنزلنا البيوت بذي طلوح","page":"ج1 ص220","text":"وأنزلنا البيوت بذي طلوح ... إلى الشامات ننفي الموعدينا\nيقول: وأنزلنا بيوتنا بمكان يعرف بذي طلوح إلى الشامات ننفي من هذه الأماكن أعداءنا الذين كانوا يوعدوننا."},{"id":"muallaqat:412","bookId":"muallaqat","type":"section","seq":412,"chapter":"مدخل","title":"29- وقد هرت كلاب الحي منا","page":"ج1 ص221","text":"وقد هرت كلاب الحي منا ... وشذبنا قتادة من يلينا\nالقتاد: شجر ذو شوك، والواحدة منها قتادة. التشذيب: نفي الشوك والأغصان الزائدة والليف عن الشجر. يلينا، أي: يقرب منا.\nيقول: وقد لبسنا الأسلحة حتى أنكرتنا الكلاب وهرت1 لإنكارها إيانا، وقد كسرنا شوكة من يقرب منا من أعدائنا، استعار لفل2 الغرب وكسر الشوكة تشذيب القتادة."},{"id":"muallaqat:413","bookId":"muallaqat","type":"section","seq":413,"chapter":"مدخل","title":"30- متى ننقل إلى قوم رحانا","page":"ج1 ص221","text":"متى ننقل إلى قوم رحانا ... يكونوا في اللقاء لها طحينا\nأراد بالرحى: رحى الحرب وهي معظمها.\nيقول: متى حاربنا قوما قتلناهم، لما استعار للحرب اسم الرحى استعار لقتلاها اسم الطحين."},{"id":"muallaqat:414","bookId":"muallaqat","type":"section","seq":414,"chapter":"مدخل","title":"31- يكون ثفالها شرقي نجد","page":"ج1 ص221","text":"يكون ثفالها شرقي نجد ... ولهوتها قضاعة أجمعينا\nالثفال: خرقة أو جلدة تبسط تحت الرحى ليقع عليها الدقيق. اللهوة القبضة من الحب تلقى في فم الرحى، وقد ألهيت الرحى ألقيت فيها لهوة.\nيقول: تكون معركتنا الجانب الشرقي في نجد، وتكون قبضتنا قضاعة أجمعين، فاستعار للمعركة اسم الثفال وللقتلى اسم اللهوة ليشاكل الرحى والطحين."},{"id":"muallaqat:415","bookId":"muallaqat","type":"section","seq":415,"chapter":"مدخل","title":"32- نزلتم منزل الأضياف منا","page":"ج1 ص221","text":"نزلتم منزل الأضياف منا ... فأعجلنا القرى أن تشتمونا\nيقول: نزلتم منزلة الأضياف فجعلنا قراكم كراهية أن تشتمونا ولكي لا تشتمونا، والمعنى: تعرضتم لمعاداتنا كما يتعرض الضيف للقرى فقتلناكم عجالا كما يحمد تعجيل قرى الضيف، ثم قال تهكما بهم واستهزاء: أن تشتمونا، أي قريناكم على عجلة كراهية شتمكم إيانا إن أخرنا قراكم."},{"id":"muallaqat:416","bookId":"muallaqat","type":"section","seq":416,"chapter":"مدخل","title":"33- قريناكم فعجلنا قراكم","page":"ج1 ص222","text":"قريناكم فعجلنا قراكم ... قبيل الصبح مرداة طحونا\nالمرداة: الصخرة التي يكسر بها الصخور، والمرداة أيضا الصخرة التي يرمى بها، والردي الرمي والفعل ردى يردي، فاستعار المرداة للحرب. الطحون: فعول من الطحن. مرداة طحونا أي حربا أهلكتهم أشد إهلاك."},{"id":"muallaqat:417","bookId":"muallaqat","type":"section","seq":417,"chapter":"مدخل","title":"34- نعم أناسنا ونعف عنهم","page":"ج1 ص222","text":"نعم أناسنا ونعف عنهم ... ونحمل عنهم ما حملونا\nيقول: نعم عشائرنا بنوالنا وسيبنا1، ونعف عن أموالهم ونحمل عنهم ما حملونا من أثقال حقوقهم ومؤنتهم، والله أعلم."},{"id":"muallaqat:418","bookId":"muallaqat","type":"section","seq":418,"chapter":"مدخل","title":"35- نطاعن ما تراخى الناس عنا","page":"ج1 ص222","text":"نطاعن ما تراخى الناس عنا ... ونضرب بالسيوف إذا غشينا\nالتراخي: البعد. الغشيان: الإتيان.\nيقول: نطاعن الأبطال ما تباعدوا عنا، أي وقت تباعدهم عنا، ونضربهم بالسيوف إذا أتينا، أي أتونا، فقربوا منا، يريد أن شأننا طعن من لا تناله سيوفنا."},{"id":"muallaqat:419","bookId":"muallaqat","type":"section","seq":419,"chapter":"مدخل","title":"36- بسمر من قنا الخطي لدن","page":"ج1 ص222","text":"بسمر من قنا الخطي لدن ... ذوابل أو ببيض يختلينا\nاللدن: اللين، والجمع لدن.\nيقول: نطاعنهم برماح سمر لينة من رماح الرجل الخطي، يريد سمهرا، أو نضاربهم بسيوف بيض يقطعن ما ضرب بها، توصف الرماح بالسمرة؛ لأن سمرتها دالة على نضجها في منابتها."},{"id":"muallaqat:420","bookId":"muallaqat","type":"section","seq":420,"chapter":"مدخل","title":"37- كأن جماجم الأبطال فيها","page":"ج1 ص222","text":"كأن جماجم الأبطال فيها ... وسوق بالأماعز يرتمينا\nالأبطال: جمع بطل وهو الشجاع الذي يبطل دماء أقرانه. الوسوق: جمع وسق وهو حمل بعير. الأماعز: جمع الأمعز وهو المكان الذي تكثر حجارته.\nيقول: كأن جماجم الشجعان منهم أحمال إبل تسقط في الأماكن الكثيرة الحجارة، شبه رءوسهم في عظمها بأحمال الإبل، والارتماء لازم ومتعد، وهو في البيت لازم."},{"id":"muallaqat:421","bookId":"muallaqat","type":"section","seq":421,"chapter":"مدخل","title":"38- نشق بها رءوس القوم شقا","page":"ج1 ص223","text":"نشق بها رءوس القوم شقا ... ونختلب الرقاب فتختلينا\nالاختلاب: قطع الشيء بالمخلب وهو المنجل الذي لا أسنان له. الاختلاء: قطع الخلا وهو رطب الحشيش.\nيقول: نشق بها رءوس الأعداء شقا ونقطع بها رقابهم فيقطعن."},{"id":"muallaqat:422","bookId":"muallaqat","type":"section","seq":422,"chapter":"مدخل","title":"39- وإن الضغن بعد الضغن يبدو","page":"ج1 ص223","text":"وإن الضغن بعد الضغن يبدو ... عليك ويخرج الداء الدفينا\nيقول: وإن الضغن بعض الضغن تفشو آثاره ويخرج الداء المدفون من الأفئدة أي يبعث على الانتقام."},{"id":"muallaqat:423","bookId":"muallaqat","type":"section","seq":423,"chapter":"مدخل","title":"40- ورثنا المجد قد علمت معد","page":"ج1 ص223","text":"ورثنا المجد قد علمت معد ... نطاعن دونه حتى يبينا\nيقول: ورثنا شرف آبائنا قد علمت ذلك معد، نطاعن الأعداء دون شرفنا حتى يظهر الشرف لنا."},{"id":"muallaqat:424","bookId":"muallaqat","type":"section","seq":424,"chapter":"مدخل","title":"41- ونحن إذا عماد الحي خرت","page":"ج1 ص223","text":"ونحن إذا عماد الحي خرت ... عن الأحفاض نمنع من يلينا\nالحفض: متاع البيت، والجمع أحفاض، والحفض البعير الذي يحمل خرثي1 البيت، والجمع أحفاض. من روى في البيت: على الأحفاض، أراد بها الأمتعة، ومن روى: عن الأحفاض، أراد بها الإبل.\nيقول: ونحن إذا قوضت الخيام فخرت على أمتعتها، نمنع ونحمي من يقرب منا من جيراننا، أو ونحن إذا سقطت الخيام عن الإبل للإسراع في الهرب نمنع ونحمي جيراننا إذا هرب غيرنا حمينا غيرنا."},{"id":"muallaqat:425","bookId":"muallaqat","type":"section","seq":425,"chapter":"مدخل","title":"42- نجذ رءوسهم في غير بر","page":"ج1 ص223","text":"نجذ رءوسهم في غير بر ... فما يدرون ماذا يتقونا\nالجذ: القطع.\nيقول: نقطع رءوسهم في غير بر، أي في عقوق، ولا يدرون ماذا يحذرون منا من القتل وسبي الحرم واستباحة الأموال."},{"id":"muallaqat:426","bookId":"muallaqat","type":"section","seq":426,"chapter":"مدخل","title":"43- كأن سيوفنا منا ومنهم","page":"ج1 ص223","text":"كأن سيوفنا منا ومنهم ... مخاريق بأيدي لاعبينا\nالمخراق1: معروف، والمخراق أيضا سيف من خشب.\nيقول: كنا لا نحفل بالضرب بالسيوف كما لا يحفل اللاعبون بالضرب بالمخاريق، أو كنا نضرب بها في سرعة كما يضرب بالمخاريق في سرعة."},{"id":"muallaqat:427","bookId":"muallaqat","type":"section","seq":427,"chapter":"مدخل","title":"44- كأن ثيابنا منا ومنهم","page":"ج1 ص224","text":"كأن ثيابنا منا ومنهم ... خضبن بأرجوان أو طلينا\nيقول: كأن ثيابنا وثياب أقراننا خضبت بأرجوان أو طليت."},{"id":"muallaqat:428","bookId":"muallaqat","type":"section","seq":428,"chapter":"مدخل","title":"45- إذا ما عي بالإسناف حي","page":"ج1 ص224","text":"إذا ما عي بالإسناف حي ... من الهول المشبه أن يكونا\nالإسناف: الإقدام.\nيقول: إذا عجز عن التقدم قوم مخافة هول منتظر متوقع يشبه أن يكون ويمكن."},{"id":"muallaqat:429","bookId":"muallaqat","type":"section","seq":429,"chapter":"مدخل","title":"46- نصبنا مثل رهوة ذات حد","page":"ج1 ص224","text":"نصبنا مثل رهوة ذات حد ... محافظة وكنا السابقينا\nيقول: نصبنا خيلا مثل هذا الجبل، أو كتيبة ذات شوكة2 محافظة على أحسابنا وسبقنا خصومنا، أي غلبناهم؛ وتحرير المعنى: إذا فزع غيرنا من التقدم أقدمنا مع كتيبة ذات شوكة وغلبنا، وإنما نفعل هذا محافظة على أحسابنا."},{"id":"muallaqat:430","bookId":"muallaqat","type":"section","seq":430,"chapter":"مدخل","title":"47- بشبان يرون القتل مجدا","page":"ج1 ص224","text":"بشبان يرون القتل مجدا ... وشيب في الحروب مجربينا\nيقول: نسبق ونغلب بشبان يعدون القتال في الحروب مجدا، وشيب قد مرنوا على الحروب."},{"id":"muallaqat:431","bookId":"muallaqat","type":"section","seq":431,"chapter":"مدخل","title":"48- حديا الناس كلهم جميعا","page":"ج1 ص224","text":"حديا الناس كلهم جميعا ... مقارعة بنيهم عن بنينا\nحديا: اسم جاء على صيغة التصغير مثل ثريا وحميا3 وهي بمعنى التحدي.\nيقول: نتحدى الناس كلهم بمثل مجدنا وشرفنا، ونقارع أبناءهم ذابين عن أبنائنا، أي نضاربهم بالسيوف حماية للحريم وذبا عن الحوزة."},{"id":"muallaqat:432","bookId":"muallaqat","type":"section","seq":432,"chapter":"مدخل","title":"49- فأما يوم خشيتنا عليهم","page":"ج1 ص224","text":"فأما يوم خشيتنا عليهم ... فتصبح خيلنا عصبا ثبينا\nالعصب: جمع عصبة وهي ما بين العشرة والأربعين. الثبة: الجماعة، والجمع الثبات، والثبون في الرفع والثبين في النصب والجر.\nيقول: فأما يوم نخشى على أبنائنا وحرمنا من الأعداء تصبح خيلنا جماعات، أي تتفرق في كل وجه لذب الأعداء عن الحرم."},{"id":"muallaqat:433","bookId":"muallaqat","type":"section","seq":433,"chapter":"مدخل","title":"50- وأما يوم لا نخشى عليهم","page":"ج1 ص225","text":"وأما يوم لا نخشى عليهم ... فنمعن غارة متلبينا\nالإمعان: الإسراع والمبالغة في الشيء. التلبب: لبس السلاح.\nيقول: وأما يوم لا نخشى على حرمنا من أعدائنا فنمعن في الإغارة على الأعداء لابسين أسلحتنا."},{"id":"muallaqat:434","bookId":"muallaqat","type":"section","seq":434,"chapter":"مدخل","title":"51- برأس من بني جشم بن بكر","page":"ج1 ص225","text":"برأس من بني جشم بن بكر ... ندق به السهولة والحزونا\nالرأس: الرئيس والسيد.\nيقول: نغير عليهم مع سيد من هؤلاء القوم ندق به السهل والحزن، أي نهزم الضعاف والأشداء."},{"id":"muallaqat:435","bookId":"muallaqat","type":"section","seq":435,"chapter":"مدخل","title":"52- ألا لا يعلم الأقوام أنا","page":"ج1 ص225","text":"ألا لا يعلم الأقوام أنا ... تضعضعنا وأنا قد ونينا\nالتضعضع: التكسر والتذلل، ضعضعته فتضعضع أي كسرته فانكسر.\nالونى: الفتور.\nيقول: لا يعلم الأقوام أننا تذللنا وانكسرنا وفترنا في الحرب، أي لسنا بهذه الصفة فتعلمنا الأقوام بها."},{"id":"muallaqat:436","bookId":"muallaqat","type":"section","seq":436,"chapter":"مدخل","title":"53- ألا لا يجهلن أحد علينا","page":"ج1 ص225","text":"ألا لا يجهلن أحد علينا ... فنجهل فوق جهل الجاهلينا\nأي لا يسفهن أحد علينا فنسفه عليهم فوق سفههم، أي نجازيهم بسفههم جزاء يربي عليه، فسمي جزاء الجهل جهلا لازدواج الكلام وحسن تجانس اللفظ، كما قال الله تعالى: {الله يستهزئ بهم} [البقرة: 15] وقال الله تعالى: {وجزاء سيئة سيئة مثلها} [الشورى: 40] وقال جل ذكره: {ومكروا ومكر الله} [آل عمران: 54] . وقال جل وعلا: {يخادعون الله وهو خادعهم} [النساء: 142] . سمي جزاء الاستهزاء والسيئة والمكر والخداع استهزاء وسيئة ومكرا وخداعا لما ذكرنا."},{"id":"muallaqat:437","bookId":"muallaqat","type":"section","seq":437,"chapter":"مدخل","title":"54- بأي مشيئة عمرو بن هند","page":"ج1 ص226","text":"بأي مشيئة عمرو بن هند ... نكون لقيلكم فيها قطينا\nالقطين: الخدم. القيل: الملك دون الملك الأعظم.\nيقول: كيف تشاء يا عمرو بن هند أن نكون خدما لمن وليتموه أمرنا من الملوك الذين وليتموهم؟ أي: أي شيء دعاك إلى هذه المشيئة المحالة؟ يريد أنه لم يظهر منهم ضعف يطمع الملك في إذلالهم باستخدام قيله إياهم."},{"id":"muallaqat:438","bookId":"muallaqat","type":"section","seq":438,"chapter":"مدخل","title":"55- بأي مشيئة عمرو بن هند","page":"ج1 ص226","text":"بأي مشيئة عمرو بن هند ... تطيع بنا الوشاة وتزدرينا\nازدراه وازدرى به: قصر به واحتقره.\nيقول: كيف تشاء أن تطيع الوشاة بنا إليك وتحتقرنا وتقصر بنا؟ أي: أي شيء دعاك إلى هذه المشيئة؟ أي لم يظهر منا ضعف يطمع الملك فينا حتى يصغي إلى من يشي بنا إليه ويغريه بنا فيحتقرنا."},{"id":"muallaqat:439","bookId":"muallaqat","type":"section","seq":439,"chapter":"مدخل","title":"56- تهددنا وأوعدنا رويدا","page":"ج1 ص226","text":"تهددنا وأوعدنا رويدا ... متى كنا لأمك مقتوينا\nالقتو: خدمة الملوك، والفعل قتا يقتو، والمقتى مصدر كالقتو، تنسب إليه فتقول: مقتوي، ثم يجمع مع طرح ياء النسبة فيقال مقتوون في الرفع، ومقتوين في الجر والنصب، كما يجمع الأعجمي بطرح ياء النسبة فيقال أعجمون في الرفع، وأعجمين في النصب والجر.\nيقول: ترفق في تهددنا وإيعادنا ولا تمعن فيهما، فمتى كنا خدما لأمك؟ أي: لم نكن خدما لها حتى نعبأ بتهديدك ووعديك إيانا، ومن روى: تهددنا وتوعدنا، كان إخبارا، ثم قال: رويدا أي دع الوعيد والتهديد وأمهله."},{"id":"muallaqat:440","bookId":"muallaqat","type":"section","seq":440,"chapter":"مدخل","title":"57- فإن قناتنا يا عمرو أعيت","page":"ج1 ص226","text":"فإن قناتنا يا عمرو أعيت ... على الأعداء قبلك أن تلينا\nالعرب تستعير للعز اسم القناة.\nيقول: فإن قناتنا أبت أن تلين لأعدائنا قبلك، يريد أن عزهم أبى أن يزول بمحاربة أعدائهم ومخاصمتهم ومكايدتهم، يريد أن عزهم منيع لا يرام."},{"id":"muallaqat:441","bookId":"muallaqat","type":"section","seq":441,"chapter":"مدخل","title":"58- إذا عض الثقاف بها اشمأزت","page":"ج1 ص226","text":"إذا عض الثقاف بها اشمأزت ... وولته عشوزنة زبونا\nالثقاف: الحديدة التي يقوم بها الرمح، وقد ثقفته: قومته. العشوزنة: الصلبة الشديدة. الزبون: الدفوع، وأصله من قولهم: زبنت الناقة حالبها، إذا ضربته بثفنات رجليها أي بركبتيها ومنه الزبانية لزبنهم أهل النار، أي لدفعهم.\nيقول: إذا أخذها الثقاف لتقويمها نفرت من التقويم، وولت الثقاف قناة صلبة شديدة دفوعا، جعل القناة التي لا يتهيأ تقويمها مثلا لعزتهم التي لا تضعضع، وجعل قهرها من تعرض لهدمها كنفار القناة من التقويم والاعتدال."},{"id":"muallaqat:442","bookId":"muallaqat","type":"section","seq":442,"chapter":"مدخل","title":"59- عشوزنة إذا انقلبت أرنت","page":"ج1 ص227","text":"عشوزنة إذا انقلبت أرنت ... تشج قفا المثقف والجبينا\nأرنت: صوتت، والإرنان، هنا لازم وقد يكون متعديا ثم بالغ في وصف القناة بأنها تصوت إذا أريد تثقيفها، ولم تطاوع الغامز بل تشج قفاه وجبينه، كذلك عزتهم لا تضعضع لمن رامها بل تهلكه وتقهره."},{"id":"muallaqat:443","bookId":"muallaqat","type":"section","seq":443,"chapter":"مدخل","title":"60- فهل حدثت في جشم بن بكر","page":"ج1 ص227","text":"فهل حدثت في جشم بن بكر ... بنقص في خطوب الأولينا\nيقول: هل أخبرت بنقص كان من هؤلاء في أمور القرون الماضية أو بنقض عهد سلف."},{"id":"muallaqat:444","bookId":"muallaqat","type":"section","seq":444,"chapter":"مدخل","title":"61- ورثنا مجد علقمة بن سيف","page":"ج1 ص227","text":"ورثنا مجد علقمة بن سيف ... أباح لنا حصون المجد دينا\nالدين: القهر، ومنه قوله عز وجل: {فلولا إن كنتم غير مدينين} [الواقعة: 86] أي غير مقهورين.\nيقول: ورثنا مجد هذا الرجل الشريف من أسلافنا، وقد جعل لنا حصون المجد مباحة قهرا وعنوة، أي غلب أقرانه على المجد ثم أورثنا مجده ذلك."},{"id":"muallaqat:445","bookId":"muallaqat","type":"section","seq":445,"chapter":"مدخل","title":"62- ورثت مهلهلا والخير منه","page":"ج1 ص227","text":"ورثت مهلهلا والخير منه ... زهيرا نعم ذخر الذاخرينا\nيقول: ورثت مجد مهلهل، ومجد الرجل الذي هو خير منه وهو زهير فنعم ذخر الذاخرين هو، أي مجده وشرفه للافتخار به."},{"id":"muallaqat:446","bookId":"muallaqat","type":"section","seq":446,"chapter":"مدخل","title":"63- وعتابا وكلثوما جميعا","page":"ج1 ص227","text":"وعتابا وكلثوما جميعا ... بهم نلنا تراث الأكرمينا\nيقول: ورثنا مجد عتاب وكلثوم وبهم بلغنا ميراث الأكارم أي حزنا مآثرهم ومفاخرهم فشرفنا بها وكرمنا."},{"id":"muallaqat:447","bookId":"muallaqat","type":"section","seq":447,"chapter":"مدخل","title":"64- وذا البرة الذي حدثت عنه","page":"ج1 ص228","text":"وذا البرة الذي حدثت عنه ... به نحمى ونحمي المحجرينا\nذو البرة: من بني تغلب، سمي به لشعر على أنفه يستدير كالحلقة.\nيقول: وورثت مجد ذي البرة الذي اشتهر وعرف وحدثت عنه أيها المخاطب وبمجده يحمينا سيدنا وبه نحمي الفقراء الملجئين إلى الاستجارة بغيرهم."},{"id":"muallaqat:448","bookId":"muallaqat","type":"section","seq":448,"chapter":"مدخل","title":"65- ومنا قبله الساعي كليب","page":"ج1 ص228","text":"ومنا قبله الساعي كليب ... فأي المجد إلا قد ولينا\nيقول: ومنا قبل ذي البرة الساعي للمعالي كليب، يعني كليب وائل، ثم قال: وأي المجد إلا وقد ولينا، أي قربنا منه فحوينا."},{"id":"muallaqat:449","bookId":"muallaqat","type":"section","seq":449,"chapter":"مدخل","title":"66- متى نعقد قرينتنا بحبل","page":"ج1 ص228","text":"متى نعقد قرينتنا بحبل ... تجذ الحبل أو تقص القرينا\nيقول: متى قرنا ناقتنا بأخرى قطعت الحبل أو كسرت عنق القرين، والمعنى: متى قرنا بقوم في قتال أو جدال غلبناهم وقهرناهم. الجذ: القطع والفعل جذ يجذ. الوقص: دق العنق، والفعل وقص يقص."},{"id":"muallaqat:450","bookId":"muallaqat","type":"section","seq":450,"chapter":"مدخل","title":"67- ونوجد نحن أمنعهم ذمارا","page":"ج1 ص228","text":"ونوجد نحن أمنعهم ذمارا ... وأوفاهم إذا عقدوا يمينا\nيقول: تجدنا أيها المخاطب أمنعهم ذمة وجوارا وحلفا وأوفاهم باليمين عند عقدها. الذمار: العهد والحلف والذمة، سمي به لأنه يتذمر له أي يتغضب لمراعاته."},{"id":"muallaqat:451","bookId":"muallaqat","type":"section","seq":451,"chapter":"مدخل","title":"68- ونحن غداة أوقد في خزازى","page":"ج1 ص228","text":"ونحن غداة أوقد في خزازى ... رفدنا فوق رفد الرافدينا\nالرفد: الإعانة، والرفد الاسم.\nيقول: ونحن غداة أوقدت نار الحرب في خزازى أعنا نزارا فوق إعانة المعينين، يفتخر بإعانة قومه بني نزار في محاربتهم اليمن."},{"id":"muallaqat:452","bookId":"muallaqat","type":"section","seq":452,"chapter":"مدخل","title":"69- ونحن الحابسون بذي أراطى","page":"ج1 ص228","text":"ونحن الحابسون بذي أراطى ... تسف الجلة الخور الدرينا\nتسف: أي تأكل يابسا، والمصدر السفوف. الجلة: الكبار من الإبل، الخور: الكثيرة الألبان، وقيل: الخور الغزار من الإبل والناقة خوراء. الدرين: ما اسود من النبت وقدم.\nيقول: ونحن حبسنا أموالنا بهذا الموضع حتى سفت النوق الغزار قديم النبت وأسوده لإعانة قومنا ومساعدتهم على قتال أعدائهم."},{"id":"muallaqat:453","bookId":"muallaqat","type":"section","seq":453,"chapter":"مدخل","title":"70- ونحن الحاكمون إذا أطعنا","page":"ج1 ص229","text":"ونحن الحاكمون إذا أطعنا ... ونحن العازمون إذا عصينا"},{"id":"muallaqat:454","bookId":"muallaqat","type":"section","seq":454,"chapter":"مدخل","title":"71- ونحن التاركون لما سخطنا","page":"ج1 ص229","text":"ونحن التاركون لما سخطنا ... ونحن الآخذون لما رضينا"},{"id":"muallaqat:455","bookId":"muallaqat","type":"section","seq":455,"chapter":"مدخل","title":"72- وكنا الأيمنين إذا التقينا","page":"ج1 ص229","text":"وكنا الأيمنين إذا التقينا ... وكان الأيسرين بنو أبينا\nيقول: كنا حماة الميمنة إذا لقينا الأعداء وكان إخواننا حماة الميسرة، يصف غناءهم في حرب نزار واليمن عندما قتل كليب وائل لبيد بن عنق الغساني عامل ملك غسان على تغلب حين لطم أخت كليب وكانت تحته."},{"id":"muallaqat:456","bookId":"muallaqat","type":"section","seq":456,"chapter":"مدخل","title":"73- فصالوا صولة فيمن يليهم","page":"ج1 ص229","text":"فصالوا صولة فيمن يليهم ... وصلنا صولة فيمن يلينا\nيقول: فحمل بنو بكر على من يليهم من الأعداء، وحملنا على من يلينا."},{"id":"muallaqat:457","bookId":"muallaqat","type":"section","seq":457,"chapter":"مدخل","title":"74- فآبوا بالنهاب وبالسبايا","page":"ج1 ص229","text":"فآبوا بالنهاب وبالسبايا ... وأبنا بالملوك مصفدينا\nالنهاب: الغنائم، الواحد نهب. الأوب: الرجوع، التصفيد: التقييد، يقال: صفدته وصفدته أي قيدته وأوثقته.\nيقول: فرجع بنو بكر بالغنائم والسبايا ورجعنا مع الملوك مقيدين، أي اغتنموا الأموال وأسرنا الملوك."},{"id":"muallaqat:458","bookId":"muallaqat","type":"section","seq":458,"chapter":"مدخل","title":"75- إليكم يا بني بكر إليكم","page":"ج1 ص229","text":"إليكم يا بني بكر إليكم ... ألما تعرفوا منا اليقينا\nيقول: تنحوا وتباعدوا مساماتنا ومباراتنا يا بني بكر، ألم تعلموا من نجدتنا وبأسنا اليقين؟ أي قد علمتم ذلك لنا فلا تتعرضوا لنا، يقال: إليك إليك، أي تنح."},{"id":"muallaqat:459","bookId":"muallaqat","type":"section","seq":459,"chapter":"مدخل","title":"76- ألما تعلموا منا ومنكم","page":"ج1 ص229","text":"ألما تعلموا منا ومنكم ... كتائب يطعن ويرتمينا\nيقول: ألم تعلموا كتائب منا ومنكم يطعن بعضهم بعضا، ويرمي بعضهم بعضا؟ وما في قول: ألما صلة زائدة. الاطعان والارتماء: مثل التطاعن والترامي."},{"id":"muallaqat:460","bookId":"muallaqat","type":"section","seq":460,"chapter":"مدخل","title":"77- علينا البيض واليلب اليماني","page":"ج1 ص229","text":"علينا البيض واليلب اليماني ... وأسياف يقمن وينحنينا\nاليلب: نسيجة من سيور1 تلبس تحت البيض2.\nيقول: وكان علينا البيض واليلب اليماني وأسياف يقمن وينحنين لطول الضراب بها."},{"id":"muallaqat:461","bookId":"muallaqat","type":"section","seq":461,"chapter":"مدخل","title":"78- علينا كل سابغة دلاص","page":"ج1 ص230","text":"علينا كل سابغة دلاص ... ترى فوق النطاق لها غضونا\nالسابغة: الدرع الواسعة التامة. الدلاص: البراقة. الغضون: جمع غضن وهو التشنج في الشيء.\nيقول: وكانت علينا كل درع واسعة براقة ترى أيها المخاطب فوق المنطقة لها غضونا لسعتها وسبوغها."},{"id":"muallaqat:462","bookId":"muallaqat","type":"section","seq":462,"chapter":"مدخل","title":"79- إذا وضعت عن الأبطال يوما","page":"ج1 ص230","text":"إذا وضعت عن الأبطال يوما ... رأيت لها جلود القوم جونا\nالجون: الأسود والجون الأبيض، والجمع الجون.\nيقول: إذا خلعها الأبطال يوما رأيت جلودهم سودا للبسهم إياها. قوله: لها، أي للبسها."},{"id":"muallaqat:463","bookId":"muallaqat","type":"section","seq":463,"chapter":"مدخل","title":"80- كأن غضونهن متون غدر","page":"ج1 ص230","text":"كأن غضونهن متون غدر ... تصفقها الرياح إذا جرينا\nالغدر: مخفف غدر وهو جمع غدير. تصفقه: تضربه، شبه غضون الدرع بمتون الغدران إذا ضربتها الرياح في جريها، والطرائق التي ترى في الدروع بالتي تراها في الماء إذا ضربته الريح."},{"id":"muallaqat:464","bookId":"muallaqat","type":"section","seq":464,"chapter":"مدخل","title":"81- وتحملنا غداة الروع جرد","page":"ج1 ص230","text":"وتحملنا غداة الروع جرد ... عرفن لنا نقائذ وافتلينا\nالروع: الفزع ويريد به الحرب هنا. الجرد: التي رق شعر جسدها وقصر، والواحد أجرد والواحدة جرداء. النقائذ: المخلصات من أيدي الأعداء، واحدتها نقيذة وهي فعيلة بمعنى مفعلة، يقال: أنقذتها، أي: خلصتها، فهي منقذة ونقيذة. الفلو والافتلاء: الفطام.\nيقول: وتحملنا في الحرب خيل رقاق الشعور قصارها، عرفن لنا وفطمت عندنا وخلصناها من أيدي أعدائنا بعد استيلائهم عليها."},{"id":"muallaqat:465","bookId":"muallaqat","type":"section","seq":465,"chapter":"مدخل","title":"82- وردن دوارعا وخرجن شعثا","page":"ج1 ص230","text":"وردن دوارعا وخرجن شعثا ... كأمثال الرصائع قد بلينا\nرجل دارع: عليه درع، ودروع الخيل تجافيفها1. الرصائع: جمع الرصيعة وهي عقدة العنان على قذال2 الفرس.\nيقول: وردت خيلنا وعليها تجافيفها، وخرجن منها شعثا قد بلين بلى عقد الأعنة لما نالها من الكلال والمشاق فيها."},{"id":"muallaqat:466","bookId":"muallaqat","type":"section","seq":466,"chapter":"مدخل","title":"83- ورثناهن عن آباء صدق","page":"ج1 ص231","text":"ورثناهن عن آباء صدق ... ونورثها إذا متنا بنينا\nيقول: ورثنا خيلنا من آباء كرام شأنهم الصدق في الفعال والمقال ونورثها أبناءنا إذا متنا، يريد أنها تناتجت وتناسلت عندهم قديما."},{"id":"muallaqat:467","bookId":"muallaqat","type":"section","seq":467,"chapter":"مدخل","title":"84- على آثارنا بيض حسان","page":"ج1 ص231","text":"على آثارنا بيض حسان ... نحاذر أن تقسم أو تهونا\nيقول: على آثارنا في الحروب نساء بيض حسان نحاذر عليها أن يسبيها الأعداء فتقسمها وتهينها، كانت العرب تشهد نساءها الحروب وتقيمها خلف الرجال ليقاتل الرجال ذبا عن حرمها فلا تفشل مخافة العار بسبي الحرم."},{"id":"muallaqat:468","bookId":"muallaqat","type":"section","seq":468,"chapter":"مدخل","title":"85- أخذن على بعولتهن عهدا","page":"ج1 ص231","text":"أخذن على بعولتهن عهدا ... إذا لاقوا كتائب معلمينا\nيقول: قد عاهدن أزواجهن إذا قاتلوا كتائب من الأعداء قد أعلموا أنفسهم بعلامات يعرفون بها في الحروب أن يثبتوا في حومة القتال ولا يفروا، والبعول والبعولة جمع بعل، يقال للرجل: هو بعل المرأة، وللمرأة هي بعله وبعلته، كما يقال: هو زوجها وهي زوجه وزوجته."},{"id":"muallaqat:469","bookId":"muallaqat","type":"section","seq":469,"chapter":"مدخل","title":"86- ليستلبن أفراسا وبيضا","page":"ج1 ص231","text":"ليستلبن أفراسا وبيضا ... وأسرى في الحديد مقرنينا\nأي ليستلب خلينا أفراس الأعداء وبيضهم وأسرى منهم قد قرنوا في الحديد."},{"id":"muallaqat:470","bookId":"muallaqat","type":"section","seq":470,"chapter":"مدخل","title":"87- ترانا بارزين وكل حي","page":"ج1 ص231","text":"ترانا بارزين وكل حي ... قد اتخذوا مخافتنا قرينا\nيقول: ترانا خارجين إلى الأرض البراز، وهي الصحراء التي لا جبل بها، لثقتنا بنجدتنا وشوكتنا، وكل قبيلة تستجير وتعتصم بغيرها مخافة سطوتنا بها."},{"id":"muallaqat:471","bookId":"muallaqat","type":"section","seq":471,"chapter":"مدخل","title":"88- إذا ما رحن يمشين الهوينى","page":"ج1 ص232","text":"إذا ما رحن يمشين الهوينى ... كما اضطربت متون الشاربينا\nالهوينى: تصغير الهونى وهي تأنيث الأهون، مثل الأكبر والكبرى.\nيقول: إذا مشين يمشين مشيا رفيقا لثقل أردافهن وكثرة لحومهن، ثم شبههن في تبخترهن بالسكارى في مشيهم."},{"id":"muallaqat:472","bookId":"muallaqat","type":"section","seq":472,"chapter":"مدخل","title":"89- يقتن جيادنا ويقلن لستم","page":"ج1 ص232","text":"يقتن جيادنا ويقلن لستم ... بعولتنا إذا لم تمنعونا\nالقوت: الإطعام بقدر الحاجة، والفعل قات يقوت، والاسم القوت والقيت، والجمع الأقوات.\nيقول: يعلفن خيلنا الجياد ويقلن: لستم أزواجنا إذا لم تمنعونا من سبي الأعداء إيانا."},{"id":"muallaqat:473","bookId":"muallaqat","type":"section","seq":473,"chapter":"مدخل","title":"90- ظعائن من بني جشم بن بكر","page":"ج1 ص232","text":"ظعائن من بني جشم بن بكر ... خلطن بميسم حسبا ودينا\nالميسم: الحسن وهو من الوسام والوسامة وهما الحسن والجمال، والفعل وسم يوسم، والنعت وسيم. الحسب: ما يحسب من مكارم الإنسان ومكارم أسلافه، فهو فعل في معنى مفعول مثل النفض1 والخبط2 والقبض 3 واللقط4 في معنى المنفوض والمخبوط والمقبوض والملقوط، فالحسب إذن في معنى المحسوب من مكارم آبائه.\nيقول: هن نساء من هذه القبيلة جمعن إلى الجمال الكرم والدين."},{"id":"muallaqat:474","bookId":"muallaqat","type":"section","seq":474,"chapter":"مدخل","title":"91- وما منع الظعائن مثل ضرب","page":"ج1 ص232","text":"وما منع الظعائن مثل ضرب ... ترى منه السواعد كالقلينا\nيقول: ما منع النساء من سبي الأعداء إياهن مثل ضرب تندر وتطير منه سواعد المضروبين كما تطير القلة إذا ضربت بالمقلى."},{"id":"muallaqat:475","bookId":"muallaqat","type":"section","seq":475,"chapter":"مدخل","title":"92- كأنا والسيوف مسللات","page":"ج1 ص232","text":"كأنا والسيوف مسللات ... ولدنا الناس طرا أجمعينا\nيقول: كأن حال استلال السيوف من أغمادها، أي حال الحرب، ولدنا جميع الناس، أي نحميهم حماية الوالد ولده."},{"id":"muallaqat:476","bookId":"muallaqat","type":"section","seq":476,"chapter":"مدخل","title":"93- يدهدون الرءوس كما تدهدي","page":"ج1 ص233","text":"يدهدون الرءوس كما تدهدي ... حزاورة بأبطحها الكرينا\nالحزور: الغلام الغليظ الشديد، والجمع الحزاورة.\nيقول: يدحرجون رءوس أقرانهم كما يدحرج الغلمان الغلاظ الشداد الكرات في مكان مطمئن من الأرض."},{"id":"muallaqat:477","bookId":"muallaqat","type":"section","seq":477,"chapter":"مدخل","title":"94- وقد علم القبائل من معد","page":"ج1 ص233","text":"وقد علم القبائل من معد ... إذا قبب بأبطحها بنينا\nيقول: وقد علمت قبائل معد إذا بنيت قبابها بمكان أبطح. القبب والقباب جمعا قبة."},{"id":"muallaqat:478","bookId":"muallaqat","type":"section","seq":478,"chapter":"مدخل","title":"95- بأنا المطمعون إذا قدرنا","page":"ج1 ص233","text":"بأنا المطمعون إذا قدرنا ... وأنا المهلكون إذا ابتلينا\nيقول: قد علمت هذه القبائل أنا نطعم الضيفان إذا قدرنا عليه، ونهلك أعداءنا إذا اختبروا قتالنا."},{"id":"muallaqat:479","bookId":"muallaqat","type":"section","seq":479,"chapter":"مدخل","title":"96- وأنا المانعون لما أردنا","page":"ج1 ص233","text":"وأنا المانعون لما أردنا ... وأنا النازلون بحيث شينا\nيقول: وأنا نمنع الناس ما أردنا منعه إياهم، وننزل حيث شئنا من بلاد العرب."},{"id":"muallaqat:480","bookId":"muallaqat","type":"section","seq":480,"chapter":"مدخل","title":"97- وأنا التاركون إذا سخطنا","page":"ج1 ص233","text":"وأنا التاركون إذا سخطنا ... وأنا الآخذون إذا رضينا\nيقول: وأنا نترك ما نسخط ونأخذ إذا رضينا، أي لا نقبل عطايا من سخطنا عليه ونقبل هدايا من رضينا عليه."},{"id":"muallaqat:481","bookId":"muallaqat","type":"section","seq":481,"chapter":"مدخل","title":"98- وأنا العاصمون إذا أطعنا","page":"ج1 ص233","text":"وأنا العاصمون إذا أطعنا ... وأنا العازمون إذا عصينا\nيقول: وأنا نعصم ونمنع جيراننا إذا أطاعونا ونعزم عليهم بالعدوان إذا عصونا."},{"id":"muallaqat:482","bookId":"muallaqat","type":"section","seq":482,"chapter":"مدخل","title":"99- ونشرب إن وردنا الماء صفوا","page":"ج1 ص233","text":"ونشرب إن وردنا الماء صفوا ... ويشرب غيرنا كدرا وطينا\nيقول: ونأخذ من كل شيء أفضله وندع لغيرنا أرذله، يريد لهم السادة والقادة وغيرهم أتباع لهم."},{"id":"muallaqat:483","bookId":"muallaqat","type":"section","seq":483,"chapter":"مدخل","title":"100- ألا أبلغ بني الطماح عنا","page":"ج1 ص233","text":"ألا أبلغ بني الطماح عنا ... ودعميا فكيف وجدتمونا\nيقول: سل هؤلاء كيف وجدونا؟ شجعانا أم جبناء؟"},{"id":"muallaqat:484","bookId":"muallaqat","type":"section","seq":484,"chapter":"مدخل","title":"101- إذا ما الملك سام الناس خسفا","page":"ج1 ص234","text":"إذا ما الملك سام الناس خسفا ... أبينا أن نقر الذل فينا\nالخسف: والخسف: بفتح الخاء وضمها: الذل. السوم: أن تجشم إنسانا مشقة وشرا، يقال: سامه خسفا، أي حمله وكلفه ما فيه ذل.\nيقول: إذا أكره الملك الناس على ما فيه ذلهم أبينا الانقياد له."},{"id":"muallaqat:485","bookId":"muallaqat","type":"section","seq":485,"chapter":"مدخل","title":"102- ملأنا البر حتى ضاق عنا","page":"ج1 ص234","text":"ملأنا البر حتى ضاق عنا ... وماء البحر نملؤه سفينا\nيقول: عممنا الدنيا برا وبحرا فضاق البر عن بيوتنا والبحر عن سفننا."},{"id":"muallaqat:486","bookId":"muallaqat","type":"section","seq":486,"chapter":"مدخل","title":"103- إذا بلغ الفطام لنا صبي","page":"ج1 ص234","text":"إذا بلغ الفطام لنا صبي ... تخر له الجبابر ساجدينا\nيقول: إذا بلغ صبياننا وقت الفطام سجدت لهم الجبابرة من غيرنا."},{"id":"muallaqat:487","bookId":"muallaqat","type":"section","seq":487,"chapter":"مدخل","title":"مدخل","page":"ج1 ص235","text":"...\nعنترة بن شداد\nهو: عنترة بن شداد بن عمرو بن معاوية بن قراد العبسي، من أهل نجد وينتهي نسبه إلى مضر.\nويلقب عنترة: بالفلحاء، فيقال: عنترة الفلحاء.\nوكانت أمه أمة حبشية يقال لها: زبيبة، وكان لها أولاد عبيد من غير شداد، وكانوا أخوة عنترة لأمه.\nوكان أبوه قد نفاه، وكان العرب في الجاهلية إذا كان لأحدهم ولد من أمه استعبده، ثم ادعاه بعد الكبر واعترف به وألحقه بنسبه.\nوكان سبب ادعاء أبيه إياه أن بعض أحياء العرب أغاروا على بني عبس فأصابوا منه واستاقوا إبلا فتبعهم العبسيون فلحقوهم فقاتلوهم عما معهم، وعنترة يومئذ فيهم، فقال له أبوه: \"كر يا عنترة\" فقال عنترة: \"العبد لا يحسن الكر، إنما يحسن الحلاب والصر\" فقال: \"كر وأنت حر\". فكر، وقاتل يومئذ قتالا حسنا فادعاه أبوه بعد ذلك وألحقه بنسبه.\nهو من الشعراء الفرسان، وكان شاعر بني عبس وفارسهم المشهور، وكان جرئيا شديد البطش. وكان مع شدة بطشه لين الطباع حليما، سهل الأخلاق، لطيف الحاضرة. وكان من أشد أهل زمانه وأجودهم بما ملكت يداه. وكان سمحا أبي النفس لا يقر على ضيم ولا يغمض على قذى، ولما أنشد للنبي -صلى الله عليه وسلم- قوله: [الكامل] :\nولقد أبيت على الطوى وأظله ... حتى أنال به كريم المأكل\nقال عليه الصلاة والسلام: \"ما وصف لي أعرابي قط فأحببت أن أراه إلا عنترة\".\nوكان قد حضر حرب داحس والغبراء، وحسن فيها بلاؤه وحمدت مشاهده.\nووقائعه كثيرة يشتبه فيها الصحيح بالموضوع.\nأغار عنترة على بني نبهان من طيئ، فأطرد لهم طريدة وهو شيخ كبير، فجعل يرتجز وهو يطردها. وكان \"وزر بن جابر النبهاني\" في فتوة فرماه وقال: خذها وأنا ابن سلمى فقطع مطاه. فتحامل بالرمية حتى أتى أهله.\nوكان الذي قتله يلقب بالأسد الرهيص.\nكان عنترة شاعرا مجيدا فصيح الألفاظ، بين المعاني نبيلها. كان كأنما الحماسة أنزلت عليه آياتها. وكان رقيق الشعر. لا يؤخذ مأخذ الجاهلية في ضخامة الألفاظ وخشونة المعاني. وكان يهوى ابنة عمه \"عبلة بنت مالك بن قراد\" فهاجت شاعريته لذلك، وكان كثيرا ما يذكرها في شعره، وكان أبوها يمنعه من زواجه بها، فهام بها حتى اشتد وجده، وقيل: إنه قد تزوجها بعد جهد وعناء.\nمعلقته هي الشعر الثابت له بلا اختلاف. أما غيرها فمنها ما هو ثابت له، ومنها ما هو مختلف فيه، ومنها ما ليس له قطعا. كأكثر ما في ديوانه المشهور.\nوسبب نظمها ما حكوا من أنه جلس يوما في مجلس بعدما كان قد أبلى وحسنت وقائعه واعترف به أبوه وأعتقه فسابه رجل من بني عبس، وعاب عليه سواد أمه وإخوته وأنه لا يقول الشعر. فسبه عنترة وفخر عليه. وقد استهل معلقته بالغرام وشكوى البعد وغير ذلك من أنواع النسيب. ثم تخلص إلى الفخر والحماسة وذكر وقائعه ومشاهده."},{"id":"muallaqat:488","bookId":"muallaqat","type":"section","seq":488,"chapter":"مدخل","title":"1- نسبه","page":"ج1 ص238","text":"في نسب عنترة روايات متعددة أبرزها:\n- عنترة بن شداد بن معاوية بن ذهل بن قراد بن مخزوم بن ربيعة بن مالك بن غالب بن قطيعة بن عبس.\n- عنترة بن شداد بن معاوية بن قراد أحد بني مخزوم بن عوذ بن غالب.\n- عنترة بن عمرو بن شداد بن قراد بن مخزوم بن عوف بن مالك بن غالب بن قطيعة بن عبس بن بغيض.\nوغيرها من الروايات المتضاربة التي تبقي نسب عنترة مضطربا ذلك أنه نشأ عبدا مغمورا ولم يعترف به أبوه إلا متأخرا."},{"id":"muallaqat:489","bookId":"muallaqat","type":"section","seq":489,"chapter":"مدخل","title":"2- مولده","page":"ج1 ص239","text":"من السائد لدى المؤرخين أن حرب داحس والغبراء قد انتهت قبل الإسلام بقليل أي قرابة سنة 600 للميلاد، وكانت هذه الحرب قد استغرقت أربعين سنة، لذلك نستطيع أن نجعل ولادة عنترة بحدود سنة 530 لأنه شهد بدء هذه الحرب واشترك فيها حتى نهايتها. وقد اعتمدنا هذه الفرضية لأنها تنسجم مع نصوص عديدة وردت عن اجتماع عنترة بعمرو بن معد يكرب ومعاصرته لعروة بن الورد وغيره من شعراء تلك الفترة."},{"id":"muallaqat:490","bookId":"muallaqat","type":"section","seq":490,"chapter":"مدخل","title":"3- نشأته","page":"ج1 ص239","text":"يروى أن أباه قد وقع على أمة حبشية يقال لها زبيبة فأولدها عنترة، وكانت\nالعرب في الجاهلية إذا كان للرجل منهم ولد من أمة استعبده، وقد ظلت عبودية عنترة هذه فترة من الزمن؛ لأن أباه حرره بعد الكبر. ولهذه الحرية قصة يذكرها الباحثون مفادها أن أمه الحبشية أتت به إلى والده فقال لأولاده: \"إن هذا الغلام ولدي\"، قالوا: كذبت أنت شيخ وقد خرفت تدعي أولاد الناس. فلما شب قالوا له: اذهب فارع الإبل والغنم. فانطلق يرعى وباع منها واشترى سيفا ورمحا وترسا ودرعا ودفنها في الرمل. ولئن كان هذا الخبر أقرب إلى الأسطورة منه إلى الواقع فإنه يؤكد حرص عنترة على تعلم الفروسية وفنون القتال منذ صغره، وهو الذي كان يشعر، بدافع من لونه، أن أفعاله وبطولته وشجاعته أمور لا ترتبط بالنشأة قدر ارتباطها بالنفس وسموها."},{"id":"muallaqat:491","bookId":"muallaqat","type":"section","seq":491,"chapter":"مدخل","title":"4- حريته","page":"ج1 ص240","text":"تعددت الروايات التي أوردت خبر حصول عنترة على حريته، وأبرز ما فيها أن بعض أحياء العرب أغاروا على قوم من بني عبس فأصابوا منهم. فتبعهم العبسيون فلحقوهم فقاتلوهم عما معهم وعنترة فيهم، فقال له أبوه: كر يا عنترة. فقال عنترة: العبد لا يحسن الكر، إنما يحس الحلاب والصر، فقال له: كر وأنت حر. فادعاه أبوه بعد ذلك وألحق به نسبه. والثابت أن عنترة لم ينل حريته إلا بشق النفس وبذل الجهد والتضحيات."},{"id":"muallaqat:492","bookId":"muallaqat","type":"section","seq":492,"chapter":"مدخل","title":"5- فروسيته","page":"ج1 ص240","text":"كانت حروب داحس والغبراء الميدان الفسيح الذي ظهرت فيه فروسية عنترة وشجاعته, وأخبار هذه الحرب تقترن مع كثير من المواقع والأيام، ومنها يوم \"الفروق\" حيث اصطدمت عبس بتميم ودارت رحى الحرب بينهما فأقدم عنترة في هذه المعركة وقتل معاوية بن نزال وافتخر بقومه حين قال: \"كنا مائة لم نكثر فنتكل ولم نقل فنذل\". ومنها أيضا معركة \"ذات الجراجر\" بين ذبيان وحليفاتها من جهة وبين بني عبس من جهة أخرى ودام القتال يومين، وقد أظهر عنترة في هذه الحرب شجاعة لا توصف، ثم أرادت عبس النزول على بني سليم فوقعت معركة ضارية انهزم فيها بنو عبس، وفروا ولكن عنترة ظل واقفا دون النساء يدافع عنهن حتى عادت الخيل واحتدمت المعركة من جديد وكان الفوز لبني عبس. والأخبار عن فروسية عنترة وشجاعته كثيرة نكتفي منها\nبهذا الخبر البارز حين قيل لعنترة: أنت أشجع الناس وأشدها قال: لا، قيل: فبم إذن شاع لك هذا في الناس؟ قال: \"كنت أقدم إذا رأيت الإقدام عزما وأحجم إذا رأيت الإحجام حزما ولا أدخل موضعا لا أرى لي منه مخرجا، وكنت أعتمد الضعيف الجبان فأضربه الضربة الهائلة يطير لها قلب الشجاع فأثني عليه فأقتله\"."},{"id":"muallaqat:493","bookId":"muallaqat","type":"section","seq":493,"chapter":"مدخل","title":"6- زواجه","page":"ج1 ص241","text":"الحديث عن زواج عنترة نراه مقترنا بخبر انتزاعه لحريته حيث نجد عند أبي هلال العسكري خبرا مفاده أن أباه استلحقه يومئذ وزوجه عمه عبلة ابنته. كما نجد أن السيوطي أورد خبرا ينقل قول عم عنترة له: إنك ابن أخي وقد زوجتك ابنتي عبلة، كما نجد نصا ثالثا نقله الميداني في المناسبة ذاتها على لسان والد عنترة حين قال له: كر وقد زوجتك عبلة، فكر وأبلى ووفى له أبوه بذلك فزوجه عبلة. وهذه النصوص تبدو صريحة في إثبات خبر الزواج.\nوقد رأينا كثيرين من الذين ترجموا لعنترة لم يتطرقوا لذكر أمر زواجه ونحن لا نجد بين أيدينا من الوسائل ما يدفعنا إلى تأكيد زواج عنترة بابنة عمه عبلة وهو أمر معقول، ذلك أن عنترة ظل فترة من حياته ما كان له أن يتزوج من حرة مما يترك الفرصة سانحة لعبلة أن تتزوج قبل أن ينال حريته بمن تشاء. وقد صادفتنا مسألة أخرى هي زواجه من امرأة أخرى من بجيلة. وقصة هذا الزواج غير معروفة إلا أن ابن السكيت يقول: \"كانت لعنترة امرأة بخيلة لا تزال تلومه في فرس يملكه واسمه الغبوق\".\nوالمرجح أن عنترة قد تزوج وإن لم يكن بابنة عمه عبلة بالتخصيص، ويؤيد ذلك قوله:\nما استمت انثى نفسها في موطن ... حتى أوفي مهرها مولاها"},{"id":"muallaqat:494","bookId":"muallaqat","type":"section","seq":494,"chapter":"مدخل","title":"7- وفاته","page":"ج1 ص241","text":"اختلف الرواة في نهاية حياة عنترة كما في سائر أخباره، فتعددت الروايات ومنها أن عنترة خرج فهاجت رائحة من صيف نافخة فأصابت الشيخ فوجدوه ميتا بينهم وكان عنترة قد كبر وعجز كما يبدو من الرواية. ومنها أيضا أنه أغار على بني\nنبهان من طيئ فأطرد لهم طريدة، وهو شيخ كبير فجعل يرتجز وهو يطردها ويقول:\nآثار ظلمان بقاع مجدب\nقال: وكان وزر بن جابر النبهاني في فتوة فرماه وقال: خذها وأنا ابن سلمى، فقطع مطاه، فتحامل بالرمية حتى أتى أهله وهو مجروح. ومن أخبار وفاته أنه غزا طيئا مع قومه فانهزمت عبس فخر عن فرسه ولم يقدر من الكبر أن يعود فيركب فدخل دغلا وأبصره ربيئة طيئ فنزل إليه وهاب أن يأخذه أسيرا فرماه وقتله، ويزعمون أن الذي قتله يلقب بالأسد الرهيص وهو القائل:\nأنا الأسد الرهيص قتلت عمرا ... وعنترة الفوارس قد قتلت"},{"id":"muallaqat:495","bookId":"muallaqat","type":"section","seq":495,"chapter":"مدخل","title":"8- شعره","page":"ج1 ص242","text":"البطولة الحربية ووصف المعارك هي أبرز الموضوعات التي تطرق إليها الشاعر في قصائده المختلفة فحاول أن يرسم لنا في قصائده صورة كاملة عن الفارس الشجاع الذي يخوض ساحات القتال وميدان الأبطال. ومن خلال صورة المقاتل الشجاع يستطيع عنترة أن يؤكد فكرة حريته وجدارته بهذه الحرية وبالتالي جدارته بحب ابنة عمه عبلة. ويحاول أن يربط بين فكرة البطولة وفكرة الحب.\nوإذا كانت المعارك عند عنترة تنتهي بموت الخصم فإن فكرة الموت ظلت ماثلة أمام عيني عنترة حين قال: \"إني امرؤ سأموت إن لم أقتل\". ولا ينسى عنترة أن يصف في شعره عدة البطولة من خيل ورماح وسيوف ودروع. فالفارس البطل هو الذي يعنى بالسلاح وآلة الحرب وهو المقدام الذي لا يتراجع مهما كانت العقبات:\nلما رأيت القوم أقبل جمعهم ... يتذامرون كررت غير مذمم\nوالفارس الشجاع والمغوار لا يداخله الخوف ولا يصيبه الوجل، والشجاعة تدفع صاحبها إلى عدم التفكير في المخاطر وتفرض عليه عدم التبصر بالعواقب:\nوإذا حملت على الكريهة لم أقل ... بعد الكريهة ليتني لم أفعل\nإلى جانب شجاعته حاول عنترة أن يظهر متحليا بكل الأخلاق الحميدة\nوالصفات الكريمة التي يتصف بها خيار الناس والفرسان. وكانت غايته من حديثه عن الأخلاق رسم صورة خلقية كاملة تغطي بإشراقها في ظل العبودية والرق. فكانت البطولة جزءا من الفروسية والرجولة الحقة تزينها الأخلاق العربية الأصيلة من صبر ونجدة وكرم وعفة ورقة وقسوة. ومع أن عنترة حاول تغطية عقدة النقص في نسبة فإنه كان لديه الاستعداد النفسي التام لتجسيد فكرة الأخلاق الكريمة والتغني بها والدفاع عنها:\nوإذا شربت فإنني مستهلك ... مالي وعرضي وافر لم يكلم\nوإذا صحوت فما أقصر عن ندى ... وكما علمت شمائلي وتكرمي\nوهو صبور يتحمل المكاره حين يسيطر الضعف على الناس وتلعب بهم رياح الاستسلام:\nوعرفت أن منيتي إن تأتني ... لا ينجني منها الفرار الأسرع\nأما فكرة التعفف فهي ظاهرة في شعره، وحين يظن المقاتل أن غاية القتال هي الكسب والربح نرى عنترة يرتفع عن هذه المعاني ليبقى قتاله للقتال وبطولته للبطولة وحربه للحرب، أما الغنائم فذاك أمر يتركه لسواه:\nيخبرك من شهد الوقيعة أنني ... أغشى الوغى وأعف عند المغنم\nوقد تميز شعر عنترة بما تميز به الشعر العربي عموما من وقوف على الأطلال ذلك أن هذه الظاهرة هي التعبير الصادق عن حنين الشاعر وعن عاطفته. فما الأطلال إلا تلك المواطن التي عاش فيها الشاعر أو مر بها أو حدثت معه فيها حادثة هزت قلبه أو عصفت بوجدانه. والحديث عن الأطلال يقودنا إلى الكلام عن الغزل عند عنترة الذي هو غزل عذري يعني بالمرأة من خلقها وصفاتها ويعني بها كمثال كما يهدف إلى التغني بجمال نفسها:\nوقال لها البدر المنير ألا اسفري ... فإنك مثلي في الكمال وفي السعد\nوالغزل العذري أمر طبيعي عند عنترة ينسجم مع توجهه الخلقي الذي أشرنا إليه والذي يطالع الديوان يجد أنه يكاد يخلو من وصف الجمال الجسدي إلا في أبيات\nمعدودة، وإذا وردت بعض الأوصاف فإنها تكون بعيدة عن الفحش ومحاطة بسياج من الحشمة:\nوألثم أرضا أنت فيها مقيمة ... لعل لهيبي من ثرى الأرض يبرد\nوهو حين يصف حبيبته فإنه يراها من خلال نفسه الشفافة:\nعربية يهتز لين قوامها ... فيخاله العشاق رمحا أسمرا\nوإذا تطرق عنترة في شعره إلى الحكمة فحكمته تدور حول الحياة والموت، فيلتقي مع طرفة بن العبد في أن الموت نهاية كل إنسان وخاتمة كل مطاف والكأس التي لا بد من ورودها والتي إذا جاء أوانها لا يمكن تداركها:\nفأجبتها إن المنية منهل ... لا بد أن أسقي بذاك المنهل]"},{"id":"muallaqat:496","bookId":"muallaqat","type":"section","seq":496,"chapter":"مدخل","title":"1- هل غادر الشعراء من متردم","page":"ج1 ص244","text":"هل غادر الشعراء من متردم ... أم هل عرفت الدار بعد توهم\nالمتردم: الموضع الذي يسترقع ويستصلح لما اعتراه من الوهن والوهي، والتردم أيضا مثل الترنم، وهو ترجيع الصوت مع تحزين.\nيقول: هل تركت الشعراء موضعا مسترقعا إلا وقد رقعوه وأصلحوه؟ وهذا استفهام يتضمن معنى الإنكار، أي لم يترك الشعراء شيئا يصاغ فيه شعر إلا وقد صاغه فيه، وتحرير المعنى: لم يترك الأول للآخر شيئا، أي سبقني من الشعراء قوم لم يتركوا لي مسترقعا أرقعه ومستصلحا أصلحه، وإن حملته على الوجه الثاني كان المعنى: إنهم لم يتركوا شيئا إلا رجعوا نغماتهم بإنشاء الشعر وإنشاده في وصفه ورصفه، ثم أضرب عن هذا الكلام وأخذ في فن آخر فقال مخاطبا لنفسه: هل عرفت دار عشيقتك بعد شكك فيها، وأم ههنا معناه بل أعرفت، وقد تكون أم بمعنى بل مع همزة الاستفهام، كما قال الأخطل: [الكامل] :\nكذبتك عينك أم رأيت بواسط ... غلس الظلام ممن الرباب خيالا\nأي بل أرأيت، ويجوز أن تكون هل ههنا بمعنى قد كقوله عز وجل: {هل أتى على الإنسان} [الإنسان: 1] أي قد أتى."},{"id":"muallaqat:497","bookId":"muallaqat","type":"section","seq":497,"chapter":"مدخل","title":"2- يا دار عبلة بالجواء تكلمي","page":"ج1 ص244","text":"يا دار عبلة بالجواء تكلمي ... وعمي صباحا دار عبلة واسلمي\nالجو: الوادي والجمع الجواء، والجواء في البيت موضع بعينه. عبلة: اسم عشيقته، وقد سبق القول في قوله: عمي صباحا.\nيقول: يا دار حبيبتي بهذا الموضع تكلمي وأخبريني عن أهلك ما فعلوا، ثم أضرب عن استخباره إلى تحيتها فقال: طاب عيشك في صباحك وسلمت يا دار حبيبتي."},{"id":"muallaqat:498","bookId":"muallaqat","type":"section","seq":498,"chapter":"مدخل","title":"3- فوقفت فيها ناقتي وكأنها","page":"ج1 ص245","text":"فوقفت فيها ناقتي وكأنها ... فدن لأقضي حاجة المتلوم\nالفدن: القصر، والجمع الأفدان. المتلوم: المتمكث.\nيقول: حبست ناقتي في دار حبيبتي، ثم شبه الناقة بقصر في عظمها وضخم جرمها، ثم قال: إنما حبستها ووقفتها فيها لأقضي حاجة المتمكث بجزعي من فراقها وبكائي على أيام وصالها."},{"id":"muallaqat:499","bookId":"muallaqat","type":"section","seq":499,"chapter":"مدخل","title":"4- وتحل عبلة بالجواء وأهلنا","page":"ج1 ص245","text":"وتحل عبلة بالجواء وأهلنا ... بالحزن فالصمان فالمتثلم\nيقول: وهي نازلة بهذا الموضع وأهلنا نازلون بهذه المواضع."},{"id":"muallaqat:500","bookId":"muallaqat","type":"section","seq":500,"chapter":"مدخل","title":"5- حييت من طلل تقادم عهده","page":"ج1 ص245","text":"حييت من طلل تقادم عهده ... أقوى وأقفر بعد أم الهيثم\nالإقواء والإقفار: الخلاء، جمع بينهما لضرب من التأكيد كما قال طرفة: [الطويل] :\nمتى أدن منه ينأ عني ويبعد\nجمع بين النأي والبعد لضرب من التأكيد. أم الهيثم: كنية عبلة.\nيقول: حييت من جملة الأطلال، أن خصصت بالتحية من بينها، ثم أخبر أنه قدم عهده بأهله وقد خلا عن السكان بعد ارتحال حبيبته عنه."},{"id":"muallaqat:501","bookId":"muallaqat","type":"section","seq":501,"chapter":"مدخل","title":"6- حلت بأرض الزائرين فأصبحت","page":"ج1 ص245","text":"حلت بأرض الزائرين فأصبحت ... عسرا علي طلابك ابنة مخرم\nالزائرون: الأعداء، جعلهم يزأرون زئير الأسد، شبه توعدهم وتهددهم بزئير الأسد.\nيقول: نزلت الحبيبة بأرض أعدائي فعسر علي طلبها، وأضرب عن الخبر في الظاهر إلى الخطاب، وهو شائع في الكلام، قال الله تعالى: {حتى إذا كنتم في الفلك وجرين بهم بريح} [يونس: 22] ."},{"id":"muallaqat:502","bookId":"muallaqat","type":"section","seq":502,"chapter":"مدخل","title":"7- علقتها عرضا وأقتل قومها","page":"ج1 ص245","text":"علقتها عرضا وأقتل قومها ... زعما لعمر أبيك ليس بمزعم\nقوله: عرضا، أي فجأة من غير قصد له. التعليق هنا: التفعيل من العلق والعلاقة وهما العشق والهوى، يقال: علق فلان بفلانة، إذا كلف بها علقا وعلاقة.\nالعمر والعمر، بفتح العين وضمها: الحياة والبقاء، ولا يستعمل في القسم إلا بفتح العين. الزعم: الطمع. والمزعم: المطمع.\nيقول: عشقتها وشغفت بها مفاجأة من غير قصد مني، أي نظرت إليها نظرة أكسبتني شغفا وكلفا مع قتلي قومها، أي مع ما بيننا من القتال، ثم قال: أطمع في حبك طمعا لا موضع له؛ لأنه لا يمكنني الظفر بوصالك مع ما بين الحيين من القتال والمعاداة، والتقدير: أزعم زعما ليس بمزعم أقسم بحياة أبيك أنه كذلك."},{"id":"muallaqat:503","bookId":"muallaqat","type":"section","seq":503,"chapter":"مدخل","title":"8- ولقد نزلت فلا تظني غيره","page":"ج1 ص246","text":"ولقد نزلت فلا تظني غيره ... مني بمنزلة المحب المكرم\nيقول: وقد نزلت من قلبي منزلة من يحب ويكرم فتيقني هذا واعلميه قطعا ولا تظني غيره."},{"id":"muallaqat:504","bookId":"muallaqat","type":"section","seq":504,"chapter":"مدخل","title":"9- كيف المزار وقد تربع أهلها","page":"ج1 ص246","text":"كيف المزار وقد تربع أهلها ... بعنيزتين وأهلنا بالغيلم\nيقول: كيف يمكنني أن أزورها وقد أقام أهلها زمن الربيع بهذين الموضعين وأهلنا بهذا الموضع وبينهما مسافة بعيدة ومشقة مديدة؟ أي كيف يتأتى لها زيارتها وبين حلتي وحلتها مسافة؟ المزار في البيت: مصدر كالزيارة. التربع: الإقامة زمن الربيع."},{"id":"muallaqat:505","bookId":"muallaqat","type":"section","seq":505,"chapter":"مدخل","title":"10- إن كنت أزمعت الفراق فإنما","page":"ج1 ص246","text":"إن كنت أزمعت الفراق فإنما ... زمت ركابكم بليل مظلم\nالإزماع: توطين النفس على الشيء. الركاب: الإبل، لا واحد لها من لفظها، وقال الفراء: واحدها ركوب مثل قلوص وقلاص.\nيقول: وإن وطنت نفسك على الفراق وعزمت عليه فإني قد شعرت به بزمكم1 إبلكم ليلا، وقيل: بل معناه قد عزمت على الفراق إبلكم قد زمت بليل مظلم، فإن، على القول الأول حرف شرط، وعلى القول الثاني حرف تأكيد."},{"id":"muallaqat:506","bookId":"muallaqat","type":"section","seq":506,"chapter":"مدخل","title":"11- ما راعني إلا حمولة أهلها","page":"ج1 ص246","text":"ما راعني إلا حمولة أهلها ... وسط الديار تسف حب الخمخم\nراعه روعا: أفزعه. الحمولة: الإبل التي تطيق أن يحمل عليها. وسط بتسكين السين، لا يكون إلا ظرفا، والوسط، بفتح السين، اسم لما بين طرفي الشيء. الخمخم: نبت تعلفه الإبل. السف والاستفاف معروفان.\nيقول: ما أفزعني إلا استفاف إبلها حب الخمخم وسط الديار، أي ما أنذرني بارتحالها إلا انقضاء مدة الانتجاع والكلأ، فإذا انقضت مدة الانتجاع علمت أنها ترتحل إلى ديار حيها."},{"id":"muallaqat:507","bookId":"muallaqat","type":"section","seq":507,"chapter":"مدخل","title":"12- فيها اثنتان وأربعون حلوبة","page":"ج1 ص247","text":"فيها اثنتان وأربعون حلوبة ... سودا كخافية الغراب الأسحم\nالحلوبة: جمع الحلوب عند البصريين، وكذلك قتوبة وقتوب1 وركوبة وركوب، وقال غيرهم: هي بمعنى محلوب، وفعول إذا كان بمعنى المفعول جاز أن تلحقه تاء التأنيث عندهم. الأسحم: الأسود. الخوافي من الجناح: أربع من ريشها، والجناح عند أكثر الأئمة: ستة عشر ريشة، أربع قوادم وأربع خواف وأربع مناكب وأربع أباهر، وقال بعضهم: بل هي عشرون ريشة وأربع منها كلى.\nيقول: في حمولتها اثنتان وأربعون ناقة تحلب سودا كخوافي الغراب الأسود، ذكر سوادها دون سائر الألوان لأنها أنفس الإبل وأعزها عندهم، وصف رهط عشيقته بالغنى والتمول."},{"id":"muallaqat:508","bookId":"muallaqat","type":"section","seq":508,"chapter":"مدخل","title":"13- إذ تستبيك بذي غروب واضح","page":"ج1 ص247","text":"إذ تستبيك بذي غروب واضح ... عذب مقبله لذيذ المطعم\nالاستباء والسبي واحد. غرب كل شيء: حده والجمع غروب، الوضوح: البياض. المقبل: موضع التقبل. المطعم: الطعم.\nيقول: إنما كان فزعك من ارتحالها حين تستبيك بثغر ذي حدة واضح عذب موضع التقبيل منه ولذ مطعمه، أراد بالغروب الأشر2 التي تكون في أسنان الشواب، وتحرير المعنى: تستبيك بذي أشر يستعذب تقبيله ويستلذ طعم ريقه."},{"id":"muallaqat:509","bookId":"muallaqat","type":"section","seq":509,"chapter":"مدخل","title":"14- وكأن فارة تاجر بقسيمة","page":"ج1 ص247","text":"وكأن فارة تاجر بقسيمة ... سبقت عوارضها إليك من الفم\nأراد بالتاجر: العطار. سميت فارة المسك فارة لأن الروائح الطيبة تفور منها، والأصل فائرة فخففت فقيل فارة، كما يقال: رجل خائل مال وخال مال، إذا كان\nحسن القيام عليه، القسامة: الحسن والصباحة، والفعل قسم يقسم، والنعت قسيم، والتقسيم والتحسين، ومنه قول العجاج: [الرجز] :\nورب هذا الأثر المقسم\nأي المحسن، يعني مقام إبراهيم عليه السلام. العوارض من الأسنان معروفة. يقول: وكأن فارة مسك عطار بنكهة امرأة حسناء سبقت عوارضها إليك من فيها، شبه طيب نكهتها بطيب ريح المسك، أي تسبق نكهتها الطيبة عوارضها إذا رمت تقبيلها."},{"id":"muallaqat:510","bookId":"muallaqat","type":"section","seq":510,"chapter":"مدخل","title":"15- أو روضة أنفا تضمن نبتها","page":"ج1 ص248","text":"أو روضة أنفا تضمن نبتها ... غيث قليل الدمن ليس بمعلم\nروضة أنف: لم ترع بعد، وكأس أنف استؤنف الشرب بها، وأمر أنف مستأنف، وأصله كله من الاستئناف والائتناف وهما بمعنى. الدمن والدمن: جمع دمنة وهي السرجين1.\nيقول: وكأن فارة تاجر أو روضة لم ترع بعد وقد زكا نبتها وساقه مطر لم يكن معه سرجين، وليست الروضة بمعلم تطؤه الدواب والناس.\nيقول: طيب نكهتها كطيب ريح فارة المسك أو كطيب ريح روضة ناضرة لم ترع، ولم يصبها سرجين ينقص طيب ريحها، ولا وطئتها الدواب فينقص نضرتها وطيب ريحها."},{"id":"muallaqat:511","bookId":"muallaqat","type":"section","seq":511,"chapter":"مدخل","title":"16- جادت عليه كل بكر حرة","page":"ج1 ص248","text":"جادت عليه كل بكر حرة ... فتركن كل قرارة كالدرهم\nالبكر من السحاب: السابق مطره، والجمع الأبكار. الحرة: الخالصة من البرد والريح. والحر من كل شيء: خالصه وجيده، ومنه طين حر لم يخالطه رمل، ومنه أحرار البقول وهي التي تؤكل منها، وحر المملوك خلص من الرق، وأرض حرة لا خراج عليها، وثوب حر لا عيب فيه. ويروى: جادت عليه كل عين ثرة. العين: مطر أيام لا يقلع. والثرة والثرثارة: الكثيرة الماء، القرارة: الحفرة.\nيقول: مطرت على هذه الروضة كل سحابة سابقة المطر لا برد معها، أو كل مطر يدوم أياما ويكثر ماؤه حتى تركت كل حفرة كالدرهم، لاستدارتها بالماء وبياض مائها وصفائه."},{"id":"muallaqat:512","bookId":"muallaqat","type":"section","seq":512,"chapter":"مدخل","title":"17- سحا وتسكابا فكل عشية","page":"ج1 ص249","text":"سحا وتسكابا فكل عشية ... يجري عليها الماء لم يتصرم\nالسح: الصب والانصباب جميعا والفعل سح يسح. التسكاب: السكب، يقال: سكبت الماء أسكبه سكبا فسكب هو يسكب سكوبا. التصرم الانقطاع.\nيقول: أصابها المطر الجود صبا وسكبا فكل عشية يجري عليها ماء السحاب ولم ينقطع عنها."},{"id":"muallaqat:513","bookId":"muallaqat","type":"section","seq":513,"chapter":"مدخل","title":"18- وخلا الذباب بها فليس ببارح","page":"ج1 ص249","text":"وخلا الذباب بها فليس ببارح ... غردا كفعل الشارب المترنم\nالبراح: الزوال، والفعل برح يبرح. التغريد: التصويت، والفعل غرد، والنعت غرد. الترنم: ترديد الصوت بضرب من التلحين.\nيقول: وخلت الذباب بهذه الروضة فلا يزايلنها ويصوتن تصويت شارب الخمر حين رجع صوته بالغناء، شبه أصواتها بالغناء."},{"id":"muallaqat:514","bookId":"muallaqat","type":"section","seq":514,"chapter":"مدخل","title":"19- هزجا يحك ذراعه بذراعه","page":"ج1 ص249","text":"هزجا يحك ذراعه بذراعه ... قدح المكب على الزناد الأجذم\nهزجا: مصوتا. المكب: المقبل على الشيء. الأجذم: الناقص اليد.\nيقول: يصوت الذباب حال حكه إحدى ذراعيه بالأخرى مثل قدح رجل ناقص اليد النار من الزندين. لما شبه طيب نكهة هذه المرأة بطيب نسيم الروضة بالغ في وصف الروضة وأمعن في نعتها ليكون ريحها أطيب ثم عاد إلى النسيب فقال:"},{"id":"muallaqat:515","bookId":"muallaqat","type":"section","seq":515,"chapter":"مدخل","title":"30- تمسي وتصبح فوق ظهر حشية","page":"ج1 ص249","text":"تمسي وتصبح فوق ظهر حشية ... وأبيت فوق سراة أدهم ملجم\nالسراة: أعلى الظهر.\nيقول: تصبح وتمسي فوق فراش وطيء وأبيت أنا فوق ظهر فرس أدهم ملجم، يقول: هي تتنعم وأنا أقاسي شدائد الأسفار والحروب."},{"id":"muallaqat:516","bookId":"muallaqat","type":"section","seq":516,"chapter":"مدخل","title":"21- وحشيتي سرج على عبل الشوى","page":"ج1 ص249","text":"وحشيتي سرج على عبل الشوى ... نهد مراكله نبيل المحزم\nالحشية من الثياب: ما حشي بقطن أو صوف أو غيرهما، والجمع الحشايا. العبل: الغليظ، والفعل عبل عبالة. الشوى: الأطراف والقوائم. النهد: الضخم المشرف. المراكل: جمع المركل وهو موضع الركل، والركل: الضرب بالرجل، وافعل ركل يركل. النبيل: السمين، ويستعار للخير والشر لأنهما يزيدان على غيرهما زيادة السمين على الأعجف. المحزم: موضع الحزام من جسد الدابة.\nيقول: وحشيتي سرج على فرس غليظ القوائم والأطراف ضخم الجنبين منتفخهما سمين موضع الحزام، يريد أنه يستوطئ سرج الفرس كما يستوطئ غيره الحشية، ويلازم ركوب الخيل لزوم غيره الجلوس على الحشية والاضطجاع عليها، ثم وصف الفرس بأوصاف يحمدونها وهي: غلظ القوائم وانتفاخ الجنبين وسمنهما."},{"id":"muallaqat:517","bookId":"muallaqat","type":"section","seq":517,"chapter":"مدخل","title":"22- هل تبلغني دارها شدنية","page":"ج1 ص250","text":"هل تبلغني دارها شدنية ... لعنت بمحروم الشراب مصرم\nشدن: أرض أو قبيلة تنسب الإبل إليها. أراد بالشراب اللبن. التصريم: القطع. يقول: هل تبلغني دار الحبيبة ناقة شدنية لعنت ودعي عليها بأن تحرم اللبن ويقطع لبنها، أي لبعد عهدها باللقاح، كأنها قد دعي عليها بأن تحرم فاستجيب ذلك الدعاء، وإنما شرط هذا لتكون أقوى وأسمن وأصبر على معاناة شدائد الأسفار لأن كثرة الحمل والولادة تكسبها ضعفا وهزالا."},{"id":"muallaqat:518","bookId":"muallaqat","type":"section","seq":518,"chapter":"مدخل","title":"23- خطارة غب السرى زيافة","page":"ج1 ص250","text":"خطارة غب السرى زيافة ... تطس الإكام بوخذ خف ميثم\nخطر البعير بذنبه يخطر خطرا وخطرانا إذا شال به. الزيف: التبختر: والفعل زاف يزيف. الوطس والوثم: الكسر.\nيقول: هي رافعة ذنبها في سيرها مرحا ونشاطا بعدما سارت الليل كله متبخترة تكسر الإكام بخفها الكثير الكسر للأشياء. ويروى: بذات خف، أي برجل ذات خف، ويروى: بوخد خف. الوخد والوخدان: السير السريع. الميثم: للمبالغة كأنه آلة الوثم1، كما يقال: رجل مسعر حرب وفرس مسح2، كأن الرجل آلة لسعر الحروب والفرس آلة لسح الجري."},{"id":"muallaqat:519","bookId":"muallaqat","type":"section","seq":519,"chapter":"مدخل","title":"24- وكأنما تطس الإكام عشية","page":"ج1 ص251","text":"وكأنما تطس الإكام عشية ... بقريب بين المنسمين مصلم\nالمصلم: من أوصاف الظليم لأنه لا أذن له، والصلم الاستئصال، كأن أذنه استؤصلت.\nيقول: كأنما تكسر الإكام لشدة وطئها عشية بعد سرى الليل وسير النهار كظليم قرب ما بين منسميه ولا أذن له، شبهها في سرعة سيرها بعد سرى ليلة ووصل سير يوم به بسرعة سير الظليم، ولما شبهها في سرعة السير بالظليم أخذ في وصفه فقال:"},{"id":"muallaqat:520","bookId":"muallaqat","type":"section","seq":520,"chapter":"مدخل","title":"25- تأوي له قلص النعام كما أوت","page":"ج1 ص251","text":"تأوي له قلص النعام كما أوت ... حزق يمانية لأعجم طمطم\nالقلوص من الإبل والنعام: بمنزلة الجارية من الناس، والجمع قلص وقلائص. يقال: أوى يأوي أويا، أي انضم، ويوصل بإلى يقال: أويت إليه وإنما وصلها باللام لأنه أراد: تأوي إليه قلص له. الحزق: الجماعات، والواحدة حزقة وكذلك الحزيقة، والجمع حزيق، وحزائق، الطمطم: الذي لا يفصح أي العي الذي لا يفصح وأراد بالأعجم الحبشي.\nيقول: تأوي إلى هذا الظليم صغائر النعام كما تأوي الإبل اليمانية إلى راع أعجم عيي لا يفصح، شبه الظليم في سواده بهذا الراعي الحبشي، وقلص النعام بإبل يمانية لأن السواد في إبل اليمانيين أكثر، وشبه أويها إليه بأوي الإبل إلى راعيها ووصفه بالعي والعجمة لأن الظليم لا نطق له."},{"id":"muallaqat:521","bookId":"muallaqat","type":"section","seq":521,"chapter":"مدخل","title":"26- يتبعن قلة رأسه وكأنه","page":"ج1 ص251","text":"يتبعن قلة رأسه وكأنه ... حدج على نعش لهن مخيم\nقلة الرأس: أعلاه. الحدج: مركب من مراكب النساء. النعش: الشيء المرفوع، والنعش بمعنى المنعوش. المخيم: المجعول خيمة.\nيقول: تتبع هؤلاء النعام أعلى رأس هذا الظليم، أي جعلته نصب أعينها لا تنحرف عنه، ثم شبه خلقه بمركب من مراكب النساء جعل كالخيمة فوق مكان مرتفع."},{"id":"muallaqat:522","bookId":"muallaqat","type":"section","seq":522,"chapter":"مدخل","title":"27- صعل يعود بذي العشيرة بيضه","page":"ج1 ص251","text":"صعل يعود بذي العشيرة بيضه ... كالعبد ذي الفرو الطويل الأصلم\nالصعل والأصعل: الصغير الرأس، يعود: يتعهد. الأصلم: الذي لا أذن له، شبه الظليم بعبد ليس فروا طويلا ولا أذن له لأنه لا أذن للنعام، وشرط الفرو الطويل\nليشبه جناحيه، وشرط العبد لسواد الظليم، وعبيد العرب السودان، ذو العشيرة: موضع، ثم رجع إلى وصف ناقته فقال:"},{"id":"muallaqat:523","bookId":"muallaqat","type":"section","seq":523,"chapter":"مدخل","title":"28- شربت بماء الدحرضين فأصبحت","page":"ج1 ص252","text":"شربت بماء الدحرضين فأصبحت ... زوراء تنفر عن حياض الديلم\nالزور: الميل، والفعل زور يزور، والنعت أزور، والأنثى زوراء، والجمع زور. مياه الديلم: مياه معروفة، وقيل: العرب تسمي الأعداء ديلما؛ لأن الديلم صنف من أعدائها.\nيقول: شربت هذه الناقة من مياه هذا الموضع، فأصبحت مائلة نافرة عن مياه الأعداء. والباء في قوله بماء الدحرضين زائدة عن البصريين كزيادتها في قوله تعالى: {ألم يعلم بأن الله يرى} [العلق: 14] وقول الشاعر: [البسيط] :\nهن الحرائر لا ربات أخمرة ... سود المحاجر لا يقرأن بالسور\nأي لا يقرأن السور، والكوفيون يجعلونها بمعنى من، وكذلك الباء في قوله تعالى: {عينا يشرب بها عباد الله} [الإنسان: 6] قد اختلف فيه على هذا الوجه."},{"id":"muallaqat:524","bookId":"muallaqat","type":"section","seq":524,"chapter":"مدخل","title":"29- وكأنما تنأى بجانب دفها ال","page":"ج1 ص252","text":"وكأنما تنأى بجانب دفها ال ... وحشي من هزج العشي مؤوم\nالدف: الجنب. الجانب الوحشي: اليمين، وسمي وحشيا لأنه لا يركب من ذلك الجانب ولا ينزل. الهزج: الصوت والفعل هزج يهزج، والنعت هزج. المؤوم: القبيح الرأس العظيمة، قوله: من هزج العشي، أي من خوف هزج العشي، فحذف المضاف، والباء في قوله بجانب دفها للتعدية.\nيقول: كأن هذه الناقة تبعد وتنحي الجانب الأيمن منها من خوف هر عظيم الرأس قبيحه، وجعله هزج العشي لأنهم إذا تعشوا فإنه يصيح على هذا الطعام ليطعم، يصف هذه الناقة بالنشاط في السير وأنها لا تستقيم في سيرها نشاطا ومرحا، فكأنها تنحي جانبها الأيمن خوف خدش سنور إياه، وقيل: بل أراد أنها تنحيه وتبعده مخافة الضرب بالسوط فكأنها تخاف خدش سنور جانبها الأيمن."},{"id":"muallaqat:525","bookId":"muallaqat","type":"section","seq":525,"chapter":"مدخل","title":"30- هر جنيب كلما عطفت له","page":"ج1 ص252","text":"هر جنيب كلما عطفت له ... غضبى اتقاها باليدين وبالفم\nهر: بدل من هزج العشي. جنيب أي مجنوب إليها أي مقود. اتقاها أي استقبلها.\nيقول: تتنحى وتتباعد من خوف سنور كلما انصرفت الناقة غضبى لتعقره استقبلها الهر بالخدش بيده والعض بفمه، يقول: كلما أمالت رأسها إليه زادها خدشا وعضا."},{"id":"muallaqat:526","bookId":"muallaqat","type":"section","seq":526,"chapter":"مدخل","title":"31- بركت على جنب الرداع كأنما","page":"ج1 ص253","text":"بركت على جنب الرداع كأنما ... بركت على قصب أجش مهضم\nرداع: موضع. أجش: له صوت. مهضم أي مكسر.\nيقول: كأنما بركت هذه الناقة وقت بروكها على جنب الرداع على قصب مكسر له صوت، شبه أنينها من كلالها بصوت القصب المكسر عند بروكها عليه، وقيل: بل شبه صوت تكسر الطين اليابس الذي نضب عنه الماء بصوت تكسر القصب."},{"id":"muallaqat:527","bookId":"muallaqat","type":"section","seq":527,"chapter":"مدخل","title":"32- وكأن ربا أو كحيلا معقدا","page":"ج1 ص253","text":"وكأن ربا أو كحيلا معقدا ... حش الوقود به جوانب قمقم\nالرب: الطلاء. الكحيل: الطقران. عقد الدواء: أغليته حتى خثر. حش النار يحشها حشا: أوقدها. الوقود: الحطب، والوقود بضم الواو: الإيقاد، شبه العرق السائل من رأسها وعنقها برب أو قطران جعل في قمقم أوقدت عليه النار، فهو يترشح به عند الغليان، وعرق الإبل أسود لذلك شبهه بهما، وشبه رأسها بالقمقم في الصلابة؛ وتقدير البيت: وكأنها ربا أو كحيلا حش الوقود بإغلائه في جوانب قمقم عرقها الذي يترشح منها."},{"id":"muallaqat:528","bookId":"muallaqat","type":"section","seq":528,"chapter":"مدخل","title":"33- ينباع من ذفرى غضوب جسرة","page":"ج1 ص253","text":"ينباع من ذفرى غضوب جسرة ... زيافة مثل الفنيق المكدم\nأراد ينبع فأشبع الفتحة لإقامة الوزن فتولدت من إشباعها ألف، ومثله قول إبراهيم بن هرمة: [البسيط] :\nمن حوثما سلكوا أدنو فأنظور\nأراد فأنظر فأشبعت الضمة فتولدت من إشباعها واو، ومثله قولنا: آمين والأصل أمين، فأشبعت الفتحة فتولدت من إشباعها ألف، يدلك عليه أنه ليس في كلام العرب اسم جاء على فاعيل، وهذه اللفظة عربية بالإجماع، ومنهم من جعله ينفعل من البوع وهو طي المسافة. الذفرى: ما خلف الأذن. الجسرة: الناقة الموثقة الخلق. الزيف: التبختر والفعل زاف يزيف. الفنيق: الفحل من الإبل.\nيقول: ينبع هذا العرق من خلف أذن ناقة غضوب موثقة الخلق شديدة التبختر في\nسيرها، مثل فحل من الإبل قد كدمته الفحول، شبهها بالفحل في تبخترها ووثاقة خلقها وضخمها."},{"id":"muallaqat:529","bookId":"muallaqat","type":"section","seq":529,"chapter":"مدخل","title":"34- إن تغدفي دوني القناع فإنني","page":"ج1 ص254","text":"إن تغدفي دوني القناع فإنني ... طب بأخذ الفارس المستلئم\nالإغداف: الإرخاء. طب: حاذق عالم. استلأم: لبس اللأمة1.\nيقول مخاطبا عشيقته: إن ترخي وترسلي دوني القناع، أي تستتري عني، فإني حاذق بأخذ الفرسان الدارعين، أي لا ينبغي لك أن تزهدي في مع نجدتي وبأسي وشدة مراسي2، وقيل: بل معناه إذا لم أعجز عن صيد الفرسان الدارعين فكيف أعجز عن صيد أمثالك؟"},{"id":"muallaqat:530","bookId":"muallaqat","type":"section","seq":530,"chapter":"مدخل","title":"35- أثني علي بما علمت فإنني","page":"ج1 ص254","text":"أثني علي بما علمت فإنني ... سمح مخالقتي إذا لم أظلم\nالمخالفة: مفاعلة من الخلق.\nيقول: أثني علي أيتها الحبيبة بما علمت من محامدي ومناقبي فإني سهل المخالطة والمخالقة إذا لم يهضم حقي ولم يبخس حظي."},{"id":"muallaqat:531","bookId":"muallaqat","type":"section","seq":531,"chapter":"مدخل","title":"36- وإذا ظلمت فإن ظلمي باسل","page":"ج1 ص254","text":"وإذا ظلمت فإن ظلمي باسل ... مر مذاقته كطعم العلقم\nباسل: كريه، ورجل باسل شجاع، والبسالة الشجاعة.\nيقول: وإذا ظلمت وجدت ظلمي كريها مرا كطعم العلقم، أي من ظلمني عاقبته عقابا بالغا يكرهه كما يكره طعم العلقم من ذاقه."},{"id":"muallaqat:532","bookId":"muallaqat","type":"section","seq":532,"chapter":"مدخل","title":"37- ولقد شربت من المدامة بعدما","page":"ج1 ص254","text":"ولقد شربت من المدامة بعدما ... ركد الهواجر بالمشوف المعلم\nركد: سكن. الهواجر: جمع الهاجرة وهي أشد الأوقات حرا. المشوف: المجلو. المدام والمدامة: الخمر، سميت بها لأنها أديمت في دنها.\nيقول: ولقد شربت من الخمر بعد اشتداد حر الهواجر وسكونه بالدينار المجلو المنقوش، يريد أنه اشترى الخمر فشربها، والعرب تفتخر بشرب الخمر والقمار، لأنها من دلائل الجود عندها.\nقوله: بالمشوف، أي بالدينار، فحذف الموصوف ومنهم من جعله من صفة القدح وقال: أراد بالقدح المشوف."},{"id":"muallaqat:533","bookId":"muallaqat","type":"section","seq":533,"chapter":"مدخل","title":"38- بزجاجة صفراء ذات أسرة","page":"ج1 ص255","text":"بزجاجة صفراء ذات أسرة ... قرنت بأزهر في الشمال مفدم\nالأسرة: جمع السر والسرر، وهما الخط من خطوط اليد والجبهة وغيرهما، وتجمع أيضا على الأسرار ثم تجمع على أسارير. بأزهر أي: بإبريق أزهر. مفدم: مسدود الرأس بالفدام1.\nيقول: شربتها بزجاجة صفراء عليها خطوط قرنتها بإبريق أبيض مسدود الرأس بالفدام لأصب الخمر من الإبريق في الزجاجة."},{"id":"muallaqat:534","bookId":"muallaqat","type":"section","seq":534,"chapter":"مدخل","title":"39- فإذا شربت فإنني مستهلك","page":"ج1 ص255","text":"فإذا شربت فإنني مستهلك ... مالي وعرضي وافر لم يكلم\nيقول: فإذا شربت الخمر فإنني أهلك مالي بجودي ولا أشين عرضي، فأكون تام العرض مهلك المال لا يكلم2 عرضي عيب عائب، يفتخر بأن سكره يحمله على محامد الأخلاق ويكفه عن المثالب."},{"id":"muallaqat:535","bookId":"muallaqat","type":"section","seq":535,"chapter":"مدخل","title":"40- وإذا صحوت فما أقصر عن ندى","page":"ج1 ص255","text":"وإذا صحوت فما أقصر عن ندى ... وكما علمت شمائلي وتكرمي\nيقول: وإذا صحوت من سكري لم أقصر عن جودي، أي يفارقني السكر ولا يفارقني الجود، ثم قال: وأخلاقي وتكرمي كما علمت أيتها الحبيبة، افتخر بالجود ووفور العقل إذ لم ينقص السكر عقله. وهذان البيتان قد حكم الرواة بتقدمهما في بابهما."},{"id":"muallaqat:536","bookId":"muallaqat","type":"section","seq":536,"chapter":"مدخل","title":"41- وحليل غانية تركت مجدلا","page":"ج1 ص255","text":"وحليل غانية تركت مجدلا ... تمكو فريصته كشدق الأعلم\nالحليل: بالمهملة: الزوج والحليلة الزوجة، وقيل في اشتقاقهما: إنهما من الحلول فسميا بهما لأنهما يحلان منزلا واحدا وفراشا واحدا، فهو على هذا القول فعيل بمعنى مفاعل، مثل شريب وأكيل ونديم بمعنى مشارب ومؤاكل ومنادم، وقيل: بل هما مشتقان من الحل لأن كلا منهما يحل لصاحبه، فهو على هذا القول فعيل\nبمعنى مفعل مثل الحكيم بمعنى المحكم، وقيل: بل هما مشتقان من الحل، وهو على هذا القول، فعيل بمعنى فاعل، وسميا بهما لأن كلا منهما يحل إزار صاحبه. الغانية: ذات الزوج من النساء لأنها غنيت بزوجها عن الرجال؛ وقال الشاعر: [الطويل] :\nأحب الأيامى إذ بثينة أيم ... وأحببت لما أن غنيت الغوانيا\nوقيل: بل الغانية البارعة الجمال المستغنية بكمال جمالها عن التزين، وقيل: الغانية المقيمة في بيت أبويها لم تزوج بعد، من غني بالمكان إذا أقام به، وقال عمارة بن عقيل: الغانية الشابة الحسناء التي تعجب الرجال ويعجبها الرجال، والأحسن القول الثاني والرابع. جدلته: ألقيته على الجدالة، وهي الأرض، فتجدل أي سقط عليها. المكاء: الصفير. العلم: الشق في الشفة العليا.\nيقول: ورب زوج امرأة بارعة الجمال مستغنية بجمالها عن التزين قتلته وألقيته على الأرض، وكانت فريصته تمكو بانصباب الدم منها كشدق الأعلم، قال أكثرهم: شبه سعة الطعن بسعة شدق الأعلم، وقال بعضهم: بل شبه صوت انصباب الدم بصوت خروج النفس من شدق الأعلم."},{"id":"muallaqat:537","bookId":"muallaqat","type":"section","seq":537,"chapter":"مدخل","title":"42- سبقت يداي له بعاجل طعنة","page":"ج1 ص256","text":"سبقت يداي له بعاجل طعنة ... ورشاش نافذة كلون العندم\nالعندم: دم الأخوين، وقيل: بل هو البقم1، وقيل شقائق النعمان.\nيقول: طعنته طعنة في عجلة ترش دما من طعنة نافذة تحكي لون العندم."},{"id":"muallaqat:538","bookId":"muallaqat","type":"section","seq":538,"chapter":"مدخل","title":"43- هلا سألت الخيل يابنة مالك","page":"ج1 ص256","text":"هلا سألت الخيل يابنة مالك ... إن كنت جاهلة بما لم تعلمي\nيقول: هل سألت الفرسان عن حالي في قتالي إن كنت جاهلة بها؟"},{"id":"muallaqat:539","bookId":"muallaqat","type":"section","seq":539,"chapter":"مدخل","title":"44- إذ لا أزال على رحالة2 سابح","page":"ج1 ص256","text":"إذ لا أزال على رحالة2 سابح ... نهد تعاوره الكماة مكلم\nالتعاور: التداول، يقال: تعاوروه ضربا جعلوا يضربونه على جهة التناوب، وكذلك الاعتوار. الكلم: الجرح، والتكليم التجريح.\nيقول: هلا سألت الفرسان عن حالي إذا لم أزل على سرج فرس سابح تناوب الأبطال في جرحه، أي جرحه كل منهم، ونهد من صفة السابح وهو الضخم."},{"id":"muallaqat:540","bookId":"muallaqat","type":"section","seq":540,"chapter":"مدخل","title":"45- طورا يجرد للطعان وتارة","page":"ج1 ص257","text":"طورا يجرد للطعان وتارة ... يأوي إلى حصد القسي عرمرم\nالطور: التارة والمرة، والجمع الأطوار.\nيقول: مرة أجرده من صف الأولياء لطعن الأعداء وضربهم وأنضم مرة إلى قوم محكمي القسي، كثير، يقول: مرة أحمل عليه على الأعداء فأحسن بلائي وأنكي فيهم أبلغ نكاية، ومرة أنضم إلى قوم أحكمت قسيهم وكثر عددهم، أراد أنهم رماة مع كثرة عددهم. العرمرم: الكثير. حصد الشيء حصدا إذا استحكم، والإحصاد: الإحكام."},{"id":"muallaqat:541","bookId":"muallaqat","type":"section","seq":541,"chapter":"مدخل","title":"46- يخبرك من شهد الوقيعة أنني","page":"ج1 ص257","text":"يخبرك من شهد الوقيعة أنني ... أغشى الوغى وأعف عند المغنم\nيخبرك: مجزوم لأنه جواب هلا سألت. الوقعة والوقيعة: اسمان من أسماء الحروب، والجمع الوقعات والوقائع. الوغى: أصوات أهل الحرب ثم استعير للحرب. المغنم والغنم والغنيمة واحد.\nيقول: إن سألت الفرسان عن حالي في الحرب يخبرك من حضر الحرب بأني كريم عالي الهمة آتي في الحروب وأعف عن اغتنام الأموال."},{"id":"muallaqat:542","bookId":"muallaqat","type":"section","seq":542,"chapter":"مدخل","title":"47- ومدجج كره الكماة نزاله","page":"ج1 ص257","text":"ومدجج كره الكماة نزاله ... لا ممعن هربا ولا مستسلم\nالمدجج والمدجج: التام السلاح. الإمعان: الإسراع في الشيء والغلو فيه. الاستسلام: الانقياد والاستكانة.\nيقول: ورب رجل تام السلاح كانت الأبطال تكره نزاله وقتاله لفرط بأسه وصدق مراسه، لا يسرع في الهرب إذا اشتد بأس عدوه، ولا يستكين له إذا صدق مراسه."},{"id":"muallaqat:543","bookId":"muallaqat","type":"section","seq":543,"chapter":"مدخل","title":"48- جادت له كفي بعاجل طعنة","page":"ج1 ص257","text":"جادت له كفي بعاجل طعنة ... بمثقف صدق الكعوب مقوم\nيقول: جادت يدي له بطعنة عاجلة برمح مقوم صلب الكعوب، والبيت جواب رب المضمر بعد الواو في: ومدجج. قوله: بعاجل طعنة، قدم الصفة على الموصوف ثم أضافها إليه، تقديره: بطعنة عاجلة. الصدق: الصلب."},{"id":"muallaqat:544","bookId":"muallaqat","type":"section","seq":544,"chapter":"مدخل","title":"49- فشككت بالرمح الأصم ثيابه","page":"ج1 ص258","text":"فشككت بالرمح الأصم ثيابه ... ليس الكريم على القنا بمحرم\nالشك: الانتظام، والفعل شك يشك، الأصم: الصلب.\nيقول: فانتظمت برمحي الصلب ثيابه، أي طعنته طعنة أنفذت الرمح في جسمه وثيابه كلها، ثم قال: ليس الكريم محرما على الرماح، يريد أن الرماح مولعة بالكرام لحرصهم على الإقدام، وقيل: بل معناه أن كرمه لا يخلصه من القتل المقدر له."},{"id":"muallaqat:545","bookId":"muallaqat","type":"section","seq":545,"chapter":"مدخل","title":"50- فتركته جزر السباع ينشنه","page":"ج1 ص258","text":"فتركته جزر السباع ينشنه ... يقضمن حسن بنانه والمعصم\nالجزر: جمع جزرة وهي الشاة التي أعدت للذبح. النوش: التناول، والفعل ناش ينوش نوشا. القضم: الأكل بمقدم الأسنان، والفعل قضم يقضم.\nيقول: فصيرته طعمة للسباع كما يكون الجزر طعمة للناس، ثم قال: تتناوله السباع وتأكل بمقدم أسنانها بنانه الحسن ومعصمه الحسن، ويريد أنه قتله فجعله عرضة للسباع حتى تناولته وأكلته."},{"id":"muallaqat:546","bookId":"muallaqat","type":"section","seq":546,"chapter":"مدخل","title":"51- ومشك سابغة1 هتكت فروجها","page":"ج1 ص258","text":"ومشك سابغة1 هتكت فروجها ... بالسيف عن حامي الحقيقة معلم\nالمشك: الدرع التي قد شك بعضها إلى بعض، وقيل: مساميرها، يشير إلى أنه الزرد، وقيل: الرجل التام السلاح. الحقيقة: ما يحق عليك حفظه أي يجب. المعلم، بكسر اللام: الذي أعلم نفسه أي شهرها بعلامة يعرف بها في الحروب حتى ينتدب الأبطال لبرازه، والمعلم، بفتح اللام: الذي يشار إليه ويدل عليه بأنه فارس الكتيبة وواحد السرية.\nيقول: ورب مشك درع، أي رب موضع انتظام درع واسعة، شققت أوساطها بالسيف عن رجل حام له يجب عليه حفظه، شاهر نفسه في حومة الحرب أو مشار إليه فيها، يريد أنه هتك مثل هذه الدرع مثل هذا الشجاع فكيف الظن بغيره."},{"id":"muallaqat:547","bookId":"muallaqat","type":"section","seq":547,"chapter":"مدخل","title":"52- ربذ يداه بالقداح إذا شتا","page":"ج1 ص258","text":"ربذ يداه بالقداح إذا شتا ... هتاك غايات التجار ملوم\nالربذ: السريع. شتا: دخل في الشتاء، يشتو شتوا. الغاية: راية ينصبها الخمار\nليعرف مكانه بها. أراد بالتجار الخمارين. الملوم: الذي ليم مرة بعد أخرى. والبيت كله من صفة حامي الحقيقة.\nيقول: هتكت الدرع عن رجل سريع اليد خفيفها في إجالة القداح في الميسر في برد الشتاء، وخص الشتاء؛ لأنهم يكثرون الميسر فيه لتفرغهم، وعن رجل يهتك رايات الخمارين، أي كان يشتري جميع ما عندهم من الخمر حتى يقلعوا راياتهم لنفاد خمرهم، ملوم على إمعانه في الجود وإسرافه في البذل، وهذا كله من صفة حامي الحقيقة."},{"id":"muallaqat:548","bookId":"muallaqat","type":"section","seq":548,"chapter":"مدخل","title":"53- لما رآني قد نزلت أريده","page":"ج1 ص259","text":"لما رآني قد نزلت أريده ... أبدي نواجذه لغير تبسم\nيقول: لما رآني هذا الرجل نزلت عن فرسي أريد قتله كشر عن أسنانه غير متبسم، أي لفرط كلوحه1 من كراهية الموت قلصت شفتاه عن أسنانه، وليس ذلك لتكلم ولا لتبسم ولكن من الخوف.\nويروى: لغير تكلم."},{"id":"muallaqat:549","bookId":"muallaqat","type":"section","seq":549,"chapter":"مدخل","title":"54- عهدي به مد النهار كأنما","page":"ج1 ص259","text":"عهدي به مد النهار كأنما ... خضب البنان ورأسه بالعظلم\nمد النهار: طوله. العظلم: نبت يختضب به. العهد: اللقاء، يقال: عهدته أعهده عهدا إذا لقيته. يقول: رأيته طول النهار وامتداده بعد قتلي إياه وجفاف الدم عليه كأن بنانه ورأسه مخضوبان بهذا النبت."},{"id":"muallaqat:550","bookId":"muallaqat","type":"section","seq":550,"chapter":"مدخل","title":"55- فطعنته بالرمح ثم علوته","page":"ج1 ص259","text":"فطعنته بالرمح ثم علوته ... بمهند صافي الحديدة مخذم\nالمخذم: السريع القطع.\nيقول: طعنته برمحي حين ألقيته من ظهر فرسه ثم علوته مع سيف مهند صافي الحديد سريع القطع."},{"id":"muallaqat:551","bookId":"muallaqat","type":"section","seq":551,"chapter":"مدخل","title":"56- بطل كأن ثيابه في سرحة","page":"ج1 ص259","text":"بطل كأن ثيابه في سرحة ... يحذى نعال السبت ليس بتوأم\nالسرحة: الشجرة العظيمة. يحذى أي تجعل حذاء له، والحذاء: النعل، والجمع الأحذية.\nيقول: وهو بطل مديد القد كأن ثيابه ألبست شجرة عظيمة من طول قامته واستواء خلقه، تجعل جلوس البقر المدبوغة بالقرظ نعالا له، أي تستوعب رجلاه السبت، ولم تحمل أمه معه غيره، بالغ في وصفه بالشدة والقوة بامتداد قامته وعظم أعضائه وتمام غذائه عند إرضاعه إذ كان فذا غير توأم."},{"id":"muallaqat:552","bookId":"muallaqat","type":"section","seq":552,"chapter":"مدخل","title":"57- يا شاة ما قنص لمن حلت له","page":"ج1 ص260","text":"يا شاة ما قنص لمن حلت له ... حرمت علي وليتها لم تحرم\nما: صلة زائدة. الشاة: كناية عن المرأة.\nيقول: يا هؤلاء اشهدوا شاة قنص لمن حلت له فتعجبوا من حسنها وجمالها، فإنها قد حازت أتم الجمال، والمعنى: هي حسناء جميلة مقنع لمن كلف بها وشغف بحبها، ولكنها حرمت علي وليتها لم تحرم علي، أي ليت أبي لم يتزوجها حتى كان يحل لي تزوجها، وقيل: أراد بذلك أنها حرمت عليه باشتباك الحرب بين قبيلتيهما ثم تمنى بقاء الصلح."},{"id":"muallaqat:553","bookId":"muallaqat","type":"section","seq":553,"chapter":"مدخل","title":"58- فبعثت جاريتي فقلت لها اذهبي","page":"ج1 ص260","text":"فبعثت جاريتي فقلت لها اذهبي ... فتجسسي أخبارها لي واعلمي\nيقول: فبعثت جاريتي لتتعرف أحوالها لي."},{"id":"muallaqat:554","bookId":"muallaqat","type":"section","seq":554,"chapter":"مدخل","title":"59- قالت","page":"ج1 ص260","text":"قالت: رأيت من الأعادي غرة ... والشاة ممكنة لمن هو مرتم\nالغرة: الغفلة، رجل غر غافل لم يجرب الأمور.\nيقول: فقالت جاريتي لما انصرفت لي: صادفت الأعادي غافلين عنها ورمي الشاة ممكن لمن أراد أن يرتميها، يريد أن زيارتها ممكن لطالبها لغفلة الرقباء والقرناء عنها."},{"id":"muallaqat:555","bookId":"muallaqat","type":"section","seq":555,"chapter":"مدخل","title":"60- وكأنما التفتت بجيد جداية","page":"ج1 ص260","text":"وكأنما التفتت بجيد جداية ... رشأ من الغزلان حر أرثم\nالجداية والجداية: ولد الظبية، الجمع الجدايا، الرشأ: الذي قوي من أولاد الظباء. والغزلان جمع الغزال. الحر من كل شيء: خالصه وجيده. الأرثم: الذي في شفته العليا وأنفه بياض.\nيقول: كأن \"التفاتها إلينا في نظرها\" التفات ولد ظبية هذه صفته في نظره."},{"id":"muallaqat:556","bookId":"muallaqat","type":"section","seq":556,"chapter":"مدخل","title":"61- نبئت عمرا غير شاكر نعمتي","page":"ج1 ص261","text":"نبئت عمرا غير شاكر نعمتي ... والكفر مخبثة لنفس المنعم\nالتنبئة والتنبيء: مثل الإنباء وهذه من سبعة أفعال تتعدى إلى ثلاثة مفاعيل، وهي: أعلمت وأريت وأنبأت ونبئت وأخبرت وخبرت وحدثت، وإنما تعددت الخمسة التي هي غير أعلمت وأريت إلى ثلاثة مفاعيل لتضمنها معنى أعلمت.\nيقول: أعلمت أن عمرا لا يشكر نعمتي، وكفران النعمة ينفر نفس المنعم عن الإنعام، فالتاء في نبئت هو المفعول الأول قد أقيم مقام الفاعل وأسند الفعل إليه، وعمرا هو المفعول الثاني، وغير هو المفعول الثالث."},{"id":"muallaqat:557","bookId":"muallaqat","type":"section","seq":557,"chapter":"مدخل","title":"62- ولقد حفظت وصاة عمي بالضحى","page":"ج1 ص261","text":"ولقد حفظت وصاة عمي بالضحى ... إذ تقلص الشفتان عن وضح الفم\nالوصاة والوصية شيء واحد. وضح الفم: الأسنان. القلوص: التشنج والقصر. يقول: ولقد حفظت وصية عمي إياي فاقتحامي القتال ومناجزتي الأبطال في أشد أحوال الحرب، وهي حالة تقلص الشفاه عن الأسنان من شدة كلوح الأبطال والكماة1 فرقا من القتل."},{"id":"muallaqat:558","bookId":"muallaqat","type":"section","seq":558,"chapter":"مدخل","title":"63- في حومة الحرب التي لا تشتكي","page":"ج1 ص261","text":"في حومة الحرب التي لا تشتكي ... غمراتها الأبطال غير تغمغم\nحومة الحرب: معظمها وهي حيث تحوم الحرب أي تدور، وغمرات الحرب: شدائدها التي تغمر أصحابها، أي تغلب قلوبهم وعقولهم. التغمغم: صياح ولجب لا يفهم منه شيء.\nيقول: ولقد حفظت وصية عمي في حومة الحرب التي لا تشكوها الأبطال إلا بجلبة وصياح."},{"id":"muallaqat:559","bookId":"muallaqat","type":"section","seq":559,"chapter":"مدخل","title":"64- إذ يتقون بي الأسنة لم أخم","page":"ج1 ص261","text":"إذ يتقون بي الأسنة لم أخم ... عنها ولكني تضايق مقدمي\nالاتقاء: الحجر بين الشيئين، تقول: أتقيت العدو بترسي، أي جعلت الترس حاجزا بيني وبين العدو. الخيم: الجبن. المقدم: موضع الإقدام، وقد يكون الإقدام في غير هذا الموضع.\nيقول: حين جعلني أصحابي حاجزا بينهم وبين أسنة أعدائهم، أي قدموني وجعلوني في نحور أعدائهم، لم أجبن عن أسنتهم ولم أتأخر، ولكن قد تضايق موضع إقدامي، فتعذر التقدم فتأخرت لذلك."},{"id":"muallaqat:560","bookId":"muallaqat","type":"section","seq":560,"chapter":"مدخل","title":"65- لما رأيت القوم أقبل جمعهم","page":"ج1 ص262","text":"لما رأيت القوم أقبل جمعهم ... يتذامرون كررت غير مذمم\nالتذامر تفاعل من الذمر وهو الحض على القتال.\nيقول: لما رأيت جمع الأعداء قد أقبلوا نحونا يحض بعضهم بعضا على قتالنا عطفت عليهم لقتالهم غير مذمم، أي محمود القتال غير مذمومه."},{"id":"muallaqat:561","bookId":"muallaqat","type":"section","seq":561,"chapter":"مدخل","title":"66- يدعون عنتر والرماح كأنها","page":"ج1 ص262","text":"يدعون عنتر والرماح كأنها ... أشطان بئر في لبان الأدهم\nالشطن: الحبل الذي يستقى به، والجمع الأشطان. اللبان: الصدر.\nيقول: كانوا يدعونني في حال إصابة رماح الأعداء صدر فرسي ودخولها فيه، ثم شبهها في طولها بالحبال التي يستقى بها من الآبار."},{"id":"muallaqat:562","bookId":"muallaqat","type":"section","seq":562,"chapter":"مدخل","title":"67- ما زلت أرميهم بثغرة نحره","page":"ج1 ص262","text":"ما زلت أرميهم بثغرة نحره ... ولبانه حتى تسربل بالدم\nالثغرة: الوقبة1 في أعلى النحر، والجمع الثغر.\nيقول: لم أزل أرمي الأعداء بنحر فرسي حتى جرح وتلطخ بالدم وصار له بمنزلة السربال، أي عم جسده عموم السربال جسد لابسه."},{"id":"muallaqat:563","bookId":"muallaqat","type":"section","seq":563,"chapter":"مدخل","title":"68- فازور من وقع القنا بلبانه","page":"ج1 ص262","text":"فازور من وقع القنا بلبانه ... وشكا إلي بعبرة وتحمحم\nالازورار: الميل. التحمحم: من صهيل الفرس ما كان فيه شبه الحنين ليرق صاحبه له.\nيقول: فمال فرسي مما أصابت رماح الأعداء صدره ووقوعها به وشكا إلي بعبرته وحمحمته، أي نظر إلي وحمحم لأرق له."},{"id":"muallaqat:564","bookId":"muallaqat","type":"section","seq":564,"chapter":"مدخل","title":"69- لو كان يدري ما المحاورة اشتكى","page":"ج1 ص262","text":"لو كان يدري ما المحاورة اشتكى ... ولكان لو علم الكلام مكلمي\nيقول: لو كان يعلم الخطاب لاشتكى إلي مما يقاسيه ويعانيه، وكلمني لو كان يعلم الكلام، يريد أنه لو قدر على الكلام لشكا إلي مما أصابه من الجراح."},{"id":"muallaqat:565","bookId":"muallaqat","type":"section","seq":565,"chapter":"مدخل","title":"70- ولقد شفى نفسي وأذهب سقمها","page":"ج1 ص263","text":"ولقد شفى نفسي وأذهب سقمها ... قيل الفوارس ويك عنتر أقدم\nيقول: ولقد شفى نفسي وأذهب سقمها قول الفوارس لي: ويلك يا عنترة أقدم نحو العدو واحمل عليه، يريد أن تعويل أصحابه عليه والتجاءهم إليه شفى نفسه ونفى غمه."},{"id":"muallaqat:566","bookId":"muallaqat","type":"section","seq":566,"chapter":"مدخل","title":"71- والخيل تقتحم الخبار عوابسا","page":"ج1 ص263","text":"والخيل تقتحم الخبار عوابسا ... من بين شيظمة وأجرد شيظم\nالخبار: الأرض اللينة. الشظيم: الطويل من الخيل.\nيقول: والخيل تسير وتجري في الأرض اللينة التي تسوخ1 فيها قوائمها بشدة وصعوبة وقد عبست وجوهها لما نالها من الإعياء، وهي لا تخلو من فرس طويل أو طويلة، أي كلها طويلة."},{"id":"muallaqat:567","bookId":"muallaqat","type":"section","seq":567,"chapter":"مدخل","title":"72- ذلل ركابي حيث شئت مشايعي","page":"ج1 ص263","text":"ذلل ركابي حيث شئت مشايعي ... لبتي وأحفزه بأمر مبرم\nذلل: جمع ذلول من الذل وهو ضد الصعوبة. الركاب: الإبل، لا واحد لها من لفظها عند جمهور الأئمة، وقال الفراء: إنها جمع ركوب مثل قلوص2 وقلاص ولقوح ولقاح. المشايعة: المعاونة، أخذت من الشياع وهو دقائق الحطب لمعاونته النار على الإيقاد في الحطب الجزل3. الحفز: الدفع. الإبرام: الإحكام.\nيقول: تذل إبلي لي حيث وجهتها من البلاد ويعاونني على أفعالي عقلي، وأمضي ما يقتضيه عقلي بأمر محكم."},{"id":"muallaqat:568","bookId":"muallaqat","type":"section","seq":568,"chapter":"مدخل","title":"73- ولقد خشيت بأن أموت ولم تدر","page":"ج1 ص263","text":"ولقد خشيت بأن أموت ولم تدر ... للحرب دائرة على ابني ضمضم\nالدائرة: اسم للحادثة، سميت بها لأنها تدور من خير إلى شر ومن شر إلى خير ثم استعملت في المكروهة دون المحبوبة.\nيقول: ولقد أخاف أن أموت ولم تدر الحرب على ابني ضمضم بما يكرهانه، وهما حصين وهرم ابنا ضمضم."},{"id":"muallaqat:569","bookId":"muallaqat","type":"section","seq":569,"chapter":"مدخل","title":"74- الشاتمي عرضي ولم أشتمهما","page":"ج1 ص264","text":"الشاتمي عرضي ولم أشتمهما ... والناذرين إذا لم القهما دمي\nيقول: اللذان يشتمان عرضي ولم أشتمهما أنا، والموجبان على أنفسهما سفك دمي إذا لم أرهما، يريد أنهما يتواعدنه حال غيبته فأما في حال الحضور فلا يتجاسران عليه."},{"id":"muallaqat:570","bookId":"muallaqat","type":"section","seq":570,"chapter":"مدخل","title":"75- إن يفعلا فلقد تركت أباهما","page":"ج1 ص264","text":"إن يفعلا فلقد تركت أباهما ... جزر السباع وكل نسر قشعم\nيقول: إن يشتماني لم أستغرب منهما ذلك؛ فإني قتلت أباهما وصيرته جزر السباع وكل نسر مسن."},{"id":"muallaqat:571","bookId":"muallaqat","type":"section","seq":571,"chapter":"مدخل","title":"مدخل","page":"ج1 ص265","text":"...\nالحارث بن حلزة اليشكري\nهو: أبو عبيدة الحارث بن حلزة بن مكروه، من أهل العراق. وينتهي نسبه إلى: يشكر بن بكر بن وائل، وينتهي نسب وائل إلى نزار بن معد بن عدنان.\nوقد شهد الحارث بن حلزة حرب البسوس.\nكان الحارث بن حلزة خبيرا بقرض الشعر ومذاهب الكلام، ومعلقته قد جمعت طائفة من أيام العرب وأخبارها، ووعت ضروبا من المفاخر يقام لها ويقعد. وقد ارتجلها بين يدي عمرو بن هند الملك وهو غضبان متوكئ على قوسه. وقيل: بل كان قد أعدها قبل ذلك. وليس ببعيد عن الصواب. لما سترى من اختلاف الرواية في ذلك.\nأما شعره فهو قليل جدا لأنه كان من المقلين. وإنما اشتهر بمعلقته هذه التي رفعت من قدره، وجعلته في صف شعراء الجاهلية المجيدين."},{"id":"muallaqat:572","bookId":"muallaqat","type":"section","seq":572,"chapter":"مدخل","title":"1- آذنتنا ببينها أسماء","page":"ج1 ص267","text":"آذنتنا ببينها أسماء ... رب ثاو يمل منه الثواء\nالإيذان: الإعلام. البين: الفراق. الثواء والثوي: الإقامة، والفعل ثوى يثوي. يقول: أعلمتنا أسماء بمفارقتها إيانا، أي بعزمها على فراقنا، ثم قال: رب مقيم تمل إقامته ولم تكن أسماء منهم، يريد أنها وإن طالت إقامتها لم أمللها، والتقدير: رب ثاو يمل من ثوائه."},{"id":"muallaqat:573","bookId":"muallaqat","type":"section","seq":573,"chapter":"مدخل","title":"2- بعد عهد لها ببرقة شما","page":"ج1 ص267","text":"بعد عهد لها ببرقة شما ... ء فأدنى ديارها الخلصاء\nالعهد: اللقاء والفعل عهد يعهد.\nيقول: عزمت على فراقنا بعد أن لقيتها ببرقة شماء وخلصاء التي هي أقرب ديارها إلينا."},{"id":"muallaqat:574","bookId":"muallaqat","type":"section","seq":574,"chapter":"مدخل","title":"3- فالمحياة فالصفاح فأعنا","page":"ج1 ص267","text":"فالمحياة فالصفاح فأعنا ... ق فتاق فعاذب فالوفاء"},{"id":"muallaqat:575","bookId":"muallaqat","type":"section","seq":575,"chapter":"مدخل","title":"4- فرياض القطا فأودية الشر","page":"ج1 ص267","text":"فرياض القطا فأودية الشر ... بب فالشعبتان فالأبلاء\nهذه كلها مواضع عهدها بها.\nيقول: قد عزمت على مفارقتنا بعد طول العهد."},{"id":"muallaqat:576","bookId":"muallaqat","type":"section","seq":576,"chapter":"مدخل","title":"5- لا أرى من عهدت فيها فأبكي ال","page":"ج1 ص267","text":"لا أرى من عهدت فيها فأبكي ال ... يوم دلها وما يحير البكاء\nالإحارة: الرد، من قولهم: حار الشيء يحو حورا، أي رجع، وأحرته أنا أي رجعته فرددته.\nيقول: لا أرى في هذه المواضع من عهدت فيها، يريد أسماء، فأنا أبكي اليوم\nذاهب العقل وأي شيء رد البكاء على صاحبه؟ وهذا استفهام يتضمن الجحود، أي لا يرد البكاء على صاحبه فائتا، ولا يجدي عليه شيئا، وتحرير المعنى: لما خلت هذه المواضع منها بكيت جزعا لفراقها مع علمي بأنه لا طائل في البكاء. الدله والدله: ذهاب العقل، والتدلية إزالته."},{"id":"muallaqat:577","bookId":"muallaqat","type":"section","seq":577,"chapter":"مدخل","title":"6- وبعينيك أوقدت هند النا","page":"ج1 ص269","text":"وبعينيك أوقدت هند النا ... ر أخيرا تلوي بها العلياء\nألوى بالشيء: أشار به. العلياء: البقعة العالية.\nيخاطب نفسه ويقول: وإنما أوقدت هند النار بمرآك ومنظر منك، وكأن البقعة العالية التي أوقدتها عليها كانت تشير إليك بها، يريد أنها ظهرت لك أتم ظهور فرأيتها أتم رؤية."},{"id":"muallaqat:578","bookId":"muallaqat","type":"section","seq":578,"chapter":"مدخل","title":"7- فتنورت نارها من بعيد","page":"ج1 ص269","text":"فتنورت نارها من بعيد ... بخزازى هيهات منك الصلاء\nالتنور: النظر إلى النار. خزازى: بقعة بعينها. هيهات: بعد الأمر جدا.\nالصلاء مصدر صلي النار، وصلي بالنار يصلى صلى وصلاء إذا احترق بها أو ناله حرها.\nيقول: ولقد نظرت إلى نار هند بهذه البقعة على بعد بيني وبينها لأصلاها، ثم قال: بعد منك الاصطلاء بها جدا، أي أردت أن آتيها فعاقتني العوائق من الحروب وغيرها."},{"id":"muallaqat:579","bookId":"muallaqat","type":"section","seq":579,"chapter":"مدخل","title":"8- أوقدتها بين العقيق فشخصي","page":"ج1 ص269","text":"أوقدتها بين العقيق فشخصي ... ن بعود كما يلوح الضياء\nيقول: أوقدت هند تلك النار بين هذين الموضعين بعود فلاحت كما يلوح الضياء."},{"id":"muallaqat:580","bookId":"muallaqat","type":"section","seq":580,"chapter":"مدخل","title":"9- غير أني قد أستعين على الهم","page":"ج1 ص269","text":"غير أني قد أستعين على الهم ... إذا خف بالثوي النجاء\nغير أني: يريد ولكني، انتقل من النسيب إلى ذكر حاله في طلب المجد. الثوي والثاوي: المقيم. النجاء: الإسراع في السير، والباء للتعدية.\nيقول: ولكني أستعين على إمضاء همي وقضاء أمري إذا أسرع المقيم في السير لعظم الخطب وفظاعة الخوف."},{"id":"muallaqat:581","bookId":"muallaqat","type":"section","seq":581,"chapter":"مدخل","title":"10- بزفوف كأنها هقلة أ","page":"ج1 ص270","text":"بزفوف كأنها هقلة أ ... م رئال دوية سقفاء\nالزفيف: إسراع النعامة في سيرها ثم يستعار لسير غيرها، والفعل زف يزف، والنعت زاف، والزفوف مبالغة. الهقلة: النعامة، والظليم هقل. الرأل: ولد النعامة، والجمع رئال، الدوية: منسوبة إلى الدو وهي المفازة1. السقف: طول مع انحناء، والنعت أسقف.\nيقول: أستعين على إمضاء همي وقضاء أمري عند صعوبة الخطب وشدته بناقة مسرعة في سيرها، كأنها في إسراعها في السير نعامة لها أولاد طويلة منحنية لا تفارق المفاوز."},{"id":"muallaqat:582","bookId":"muallaqat","type":"section","seq":582,"chapter":"مدخل","title":"11- آنست نبأة وأفزعها الق","page":"ج1 ص270","text":"آنست نبأة وأفزعها الق ... ناص عصرا وقد دنا الإمساء\nالنبأة: الصوت الخفي يسمعه الإنسان أو يتخيله. القناص. جمع قانص وهو الصائد. الإفزاع: الإخافة. العصر: العشي.\nيقول: أحست هذه النعامة بصوت الصيادين فأخافها ذلك عشيا وقد دنا دخولها في المساء، لما شبه ناقته بالنعامة بسيرها بالغ في وصف النعامة بالإسراع في السير بأنها تئوب إلى أولادها مع إحساسها بالصيادين وقرب المساء، فإن هذه الأسباب تزيدها إسراعا في سيرها."},{"id":"muallaqat:583","bookId":"muallaqat","type":"section","seq":583,"chapter":"مدخل","title":"12- فترى خلفها من الرجع والوق","page":"ج1 ص270","text":"فترى خلفها من الرجع والوق ... ع منينا كأنه إهباء\nالمنين: الغبار الرقيق. الأهباء: جمع هباء، والإهباء إثارته.\nيقول: فترى أنت أيها المخاطب خلف هذه الناقة من رجعها2 قوائمها وضربها الأرض بها غبارا رقيقا كأنه هباء منبث. وجعله رقيقا إشارة إلى غاية إسراعها."},{"id":"muallaqat:584","bookId":"muallaqat","type":"section","seq":584,"chapter":"مدخل","title":"13- وطراقا من خلفهن طراق","page":"ج1 ص270","text":"وطراقا من خلفهن طراق ... ساقطات ألوت بها الصحراء\nالطراق: يريد بها أطباق نعلها. ألوى بالشيء: أفناه وأبطله، وألوى بالشيء أشار به.\nيقول: وترى خلفهما أطباق نعلها في أماكن مختلفة قد قطعها وأبطلها قطع الصحراء ووطؤها."},{"id":"muallaqat:585","bookId":"muallaqat","type":"section","seq":585,"chapter":"مدخل","title":"14- أتلهى بها الهواجر إذ كل","page":"ج1 ص271","text":"أتلهى بها الهواجر إذ كل ... ابن هم بلية عمياء\nيقول: أتلعب بها في أشد ما يكون من الحر إذا تحير صاحب كل هم تحير الناقة البلية1 العمياء.\nيقول: أركبها وأقتحم بها لفح الهواجر إذا تحير غيري في أمره، يريد أنه لا يعوقه الحر عن مرامه."},{"id":"muallaqat:586","bookId":"muallaqat","type":"section","seq":586,"chapter":"مدخل","title":"15- وأتانا من الحوادث والأنبا","page":"ج1 ص271","text":"وأتانا من الحوادث والأنبا ... ء خطب نعنى به ونساء\nيقول: ولقد أتانا من الحوادث والأخبار أمر عظيم نحن معنيون محزونون لأجله. عني الرجل بالشيء يعنى به فهو معني به، وعني يعنى إذا كان ذا عناء به. وسؤت الرجل سواء ومساءة وسوائية أحزنته."},{"id":"muallaqat:587","bookId":"muallaqat","type":"section","seq":587,"chapter":"مدخل","title":"16- إن إخواننا الأراقم يغلو","page":"ج1 ص271","text":"إن إخواننا الأراقم يغلو ... ن علينا في قيلهم إحفاء\nالأراقم: بطون من تغلب، سموا بها لأن امرأة شبهت عيون آبائهم بعيون الأراقم2. الغلو: مجاوزة الحد. الإحفاء: الإلحاح. ثم فسر ذلك الخطب فقال: هو تعدي إخواننا من الأراقم علينا وغلوهم في عدوانهم علينا في مقالتهم."},{"id":"muallaqat:588","bookId":"muallaqat","type":"section","seq":588,"chapter":"مدخل","title":"17- يخلطون البريء منا بذي الذن","page":"ج1 ص271","text":"يخلطون البريء منا بذي الذن ... ب ولا ينفع الخلي الخلاء\nيريد بالخلي: البريء الخالي من الذنب.\nيقول: هم يخلطون برآءنا بمذنبينا، فلا تنفع البريء براءة ساحته من الذنب."},{"id":"muallaqat:589","bookId":"muallaqat","type":"section","seq":589,"chapter":"مدخل","title":"18- زعموا أن كل من ضرب العي","page":"ج1 ص271","text":"زعموا أن كل من ضرب العي ... ر موال لنا وأنا الولاء\nالعير في هذا البيت يفسر: بالسيد، والحمار، والوتد، والقذى، وجبل بعينه. قوله: وأنا الولاء، أي أصحاب ولائهم، فحذف المضاف، ثم إن فسر العير بالسيد\nكان تحرير المعنى: زعم الأراقم أن كل من يرضى بقتل كليب وائل بنو أعمامنا وأنا أصحاب ولائهم تلحقنا جرائرهم، وإن فسر بالحمار كان المعنى: أنهم زعموا أن كل من صاد حمر الوحش موالينا، أي ألزموا العامة جناية الخاصة، وإن فسر بالوتد كان المعنى: زعموا أن كل من ضرب الخيام وطنبها بأوتادها موالينا، أي ألزموا العرب جناية بعضنا، وإن فسر بالقذى كان المعنى: زعموا أن كل من ضرب القذى ليتنحي فيصفوا الماء موالينا، وإن فسر بالجبل المعين كان المعنى: زعموا أن كل من صار إلى هذا الجبل موال لنا. وتفسير آخر البيت في جميع الأقوال على نمط واحد."},{"id":"muallaqat:590","bookId":"muallaqat","type":"section","seq":590,"chapter":"مدخل","title":"19- أجمعوا أمرهم عشاء فلما","page":"ج1 ص272","text":"أجمعوا أمرهم عشاء فلما ... أصبحوا أصبحت لهم ضوضاء\nالضوضاء: الجلبة والصياح. إجماع الأمر: عقد القلب وتوطين النفس عليه. يقول: أطبقوا على أمرهم من قتلنا وجدالنا عشاء، فلما أصبحوا جلبوا وصاحوا."},{"id":"muallaqat:591","bookId":"muallaqat","type":"section","seq":591,"chapter":"مدخل","title":"20- من مناد ومن مجيب ومن تص","page":"ج1 ص272","text":"من مناد ومن مجيب ومن تص ... هال خيل خلال ذاك رغاء\nالتصهال كالصهيل، وتفعال لا يكون إلا مصدرا، وتفعال لا يكون إلا اسما. يقول: اختلطت أصوات الداعين والمجيبين والخيل والإبل، يريد بذلك تجمعهم وتأهبهم."},{"id":"muallaqat:592","bookId":"muallaqat","type":"section","seq":592,"chapter":"مدخل","title":"21- أيها الناطق المرقش1 عنا","page":"ج1 ص272","text":"أيها الناطق المرقش1 عنا ... عند عمرو وهل لذاك بقاء\nيقول: أيها الناطق عند الملك الذي يبلغ عنا الملك ما يريبه ويشككه في محبتنا إياه ودخولنا تحت طاعته وانقيادنا لحبل سياسته، هل لذلك التبليغ بقاء؟ وهذا استفهام معناه النفي، أي لا بقاء لذلك؛ لأن الملك يبحث عنه فيعلم أن ذلك من الأكاذيب المخترعة والأباطيل المبتدعة؛ وتحرير المعنى: أنه يقول: أيها المضرب2 بيننا وبين الملك بتبليغك إياه عنا ما يكرهه لا بقاء لما أنت عليه لأن بحث الملك عنه يعرفه أنه كذب بحت محض."},{"id":"muallaqat:593","bookId":"muallaqat","type":"section","seq":593,"chapter":"مدخل","title":"22- لا تخلنا على غراتك إنا","page":"ج1 ص273","text":"لا تخلنا على غراتك إنا ... قبل ما قد وشى بنا الأعداء\nالغراة: اسم بمعنى الإغراء، يخاطب من يسعى بهم من بني تغلب إلى عمرو بن هند ملك العرب.\nيقول: لا تظننا متذللين متخاشعين لإغرائك الملك بنا، فقد وشى بنا أعداؤنا إلى الملوك قبلك؛ وتحرير المعنى: إن إغراءك الملك بنا لا يقدح في أمرنا كما لم يقدح إغراء غيرك فيه، قوله: على غراتك، أي على امتداد غراتك، والمفعول الثاني لتخلنا محذوف تقديره: لا تخلنا متخاشعين، وما أشبه ذلك."},{"id":"muallaqat:594","bookId":"muallaqat","type":"section","seq":594,"chapter":"مدخل","title":"23- فبقينا على الشناءة تنمي","page":"ج1 ص273","text":"فبقينا على الشناءة تنمي ... نا حصون وعزة قعساء\nالشناءة: البغض. تنمينا: ترفعنا.\nيقول: فبقينا على بغض الناس إيانا وإغرائهم الملوك بنا ترفع شأننا وتعلي قدرنا حصون منيعة وعزة ثابتة لا تزول."},{"id":"muallaqat:595","bookId":"muallaqat","type":"section","seq":595,"chapter":"مدخل","title":"24- قبل ما اليوم بيضت بعيون الن","page":"ج1 ص273","text":"قبل ما اليوم بيضت بعيون الن ... اس فيها تغيظ وإباء\nالباء في: بعيون، زائدة، أي بيضت عيون الناس، وتبييض العين: كناية عن الإعماء. وما في قوله: قبل ما، صلة زائدة.\nيقول: قد أعمت عزتنا قبل يومنا الذي نحن فيه عيون أعدئنا من الناس، يريد أن الناس يحسدوننا على إباء عزتنا على من كادها وتغيظها على من أرادها بسوء، حتى كأنهم عموا عند نظرهم إلينا لفرط كراهيتهم ذلك وشدة بغضهم إيانا، وجعل التغيظ والإباء للعزة مجازا وهما عند التحقيق لهم."},{"id":"muallaqat:596","bookId":"muallaqat","type":"section","seq":596,"chapter":"مدخل","title":"25- وكأن المنون تردي بنا أر","page":"ج1 ص273","text":"وكأن المنون تردي بنا أر ... عن جونا ينجاب عنه العماء\nالردي: الرمي، والفعل منه ردى يردي. قوله: بنا، أي تردينا. الأرعن: الجبل الذي له رعن1. الجون: الأسود والأبيض جميعا، والجمع الجون، والمراد به الأسود في البيت.\nالانجياب: الانكشاف والانشقاق. العماء: السحاب.\nيقول: وكأن الدهر برميه إيانا بمصائبه ونوائبه يرمي جبلا أرعن أسود ينشق عنه السحاب، أي يحيط به ولا يبلغ أعلاه، يريد أن نوائب الزمان وطوارق الحدثان لا تؤثر فيهم ولا تقدح في عزهم، كما لا تؤثر في مثل هذا الجبل الذي لا يبلغ السحاب أعلاه لسموه وعلوه."},{"id":"muallaqat:597","bookId":"muallaqat","type":"section","seq":597,"chapter":"مدخل","title":"26- مكفهرا على الحوادث لا تر","page":"ج1 ص274","text":"مكفهرا على الحوادث لا تر ... توه للدهر مؤيد صماء\nالاكفهرار: شدة العبوس والقطوب. الرتو: الشد والإرخاء جميعا، وهو من الأضداد، ولكنه في البيت بمعنى الإرخاء. المؤيد: الداهية العظيمة، مشتقة من الأيد والآد وهما القوة.\nالصماء: الشديدة، من الصمم الذي هو الشدة والصلابة، والبيت من صفة الأرعن.\nيقول: يشتد ثباته على انتياب الحوادث لا ترخيه ولا تضعفه داهية قوية شديدة من دواهي الدهر، يقول: ونحن مثل هذا الجبل في المنعة والقوة."},{"id":"muallaqat:598","bookId":"muallaqat","type":"section","seq":598,"chapter":"مدخل","title":"27- إرمي بمثله جالت الخي","page":"ج1 ص274","text":"إرمي بمثله جالت الخي ... ل وتأبى لخصمها الإجلاء\nإرم: جد عاد، وهو عاد بن عوص بن إرم بن سام.\nيقول: هو إرمي من الحسب قديم الشرف، بمثله ينبغي أن تجول الخيل وأن تأبى لخصمها أن يجلى صاحبها عن أوطانه، يريد أن مثله يحمي الحوزة ويذب عن الحريم."},{"id":"muallaqat:599","bookId":"muallaqat","type":"section","seq":599,"chapter":"مدخل","title":"28- ملك مقسط وأفضل من يم","page":"ج1 ص274","text":"ملك مقسط وأفضل من يم ... شي ومن دون ما لديه الثناء\nالإقساط: العدل.\nيقول: هو ملك عادل وهو أفضل ماش على الأرض، أي أفضل الناس، والثناء قاصر عما عنده."},{"id":"muallaqat:600","bookId":"muallaqat","type":"section","seq":600,"chapter":"مدخل","title":"29- أيما خطة أردتم فأدو","page":"ج1 ص274","text":"أيما خطة أردتم فأدو ... ها إلينا تشفى بها الأملاء\nالخطة: الأمر العظيم الذي يحتاج إلى مخلص منه. أدوها أي فوضوها. الأملاء: الجماعات من الأشراف، الواحد ملأ، لأنهم يملأون القلوب والعيون جلالة وجمالا.\nيقول: فوضوا إلى آرائنا كل خصومة أردتم تشفى بها جماعات الأشراف والرؤساء بالتخلص منها إذ لا يجدون عنها مخلصا، يريد أنهم أولو رأي وحزم يشفى به ويسهل عليهم، ما يتعذر على غيرهم من الأشراف في فصل الخصومات والقضاء في المشكلات."},{"id":"muallaqat:601","bookId":"muallaqat","type":"section","seq":601,"chapter":"مدخل","title":"30- إن نبشتم ما بين ملحة فالصا","page":"ج1 ص275","text":"إن نبشتم ما بين ملحة فالصا ... قب فيه الأموات والأحياء\nيقول: إن بحثتم عن الحروب التي كانت بيننا وبين هذين الموضعين وجدتم قتلى لم يثأر بها وقتلى قد ثئر بها، فسمى الذي لم يثأر بها أمواتا، والذي ثئر بهم أحياء؛ لأنهم لما قتل بهم من أعدائهم كأنهم عادوا أحياء إذ لم تذهب دماؤهم هدرا، يريد أنهم ثأروا بقتلاهم وتغلب لم تثأر بقتلاهم."},{"id":"muallaqat:602","bookId":"muallaqat","type":"section","seq":602,"chapter":"مدخل","title":"31- أو نقشتم فالنقش يجشمه النا","page":"ج1 ص275","text":"أو نقشتم فالنقش يجشمه النا ... س وفيه الإسقام والإبراء\nالإسقام: مصدر، والأسقام جمع سقم وسقم. الإبراء: مصدر، والأبراء: جمع برء. النقش: الاستقصاء، ومنه قيل لاستخراج الشوك من البدن نقش. والفعل منه نقش ينقش.\nيقول: فإن استقصيتم في ذكر ما جرى بيننا من جدال وقتال، فهو شيء قد يتكلفه ويتبين فيه المذنب من البريء، كنى بالسقم عن الذنب وبالبرء عن براءة الساحة، يريد أن الاستقصاء فيما ذكر يبين براءتنا من الذنب والذنب ذنبكم."},{"id":"muallaqat:603","bookId":"muallaqat","type":"section","seq":603,"chapter":"مدخل","title":"32- أو سكتم عنا فكنا كمن أغ","page":"ج1 ص275","text":"أو سكتم عنا فكنا كمن أغ ... مض عينا في جفنها الأقذاء\nالأقذاء: جمع القذى، والقذى جمع قذاة.\nيقول: وإن أعرضتم عن ذلك أعرضنا عنكم مع إضمارنا الحقد عليكم كمن أغضى الجفون عن القذى."},{"id":"muallaqat:604","bookId":"muallaqat","type":"section","seq":604,"chapter":"مدخل","title":"33- أو منعتم ما تسألون فمن حد","page":"ج1 ص275","text":"أو منعتم ما تسألون فمن حد ... ثتموه له علينا العلاء\nيقول: وإن منعتم ما سألناكم من المهادنة والموادعة، فمن الذي حدثتم عنه أنه عزنا وعلانا، أي فأي قوم أخبرتم عنهم أنهم فضلونا، أي لا قوم أشرف منا، فلا نعجز عن مقابلتكم بمثل صنيعكم."},{"id":"muallaqat:605","bookId":"muallaqat","type":"section","seq":605,"chapter":"مدخل","title":"34- هل علمتم أيام ينتهب النا","page":"ج1 ص276","text":"هل علمتم أيام ينتهب النا ... س غوارا لكل حي عواء\nالغوار: المغاورة. العواء: صوت الذئب ونحوه، وهو ههنا مستعار للضجيج والصياح.\nيقول: قد علمتم غناءنا في الحروب وحمايتنا أيام إغارة الناس بعضهم على بعض، وضجيجهم وصياحهم مما ألم بهم من الغارات. وهل في البيت بمعنى قد لأنه يحتج عليهم بما علموه. الانتهاب: الإغارة."},{"id":"muallaqat:606","bookId":"muallaqat","type":"section","seq":606,"chapter":"مدخل","title":"35- إذ رفعنا الجمال من سعف البح","page":"ج1 ص276","text":"إذ رفعنا الجمال من سعف البح ... رين سيرا حتى نهاها الحساء\nالسعف: أغصان النخلة، والوحدة سعفة. قوله، سيرا، أي فسارت سيرا فحذف الفعل لدلالة المصدر عليه، الحساء: موضع بعينه.\nيقول: حين رفعنا جمالنا على أشد السير حتى سارت من البحرين سيرا شديدا إلى أن بلغت هذا الموضع الذي يعرف بالحساء، أي طوينا ما بين هذين الموضعين سيرا وإغارة على القبائل، فلم يكفنا شيء عن مرامنا حتى انتهينا إلى الحساء."},{"id":"muallaqat:607","bookId":"muallaqat","type":"section","seq":607,"chapter":"مدخل","title":"36- ثم ملنا على تميم فأحرم","page":"ج1 ص276","text":"ثم ملنا على تميم فأحرم ... نا وفينا بنات قوم إماء\nأحرمنا أي دخلنا في الشهر الحرام.\nيقول: ثم ملنا من الحساء فأغرنا على بني تميم، ثم دخل الشهر الحرام وعندنا سبايا القبائل قد استخدمناهن، فبنات الذين أغرنا عليهم كن إماء لنا."},{"id":"muallaqat:608","bookId":"muallaqat","type":"section","seq":608,"chapter":"مدخل","title":"37- لا يقيم العزيز بالبلد السه","page":"ج1 ص276","text":"لا يقيم العزيز بالبلد السه ... ل ولا ينفع الذليل النجاء\nالنجاء، ممدودا ومقصورا: الإسراع في السير.\nيقول: وحين كان الأحياء الأعزة يتحصنون بالجبال ولا يقيمون بالبلاد السهلة، والأذلاء كان لا ينفعهم إسراعهم في الفرار، يريد أن الشر كان شاملا عاما لم يسلم منه العزيز ولا الذليل."},{"id":"muallaqat:609","bookId":"muallaqat","type":"section","seq":609,"chapter":"مدخل","title":"38- ليس ينجي الذي يوائل منا","page":"ج1 ص277","text":"ليس ينجي الذي يوائل منا ... رأس طود وحرة رجلاء\nوأل، وواءل: أي هرب وفزع. الرجلاء: الغليظة الشديدة.\nيقول: لم ينج الهارب منا تحصنه بالجبل ولا بالحرة1 الغليظة الشديدة."},{"id":"muallaqat:610","bookId":"muallaqat","type":"section","seq":610,"chapter":"مدخل","title":"39- ملك أضرع البرية لا يو","page":"ج1 ص277","text":"ملك أضرع البرية لا يو ... جد فيها لما لديه كفاء\nأضرع: ذلل وقهر ومنه قولهم في المثل: الحمى أضرعتني لك. الكفاءة والمكافأة: المساواة.\nيقول: هو ملك ذلل وقهر الخلق فما يوجد فيهم من يساويه في معاليه. والكفاء بمعنى المكافئ، فالمصدر موضوع اسم الفاعل."},{"id":"muallaqat:611","bookId":"muallaqat","type":"section","seq":611,"chapter":"مدخل","title":"40- كتكاليف قومنا إذ غزا المن","page":"ج1 ص277","text":"كتكاليف قومنا إذ غزا المن ... ذر هل نحن لابن هند رعاء\nالتكاليف: المشاق والشدائد.\nيقول: هل قاسيتم من المشاق والشدائد ما قاسى قومنا حين غزا منذر أعداءه فحاربهم؟ وهل كان رعاء2 لعمرو بن هند كما كنتم رعاءه؟ ذكر أنهم نصروا الملك حين لم ينصره بنو تغلب، وعيرهم بأنهم رعاء الملك وقومه يأنفون من ذلك."},{"id":"muallaqat:612","bookId":"muallaqat","type":"section","seq":612,"chapter":"مدخل","title":"41- ما أصابوا من تغلبي فمطلو","page":"ج1 ص277","text":"ما أصابوا من تغلبي فمطلو ... ل عليه إذا أصيب العفاء\nطل دمه وأطل: أهدر. العفاء: الدروس، وهو أيضا التراب الذي يغطي الأثر يقول: ما قتلوه من بني تغلب أهدرت دماؤهم حتى كأنها غطيت بالتراب ودرست، يريد أن دماء بني تغلب تهدر ودماؤهم لا تهدر بل يدركون ثأرهم."},{"id":"muallaqat:613","bookId":"muallaqat","type":"section","seq":613,"chapter":"مدخل","title":"42- إذ أحل العلياء قبة ميسو","page":"ج1 ص277","text":"إذ أحل العلياء قبة ميسو ... ن فأدنى ديارها العوصاء\nميسون: امرأة.\nيقول: وإنما كان هذا حين أنزل الملك قبة هذه المرأة علياء وعوصاء التي هي أقرب ديارها إلى الملك."},{"id":"muallaqat:614","bookId":"muallaqat","type":"section","seq":614,"chapter":"مدخل","title":"43- فتأوت له قراضبة من","page":"ج1 ص278","text":"فتأوت له قراضبة من ... كل حي كأنهم ألقاء\nالقرضوب والقرضاب: اللص الخبيث، والجمع القراضبة. التأوي: التجمع. الألقاء: جمع لقوة وهي العقاب.\nيقول: تجمعت له لصوص خبثاء كأنهم عقبان لقوتهم وشجاعتهم."},{"id":"muallaqat:615","bookId":"muallaqat","type":"section","seq":615,"chapter":"مدخل","title":"44- فهداهم بالأسودين وأمر الله","page":"ج1 ص278","text":"فهداهم بالأسودين وأمر الله ... بلغ تشقى به الأشقياء\nالأسودان: الماء والتمر. هداهم أي تقدمهم.\nيقول: وكان يتقدمهم ومعه زادهم من الماء والتمر، وقد يكون هدى بمعنى قاد، والمعنى: فقاد هذا المعسكر وزادهم التمر والماء، ثم قال: وأمر الله بالغ مبالغة يشقى به الأشقياء في حكمه وقضائه."},{"id":"muallaqat:616","bookId":"muallaqat","type":"section","seq":616,"chapter":"مدخل","title":"45- إذ تمنونهم غرورا فساقت","page":"ج1 ص278","text":"إذ تمنونهم غرورا فساقت ... هم إليكم أمنية أشراء\nالأشر: البطر، والأشراء: البطرة.\nيقول: حين تمنيتم قتالهم إياكم ومصيرهم إليكم اغترارا بشوكتكم وعدتكم، فساقتهم إليكم أمنيتكم التي كانت مع البطر."},{"id":"muallaqat:617","bookId":"muallaqat","type":"section","seq":617,"chapter":"مدخل","title":"46- لم يغروكم غرورا ولكن","page":"ج1 ص278","text":"لم يغروكم غرورا ولكن ... رفع الآل شخصهم والضحاء\nالآل: ما يرى كالسراب في طرفي النهار. الضحاء: بعيد الضحى.\nيقول: لم يفاجئوكم مفاجأة ولكن أتوكم وأنتم ترونهم خلال السراب حتى كأن السراب يرفع أشخاصهم لكم."},{"id":"muallaqat:618","bookId":"muallaqat","type":"section","seq":618,"chapter":"مدخل","title":"47- أيها الناطق المبلغ عنا","page":"ج1 ص278","text":"أيها الناطق المبلغ عنا ... عند عمرو وهل لذاك انتهاء\nيقول: أيها الناطق المبلغ عنا عند عمرو بن هند الملك ألا تنتهي عن تبليغ الأخبار الكاذبة عنا؟"},{"id":"muallaqat:619","bookId":"muallaqat","type":"section","seq":619,"chapter":"مدخل","title":"48- من لنا عنده من الخير آيا","page":"ج1 ص278","text":"من لنا عنده من الخير آيا ... ت ثلاث في كلهن القضاء\nيقول: هو الذي لنا عنده ثلاث آيات، أي ثلاث دلائل من دلائل غنائنا وحسن بلائنا في الحروب والخطوب، يقضى لنا على خصومنا في كلها، أي يقضي الناس لنا بالفضل على غيرنا فيها."},{"id":"muallaqat:620","bookId":"muallaqat","type":"section","seq":620,"chapter":"مدخل","title":"49- آية شارق الشقيقة إذ جا","page":"ج1 ص279","text":"آية شارق الشقيقة إذ جا ... ءت معد لكل حي لواء\nالشقيقة: أرض صلبة بين رملتين، والجمع شقائق. الشروق: الطلوع والإضاءة. يقول: إحداها شارق1 الشقيقة حين جاءت معد بألويتها وراياتها. وأراد بشارق الشقيقة: الحرب التي قامت بها."},{"id":"muallaqat:621","bookId":"muallaqat","type":"section","seq":621,"chapter":"مدخل","title":"50- حول قيس مستلئمين بكبش","page":"ج1 ص279","text":"حول قيس مستلئمين بكبش ... قرظي كأنه عبلاء\nأراد قيس بن معد يكرب من ملوك حمير. الاستلئام: لبس اللأمة وهي الدرع. القرظ: شجر يدبغ به الأديم. الكبش: السيد، مستعار له بمنزلة القرم. البعلاء: هضبة بيضاء.\nيقول: جاءت مع راياتها حول قيس متحصنين بسيد من بلاد القرظ، وبلاد القرظ: اليمن كأنه في منعته وشوكته هضبة من الهضاب، يريد أنهم كفوا عادية قيس وجيشه عن عمرو بن هند."},{"id":"muallaqat:622","bookId":"muallaqat","type":"section","seq":622,"chapter":"مدخل","title":"51- وصتيت من العواتك لا تن","page":"ج1 ص279","text":"وصتيت من العواتك لا تن ... هاه إلا مبيضة رعلاء\nالصتيت: الجماعة. العواتك: الشواب الحرائر الخيار من النساء. الرعلاء: الطويلة الممتدة.\nيقول: والثانية جماعة من أولاد الحرائر الكرائم الشواب، لا يمنعها عن مرامها ولا يكفها عن مطالبها إلا كتيبة مبيضة ببياض دروعها وبيضها عظيمة ممتدة، وقيل: بل معناه إلا سيوف مبيضة طوال، وقوله: من العواتك، أي من أولاد العواتك."},{"id":"muallaqat:623","bookId":"muallaqat","type":"section","seq":623,"chapter":"مدخل","title":"52- فرددناهم بطعن كما يخ","page":"ج1 ص279","text":"فرددناهم بطعن كما يخ ... رج من خربة المزاد الماء\nخربة المزاد: ثقبها. والمزاد: جمع مزادة وهي زق الماء خاصة.\nيقول: رددنا هؤلاء القوم بطعن خرج الدم من جراحه خروج الماء من أفواه القرب وثقوبها."},{"id":"muallaqat:624","bookId":"muallaqat","type":"section","seq":624,"chapter":"مدخل","title":"53- وحملناهم على حزم ثهلا","page":"ج1 ص279","text":"وحملناهم على حزم ثهلا ... ن شلالا ودمي الأنساء\nالحزم: أغلظ من الحزن1. ثهلان: جبل بعينه. الشلال: الطراد. الأنساء: جمع النسا وهو عرق معروف في الفخذ. التدمية والإدماء: اللطخ بالدم.\nيقول: ألجأناهم إلى التحصين بغلظ هذا الجبل والالتجاء إليه في مطاردتنا إياهم وأدمينا أفخاذهم بالطعن والضرب."},{"id":"muallaqat:625","bookId":"muallaqat","type":"section","seq":625,"chapter":"مدخل","title":"54- وجبهناهم بطعن كما تن","page":"ج1 ص280","text":"وجبهناهم بطعن كما تن ... هز في جمة الطوي الدلاء\nالجبه: أعنف الردع، والفعل جبه يجبه. النهز: التحريك. الجمة: الماء الكثير المجتمع. الطوي: البئر التي طويت بالحجارة أو اللبن.\nيقول: منعناهم أشد منع وأعنف ردع، فتحركت رماحنا في أجسامهم كما تحرك الدلاء في ماء البئر المطوية بالحجارة."},{"id":"muallaqat:626","bookId":"muallaqat","type":"section","seq":626,"chapter":"مدخل","title":"55- وفعلنا بهم كما علم الله","page":"ج1 ص280","text":"وفعلنا بهم كما علم الله ... وما إن للحائنين دماء\nحان: تعرض للهلاك، وحان: هلك، يحين حينا.\nيقول: وفعلنا بهم فعلا بليغا لا يحيط به علما إلا الله ولا دماء للمتعرضين للهلاك أوالهالكين، أي لم يطلب بثأرهم ودمائهم."},{"id":"muallaqat:627","bookId":"muallaqat","type":"section","seq":627,"chapter":"مدخل","title":"56- ثم حجرا أعني ابن أم قطام","page":"ج1 ص280","text":"ثم حجرا أعني ابن أم قطام ... وله فارسية خضراء\nيقول: ثم قاتلنا بعد ذلك حجر بن أم قطام، وكانت له كتيبة فارسية خضراء لما ركب دروعها وبيضها من الصدأ، وقيل: بل أراد وله دروع فارسية خضراء لصدئها."},{"id":"muallaqat:628","bookId":"muallaqat","type":"section","seq":628,"chapter":"مدخل","title":"57- أسد في اللقاء ورد هموس","page":"ج1 ص280","text":"أسد في اللقاء ورد هموس ... وربيع إن شمرت غبراء\nالورد: الذي يضرب لونه إلى الحمرة. الهمس: صوت القدم. وجعل الأسد هموسا؛ لأنه يسمع من رجليه في مشيه صوت. شمرت: استعدت. الغبراء: السنة الشديدة لاغبرار الهواء فيها.\nيقول: كان حجر أسدا في الحرب بهذه الصفة، وكان للناس بمنزلة الربيع إذا\nتهيأت، واستعدت السنة الشديدة للشر، يريد أنه كان ليث الحرب غيث الجدب."},{"id":"muallaqat:629","bookId":"muallaqat","type":"section","seq":629,"chapter":"مدخل","title":"58- وفككنا غل امرئ القيس عنه","page":"ج1 ص281","text":"وفككنا غل امرئ القيس عنه ... بعدما طال حبسه والعناء\nيقول: وخلصنا امرأ القيس من حبسه وعنائه بعدما طال عليه."},{"id":"muallaqat:630","bookId":"muallaqat","type":"section","seq":630,"chapter":"مدخل","title":"59- ومع الجون جون آل بني الأو","page":"ج1 ص281","text":"ومع الجون جون آل بني الأو ... س عنود كأنها دفواء\nيقول: وكانت مع الجون كتيبة شديدة العناد كأنها في شوكتها وعدتها هضبة دفئة. والجون الثاني بدل من الأول، والأول في التقدير محذوف كقوله تعالى: {لعلي أبلغ الأسباب، أسباب السموات} [غافر: 36، 37] ."},{"id":"muallaqat:631","bookId":"muallaqat","type":"section","seq":631,"chapter":"مدخل","title":"60- ما جزعنا تحت العجاجة إذ ول","page":"ج1 ص281","text":"ما جزعنا تحت العجاجة إذ ول ... وا شلالا وإذ تلظى الصلاء\nالعجاجة: الغبار. تلظى: تلهب. الصلاء والصلى: مصدر صليت بالنار أصلى إذا نالك حرها.\nيقول: ما جزعنا تحت غبار الحرب حين تولوا في حال الطراد ولا حين تلهب نار الحرب."},{"id":"muallaqat:632","bookId":"muallaqat","type":"section","seq":632,"chapter":"مدخل","title":"61- وأقدناه رب غسان بالمن","page":"ج1 ص281","text":"وأقدناه رب غسان بالمن ... ذر كرها إذ لا تكال الدماء\nأقدته: أعطيته القود1.\nيقول: وأعطيناه ملك غسان قودا بالمنذر حين عجز الناس عن الاقتصاص وإدراك الأثآر، وجعل كيل الدماء مستعارا للقصاص، وهذه هي الآية الثالثة."},{"id":"muallaqat:633","bookId":"muallaqat","type":"section","seq":633,"chapter":"مدخل","title":"62- وأتيناهم بتسعة أملا","page":"ج1 ص281","text":"وأتيناهم بتسعة أملا ... ك كرام أسلابهم أغلاء\nيقول: وأتيناهم بتسعة من الملوك وقد أسرناهم وكانت أسلابهم غالية الأثمان لعظم أخطارهم وجلالة أقدارهم. الأسلاب: جمع السلب وهو الثياب والسلاح والفرس."},{"id":"muallaqat:634","bookId":"muallaqat","type":"section","seq":634,"chapter":"مدخل","title":"63- وولدنا عمرو بن أم أناس","page":"ج1 ص281","text":"وولدنا عمرو بن أم أناس ... من قريب لما أتانا الحباء\nيقول: وولدنا هذا الملك بعد زمان قريب لما أتانا الحباء، أي زوجنا أمه من أبيه لما أتانا مهرها، يريد إنا أخوال هذا الملك."},{"id":"muallaqat:635","bookId":"muallaqat","type":"section","seq":635,"chapter":"مدخل","title":"64- مثلها تخرج النصيحة للقو","page":"ج1 ص282","text":"مثلها تخرج النصيحة للقو ... م فلاة من دونها أفلاء\nيقول: مثل هذه القرابة تستخرج النصيحة للقوم الأقارب قربى أرحام يتصل بعضها ببعض كفلوات يتصل بعضها ببعض. الفلاة تجمع على الفلا ثم تجمع الفلا على الأفلاء، وتحرير المعنى: إن مثل هذه القرابة التي بيننا وبين الملك توجب النصيحة له إذ هي أرحام مشتبكة."},{"id":"muallaqat:636","bookId":"muallaqat","type":"section","seq":636,"chapter":"مدخل","title":"65- فاتركوا الطيخ والتعاشي وإما","page":"ج1 ص282","text":"فاتركوا الطيخ والتعاشي وإما ... تتعاشوا ففي التعاشي الداء\nالطيخ: التكبر. التعاشي: التعامي، وهما تكلف العشى والعمى ممن ليس به عشى وعمى وكذلك التفاعل إذا كان بمعنى التكلف.\nيقول: فاتركوا الكبر وإظهار التجبر والجهل وإن لزمتهم ذلك ففيه الداء، يعني: أفضى بكم ذلك إلى شر عظيم."},{"id":"muallaqat:637","bookId":"muallaqat","type":"section","seq":637,"chapter":"مدخل","title":"66- واذكروا حلف ذي المجاز وما قد","page":"ج1 ص282","text":"واذكروا حلف ذي المجاز وما قد ... م فيه العهود والكفلاء\nذو المجاز: موضع جمع به عمرو بن هند بكرا وتغلب وأصلح بينهما وأخذ منهما الوثائق والرهون.\nيقول: واذكروا العهد الذي كان منا بهذا الموضع وتقديم الكفلاء فيه."},{"id":"muallaqat:638","bookId":"muallaqat","type":"section","seq":638,"chapter":"مدخل","title":"67- حذر الجور والتعدي وهل ين","page":"ج1 ص282","text":"حذر الجور والتعدي وهل ين ... قض ما في المهارق الأهواء؟\nالمهارق: جمع المهرق، وهو فارسي معرب، يأخذون الخرقة ويطلونها بشيء ثم يصقلونها ثم يكتبون عليها شيئا، والمهرق: معرب مهر كرد.\nيقول: وإنما تعاقدنا هناك حذر الجور والتعدي من إحدى القبيلتين فلا ينقض ما كتب في المهارق الأهواء الباطلة، يريد أن ما كتب في العهود لا تبطله أهواؤكم الضالة."},{"id":"muallaqat:639","bookId":"muallaqat","type":"section","seq":639,"chapter":"مدخل","title":"68- واعلموا أننا وإياكم في","page":"ج1 ص282","text":"واعلموا أننا وإياكم في ... ما اشترطنا يوم اختلفنا سواء\nيقول: واعملوا أننا وإياكم في تلك الشرائط التي أوثقناها يوم تعاقدنا مستوون."},{"id":"muallaqat:640","bookId":"muallaqat","type":"section","seq":640,"chapter":"مدخل","title":"69- عننا باطلا وظلما كما تع","page":"ج1 ص283","text":"عننا باطلا وظلما كما تع ... تر عن حجرة الربيض1 الظباء\nالعنن: الاعتراض، والفعل عن يعن. العتر: ذبح العتيرة، وهي ذبيحة كانت تذبح للأصنام في رجب. الحجرة: الناحية، والجمع الحجرات. وقد كان الرجل ينذر إن بلغ الله غنمه مائة ذبح منها واحدة للأصنام ثم ربما ضنت نفسه بها فأخذ ظبيا وذبحه مكان الشاة الواجبة عليها.\nيقول: ألزمتمونا ذنب غيرنا عننا كما يذبح الظبي لحق وجب في الغنم."},{"id":"muallaqat:641","bookId":"muallaqat","type":"section","seq":641,"chapter":"مدخل","title":"70- أعلينا جناح كندة أن يغ","page":"ج1 ص283","text":"أعلينا جناح كندة أن يغ ... نم غازيهم ومنا الجزاء\nالجناح: الإثم.\nيقول: أعلينا ذنب كندة أن يغنم غازيهم منكم ومنا يكون جزاء ذلك؟ يوبخهم ويعيرهم أن كندة غزتهم فغنمت منهم، وأنا يلزمنا جزاء ذلك."},{"id":"muallaqat:642","bookId":"muallaqat","type":"section","seq":642,"chapter":"مدخل","title":"71- أم علينا جرى إياد كما ني","page":"ج1 ص283","text":"أم علينا جرى إياد كما ني ... ط بجوز المحمل الأعباء\nالجراء والجرى بالمد والقصر: الجناية. النوط: التعليق. الجوز: الوسط، والجمع الأجواز. العبء: الثقل.\nيقول: أم علينا جناية إياد؟ ثم قال: ألزمتمونا ذلك كما تعلق الأثقال على وسط البعير المحمل."},{"id":"muallaqat:643","bookId":"muallaqat","type":"section","seq":643,"chapter":"مدخل","title":"72- ليس منا المضربون ولا قي","page":"ج1 ص283","text":"ليس منا المضربون ولا قي ... س ولا جندل ولا الحداء\nيقول: هؤلاء المضربون ليسوا منا، عيرهم بأنهم منهم."},{"id":"muallaqat:644","bookId":"muallaqat","type":"section","seq":644,"chapter":"مدخل","title":"73- أم جنايا بني عتيق فإنا","page":"ج1 ص283","text":"أم جنايا بني عتيق فإنا ... منكم إن غدرتم برآء\nيقول: أم علينا جنايا بني عتيق؟ ثم قال: إن نقضتم العهد فإنا برآء منكم."},{"id":"muallaqat:645","bookId":"muallaqat","type":"section","seq":645,"chapter":"مدخل","title":"74- وثمانون من تميم بأيدي","page":"ج1 ص283","text":"وثمانون من تميم بأيدي ... هم رماح صدورهن القضاء\nالقضاء: القتل.\nيقول: وغزاكم ثمانون من بني تميم بأيديهم رماح أسنتها القتل، أي القاتلة. وصدر كل شيء: أوله."},{"id":"muallaqat:646","bookId":"muallaqat","type":"section","seq":646,"chapter":"مدخل","title":"75- تركوهم ملحبين وآبوا","page":"ج1 ص284","text":"تركوهم ملحبين وآبوا ... بنهاب يصم منها الحداء\nالتلحيب: التقطيع. الأوب والإياب: الرجوع.\nيقول: تركت بنو تميم هؤلاء القوم مقطعين بالسيوف وقد رجعوا إلى بلادهم مع غنائم يصم حداء حداتها آذان السامعين، أشار بذلك إلى كثرتها."},{"id":"muallaqat:647","bookId":"muallaqat","type":"section","seq":647,"chapter":"مدخل","title":"76- أم علينا جرى حنيفة أم ما","page":"ج1 ص284","text":"أم علينا جرى حنيفة أم ما ... جمعت من محارب غبراء\nيقول: أم علينا جناية بني حنيفة أم جناية ما جمعت الأرض أو السنة الغبراء من محارب."},{"id":"muallaqat:648","bookId":"muallaqat","type":"section","seq":648,"chapter":"مدخل","title":"77- أم علينا جرحى قضاعة أم لي","page":"ج1 ص284","text":"أم علينا جرحى قضاعة أم لي ... س علينا فيما جنوا أنداء\nيقول: أم علينا جناية قضاعة؟ بل ليس علينا في جنايتهم ندى، أي لا تلحقنا ولا تلزمنا تلك الجناية."},{"id":"muallaqat:649","bookId":"muallaqat","type":"section","seq":649,"chapter":"مدخل","title":"78- ثم جاءوا يسترجعون فلم تر","page":"ج1 ص284","text":"ثم جاءوا يسترجعون فلم تر ... جع لهم شامة ولا زهراء\nيقول: ثم جاءوا يسترجعون الغنائم فلم ترد عليهم شاة زهراء، أي بيضاء، ولا ذات شامة، هذه الأبيات كلها تعيير لهم وإبانة عن تعديهم وطلبهم المحال؛ لأن مؤاخذة الإنسان بذنب غيره ظلم صراح."},{"id":"muallaqat:650","bookId":"muallaqat","type":"section","seq":650,"chapter":"مدخل","title":"79- لم يحلوا بني رزاح ببرقا","page":"ج1 ص284","text":"لم يحلوا بني رزاح ببرقا ... ء نطاع لهم عليهم دعاء\nأحللته: جعلته حلالا.\nيقول: ما أحل قومنا محارم هؤلاء القوم وما كان منهم دعاء على قومنا، يعيرهم بأنهم أحلوا محارم هؤلاء القوم بهذا الموضع فدعوا عليهم."},{"id":"muallaqat:651","bookId":"muallaqat","type":"section","seq":651,"chapter":"مدخل","title":"80- ثم فاءوا منهم بقاصمة الظه","page":"ج1 ص284","text":"ثم فاءوا منهم بقاصمة الظه ... ر ولا يبرد الغليل الماء\nالفيء: الرجوع، والفعل فاء يفيء.\nيقول: ثم انصرفوا منهم بداهية قصمت ظهورهم وغليل أجواف لا يسكنه شرب الماء لأنه حرارة الحقد لا حرارة العطش، يريد أنهم فاءوا وقتلوا ولم يثأروا بقتلاهم."},{"id":"muallaqat:652","bookId":"muallaqat","type":"section","seq":652,"chapter":"مدخل","title":"81- ثم خيل من بعد ذاك مع الغلا","page":"ج1 ص285","text":"ثم خيل من بعد ذاك مع الغلا ... ق لا رأفة ولا إبقاء\nيقول: ثم جاءتكم خيل من الغلاق فأغارت عليكم ولم ترحمكم، ولم تبق عليكم."},{"id":"muallaqat:653","bookId":"muallaqat","type":"section","seq":653,"chapter":"مدخل","title":"82- وهو الرب والشهيد على يو","page":"ج1 ص285","text":"وهو الرب والشهيد على يو ... م الحيارين والبلاء بلاء\nيقول: وهو الملك والشاهد على حسن بلائنا يوم قتالنا بهذا الموضع والعناء عناء، أي قد بلغ الغاية، يريد عمرو بن هند فإنه شهد عناءهم هذا، والله سبحانه وتعالى أعلم."}]};